func TestBuildSurfaceToolApprovalRequestIncludesSandboxDenialReason(t *testing.T) {
	ctx := context.Background()
	home := t.TempDir()
	db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
	if err != nil {
		t.Fatalf("OpenStateForTest error: %v", err)
	}
	defer db.Close()

	actions := newTestActions(t, db)
	runs := &state.RunStore{DB: db}
	run, err := runs.CreateRun(ctx, "s1", "sandbox retry")
	if err != nil {
		t.Fatalf("CreateRun error: %v", err)
	}
	act, err := actions.CreatePending(ctx, "s1", "shell", map[string]any{
		"command": "go test ./...", "justification": "The sandbox blocked this command: listen tcp 127.0.0.1:0: bind: operation not permitted. Allow it to run outside the sandbox?",
		"sandbox_denial_reason": "listen tcp 127.0.0.1:0: bind: operation not permitted",
	})
	if err != nil {
		t.Fatalf("CreatePending error: %v", err)
	}
	if err := runs.SetWaitingAction(ctx, run.ID, state.Wait{
		RunID: run.ID, ActionID: act.ID, ToolName: "shell",
		ToolInputJSON: `{"command":"go test ./...","justification":"The sandbox blocked this command: listen tcp 127.0.0.1:0: bind: operation not permitted. Allow it to run outside the sandbox?","sandbox_denial_reason":"listen tcp 127.0.0.1:0: bind: operation not permitted"}`,
	}); err != nil {
		t.Fatalf("SetWaitingAction error: %v", err)
	}

	req, err := (sessionEnv{ActionSvc: actions, RunSvc: runs}.session()).buildSurfaceToolApprovalRequest(ctx, "s1")
	if err != nil {
		t.Fatalf("buildSurfaceToolApprovalRequest error: %v", err)
	}
	want := "The sandbox blocked this command: listen tcp 127.0.0.1:0: bind: operation not permitted. Allow it to run outside the sandbox?"
	if req == nil || req.Reason != want {
		t.Fatalf("approval reason = %#v, want %q", req, want)
	}
	if req.Description != "" {
		t.Fatalf("sandbox retry must not masquerade as a command description: %#v", req)
	}
}

func TestBuildSurfaceToolApprovalRequestIncludesShellSuggestions(t *testing.T) {
	ctx := context.Background()
	home := t.TempDir()
	db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
	if err != nil {
		t.Fatalf("OpenStateForTest error: %v", err)
	}
	defer db.Close()

	actions := newTestActions(t, db)
	runs := &state.RunStore{DB: db}
	run, err := runs.CreateRun(ctx, "s1", "pending tool approval")
	if err != nil {
		t.Fatalf("CreateRun error: %v", err)
	}
	act, err := actions.CreatePending(ctx, "s1", "shell", map[string]any{"command": "npm run build"})
	if err != nil {
		t.Fatalf("CreatePending error: %v", err)
	}
	if err := runs.SetWaitingAction(ctx, run.ID, state.Wait{
		RunID:         run.ID,
		ActionID:      act.ID,
		ToolName:      "shell",
		ToolInputJSON: `{"command":"npm run build"}`,
	}); err != nil {
		t.Fatalf("SetWaitingAction error: %v", err)
	}

	cs := sessionEnv{ActionSvc: actions, RunSvc: runs}.session()
	req, err := cs.buildSurfaceToolApprovalRequest(ctx, "s1")
	if err != nil {
		t.Fatalf("buildSurfaceToolApprovalRequest error: %v", err)
	}
	if req == nil {
		t.Fatalf("expected approval request")
	}
	if req.PermissionToolName != "Bash" {
		t.Fatalf("unexpected permission tool name: %+v", req)
	}
	if req.PermissionInput != "npm run build" {
		t.Fatalf("unexpected permission input: %+v", req)
	}
	if req.ExactRuleContent != "npm run build" {
		t.Fatalf("unexpected exact rule: %+v", req)
	}
	if req.PrefixRuleContent != "npm run build:*" {
		t.Fatalf("unexpected prefix rule: %+v", req)
	}
	if len(req.DestinationOptions) == 0 || req.SuggestedDestination != safety.DestinationLocalSettings {
		t.Fatalf("unexpected destination metadata: %+v", req)
	}
}

