func TestSurfaceApprovalSinkAllowPrefixBuildsUpdateAndAppliesIt(t *testing.T) {
	ctx := context.Background()
	home := t.TempDir()
	db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
	if err != nil {
		t.Fatalf("OpenStateForTest error: %v", err)
	}
	defer db.Close()

	actions := newTestActions(t, db)
	runs := &state.RunStore{DB: db}
	runRow, err := runs.CreateRun(ctx, "s1", "pending tool approval")
	if err != nil {
		t.Fatalf("CreateRun error: %v", err)
	}
	act, err := actions.CreatePending(ctx, "s1", "shell", map[string]any{"command": "go test ./..."})
	if err != nil {
		t.Fatalf("CreatePending error: %v", err)
	}
	if err := runs.SetWaitingAction(ctx, runRow.ID, state.Wait{
		RunID:         runRow.ID,
		ActionID:      act.ID,
		ToolName:      "shell",
		ToolInputJSON: `{"command":"go test ./..."}`,
	}); err != nil {
		t.Fatalf("SetWaitingAction error: %v", err)
	}

	runner := &run.Runner{Deps: &run.Deps{Home: home}}
	cs := sessionEnv{
		Home:      home,
		ActionSvc: actions,
		RunSvc:    runs,
		Runner:    runner,
	}.session()
	req, err := cs.buildSurfaceToolApprovalRequest(ctx, "s1")
	if err != nil {
		t.Fatalf("buildSurfaceToolApprovalRequest error: %v", err)
	}
	if req == nil {
		t.Fatalf("expected approval request")
	}
	if len(req.AvailableDecisions) != 3 || req.AvailableDecisions[1].Decision != safety.DecisionAcceptWithExecPolicyAmendment ||
		!slices.Equal(req.AvailableDecisions[1].ExecPolicyAmendment, []string{"go", "test"}) {
		t.Fatalf("surface did not receive the service-proposed decisions: %#v", req.AvailableDecisions)
	}

	// The surface builds the persistent-rule decision itself; go through that
	// production path rather than a parallel one, so this test fails if the
	// approval a user grants stops producing the rule it promises.
	decision, err := buildRuleDecisionToDestination(*req, safety.DestinationLocalSettings)
	if err != nil {
		t.Fatalf("buildRuleDecisionToDestination error: %v", err)
	}
	if !decision.Approved || decision.Update == nil {
		t.Fatalf("expected structured approval with update, got %+v", decision)
	}
	if decision.Update.Type != safety.UpdateAddRules ||
		decision.Update.Destination != safety.DestinationLocalSettings ||
		decision.Update.Behavior != safety.BehaviorAllow {
		t.Fatalf("unexpected permission update: %+v", decision.Update)
	}
	if len(decision.Update.Rules) != 1 || decision.Update.Rules[0].ToolName != "Bash" ||
		decision.Update.Rules[0].RuleContent != "" ||
		!slices.Equal(decision.Update.Rules[0].CommandPrefix, []string{"go", "test"}) {
		t.Fatalf("unexpected update rules: %+v", decision.Update.Rules)
	}
	if err := cs.completeSurfaceToolApprovalDecision(ctx, req.ActionID, turn.ToolApprovalDecision{
		Approved: decision.Approved,
		Update:   decision.Update,
	}); err != nil {
		t.Fatalf("completeSurfaceToolApprovalDecision error: %v", err)
	}
	if d := runner.EvaluatePermission("Bash", "go test ./..."); d.Behavior != safety.BehaviorAllow || !d.BypassSandbox {
		t.Fatalf("expected approved command to be trusted, got %+v", d)
	}
	if d := runner.EvaluatePermission("Bash", "npm run test"); d.Matched != nil || d.BypassSandbox {
		t.Fatalf("approval widened to a different command: %+v", d)
	}
}

