// TestBuildSurfaceToolApprovalRequestExitPlanModePlanPath verifies that the
// exit_plan_mode approval request resolves the plan file path from the per-agent
// state root (workspace root), NOT from s.home(). The plan is written/edited at
// state.PlanPathForProject(stateRoot, projectKey) by the plan-mode tools and write_file/edit
// gating; if the approval request used s.home() the overlay would look at a
// different path and show "No plan found" even though the plan exists.
func TestBuildSurfaceToolApprovalRequestExitPlanModePlanPath(t *testing.T) {
	ctx := context.Background()
	home := t.TempDir()
	db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
	if err != nil {
		t.Fatalf("OpenStateForTest error: %v", err)
	}
	defer db.Close()

	actions := newTestActions(t, db)
	runs := &state.RunStore{DB: db}
	run, err := runs.CreateRun(ctx, "s1", "pending tool approval")
	if err != nil {
		t.Fatalf("CreateRun error: %v", err)
	}
	act, err := actions.CreatePending(ctx, "s1", "exit_plan_mode", map[string]any{
		"session_id": "s1",
		"action":     "exit",
	})
	if err != nil {
		t.Fatalf("CreatePending error: %v", err)
	}
	if err := runs.SetWaitingAction(ctx, run.ID, state.Wait{
		RunID:         run.ID,
		ActionID:      act.ID,
		ToolName:      "exit_plan_mode",
		ToolInputJSON: `{}`,
	}); err != nil {
		t.Fatalf("SetWaitingAction error: %v", err)
	}

	cs := sessionEnv{Home: home, ActionSvc: actions, RunSvc: runs}.session()

	// The per-agent state root is the active agent's workspace root (<home>/workspace
	// for the main agent), which is DIFFERENT from home itself.
	stateRoot := cs.stateRoot()
	if stateRoot == "" {
		t.Fatalf("expected non-empty state root")
	}
	if stateRoot == home {
		t.Fatalf("state root should differ from home for this test to be meaningful: stateRoot=%q home=%q", stateRoot, home)
	}

	// Write the plan at the location the plan-mode tools actually use.
	wantPlan := "# Plan\n1. Do the thing\n2. Verify"
	wantPath := state.PlanPathForProject(stateRoot, "")
	if err := state.SetPlanForProject(stateRoot, "", wantPlan); err != nil {
		t.Fatalf("planstore.Set error: %v", err)
	}

	req, err := cs.buildSurfaceToolApprovalRequest(ctx, "s1")
	if err != nil {
		t.Fatalf("buildSurfaceToolApprovalRequest error: %v", err)
	}
	if req == nil {
		t.Fatalf("expected approval request")
	}

	// PlanFilePath must point at the state-root-based path, not the home-based one.
	if req.PlanFilePath != wantPath {
		t.Fatalf("PlanFilePath=%q want %q (stateRoot-based)", req.PlanFilePath, wantPath)
	}
	homePath := state.PlanPathForProject(home, "")
	if req.PlanFilePath == homePath {
		t.Fatalf("PlanFilePath should NOT be the home-based path %q (this is the bug: plan written under stateRoot but read under home)", homePath)
	}

	// The plan file at the resolved path must actually be readable - this is what
	// the approval overlay does to render "Here is the plan".
	got, rerr := os.ReadFile(req.PlanFilePath)
	if rerr != nil {
		t.Fatalf("plan file not readable at resolved PlanFilePath %q: %v", req.PlanFilePath, rerr)
	}
	if strings.TrimSpace(string(got)) != strings.TrimSpace(wantPlan) {
		t.Fatalf("plan content mismatch: got %q want %q", got, wantPlan)
	}
}

