// TestManualCompactSlashEmitsRunningAndTerminalFailureEvents pins the manual
// /compact end to end on the terminal: the compaction's own lifecycle — not a
// message the slash handler made up — reaches the screen through the runner's
// event sink, and it is written to the session's event log, which is what a
// resumed session replays the card from.
func TestManualCompactSlashEmitsRunningAndTerminalFailureEvents(t *testing.T) {
	ctx := context.Background()
	home := t.TempDir()
	db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
	require.NoError(t, err)
	t.Cleanup(func() { _ = db.Close() })
	sess := state.NewSessionStore(db, "main")
	runs := &state.RunStore{DB: db}
	_, err = sess.Append(ctx, "s1", "user", "compact this conversation")
	require.NoError(t, err)

	s := sessionEnv{Home: home, SessStore: sess, RunSvc: runs, Runner: &run.Runner{Deps: &run.Deps{Home: home}}}.session()
	s.runner().Events = event.SinkFunc(s.publishRunEvent)
	t.Cleanup(s.stopUINotificationDispatcher)
	events := make(chan any, 4)
	s.PrependUINotify(func(msg any) { events <- msg })
	reply, handled := s.HandleCompactSlash(ctx, "s1", "tui", nil)
	require.True(t, handled)
	require.Empty(t, reply)

	nextEvent := func() any {
		select {
		case event := <-events:
			return event
		case <-time.After(2 * time.Second):
			t.Fatal("timed out waiting for compact lifecycle event")
			return nil
		}
	}
	first := nextEvent()
	second := nextEvent()
	started, ok := first.(ContextCompactingMsg)
	require.True(t, ok, "first event=%T", first)
	failed, ok := second.(ContextCompactFailedMsg)
	require.True(t, ok, "second event=%T", second)
	require.Equal(t, started.CompactionID, failed.CompactionID)
	require.Equal(t, "manual", started.Trigger)
	require.Contains(t, failed.Error, "current model unavailable")

	logged, err := runs.ListSessionEventsOfType(ctx, "s1", event.RunEventContextCompactError, 10)
	require.NoError(t, err)
	require.Len(t, logged, 1)
}

func TestPrimaryAgentOptionsAndSwitchUseResolver(t *testing.T) {
	home := t.TempDir()
	cfg := appcfg.Root{}
	cfg.Agents.Definitions = map[string]appcfg.AgentDefinition{
		"main": {
			LLMProviders: []appcfg.AgentLLMProviderConfig{{
				Provider: "openai",
				Model:    "gpt-5",
				APIKey:   "test-key",
				BaseURL:  "http://127.0.0.1:9/v1",
			}},
		},
		"review": {
			Primary: true,
			LLMProviders: []appcfg.AgentLLMProviderConfig{{
				Provider: "openai",
				Model:    "gpt-5",
				APIKey:   "test-key",
				BaseURL:  "http://127.0.0.1:9/v1",
			}},
		},
	}
	runner := &run.Runner{Deps: &run.Deps{Home: home, AppCfg: &cfg}}
	// Env is what production always has, and the session now reads the tool
	// state through it rather than through the Runner (R4).
	s := sessionEnv{Home: home, Config: cfg, Runner: runner}.session()
	opts, err := s.PrimaryAgents()
	require.NoError(t, err)
	require.Len(t, opts, 2)
	require.Equal(t, "main", opts[0].ID)
	require.True(t, opts[0].Active)

	switched, err := s.SwitchPrimaryAgent(context.Background(), "rev")
	require.NoError(t, err)
	require.Equal(t, "review", switched.ID)
	require.True(t, switched.Active)
	require.Equal(t, "review", s.runner().AgentName)
	reviewWS := filepath.Join(home, "workspaces", "review")
	mainWS := filepath.Join(home, "workspace")
	require.Equal(t, reviewWS, s.runner().WorkspaceRoot)
	require.True(t, s.Env.Tools().PathUnderPrimaryWorkspace(filepath.Join(reviewWS, "state", "note.md")))
	require.False(t, s.Env.Tools().PathUnderPrimaryWorkspace(filepath.Join(mainWS, "state", "note.md")))
	_, err = tool.ResolveWithinRoots(filepath.Join(mainWS, "private.txt"), s.Env.Tools().AllowedRoots())
	require.ErrorIs(t, err, tool.ErrPathNotAllowed)
}

func TestHandlePermissionsSlashExplainRendersDecisionAndMatchedRule(t *testing.T) {
	home := t.TempDir()
	s := sessionEnv{
		Home:    home,
		Config:  appcfg.Root{},
		Sandbox: safety.NewManager(),
		Runner:  &run.Runner{Deps: &run.Deps{Home: home}},
	}.session()
	s.runner().ApplyPermissionUpdate(safety.PermissionUpdate{
		Type:        safety.UpdateAddRules,
		Destination: safety.DestinationSession,
		SessionID:   "s1",
		Behavior:    safety.BehaviorAllow,
		Rules:       []safety.PermissionRuleValue{{ToolName: "Bash", RuleContent: "npm run:*"}},
	})

	reply, handled := s.HandlePermissionsSlash("s1", "cli", []string{"explain", "Bash", "npm run build"})
	require.True(t, handled)
	require.Contains(t, reply, "Permissions: Bash")
	require.Contains(t, reply, "npm run build")
	require.Contains(t, reply, "Allowed — runs without asking.")
	require.Contains(t, reply, "An allow rule in this session matched.")
	require.Contains(t, reply, "Matched rules")
	require.Contains(t, reply, "allow npm run:*  (this session)")
	require.Contains(t, reply, "Approval mode: on-request")
}

