func TestApplyModelReasoningSelectionPreservesExistingParams(t *testing.T) {
	t.Setenv("OPENAI_API_KEY", "test-key")
	home := t.TempDir()
	model := codeModelID("5.3")
	cfg := appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
		"main": {
			LLMProviders: []appcfg.AgentLLMProviderConfig{{
				Provider: "openai",
				Model:    model,
				APIKey:   "${OPENAI_API_KEY}",
				BaseURL:  "https://fast.example/v1",
				APIPath:  "/responses",
				Params:   appcfg.LLMRequestParams(`{"stream":true,"reasoning":{"effort":"medium"}}`),
			}},
		},
	}}}
	require.NoError(t, appcfg.Save(filepath.Join(home, "forebrain.yaml"), cfg))
	db, err := state.OpenStateForTest(context.Background(), filepath.Join(home, "state.db"))
	require.NoError(t, err)
	t.Cleanup(func() { _ = db.Close() })

	s := sessionEnv{
		Home:      home,
		SQL:       db,
		SessStore: state.NewSessionStore(db, "main"),
		Config:    cfg,
		Runner:    &run.Runner{Deps: &run.Deps{AppCfg: &cfg}},
	}.session()

	picked := chooseInSession(t, s, "model", "openai / "+model+" - GPT-5.3 Codex")
	require.Equal(t, "", picked.Reply, "re-picking the model in force changes nothing")
	require.NotNil(t, picked.Picker)
	require.Equal(t, "model-effort", picked.Picker.Command)
	var xhigh string
	for _, item := range picked.Picker.Items {
		require.Equal(t, item.Label == "medium", item.Current)
		if item.Label == "xhigh" {
			xhigh = item.Value
		}
	}
	require.Equal(t, "Reasoning effort set to xhigh.", chooseInSession(t, s, "model-effort", xhigh).Reply)

	saved, err := appcfg.Load(filepath.Join(home, "forebrain.yaml"))
	require.NoError(t, err)
	got := saved.Agents.Definitions["main"].LLMProviders[0]
	require.Equal(t, "https://fast.example/v1", got.BaseURL)
	require.Equal(t, "/responses", got.APIPath)
	require.JSONEq(t, `{"stream":true,"reasoning":{"effort":"xhigh"}}`, string(got.Params))
}

