func TestMemoryNoteApprovalConfirmationText(t *testing.T) {
	req := turn.ToolApprovalRequest{
		ToolName:      "memories_add_ad_hoc_note",
		ToolInputJSON: `{"filename":"user-profile.md","note":"sensitive body"}`,
	}
	for _, tc := range []struct {
		name     string
		decision turn.ToolApprovalDecision
		want     string
		approved bool
	}{
		{name: "approved", decision: turn.ToolApprovalDecision{Approved: true}, want: "You approved saving memory note user-profile.md", approved: true},
		{name: "denied", decision: turn.ToolApprovalDecision{Denied: true}, want: "You did not approve saving memory note user-profile.md"},
		{name: "canceled", decision: turn.ToolApprovalDecision{Cancelled: true}, want: "You canceled saving memory note user-profile.md"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got, approved := approvalConfirmationText(req, tc.decision)
			if got != tc.want || approved != tc.approved {
				t.Fatalf("confirmation=(%q, %v) want=(%q, %v)", got, approved, tc.want, tc.approved)
			}
			if strings.Contains(got, "sensitive body") || strings.Contains(got, `"note"`) {
				t.Fatalf("confirmation leaked note payload: %q", got)
			}
		})
	}
}

// Memory queries pass their whole argument JSON as the permission input, so the
// generic confirmation printed it back ("You approved forebrain to run
// {"path":"MEMORY.md",…} this time"). Every decision must name the action.
func TestMemoryQueryApprovalConfirmationText(t *testing.T) {
	for _, tc := range []struct {
		name      string
		tool      string
		inputJSON string
		approved  string
		denied    string
		canceled  string
	}{
		{
			name:      "read",
			tool:      "memories_read",
			inputJSON: `{"path":"MEMORY.md","line_offset":80,"max_lines":30}`,
			approved:  "You approved reading memory MEMORY.md",
			denied:    "You did not approve reading memory MEMORY.md",
			canceled:  "You canceled reading memory MEMORY.md",
		},
		{
			name:      "search",
			tool:      "memories_search",
			inputJSON: `{"queries":["deploy","rollback"],"case_sensitive":false,"cursor":"0"}`,
			approved:  `You approved searching memories for "deploy", "rollback"`,
			denied:    `You did not approve searching memories for "deploy", "rollback"`,
			canceled:  `You canceled searching memories for "deploy", "rollback"`,
		},
		{
			name:      "list",
			tool:      "memories_list",
			inputJSON: `{"path":"rollout_summaries"}`,
			approved:  "You approved listing memories in rollout_summaries",
			denied:    "You did not approve listing memories in rollout_summaries",
			canceled:  "You canceled listing memories in rollout_summaries",
		},
		{
			name:      "read without a path",
			tool:      "memories_read",
			inputJSON: `{}`,
			approved:  "You approved reading this memory file",
			denied:    "You did not approve reading this memory file",
			canceled:  "You canceled reading this memory file",
		},
		{
			name:      "search without queries",
			tool:      "memories_search",
			inputJSON: "",
			approved:  "You approved searching your memories",
			denied:    "You did not approve searching your memories",
			canceled:  "You canceled searching your memories",
		},
		{
			name:      "list at the root",
			tool:      "memories_list",
			inputJSON: `{"cursor":"0"}`,
			approved:  "You approved listing your memories",
			denied:    "You did not approve listing your memories",
			canceled:  "You canceled listing your memories",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			req := turn.ToolApprovalRequest{
				ToolName:           tc.tool,
				PermissionToolName: tc.tool,
				ToolInputJSON:      tc.inputJSON,
				PermissionInput:    tc.inputJSON,
				ExactRuleContent:   tc.inputJSON,
			}
			for _, decision := range []struct {
				decision turn.ToolApprovalDecision
				want     string
				approved bool
			}{
				{turn.ToolApprovalDecision{Approved: true}, tc.approved, true},
				{turn.ToolApprovalDecision{Denied: true}, tc.denied, false},
				{turn.ToolApprovalDecision{Cancelled: true}, tc.canceled, false},
			} {
				got, approved := approvalConfirmationText(req, decision.decision)
				if got != decision.want || approved != decision.approved {
					t.Fatalf("confirmation=(%q, %v) want=(%q, %v)", got, approved, decision.want, decision.approved)
				}
				for _, forbidden := range []string{"run ", "{", "}", "cursor"} {
					if strings.Contains(got, forbidden) {
						t.Fatalf("memory confirmation uses generic/raw wording %q: %q", forbidden, got)
					}
				}
			}
		})
	}
}

