func TestFileMutationApprovalConfirmationText(t *testing.T) {
	req := turn.ToolApprovalRequest{
		ToolName:           "edit_file",
		PermissionToolName: "edit_file",
		PermissionInput:    "internal/memories/pollution_test.go",
		ExactRuleContent:   "internal/memories/pollution_test.go",
		PrefixRuleContent:  "internal/memories/*",
	}
	tests := []struct {
		name     string
		decision turn.ToolApprovalDecision
		want     string
		approved bool
	}{
		{
			name:     "allow once",
			decision: turn.ToolApprovalDecision{Approved: true},
			want:     "You approved this change to `internal/memories/pollution_test.go`",
			approved: true,
		},
		{
			name:     "deny",
			decision: turn.ToolApprovalDecision{Denied: true},
			want:     "You did not approve this change to `internal/memories/pollution_test.go`",
		},
		{
			name:     "cancel",
			decision: turn.ToolApprovalDecision{Cancelled: true},
			want:     "You canceled this change to `internal/memories/pollution_test.go`",
		},
		{
			name: "session",
			decision: turn.ToolApprovalDecision{Approved: true, Update: &safety.PermissionUpdate{
				Type: safety.UpdateAddRules, Destination: safety.DestinationSession, Behavior: safety.BehaviorAllow,
				Rules: []safety.PermissionRuleValue{{RuleContent: "internal/memories/pollution_test.go"}},
			}},
			want:     "You approved changes to `internal/memories/pollution_test.go` for this session",
			approved: true,
		},
		{
			name: "persistent pattern",
			decision: turn.ToolApprovalDecision{Approved: true, Update: &safety.PermissionUpdate{
				Type: safety.UpdateAddRules, Destination: safety.DestinationLocalSettings, Behavior: safety.BehaviorAllow,
				Rules: []safety.PermissionRuleValue{{RuleContent: "internal/memories/*"}},
			}},
			want:     "You approved changes to files matching `internal/memories/*`",
			approved: true,
		},
		{
			name: "persistent exact",
			decision: turn.ToolApprovalDecision{Approved: true, Update: &safety.PermissionUpdate{
				Type: safety.UpdateAddRules, Destination: safety.DestinationLocalSettings, Behavior: safety.BehaviorAllow,
				Rules: []safety.PermissionRuleValue{{RuleContent: "forebrain.yaml"}},
			}},
			want:     "You approved changes to `forebrain.yaml`",
			approved: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, approved := approvalConfirmationText(req, tt.decision)
			if got != tt.want || approved != tt.approved {
				t.Fatalf("confirmation = %q, %v; want %q, %v", got, approved, tt.want, tt.approved)
			}
			if strings.Contains(got, "run") || strings.Contains(got, "command") {
				t.Fatalf("file confirmation uses command wording: %q", got)
			}
		})
	}
}

