func TestApprovalOverlay_RunLoopHidesHardwareCursor(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	out := newApprovalPaintWriter()
	r := NewRenderer(out, out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	r.RenderFrame(Frame{Kind: FrameSystem, Title: "sys", Content: "context", Final: true})

	req := turn.ToolApprovalRequest{
		ToolName:      "Bash",
		ToolInputJSON: `{"command":"ls"}`,
	}

	readEnd, writeEnd, err := os.Pipe()
	if err != nil {
		t.Fatalf("os.Pipe: %v", err)
	}
	t.Cleanup(func() {
		readEnd.Close()
		writeEnd.Close()
	})

	rs := newRawSelector(readEnd, r)
	overlay := newApprovalOverlay(context.Background(), out, rs, req, nil)

	// Keys must arrive after the overlay's first paint: bytes queued earlier are
	// pre-open input that Run intentionally discards.
	out.clearWriteSignals()
	done := make(chan error, 1)
	go func() {
		_, err := overlay.Run()
		done <- err
	}()

	out.waitForPaint(t)
	if _, err := writeEnd.Write([]byte{'\r'}); err != nil {
		t.Fatalf("write Enter: %v", err)
	}
	if err := <-done; err != nil {
		t.Fatalf("overlay run failed: %v", err)
	}

	rendered := out.String()
	footerIdx := strings.Index(rendered, "? for keys")
	if footerIdx < 0 {
		t.Fatalf("overlay output should show footer; got:\n%s", rendered)
	}
	// Look at the segment after the footer for any show-cursor sequence while
	// the overlay is still on screen (before EndOverlay re-shows the composer
	// caret). The footer itself is part of the last overlay line, so anything
	// after it within a reasonable window belongs to the same paint.
	window := rendered[footerIdx:]
	if len(window) > 200 {
		window = window[:200]
	}
	if strings.Contains(window, "\x1b[?25h") {
		t.Fatalf("approval overlay footer should not be followed by hardware cursor show (\\x1b[?25h), got:\n%s", window)
	}
}

func TestApprovalOverlay_RunLoopAfterNavHidesHardwareCursor(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	out := newApprovalPaintWriter()
	r := NewRenderer(out, out)
	r.EnableViewportMode()
	r.EnableSoftwareCursor()
	t.Cleanup(r.DisableViewportMode)

	r.RenderComposerState(ComposerRenderState{Text: "hi", Cursor: ptrInt(2)})

	req := turn.ToolApprovalRequest{
		ToolName:      "Bash",
		ToolInputJSON: `{"command":"ls"}`,
	}

	readEnd, writeEnd, err := os.Pipe()
	if err != nil {
		t.Fatalf("os.Pipe: %v", err)
	}
	t.Cleanup(func() {
		readEnd.Close()
		writeEnd.Close()
	})

	rs := newRawSelector(readEnd, r)
	overlay := newApprovalOverlay(context.Background(), out, rs, req, nil)

	out.clearWriteSignals()
	done := make(chan error, 1)
	go func() {
		_, err := overlay.Run()
		done <- err
	}()

	out.waitForPaint(t)
	// Move down to option 2, then back to option 1, then confirm.
	if _, err := writeEnd.Write([]byte{'j', 'k', '\r'}); err != nil {
		t.Fatalf("write navigation: %v", err)
	}
	if err := <-done; err != nil {
		t.Fatalf("overlay run failed: %v", err)
	}

	rendered := out.String()
	footerIdx := strings.Index(rendered, "? for keys")
	if footerIdx < 0 {
		t.Fatalf("overlay output should show footer; got:\n%s", rendered)
	}
	// After each navigation re-render the cursor must stay hidden while the
	// overlay is visible. Only the final EndOverlay restore may show it.
	window := rendered[footerIdx:]
	if len(window) > 400 {
		window = window[:400]
	}
	if strings.Contains(window, "\x1b[?25h") {
		t.Fatalf("approval overlay footer should not be followed by hardware cursor show (\\x1b[?25h) while navigating, got:\n%s", window)
	}
}

// fakeRawSelector creates a *rawSelector backed by a pipe so tests can
// inject key events by writing raw bytes to the write-end.
type fakeRawSelector struct {
	rs   *rawSelector
	pipe *os.File // write end
}

type signalWriter struct {
	wrote chan struct{}
	once  sync.Once
	mu    sync.Mutex
	buf   strings.Builder
}

func newSignalWriter() *signalWriter {
	return &signalWriter{wrote: make(chan struct{})}
}

func (w *signalWriter) Write(p []byte) (int, error) {
	w.once.Do(func() {
		close(w.wrote)
	})
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.buf.Write(p)
}

func newFakeRawSelector(t *testing.T) *fakeRawSelector {
	t.Helper()
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("os.Pipe: %v", err)
	}
	rs := &rawSelector{in: r}
	t.Cleanup(func() {
		r.Close()
		w.Close()
	})
	return &fakeRawSelector{rs: rs, pipe: w}
}

// write sends raw bytes into the pipe (the rawSelector reads them as key events).
func (f *fakeRawSelector) write(b []byte) {
	_, _ = f.pipe.Write(b)
}

// close closes the write end, causing the next readKey to return io.EOF.
func (f *fakeRawSelector) close() {
	_ = f.pipe.Close()
}

// runOverlay runs the overlay with injected keys synchronously. The caller is
// responsible for writing keys before calling runOverlay (or in a goroutine).
func runOverlayWithKeys(t *testing.T, req turn.ToolApprovalRequest, keys []byte) (turn.ToolApprovalDecision, error) {
	t.Helper()
	req = withServiceDecisions(req)
	f := newFakeRawSelector(t)
	// Write all keys then close so the overlay eventually terminates.
	f.write(keys)
	f.close()

	out := &strings.Builder{}
	// Bounded: an approval that cannot get the input waits for its request's
	// context, and a regression must fail this test, not hang the package.
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	overlay := newApprovalOverlay(ctx, out, f.rs, req, nil)
	return overlay.Run()
}

func withServiceDecisions(req turn.ToolApprovalRequest) turn.ToolApprovalRequest {
	if len(req.AvailableDecisions) > 0 || isApprovalExitPlanMode(req) {
		return req
	}
	toolName := strings.TrimSpace(req.ToolName)
	if toolName == "" {
		toolName = strings.TrimSpace(req.PermissionToolName)
	}
	actionKind := strings.TrimSpace(req.ActionKind)
	if actionKind == "" {
		actionKind = toolName
	}
	var input any = req.ToolInputJSON
	if req.NetworkApproval != nil {
		if toolName == "" {
			toolName = "shell"
			actionKind = "shell"
		}
		input = map[string]any{
			"command":                  req.PermissionInput,
			"network_approval_context": *req.NetworkApproval,
			"network_port":             req.NetworkPort,
		}
	} else if strings.TrimSpace(req.ToolInputJSON) == "" {
		input = map[string]any{
			"command":   req.ExactRuleContent,
			"file_path": req.ExactRuleContent,
		}
		if req.OneShotOnly {
			input.(map[string]any)["mcp_approval_mode"] = "writes"
		}
	}
	req.AvailableDecisions = safety.BuildApprovalDecisionOptions(actionKind, toolName, input)
	return req
}

