func TestApprovalOverlay_FileMutationLabels(t *testing.T) {
	tests := []struct {
		name string
		tool string
	}{
		{name: "edit internal", tool: "edit_file"},
		{name: "edit alias", tool: "Edit"},
		{name: "write internal", tool: "write_file"},
		{name: "write alias", tool: "Write"},
		{name: "multi edit internal", tool: "multi_edit"},
		{name: "multi edit alias", tool: "MultiEdit"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req := turn.ToolApprovalRequest{
				ToolName:           tt.tool,
				PermissionToolName: tt.tool,
				PermissionInput:    "internal/memories/pollution_test.go",
				ExactRuleContent:   "internal/memories/pollution_test.go",
				PrefixRuleContent:  "internal/memories/*",
			}
			choices := buildOverlayChoices(withServiceDecisions(req), 0)
			want := []string{
				"Yes, proceed",
				"Yes, and don't ask again for these files",
				"No, and tell Forebrain Harness what to do differently",
			}
			if len(choices) != len(want) {
				t.Fatalf("choices = %d, want %d", len(choices), len(want))
			}
			for i, label := range want {
				if choices[i].label != label {
					t.Errorf("choice %d = %q, want %q", i+1, choices[i].label, label)
				}
			}
		})
	}
}

