// A compound command whose clauses yield no prefix at all offers the command
// itself instead of leaving "yes, this once" as the only way to approve it.
func TestApprovalOverlay_ExactCommandChoicePersistsThatCommandOnly(t *testing.T) {
	command := "gofmt -w internal/a.go && rm -rf /tmp/x"
	req := withServiceDecisions(turn.ToolApprovalRequest{
		ToolName:           "Bash",
		PermissionToolName: "Bash",
		ToolInputJSON:      `{"command":"gofmt -w internal/a.go && rm -rf /tmp/x"}`,
		ExactRuleContent:   command,
		BypassSandbox:      true,
	})
	choices := buildOverlayChoices(req, 0)
	if len(choices) != 3 {
		t.Fatalf("expected 3 choices, got %d: %#v", len(choices), choices)
	}
	if choices[1].label != "Yes, and don't ask again for this command" {
		t.Fatalf("persistent label = %q", choices[1].label)
	}
	overlay := &approvalOverlay{out: io.Discard, req: req, options: choices, cursor: 1}
	decision := overlay.commit()
	if !decision.Approved || decision.Update == nil || len(decision.Update.Rules) != 1 {
		t.Fatalf("decision did not persist a rule: %#v", decision)
	}
	rule := decision.Update.Rules[0]
	if decision.Update.Destination != safety.DestinationLocalSettings ||
		rule.Command != command || rule.RuleContent != "" || len(rule.CommandPrefix) != 0 || !rule.BypassSandbox {
		t.Fatalf("persisted rule = %+v (destination %q)", rule, decision.Update.Destination)
	}
	if msg, ok := approvalConfirmationText(req, decision); !ok || msg != "You approved forebrain to always run "+command {
		t.Fatalf("confirmation = %q (%v)", msg, ok)
	}
}

// Every persistent choice that covers one command and nothing else says so in
// the same words, whatever that command looks like. The command is displayed
// in full above the choices, so a row that repeated it added nothing and, on
// a long one, wrapped over several lines.
func TestApprovalOverlay_OneCommandScopeHasOneWording(t *testing.T) {
	const want = "Yes, and don't ask again for this command"
	for _, command := range []string{
		"gofmt -w internal/a.go && rm -rf /tmp/x",
		"gofmt -w internal/a.go && rm -rf /tmp/scratch/build/artifacts/generated/output",
		"gofmt -w internal/foo.go internal/bar.go",
		"sudo ls",
	} {
		req := withServiceDecisions(turn.ToolApprovalRequest{
			ToolName:           "Bash",
			PermissionToolName: "Bash",
			ToolInputJSON:      `{"command":"` + command + `"}`,
			ExactRuleContent:   command,
			BypassSandbox:      true,
		})
		choices := buildOverlayChoices(req, 0)
		if len(choices) != 3 || choices[1].label != want {
			t.Fatalf("%q persistent label = %q", command, choices[1].label)
		}
	}
}

// The model wraps its real work in the same scaffolding every call — an
// `export VAR=$(...)` in front, a `| tail -N` behind — and only the middle
// clause varies. The engine allows a compound command only when every clause
// that is not known-safe matches a rule of its own, so the persistent row has
// to store one rule per clause: the scaffolding verbatim, the work as a prefix.
// A single rule naming one clause would leave the prompt returning forever.
func TestApprovalOverlay_CompoundCommandPersistsOneRulePerClause(t *testing.T) {
	command := `export JAVA_HOME=$(/usr/libexec/java_home -v 17) && mvn clean install -DskipTests 2>&1 | tail -12`
	req := withServiceDecisions(turn.ToolApprovalRequest{
		ToolName:           "Bash",
		PermissionToolName: "Bash",
		ToolInputJSON:      `{"command":"` + strings.ReplaceAll(command, `"`, `\"`) + `"}`,
		ExactRuleContent:   command,
		BypassSandbox:      true,
	})
	choices := buildOverlayChoices(req, 0)
	if len(choices) != 3 {
		t.Fatalf("expected 3 choices, got %d: %#v", len(choices), choices)
	}
	if choices[1].label != "Yes, and don't ask again for this command or its `mvn clean` variants" {
		t.Fatalf("persistent label = %q", choices[1].label)
	}
	overlay := &approvalOverlay{out: io.Discard, req: req, options: choices, cursor: 1}
	decision := overlay.commit()
	if !decision.Approved || decision.Update == nil {
		t.Fatalf("decision did not persist a rule: %#v", decision)
	}
	want := []safety.PermissionRuleValue{
		{ToolName: "Bash", Command: "export JAVA_HOME=$(/usr/libexec/java_home -v 17)", BypassSandbox: true},
		{ToolName: "Bash", CommandPrefix: []string{"mvn", "clean"}, BypassSandbox: true},
	}
	if len(decision.Update.Rules) != len(want) {
		t.Fatalf("persisted rules = %+v", decision.Update.Rules)
	}
	for i, rule := range decision.Update.Rules {
		if rule.Command != want[i].Command || rule.RuleContent != want[i].RuleContent ||
			!slices.Equal(rule.CommandPrefix, want[i].CommandPrefix) || !rule.BypassSandbox {
			t.Fatalf("rule %d = %+v, want %+v", i, rule, want[i])
		}
	}
	// The remembered set is what the engine needs to stop asking: the same
	// command with a different pager, and a different mvn goal, both pass.
	store := safety.NewStore()
	store.ReplaceRules(safety.SourceLocalSettings, safety.BehaviorAllow, decision.Update.Rules)
	engine := &safety.Engine{}
	for _, next := range []string{
		command,
		`export JAVA_HOME=$(/usr/libexec/java_home -v 17) && mvn clean install -DskipTests 2>&1 | tail -4`,
		`export JAVA_HOME=$(/usr/libexec/java_home -v 17) && mvn clean package -q 2>&1 | head -20`,
	} {
		if d := engine.EvaluateForSession(store, "", "Bash", next); d.Behavior != safety.BehaviorAllow {
			t.Fatalf("%q evaluated as %s/%s, want allow", next, d.Behavior, d.Reason)
		}
	}
}

// exactCommandApproval builds the request/decision pair produced by choosing
// "don't ask again for this exact command" on a Bash prompt.
func exactCommandApproval(command string) (turn.ToolApprovalRequest, turn.ToolApprovalDecision) {
	req := withServiceDecisions(turn.ToolApprovalRequest{
		ToolName:           "Bash",
		PermissionToolName: "Bash",
		ToolInputJSON:      `{"command":"git commit"}`,
		ExactRuleContent:   command,
		BypassSandbox:      true,
	})
	decision := turn.ToolApprovalDecision{Approved: true, Update: &safety.PermissionUpdate{
		Type:        safety.UpdateAddRules,
		Destination: safety.DestinationLocalSettings,
		Behavior:    safety.BehaviorAllow,
		Rules:       []safety.PermissionRuleValue{{ToolName: "Bash", RuleContent: command, BypassSandbox: true}},
	}}
	return req, decision
}

// The confirmation names the approved command in full, so the sink — not the
// text builder — is what keeps it inside three display lines. Drives
// printApprovalConfirmation so removing the cap fails the test.
func TestApprovalSink_ConfirmationIsCappedAtThreeLines(t *testing.T) {
	forcedTermWidth = 80
	t.Cleanup(func() { forcedTermWidth = 0 })

	command := "git commit -m \"" + strings.Repeat("重构 approval ", 30) + "\""
	req, decision := exactCommandApproval(command)

	var buf bytes.Buffer
	NewInteractiveApprovalSinkWithTTY(&buf, nil).printApprovalConfirmation(req, decision)

	out := strings.TrimSpace(buf.String())
	lines := strings.Split(out, "\r\n")
	if len(lines) != approvalConfirmationMaxLines {
		t.Fatalf("expected %d display lines, got %d: %q", approvalConfirmationMaxLines, len(lines), out)
	}
	if !strings.HasSuffix(out, "…") {
		t.Fatalf("truncated confirmation missing ellipsis: %q", out)
	}
	if !strings.Contains(out, "always run git commit") {
		t.Fatalf("confirmation does not name the command: %q", out)
	}
	for _, line := range lines {
		if w := displayLineWidth(line); w > forcedTermWidth {
			t.Fatalf("line of %d columns exceeds the %d-column terminal: %q", w, forcedTermWidth, line)
		}
	}
}

// The approved command is model-authored, so it can carry terminal escapes and
// newlines. None of it may reach the terminal verbatim: a surviving CSI/OSC
// repaints or retitles the terminal, and an ESC also defeats the wrapper's
// width math, which is what the three-line cap rides on.
func TestApprovalSink_ConfirmationStripsTerminalControlSequences(t *testing.T) {
	forcedTermWidth = 80
	t.Cleanup(func() { forcedTermWidth = 0 })

	command := "echo hi\x1b[2J\x1b]0;pwned\x07 && \rrm -rf /\nsecond line\ttabbed‮gnitirw"
	req, decision := exactCommandApproval(command)

	var buf bytes.Buffer
	NewInteractiveApprovalSinkWithTTY(&buf, nil).printApprovalConfirmation(req, decision)

	// The leading ✔ is styled by the sink itself; strip that known-good SGR
	// pair before asserting no escapes survived from the command.
	out := strings.ReplaceAll(strings.ReplaceAll(buf.String(), "\x1b[32m", ""), "\x1b[0m", "")
	if strings.ContainsRune(out, 0x1b) {
		t.Fatalf("escape sequence survived into the confirmation: %q", out)
	}
	// CRLF is the sink's own line separator; what must not survive is any
	// control character carried in from the command.
	body := strings.ReplaceAll(strings.TrimSpace(out), "\r\n", " ")
	for _, bad := range []string{"\x07", "\n", "\r", "\t", "‮", "[2J", "0;pwned"} {
		if strings.Contains(body, bad) {
			t.Fatalf("control payload %q survived: %q", bad, out)
		}
	}
	if !strings.Contains(out, "echo hi") || !strings.Contains(out, "rm -rf /") {
		t.Fatalf("sanitizing dropped the command text itself: %q", out)
	}
	if lines := strings.Split(strings.TrimSpace(out), "\r\n"); len(lines) > approvalConfirmationMaxLines {
		t.Fatalf("expected at most %d lines, got %d: %q", approvalConfirmationMaxLines, len(lines), out)
	}
}

