func TestExitPlanChoicesOnlyControlContextAndProceeding(t *testing.T) {
	plan := filepath.Join(t.TempDir(), "implementation.md")
	if err := os.WriteFile(plan, []byte("# Plan\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	req := turn.ToolApprovalRequest{
		ToolName:           "exit_plan_mode",
		PermissionToolName: "exit_plan_mode",
		PlanFilePath:       plan,
	}
	choices := buildExitPlanChoices(req, 37)
	if len(choices) != 3 {
		t.Fatalf("choices=%d want 3", len(choices))
	}
	wantLabels := []string{
		"Yes, clear context (37% used) and proceed",
		"Yes, proceed",
		"No, keep planning",
	}
	for i, want := range wantLabels {
		if choices[i].label != want {
			t.Fatalf("choice %d label=%q want %q", i+1, choices[i].label, want)
		}
	}

	first := (&approvalOverlay{req: req, options: choices, cursor: 0}).commit()
	if !first.Approved || !first.ClearContext || first.Update != nil {
		t.Fatalf("first choice decision=%#v, want approve+clear without permission update", first)
	}
	second := (&approvalOverlay{req: req, options: choices, cursor: 1}).commit()
	if !second.Approved || second.ClearContext || second.Update != nil {
		t.Fatalf("second choice decision=%#v, want approve without clear or permission update", second)
	}
	third := (&approvalOverlay{req: req, options: choices, cursor: 2}).commit()
	if !third.Denied || third.Approved || third.Update != nil {
		t.Fatalf("third choice decision=%#v, want keep planning", third)
	}
}

