func TestApprovalOverlay_PlanDenyBracketedPasteDoesNotSubmit(t *testing.T) {
	req := turn.ToolApprovalRequest{
		ToolName:           "exit_plan_mode",
		ToolInputJSON:      `{}`,
		PermissionToolName: "exit_plan_mode",
	}
	f := newFakeRawSelector(t)
	overlay := newApprovalOverlay(context.Background(), io.Discard, f.rs, req, nil)
	done := make(chan struct{})
	var decision turn.ToolApprovalDecision
	var runErr error
	go func() {
		decision, runErr = overlay.Run()
		close(done)
	}()

	// Choose "No, keep planning", then paste multiline feedback. The newline
	// inside the bracketed paste is content and must not act as Enter.
	f.write([]byte{'3', '\r'})
	f.write([]byte("\x1b[200~revise the API\nadd tests\x1b[201~"))

	select {
	case <-done:
		t.Fatalf("overlay submitted during paste: decision=%#v err=%v", decision, runErr)
	case <-time.After(100 * time.Millisecond):
	}

	// A separate, explicit Enter submits the feedback.
	f.write([]byte{'\r'})
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("overlay did not submit after explicit Enter")
	}
	if runErr != nil {
		t.Fatalf("overlay run failed: %v", runErr)
	}
	if !decision.Denied || decision.DenyReason != "revise the API\nadd tests" {
		t.Fatalf("unexpected denial decision: %#v", decision)
	}
}

