func TestApprovalOverlay_RunHoldsRendererMutexWhileAwaitingInput(t *testing.T) {
	req := turn.ToolApprovalRequest{
		ToolName:           "custom_tool",
		ToolInputJSON:      `{}`,
		PermissionToolName: "custom_tool",
		ExactRuleContent:   "custom_tool",
	}
	f := newFakeRawSelector(t)
	renderMu := &sync.Mutex{}
	f.rs.mu = renderMu
	out := newSignalWriter()
	overlay := newApprovalOverlay(context.Background(), out, f.rs, req, nil)
	done := make(chan error, 1)
	go func() {
		_, err := overlay.Run()
		done <- err
	}()

	select {
	case <-out.wrote:
	case <-time.After(time.Second):
		t.Fatal("approval overlay did not render")
	}
	if renderMu.TryLock() {
		renderMu.Unlock()
		t.Fatal("approval overlay should hold renderer mutex while waiting for input")
	}

	f.write([]byte{'\r'})
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("overlay run failed: %v", err)
		}
	case <-time.After(time.Second):
		t.Fatal("approval overlay did not finish")
	}
	if !renderMu.TryLock() {
		t.Fatal("approval overlay did not release renderer mutex after finishing")
	}
	renderMu.Unlock()
}

