// compactCheckpointFrame builds a finalized compact block whose body is a
// Markdown checkpoint long enough to fold.
func compactCheckpointFrame() Frame {
	return Frame{
		Kind: FrameMemoryCompact, Title: compactTitleDone, StepID: "compact-1", Final: true,
		Summary: "120k → 28k tokens (−76%) · 3s",
		Content: "# Context Checkpoint: Filter pip artifacts\n\n## Goal\n\n- item one\n- item two\n- item three\n\nTrailing **prose** about the checkpoint.\n",
	}
}

// A folded compact block promises "click to expand" on its truncation hint, so
// every row of the block — not just the header — must toggle it.
func TestCompactBlockTogglesOnAnyRow(t *testing.T) {
	vm := &viewModel{}
	vm.append(compactCheckpointFrame())
	vr := renderViewport(vm, 90, 40, 0, DiffThemeDark)
	if len(vr.lines) < 2 {
		t.Fatalf("compact block did not fold: %d lines", len(vr.lines))
	}
	hintRow := len(vr.lines) - 1
	if !strings.Contains(vr.lines[hintRow], "click to expand") {
		t.Fatalf("last folded row is not the truncation hint: %q", vr.lines[hintRow])
	}
	for row := range vr.lines {
		if !vr.isClickableRow(row, vm) {
			t.Errorf("row %d is not clickable", row)
		}
	}
	if !vm.toggleAtScreenRow(vr, hintRow) {
		t.Fatalf("clicking the truncation hint did not expand the block")
	}
	expanded := renderViewport(vm, 90, 60, 0, DiffThemeDark)
	if len(expanded.lines) <= len(vr.lines) {
		t.Fatalf("expanded block is not longer: %d <= %d", len(expanded.lines), len(vr.lines))
	}
	if !vm.toggleAtScreenRow(expanded, 0) {
		t.Fatalf("clicking the header did not collapse the block")
	}
}

// The compact body carries only the checkpoint, rendered as Markdown: no
// strategy/reason debug lines, and no literal "#"/list markup.
func TestCompactBlockRendersCheckpointAsMarkdown(t *testing.T) {
	vm := &viewModel{}
	f := compactCheckpointFrame()
	vm.append(f)
	if b := vm.blocks[0]; b != nil {
		b.expanded = true
	}
	lines := renderViewport(vm, 90, 60, 0, DiffThemeDark).lines
	body := strings.Join(lines, "\n")
	for _, banned := range []string{"strategy:", "model_context_window_pressure", "# Context Checkpoint"} {
		if strings.Contains(body, banned) {
			t.Errorf("compact body still contains %q:\n%s", banned, body)
		}
	}
	if !strings.Contains(body, "Context Checkpoint: Filter pip artifacts") {
		t.Errorf("checkpoint heading missing:\n%s", body)
	}
	if !strings.Contains(body, "item three") {
		t.Errorf("checkpoint body missing:\n%s", body)
	}
	// The banner belongs on the header line, next to the title.
	if !strings.Contains(lines[0], compactTitleDone+" · 120k → 28k tokens (−76%) · 3s") {
		t.Errorf("header lost the compact banner: %q", lines[0])
	}
}

// TestPaintCJKCaretColumn enables viewport mode + software cursor and verifies
// the painted caret CUP column matches the expected display column for each
// cursor position in CJK text. The composer prompt is "› " (2 cols), so for
// "我爱北京" (each CJK = 2 cols), the caret at logical cursor N must be painted
// at 1-based screen column 3 + 2*N.
func TestPaintCJKCaretColumn(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	text := "我爱北京"
	// rune -> cumulative display width: 我=2 爱=4 北=6 京=8
	for cursor := 0; cursor <= 4; cursor++ {
		t.Run(fmt.Sprintf("cursor=%d", cursor), func(t *testing.T) {
			var out bytes.Buffer
			r := NewRenderer(&out, &out)
			r.EnableViewportMode()
			t.Cleanup(r.DisableViewportMode)
			cur := cursor
			r.RenderComposerState(ComposerRenderState{Text: text, Cursor: &cur})
			r.EnableSoftwareCursor()
			out.Reset()
			r.mu.Lock()
			r.cursorBlinkVisible = true // force the on-phase so the block + CUP are emitted
			r.paintViewportLocked()
			paint := out.String()
			r.mu.Unlock()

			wantCol := 3 + 2*cursor // 1-based: prompt(2) + contentWidth
			wantRow := r.vpBodyHeight + r.vpLastComposer.cursorRow + 1
			wantCUP := fmt.Sprintf("\x1b[%d;%dH", wantRow, wantCol)
			if !strings.Contains(paint, wantCUP) {
				t.Fatalf("cursor=%d: painted caret CUP not found at expected %q.\nLayout cursorCol=%d (want %d). paint:\n%q",
					cursor, wantCUP, r.vpLastComposer.cursorCol, wantCol-1, paint)
			}
			t.Logf("cursor=%d: OK caret at col %d (1-based)", cursor, wantCol)
		})
	}
}

// TestSoftwareCursorBlockPreservesWideRune verifies the fix for the CJK caret
// corruption bug. When the caret sits in front of a wide (CJK) rune, the
// software cursor must re-emit that rune in reverse video (covering BOTH cells)
// rather than painting a single 1-cell reverse space that overwrites only the
// wide rune's first cell and leaves a dangling second cell — which made the
// caret visually drift by one CJK column.
func TestSoftwareCursorBlockPreservesWideRune(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	text := "我爱北京"
	// At cursor=2 the caret is between 爱 and 北; the cell at the caret is 北
	// (wide, 2 cells). The reverse block must contain 北, not a bare space.
	cursor := 2
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)
	r.RenderComposerState(ComposerRenderState{Text: text, Cursor: &cursor})
	r.EnableSoftwareCursor()
	paint := blinkCaretOn(t, r, &out)

	// The wide rune 北 must appear inside the reverse-video block.
	wantBlock := "\x1b[7m北\x1b[0m"
	if !strings.Contains(paint, wantBlock) {
		t.Fatalf("caret before wide rune 北 must re-emit 北 in reverse (%q), "+
			"not a 1-cell space that corrupts the wide char. paint:\n%q", wantBlock, paint)
	}
	// And it must NOT be the old bare-space block over 北's first cell.
	if strings.Contains(paint, "\x1b[7m \x1b[0m") {
		// A bare reverse space is only acceptable at end-of-line (cursor=4);
		// here (cursor=2) it indicates the wide-rune bug.
		t.Fatalf("caret before wide rune must not paint a 1-cell reverse space. paint:\n%q", paint)
	}
}

// TestSoftwareCursorBlockAfterAmbiguousWidthRune covers the composer half of
// the same caret arithmetic the pickers use. "·" is East Asian Ambiguous: the
// terminal draws it in one cell, so the caret behind "a·b" belongs in the cell
// right after "b". A width model that charged the rune two cells pushed the
// caret one column past the text and made it repaint the character it skipped.
func TestSoftwareCursorBlockAfterAmbiguousWidthRune(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	text := "a·b"
	cursor := 3 // end of line
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)
	r.RenderComposerState(ComposerRenderState{Text: text, Cursor: &cursor})
	r.EnableSoftwareCursor()
	paint := blinkCaretOn(t, r, &out)

	col, glyph := softwareCaretCellFromPaint(t, paint)
	// "› " + "a·b", all one cell each, and the CUP column is 1-based.
	wantCol := lipgloss.Width(composerPromptMarker) + lipgloss.Width(text) + 1
	if col != wantCol {
		t.Errorf("caret painted at column %d, want %d (paint: %q)", col, wantCol, paint)
	}
	if glyph != " " {
		t.Errorf("caret at end of line painted %q, want a blank cell (paint: %q)", glyph, paint)
	}
}

// softwareCaretCellFromPaint pulls the one cell the software caret painted out
// of a frame: the column it addressed and the glyph it put there.
func softwareCaretCellFromPaint(t *testing.T, paint string) (col int, glyph string) {
	t.Helper()
	re := regexp.MustCompile("\x1b\\[[0-9]+;([0-9]+)H((?:\x1b\\[[0-9;]*m)*)\x1b\\[7m(.)")
	m := re.FindStringSubmatch(paint)
	if m == nil {
		t.Fatalf("no software caret cell in paint %q", paint)
	}
	col, err := strconv.Atoi(m[1])
	if err != nil {
		t.Fatalf("caret column %q: %v", m[1], err)
	}
	return col, m[3]
}

// blinkCaretOn drives one full off->on cycle of the software caret and returns
// the bytes the on-phase paint emitted. The caret is a one-cell object, so a
// blink must produce only that cell: the assertion below is what keeps the
// blink from erasing and rewriting the line the user is typing on.
func blinkCaretOn(t *testing.T, r *Renderer, out *bytes.Buffer) string {
	t.Helper()
	r.mu.Lock()
	r.cursorBlinkVisible = false
	r.paintViewportLocked()
	out.Reset()
	r.cursorBlinkVisible = true
	r.paintViewportLocked()
	paint := out.String()
	r.mu.Unlock()
	if strings.Contains(paint, "\x1b[2K") {
		t.Fatalf("caret blink must repaint only the caret cell, never erase a screen row; got %q", paint)
	}
	return paint
}

// TestSoftwareCursorBlockEmptyCellAtEndOfLine verifies that at the end of the
// text (no rune to the right of the caret) the caret is still a 1-cell reverse
// space.
func TestSoftwareCursorBlockEmptyCellAtEndOfLine(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	text := "我爱北京"
	cursor := 4 // end of line
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)
	r.RenderComposerState(ComposerRenderState{Text: text, Cursor: &cursor})
	r.EnableSoftwareCursor()
	paint := blinkCaretOn(t, r, &out)

	if !strings.Contains(paint, "\x1b[7m \x1b[0m") {
		t.Fatalf("caret at end of line must paint a 1-cell reverse space. paint:\n%q", paint)
	}
}

// TestCellAtDisplayCol exercises the cell-extraction helper directly: it must
// return the glyph occupying a display column together with the styling in
// effect there, so the software caret can repaint that one cell exactly.
func TestCellAtDisplayCol(t *testing.T) {
	// "› 我爱北京" with ANSI styling around the prompt + content.
	line := composerPromptStyle + composerPromptMarker + sharedBlockTextStyle + "我爱北京" + sharedBlockTextStyle + "\x1b[K\x1b[0m"
	// display cols (0-based): ›=0, space=1, 我=2-3, 爱=4-5, 北=6-7, 京=8-9
	cases := []struct {
		col       int
		wantGlyph string
		wantStyle string
	}{
		{0, "›", composerPromptStyle},
		{1, " ", composerPromptStyle},
		{2, "我", composerPromptStyle + sharedBlockTextStyle},
		{4, "爱", composerPromptStyle + sharedBlockTextStyle},
		{6, "北", composerPromptStyle + sharedBlockTextStyle},
		{8, "京", composerPromptStyle + sharedBlockTextStyle},
		// Past the text: the cell was painted by the line's erase-to-end-of-line,
		// so it carries the styling that was active at that EL — the composer
		// card's background — rather than the reset the line ends with.
		{10, " ", composerPromptStyle + sharedBlockTextStyle + sharedBlockTextStyle},
		// The second cell of a wide rune starts no rune of its own.
		{3, " ", composerPromptStyle + sharedBlockTextStyle},
		{-1, " ", ""},
	}
	for _, c := range cases {
		gotStyle, gotGlyph := cellAtDisplayCol([]string{line}, 0, c.col)
		if gotGlyph != c.wantGlyph || gotStyle != c.wantStyle {
			t.Errorf("col=%d: got (%q,%q) want (%q,%q)", c.col, gotStyle, gotGlyph, c.wantStyle, c.wantGlyph)
		}
	}
	// Out-of-range row.
	if _, glyph := cellAtDisplayCol([]string{line}, 5, 0); glyph != " " {
		t.Errorf("out-of-range row should return a blank cell, got %q", glyph)
	}
}

type pasteCursorVariant struct {
	name      string
	setup     func(w *os.File)
	setupWait time.Duration
}

// TestReproPasteCJKCursorOffsetVariants tries several paste/type variants and
// reports exactly where the raw reader inserts 大 when the user believes the
// caret is "after 爱" (logical cursor 2). A correct implementation always
// produces "我爱大北京".
func TestReproPasteCJKCursorOffsetVariants(t *testing.T) {
	drainInteractiveInputSeedQueue()
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	variants := []pasteCursorVariant{
		{
			name:      "bracketed_paste",
			setup:     bracketedPaste("我爱北京"),
			setupWait: 120 * time.Millisecond,
		},
		{
			name:      "bracketed_paste_trailing_newline",
			setup:     bracketedPaste("我爱北京\n"),
			setupWait: 120 * time.Millisecond,
		},
		{
			name:      "fast_typed_burst",
			setup:     fastType("我爱北京"),
			setupWait: 120 * time.Millisecond,
		},
		{
			name:      "slow_typed_ime",
			setup:     slowType("我爱北京", 25*time.Millisecond),
			setupWait: 120 * time.Millisecond,
		},
	}

	left := []byte{0x1b, '[', 'D'}
	for _, v := range variants {
		t.Run(v.name, func(t *testing.T) {
			drainInteractiveInputSeedQueue()
			ctx, cancel := context.WithCancel(context.Background())
			defer cancel()
			r, w, err := os.Pipe()
			if err != nil {
				t.Fatalf("pipe: %v", err)
			}
			defer r.Close()

			session := newRTSession()
			state := &streamState{sessionID: "s1"}
			renderer := NewRenderer(io.Discard, io.Discard)

			var mu sync.Mutex
			events := readRawInputEvents(ctx, r, io.Discard, stubRawInputController{}, nil)
			go func() {
				for ev := range events {
					mu.Lock()
					handleActiveRunInput(ctx, session, renderer, nil, state, nil, ev, nil)
					mu.Unlock()
				}
			}()
			defer func() {
				cancel()
				_ = w.Close()
				for range events {
				}
			}()

			writeAll := func(b []byte) {
				if _, err := w.Write(b); err != nil {
					t.Fatalf("write: %v", err)
				}
			}

			v.setup(w)
			time.Sleep(v.setupWait)

			mu.Lock()
			draftAfter := state.composer.DraftText
			cursorAfter := state.composer.Cursor
			mu.Unlock()
			t.Logf("after setup: draft=%q cursor=%d", draftAfter, cursorAfter)

			// Move caret left until state.composer.Cursor == 2 (after 爱), but
			// also record the reader's cursor from each draft event to detect
			// divergence between paint cursor and insertion cursor.
			leftPresses := 0
			for {
				mu.Lock()
				c := state.composer.Cursor
				mu.Unlock()
				if c <= 2 {
					break
				}
				writeAll(left)
				leftPresses++
				time.Sleep(40 * time.Millisecond)
				if leftPresses > 10 {
					t.Fatalf("could not reach cursor 2 after %d left presses (cursor=%d)", leftPresses, c)
				}
			}
			t.Logf("reached cursor 2 after %d left presses", leftPresses)

			// Drain pending drafts so the insertion 大 is processed cleanly.
			time.Sleep(60 * time.Millisecond)

			writeAll([]byte("大"))
			// Single non-ASCII char is held as pasteBurst pendingFirstChar and
			// flushed after ~8ms idle, so wait long enough for the flush + the
			// draft round-trip through the handler.
			time.Sleep(150 * time.Millisecond)
			mu.Lock()
			stateDraft := state.composer.DraftText
			stateCursor := state.composer.Cursor
			mu.Unlock()
			t.Logf("after typing 大: stateDraft=%q stateCursor=%d", stateDraft, stateCursor)

			// 大 must be inserted at logical cursor 2 (right after 爱),
			// regardless of any trailing newline. A correct caret produces
			// "我爱大北京...".
			runes := []rune(stateDraft)
			wantPrefix := []rune("我爱大北京")
			if len(runes) < len(wantPrefix) || string(runes[:len(wantPrefix)]) != string(wantPrefix) {
				t.Errorf("INSERTION OFFSET: stateDraft=%q want prefix %q (leftPresses=%d)", stateDraft, string(wantPrefix), leftPresses)
			}
		})
	}
}

func bracketedPaste(content string) func(*os.File) {
	return func(w *os.File) {
		w.Write([]byte{0x1b, '[', '2', '0', '0', '~'})
		w.Write([]byte(content))
		w.Write([]byte{0x1b, '[', '2', '0', '1', '~'})
	}
}

func fastType(content string) func(*os.File) {
	return func(w *os.File) {
		w.Write([]byte(content))
	}
}

func slowType(content string, per time.Duration) func(*os.File) {
	return func(w *os.File) {
		for _, b := range []byte(content) {
			w.Write([]byte{b})
			time.Sleep(per)
		}
	}
}

func queuePreviewPlainLines(p ComposerPendingInputPreview, termWidth int) []string {
	out := make([]string, 0, 8)
	for _, line := range formatComposerPendingInputPreview(p, termWidth) {
		out = append(out, strings.ReplaceAll(stripANSI(line), "\x1b[K", ""))
	}
	return out
}

// Every queue action must be visible while a run is working, otherwise the
// queue is only operable by users who already memorised the keys.
func TestQueuePreviewShowsEveryQueueShortcut(t *testing.T) {
	cases := []struct {
		name    string
		preview ComposerPendingInputPreview
		want    []string
	}{
		{
			name:    "pending steer",
			preview: ComposerPendingInputPreview{PendingSteers: []string{"adjust the plan"}},
			want:    []string{"press esc to interrupt", "⇧+← recall last queued", "tab queue follow-up"},
		},
		{
			name:    "rejected steer",
			preview: ComposerPendingInputPreview{RejectedSteers: []string{"retry"}},
			want:    []string{"⇧+← recall last queued", "tab queue follow-up"},
		},
		{
			name:    "queued follow-up",
			preview: ComposerPendingInputPreview{QueuedMessages: []string{"then commit"}},
			want:    []string{"⇧+← recall last queued", "tab queue follow-up"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			rendered := strings.Join(queuePreviewPlainLines(tc.preview, 100), "\n")
			for _, want := range tc.want {
				if !strings.Contains(rendered, want) {
					t.Fatalf("missing shortcut hint %q in:\n%s", want, rendered)
				}
			}
		})
	}
}

// A rejected steer is a follow-up that missed the steer window. The user never
// chose that state and cannot act on it differently, so it shares the follow-up
// section rather than getting a header that names an internal failure mode.
func TestQueuePreviewMergesRejectedSteersIntoFollowUps(t *testing.T) {
	lines := queuePreviewPlainLines(ComposerPendingInputPreview{
		RejectedSteers: []string{"missed the window"},
		QueuedMessages: []string{"ordinary follow-up"},
	}, 100)
	rendered := strings.Join(lines, "\n")

	headers := 0
	for _, line := range lines {
		if strings.HasPrefix(strings.TrimSpace(line), "•") {
			headers++
		}
	}
	if headers != 1 {
		t.Fatalf("expected a single follow-up header, got %d:\n%s", headers, rendered)
	}
	if strings.Contains(rendered, "end of turn") {
		t.Fatalf("the rejected-steer header must be gone:\n%s", rendered)
	}
	for _, want := range []string{"missed the window", "ordinary follow-up"} {
		if !strings.Contains(rendered, want) {
			t.Fatalf("merged section dropped %q:\n%s", want, rendered)
		}
	}
	// Listed in the order they will run: rejected steers are submitted first.
	if strings.Index(rendered, "missed the window") > strings.Index(rendered, "ordinary follow-up") {
		t.Fatalf("merged section must list messages in execution order:\n%s", rendered)
	}
}

// An empty queue shows no preview at all, so it must not show shortcuts either.
func TestQueuePreviewShowsNoShortcutsWhenEmpty(t *testing.T) {
	if got := formatComposerPendingInputPreview(ComposerPendingInputPreview{}, 100); len(got) != 0 {
		t.Fatalf("expected no preview rows for an empty queue, got %#v", got)
	}
}

// The hints wrap instead of being cut mid-key, which would leave a shortcut
// unreadable ("⇧+…") and hide the very key it documents. 40 columns is the
// floor: below that the wrap itself lands inside a key name, but the composer is
// unusable at that size anyway.
func TestQueuePreviewShortcutsWrapInsteadOfTruncating(t *testing.T) {
	preview := ComposerPendingInputPreview{QueuedMessages: []string{"then commit"}}
	for _, width := range []int{120, 100, 80, 60, 40} {
		rows := composerPreviewShortcutLines(composerQueueShortcutHints(preview), "  ", width)
		if len(rows) == 0 {
			t.Fatalf("width %d: no shortcut rows rendered", width)
		}
		joined := strings.Join(rows, " ")
		for _, key := range []string{"⇧+←", "tab"} {
			if !strings.Contains(joined, key) {
				t.Fatalf("width %d: key %q was dropped:\n%s", width, key, strings.Join(rows, "\n"))
			}
		}
		for _, row := range rows {
			if strings.HasSuffix(row, "…") {
				t.Fatalf("width %d: row was truncated mid-hint: %q", width, row)
			}
			if got := displayLineWidth(row); got > width-1 {
				t.Fatalf("width %d: row overflows at %d columns: %q", width, got, row)
			}
		}
	}
}

// At a usable terminal width the whole block stays compact: the queue must not
// push the transcript off screen to document itself.
func TestQueuePreviewShortcutsStayCompactAtNormalWidths(t *testing.T) {
	preview := ComposerPendingInputPreview{QueuedMessages: []string{"then commit"}}
	for _, width := range []int{100, 120} {
		if rows := composerPreviewShortcutLines(composerQueueShortcutHints(preview), "  ", width); len(rows) != 1 {
			t.Fatalf("width %d: expected a single shortcut row, got %#v", width, rows)
		}
	}
}

// Packing is what keeps the block short: hints share a row until one no longer
// fits, so a wide terminal spends a single row on the whole set.
func TestComposerPreviewShortcutLinesPacksHintsPerRow(t *testing.T) {
	hints := []string{"aaaa", "bbbb", "cccc"}
	if got := composerPreviewShortcutLines(hints, "  ", 100); len(got) != 1 {
		t.Fatalf("expected one packed row at width 100, got %#v", got)
	}
	// Room for "aaaa · bbbb" (12 columns — the middle dot is ambiguous-width and
	// counts as 2) plus the 2-column indent and the reserved trailing column,
	// but not for a third hint.
	got := composerPreviewShortcutLines(hints, "  ", 15)
	if len(got) != 2 || got[0] != "  aaaa · bbbb" || got[1] != "  cccc" {
		t.Fatalf("expected the row to break between whole hints, got %#v", got)
	}
	if composerPreviewShortcutLines(nil, "  ", 100) != nil {
		t.Fatal("expected no rows for an empty hint list")
	}
}

const connectTestConfig = "sandbox_mode: %MODE%\n" +
	"agents:\n  definitions:\n    main:\n      primary: true\n      llm_providers:\n" +
	"        - provider: openai\n          model: %MODEL%\n" +
	"          api_key: ${OPENAI_API_KEY}\n          base_url: http://localhost:0/v1\n"

func writeConnectConfig(t *testing.T, path, mode, model string) {
	t.Helper()
	body := strings.ReplaceAll(connectTestConfig, "%MODE%", mode)
	body = strings.ReplaceAll(body, "%MODEL%", model)
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("write config: %v", err)
	}
}

// /connect saves the whole config document. Resolve() caches the file as it was
// when the process started, so writing that copy back would revert everything
// changed since — the sandbox picked with /sandbox, the model picked with
// /model — as a side effect of configuring one provider.
func TestConnectRuntimeContextReadsCurrentFileNotStartupCache(t *testing.T) {
	home := t.TempDir()
	t.Setenv("FOREBRAIN_HOME", home)
	t.Setenv("OPENAI_API_KEY", "test-key")
	cfgPath := filepath.Join(home, "forebrain.yaml")
	writeConnectConfig(t, cfgPath, "read-only", "gpt-startup")

	process.ResetResolve()
	t.Cleanup(process.ResetResolve)
	if _, err := process.Resolve(); err != nil {
		t.Fatalf("resolve: %v", err)
	}

	// Something else in the session rewrites the file, as /sandbox and /model do.
	writeConnectConfig(t, cfgPath, "danger-full-access", "gpt-chosen-in-session")

	rt, err := connectRuntimeContext()
	if err != nil {
		t.Fatalf("connectRuntimeContext: %v", err)
	}
	if got := rt.Config.SandboxMode; got != appcfg.SandboxModeDangerFullAccess {
		t.Fatalf("sandbox_mode = %q, want the value on disk; saving this back would revert it", got)
	}
	p := connectCurrentLLM(&rt.Config, "main")
	if p == nil || p.Model != "gpt-chosen-in-session" {
		t.Fatalf("model = %+v, want the value on disk", p)
	}
	// The persisted form keeps the reference, so saving cannot bake a resolved
	// secret into the file.
	if p.APIKey != "${OPENAI_API_KEY}" {
		t.Fatalf("api_key = %q, want the unexpanded reference", p.APIKey)
	}
}

// The prompt offers the active primary agent's current values as defaults, not
// main's, so a session running another agent is not shown someone else's setup.
func TestConnectCurrentValuesFollowTheNamedAgent(t *testing.T) {
	cfg := appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
		"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{{
			Provider: "openai", Model: "gpt-main", BaseURL: "https://main.example/v1", APIPath: "/chat",
		}}},
		"review": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{{
			Provider: "openai", Model: "gpt-review", BaseURL: "https://review.example/v1", APIPath: "/responses",
		}}},
	}}}

	if got := connectCurrentBaseURL(&cfg, "review"); got != "https://review.example/v1" {
		t.Fatalf("base url = %q, want review's", got)
	}
	if got := connectCurrentAPIPath(&cfg, "review"); got != "/responses" {
		t.Fatalf("api path = %q, want review's", got)
	}
	// An empty name still means main, which is what onboarding configures.
	if got := connectCurrentBaseURL(&cfg, ""); got != "https://main.example/v1" {
		t.Fatalf("base url = %q, want main's", got)
	}
}

func TestTrackerConcurrentAccess(t *testing.T) {
	tracker := NewTracker()

	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(2)
		go func() {
			defer wg.Done()
			tracker.ObserveTool("Read")
		}()
		go func() {
			defer wg.Done()
			_ = tracker.SnapshotSession()
		}()
	}
	wg.Wait()

	snap := tracker.SnapshotSession()
	if snap.Tools != 50 {
		t.Errorf("expected Tools=50, got %d", snap.Tools)
	}
}

func TestTrackerObserveToolStepDedupesByStepID(t *testing.T) {
	tracker := NewTracker()

	tracker.ObserveToolStep("", "call-1", "shell", "")
	tracker.ObserveToolStep("", "call-1", "shell", "")
	tracker.ObserveToolStep("", "call-2", "shell", "")
	tracker.ObserveToolStep("", "", "shell", "")
	tracker.ObserveToolStep("", "", "shell", "")

	snap := tracker.SnapshotSession()
	if snap.Tools != 4 {
		t.Fatalf("expected 4 logical tools, got %d", snap.Tools)
	}
}

