// TestTrackerPerRunCountersIsolateTurns verifies tools/agents/tokens are
// scoped to the active run, not accumulated session-wide, so the "Worked for"
// and "Working for" lines reflect only the current turn.
func TestTrackerPerRunCountersIsolateTurns(t *testing.T) {
	tracker := NewTracker()

	// Turn 1. Streaming deltas (emitted by OnUsage, or back-filled by
	// reportFinalIfNeeded for non-streaming providers) feed the per-run
	// counter; ObserveRunEndForRun no longer overwrites them.
	tracker.StartRun("run-1")
	tracker.ObserveToolStep("", "t1", "read_file", "")
	tracker.ObserveToolStep("", "t2", "read_file", "")
	tracker.ObserveAgent("agent-1", time.Time{})
	tracker.ObserveUsageDelta("run-1", 1000, 100)
	tracker.ObserveRunEndForRun("run-1", 1000, 100)

	r1 := tracker.SnapshotRun("run-1")
	if r1.Tools != 2 || r1.Agents != 1 || r1.InputTokens != 1000 || r1.OutputTokens != 100 {
		t.Fatalf("run-1 snapshot = %+v, want tools=2 agents=1 in=1000 out=100", r1)
	}

	// Turn 2 — different run.
	tracker.StartRun("run-2")
	tracker.ObserveToolStep("", "t3", "read_file", "")
	tracker.ObserveUsageDelta("run-2", 500, 50)
	tracker.ObserveRunEndForRun("run-2", 500, 50)

	r2 := tracker.SnapshotRun("run-2")
	if r2.Tools != 1 || r2.Agents != 0 || r2.InputTokens != 500 || r2.OutputTokens != 50 {
		t.Fatalf("run-2 snapshot = %+v, want tools=1 agents=0 in=500 out=50", r2)
	}

	// Session totals still aggregate across both turns.
	sess := tracker.SnapshotSession()
	if sess.Tools != 3 || sess.Agents != 1 || sess.InputTokens != 1500 || sess.OutputTokens != 150 {
		t.Fatalf("session snapshot = %+v, want tools=3 agents=1 in=1500 out=150", sess)
	}
}

// TestTrackerRunEndKeepsSessionCumulativeOnOvershoot verifies that when
// streaming usage deltas overshoot the run's authoritative final, the per-run
// counter KEEPS the streamed total (the "Worked for" line reuses the "Working"
// total verbatim) while the session total (composer footer) is NOT pulled down
// to the single-run final: the negative delta is clamped so the cross-turn
// cumulative stays monotonic. Pulling the footer or the per-run counter down to
// match each run's final collapsed it onto the latest turn - the bug where
// "after a turn finishes, Worked for becomes equal to the (lower) final".
func TestTrackerRunEndKeepsSessionCumulativeOnOvershoot(t *testing.T) {
	tracker := NewTracker()

	tracker.StartRun("run-1")
	// Streaming deltas accumulate the inflated live total (29k in / 510 out).
	tracker.ObserveUsageDelta("run-1", 29000, 510)
	// Authoritative final from the run Summary is lower (12k in / 224 out).
	tracker.ObserveRunEndForRun("run-1", 12000, 224)

	run := tracker.SnapshotRun("run-1")
	if run.InputTokens != 29000 || run.OutputTokens != 510 {
		t.Fatalf("run snapshot = %+v, want in=29000 out=510 (streamed total preserved, not overwritten by lower final)", run)
	}
	// The footer keeps the streamed accumulation; it must not collapse to the
	// single-run final.
	sess := tracker.SnapshotSession()
	if sess.InputTokens != 29000 || sess.OutputTokens != 510 {
		t.Fatalf("session = %+v, want in=29000 out=510 (cumulative, not pulled down to final)", sess)
	}
}

// TestTrackerSessionAccumulatesAcrossTurns verifies the composer footer
// (session total) is the sum of each turn's authoritative final across turns
// when streaming deltas match the final - the norm once external LLM calls no
// longer leak into the live stream. The footer must grow turn over turn, not
// reset to the latest run's final.
func TestTrackerSessionAccumulatesAcrossTurns(t *testing.T) {
	tracker := NewTracker()

	tracker.StartRun("run-1")
	tracker.ObserveUsageDelta("run-1", 12000, 224)
	tracker.ObserveRunEndForRun("run-1", 12000, 224)
	if sess := tracker.SnapshotSession(); sess.InputTokens != 12000 || sess.OutputTokens != 224 {
		t.Fatalf("after turn 1 session = %+v, want in=12000 out=224", sess)
	}

	tracker.StartRun("run-2")
	tracker.ObserveUsageDelta("run-2", 8000, 176)
	tracker.ObserveRunEndForRun("run-2", 8000, 176)
	if sess := tracker.SnapshotSession(); sess.InputTokens != 20000 || sess.OutputTokens != 400 {
		t.Fatalf("after turn 2 session = %+v, want in=20000 out=400 (cumulative)", sess)
	}
	if r2 := tracker.SnapshotRun("run-2"); r2.InputTokens != 8000 || r2.OutputTokens != 176 {
		t.Fatalf("run-2 = %+v, want in=8000 out=176", r2)
	}
}

// TestTrackerLiveSessionEqualsActiveRunSingleTurn verifies that mid-turn (before
// the run ends) the session totals equal the active-run totals: every streaming
// usage delta folds into both counters by the same amount. The composer footer
// (session) and the "Working" line (active run) read these two snapshots, so any
// inequality here would surface as a mismatch on the very first turn.
func TestTrackerLiveSessionEqualsActiveRunSingleTurn(t *testing.T) {
	tracker := NewTracker()
	tracker.StartRun("run-1")
	tracker.ObserveUsageDelta("run-1", 50000, 1000)
	tracker.ObserveUsageDelta("run-1", 47000, 1400)
	tracker.ObserveUsageDelta("run-1", 34000, 0)

	run := tracker.SnapshotActiveRun()
	sess := tracker.SnapshotSession()
	if run.InputTokens != sess.InputTokens || run.OutputTokens != sess.OutputTokens {
		t.Fatalf("live active-run %+v must equal session %+v", run, sess)
	}
	if sess.InputTokens != 131000 || sess.OutputTokens != 2400 {
		t.Fatalf("session = %+v, want in=131000 out=2400", sess)
	}
}

// TestTrackerEndRunFreesScratchMapsKeepsCounts verifies EndRun drops the per-run
// dedup scratch maps (bounding memory) while preserving the run's counts for the
// "Worked for" snapshot read after the run ends.
func TestTrackerEndRunFreesScratchMapsKeepsCounts(t *testing.T) {
	tracker := NewTracker()
	tracker.StartRun("run-1")
	tracker.ObserveToolStep("", "t1", "read_file", "")
	tracker.ObserveAgent("agent-1", time.Time{})
	tracker.ObserveUsageDelta("run-1", 1000, 100)
	tracker.ObserveRunEndForRun("run-1", 1000, 100)

	tracker.EndRun("run-1")

	tracker.mu.RLock()
	_, hasAgents := tracker.runAgentIDs["run-1"]
	tracker.mu.RUnlock()
	if hasAgents {
		t.Fatalf("EndRun should free scratch maps, got runAgentIDs=%v", hasAgents)
	}

	// Counts survive for the post-run "Worked for" snapshot.
	r := tracker.SnapshotRun("run-1")
	if r.Tools != 1 || r.Agents != 1 || r.InputTokens != 1000 {
		t.Fatalf("post-EndRun snapshot = %+v, want tools=1 agents=1 in=1000", r)
	}
}

// TestTrackerSubagentUsageCombinesIntoRunAndSession verifies subagent token
// usage is added on top of the parent run's own tokens in the per-run
// (Working/Worked line) and session (footer) snapshots, and — crucially —
// survives ObserveRunEndForRun, which reconciles the parent's runUsage entry
// down to its authoritative Summary.Usage that does NOT account for subagent
// LLM calls.
func TestTrackerSubagentUsageCombinesIntoRunAndSession(t *testing.T) {
	tracker := NewTracker()
	tracker.StartRun("run-1")

	// Parent streams its own usage; a subagent reports usage attributed to the
	// same parent run.
	tracker.ObserveUsageDelta("run-1", 1000, 200)
	tracker.ObserveSubagentUsage("run-1", "", 600, 150)

	live := tracker.SnapshotActiveRun()
	if live.InputTokens != 1600 || live.OutputTokens != 350 {
		t.Fatalf("live active-run = %+v, want in=1600 out=350 (parent+subagent)", live)
	}
	sess := tracker.SnapshotSession()
	if sess.InputTokens != 1600 || sess.OutputTokens != 350 {
		t.Fatalf("session = %+v, want in=1600 out=350 (parent+subagent)", sess)
	}

	// Parent run ends: authoritative final reconciles the PARENT's tokens only.
	// Subagent tokens must remain on top, not be wiped by reconciliation.
	tracker.ObserveRunEndForRun("run-1", 1000, 200)

	run := tracker.SnapshotRun("run-1")
	if run.InputTokens != 1600 || run.OutputTokens != 350 {
		t.Fatalf("post-RunEnd run = %+v, want in=1600 out=350 (subagent survives reconcile)", run)
	}
	sess = tracker.SnapshotSession()
	if sess.InputTokens != 1600 || sess.OutputTokens != 350 {
		t.Fatalf("post-RunEnd session = %+v, want in=1600 out=350", sess)
	}
}

