func deliveredSteerTranscript(t *testing.T, r *Renderer) []string {
	t.Helper()
	out := []string{}
	for _, block := range r.vm.blocks {
		if block.frame.Kind == FrameUser {
			out = append(out, block.frame.Content)
		}
	}
	return out
}

// A steer delivered to the model at a tool boundary must be rendered as a user
// transcript message ("you") so it does not silently vanish from the pending
// preview.
func TestRenderDeliveredSteerMessagesSkipsBlank(t *testing.T) {
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	renderDeliveredSteerMessages(renderer, []ComposerSubmission{{}, {Text: "   "}})
	if got := deliveredSteerTranscript(t, renderer); len(got) != 0 {
		t.Fatalf("expected no frame for blank delivered steers, got %#v", got)
	}
}

// An image-only steer has no text at all: it must still land in the transcript
// as its composer placeholder, otherwise the user sees the message leave the
// queue with nothing taking its place and assumes it was dropped.
func TestRenderDeliveredSteerMessagesRendersImageOnlySubmission(t *testing.T) {
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	renderDeliveredSteerMessages(renderer, []ComposerSubmission{{
		Parts:       []llm.ContentPart{{Type: llm.ContentTypeImageURL}},
		DisplayText: "[Image #1]",
		Attachments: []InputAttachment{{Path: "/tmp/shot.png"}},
	}})
	got := deliveredSteerTranscript(t, renderer)
	if len(got) != 1 || !strings.Contains(got[0], "[Image #1]") {
		t.Fatalf("expected image placeholder in transcript, got %#v", got)
	}
}

// Text and attachments together: the transcript shows the composer's display
// form (placeholders intact), not the model-facing text that has the image
// placeholder stripped and the large paste expanded.
func TestRenderDeliveredSteerMessagesRendersDisplayTextNotModelText(t *testing.T) {
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	renderDeliveredSteerMessages(renderer, []ComposerSubmission{{
		Text:        "look at this " + strings.Repeat("x", 40),
		DisplayText: "[Image #1] look at this [Pasted Content 40 chars]",
		Attachments: []InputAttachment{{Path: "/tmp/shot.png"}},
	}})
	got := deliveredSteerTranscript(t, renderer)
	if len(got) != 1 {
		t.Fatalf("expected one transcript card, got %#v", got)
	}
	if !strings.Contains(got[0], "[Image #1]") {
		t.Fatalf("expected image placeholder in transcript, got %q", got[0])
	}
	if !strings.Contains(got[0], "[Pasted Content 40 chars]") {
		t.Fatalf("expected paste placeholder in transcript, got %q", got[0])
	}
	if strings.Contains(got[0], strings.Repeat("x", 40)) {
		t.Fatalf("expected expanded paste to stay out of the transcript, got %q", got[0])
	}
}

// The mirror is what carries the display form, so reconciliation must hand the
// delivered submissions back rather than dropping them on the floor.
func TestReconcilePendingSteersCountReturnsDeliveredPrefix(t *testing.T) {
	state := &streamState{
		sessionID: "s1",
		pendingSteers: []ComposerSubmission{
			{Text: "A", DisplayText: "A"},
			{Text: "B", DisplayText: "B"},
			{Text: "C", DisplayText: "C"},
		},
	}

	delivered := state.reconcilePendingSteersCount(1)

	if len(delivered) != 2 || delivered[0].DisplayText != "A" || delivered[1].DisplayText != "B" {
		t.Fatalf("expected delivered prefix [A B], got %#v", delivered)
	}
	if len(state.pendingSteers) != 1 || state.pendingSteers[0].DisplayText != "C" {
		t.Fatalf("expected undelivered suffix [C], got %#v", state.pendingSteers)
	}
	// Popping is destructive so the other reconcile path cannot render a
	// second copy of the same steers.
	if again := state.reconcilePendingSteersCount(1); len(again) != 0 {
		t.Fatalf("expected no re-delivery on a second reconcile, got %#v", again)
	}
}

func TestDiffGutterWidthFor(t *testing.T) {
	hunks := []event.Hunk{{Lines: []event.DiffLine{
		{Kind: event.LineContext, OldNo: 9, NewNo: 9},
		{Kind: event.LineAdd, NewNo: 1234},
	}}}
	if got := diffGutterWidthFor(hunks); got != 4 {
		t.Fatalf("gutter width for max=1234 = %d, want 4", got)
	}
	if got := diffGutterWidthFor(nil); got != 3 {
		t.Fatalf("min gutter width = %d, want 3", got)
	}
}

func TestRenderClaudeDiffLine_AddBandPadding(t *testing.T) {
	t.Setenv("NO_COLOR", "")
	t.Setenv("COLORTERM", "truecolor")
	p := claudeDiffPaletteFor(DiffThemeDark)
	lexer, style := resolveDiffHighlight("x.go", p)
	rows := renderClaudeDiffLine(
		event.DiffLine{Kind: event.LineAdd, NewNo: 5, Text: "ok := true"},
		p, 3, 40, lexer, style,
	)
	if len(rows) != 1 {
		t.Fatalf("expected 1 row, got %d", len(rows))
	}
	row := rows[0]
	// One band encoding, never both: on a 24-bit terminal the row opens with
	// the 24-bit band alone.
	wantPrefix := "\x1b[48;2;18;77;31m"
	if !strings.HasPrefix(row, wantPrefix) {
		t.Fatalf("row should open with the add band SGR: %q", row)
	}
	if strings.Contains(row, "\x1b[48;5;") {
		t.Fatalf("24-bit terminal row also carried a 256-colour band: %q", row)
	}
	if !strings.HasSuffix(row, "\x1b[0m") {
		t.Fatalf("row should end with a reset: %q", row)
	}
	// Visible width is padded to bandW (40).
	if w := visualWidth(row); w != 40 {
		t.Fatalf("padded visible width = %d, want 40", w)
	}
}

func TestRenderClaudeDiffLine_NoColorPlain(t *testing.T) {
	t.Setenv("NO_COLOR", "1")
	p := claudeDiffPaletteFor(DiffThemeDark)
	lexer, style := resolveDiffHighlight("x.go", p)
	rows := renderClaudeDiffLine(
		event.DiffLine{Kind: event.LineDel, OldNo: 7, Text: "drop()"},
		p, 3, 40, lexer, style,
	)
	if len(rows) != 1 || strings.Contains(rows[0], "\x1b[") {
		t.Fatalf("NO_COLOR row must be plain: %q", rows[0])
	}
	if rows[0] != "  7 - drop()" {
		t.Fatalf("unexpected plain row: %q", rows[0])
	}
}

func visualWidth(s string) int {
	return len([]rune(stripANSI(s)))
}

func minimalDoc() event.DiffDoc {
	return event.Parse(`diff --git a/foo.go b/foo.go
index abc..def 100644
--- a/foo.go
+++ b/foo.go
@@ -1,3 +1,4 @@
 package main
-// old
+// new
+// added
 func main() {}`)
}

func TestRenderDiff_FileHeaderPresent(t *testing.T) {
	doc := minimalDoc()
	for _, theme := range []DiffTheme{DiffThemeDark, DiffThemeLight, DiffThemeUnknown} {
		out := RenderDiff(doc, theme)
		if !strings.Contains(out, "foo.go") {
			t.Errorf("theme %v: file name not in output:\n%s", theme, out)
		}
		if !strings.Contains(out, "+2") && !strings.Contains(out, "−1") {
			t.Errorf("theme %v: stats not in output:\n%s", theme, out)
		}
	}
}

func TestRenderDiff_AddDelPresent(t *testing.T) {
	doc := minimalDoc()
	for _, theme := range []DiffTheme{DiffThemeDark, DiffThemeLight, DiffThemeUnknown} {
		out := RenderDiff(doc, theme)
		if !strings.Contains(out, "// new") || !strings.Contains(out, "// old") {
			t.Errorf("theme %v: add/del text not in output:\n%s", theme, out)
		}
		if !strings.Contains(out, "+") || !strings.Contains(out, "-") {
			t.Errorf("theme %v: markers not in output:\n%s", theme, out)
		}
	}
}

// /diff is what the user asked to see: a long file is shown line by line,
// never summarised in place of its lines.
func TestRenderDiff_ShowsEveryLineOfALongFile(t *testing.T) {
	var sb strings.Builder
	sb.WriteString("diff --git a/big.go b/big.go\nindex a..b 100644\n--- a/big.go\n+++ b/big.go\n@@ -1,1 +1,60 @@\n")
	for i := 0; i < 55; i++ {
		fmt.Fprintf(&sb, "+added line %d\n", i)
	}
	out := stripAllANSI(RenderDiff(event.Parse(sb.String()), DiffThemeDark))
	for _, want := range []string{"added line 0", "added line 54"} {
		if !strings.Contains(out, want) {
			t.Fatalf("missing %q:\n%s", want, out)
		}
	}
	if strings.Contains(out, "collapsed") {
		t.Fatalf("a long file was collapsed:\n%s", out)
	}
}

// yamlDiffFixture mirrors the shape that showed the problem: a config file
// whose changed hunk is mostly comments, the token type every chroma style
// mutes hardest.
const yamlDiffFixture = `diff --git a/forebrain.yaml b/forebrain.yaml
index 1111111..2222222 100644
--- a/forebrain.yaml
+++ b/forebrain.yaml
@@ -1209,7 +1209,7 @@ memories:
 # Run the background pipeline that extracts and consolidates memories
 # from completed turns.
 generate_memories: true
-# Register the namespaced memory tools (memories/list, memories/read).
+# Register the dedicated memory tools (memories_list, memories_read).
 dedicated_tools: true
`

var diffTrueColorFG = regexp.MustCompile(`\x1b\[38;2;(\d+);(\d+);(\d+)m`)

func diffForegroundLuminances(t *testing.T, rendered string) []float64 {
	t.Helper()
	matches := diffTrueColorFG.FindAllStringSubmatch(rendered, -1)
	if len(matches) == 0 {
		t.Fatalf("no syntax colours emitted:\n%q", rendered)
	}
	lums := make([]float64, 0, len(matches))
	for _, m := range matches {
		var rgb [3]uint8
		for i := 0; i < 3; i++ {
			v, err := strconv.Atoi(m[i+1])
			if err != nil || v < 0 || v > 255 {
				t.Fatalf("bad colour component %q in %q", m[i+1], m[0])
			}
			rgb[i] = uint8(v)
		}
		lums = append(lums, relativeLuminance(rgb[0], rgb[1], rgb[2]))
	}
	return lums
}

// TestRenderDiffSyntaxColorsMatchProseBrightness pins the rule that the diff
// body reads at the brightness of the assistant text around it: chroma's muted
// comment/punctuation greys are lifted to the palette's target, and no part of
// the block uses ANSI dim.
func TestRenderDiffSyntaxColorsMatchProseBrightness(t *testing.T) {
	const tolerance = 0.02
	t.Setenv("NO_COLOR", "")
	t.Setenv("COLORTERM", "truecolor")

	dark := RenderDiff(event.Parse(yamlDiffFixture), DiffThemeDark)
	if strings.Contains(dark, "\x1b[2m") {
		t.Fatalf("diff used ANSI dim:\n%q", dark)
	}
	for _, lum := range diffForegroundLuminances(t, dark) {
		if lum < syntaxLuminanceDark-tolerance {
			t.Fatalf("dark diff colour at luminance %.3f is dimmer than the %.2f target", lum, syntaxLuminanceDark)
		}
	}

	light := RenderDiff(event.Parse(yamlDiffFixture), DiffThemeLight)
	for _, lum := range diffForegroundLuminances(t, light) {
		if lum > syntaxLuminanceLight+tolerance {
			t.Fatalf("light diff colour at luminance %.3f is lighter than the %.2f target", lum, syntaxLuminanceLight)
		}
	}
}

// TestNormalizeFGKeepsHueAndLeavesAccentsAlone checks the two halves of the
// normalisation: a muted colour is lifted to the target while keeping the hue
// the style chose, and a colour already at or past the target is returned
// byte-for-byte.
func TestNormalizeFGKeepsHueAndLeavesAccentsAlone(t *testing.T) {
	t.Setenv("NO_COLOR", "")
	p := claudeDiffPaletteFor(DiffThemeDark)

	// github-dark's comment grey, the colour that made the report's diff dim.
	r, g, b := p.fg.normalize(0x8b, 0x94, 0x9e)
	if got := relativeLuminance(r, g, b); got < syntaxLuminanceDark-0.02 {
		t.Fatalf("comment grey stayed at luminance %.3f, want >= %.2f", got, syntaxLuminanceDark)
	}
	if !(r < g && g < b) {
		t.Fatalf("normalisation lost the colour's hue order: #%02x%02x%02x", r, g, b)
	}

	// A colour already brighter than the target must be untouched.
	const wr, wg, wb = 0xe6, 0xed, 0xf3
	if r, g, b := p.fg.normalize(wr, wg, wb); r != wr || g != wg || b != wb {
		t.Fatalf("bright colour was altered: #%02x%02x%02x", r, g, b)
	}

	// The same rule inverts on a light background: bright colours are deepened.
	light := claudeDiffPaletteFor(DiffThemeLight)
	if r, g, b := light.fg.normalize(0xff, 0xd0, 0xd0); relativeLuminance(r, g, b) > syntaxLuminanceLight+0.02 {
		t.Fatalf("light theme kept a washed-out colour: #%02x%02x%02x", r, g, b)
	}
}

var ansi256FG = regexp.MustCompile(`\x1b\[38;5;(\d+)m`)

// syntaxRGBs returns the distinct 24-bit foreground colours a rendered string
// emits, in emission order.
func syntaxRGBs(t *testing.T, rendered string) [][3]uint8 {
	t.Helper()
	var out [][3]uint8
	for _, m := range diffTrueColorFG.FindAllStringSubmatch(rendered, -1) {
		var rgb [3]uint8
		for i := 0; i < 3; i++ {
			v, err := strconv.Atoi(m[i+1])
			if err != nil || v < 0 || v > 255 {
				t.Fatalf("bad colour component %q in %q", m[i+1], m[0])
			}
			rgb[i] = uint8(v)
		}
		dup := false
		for _, seen := range out {
			if seen == rgb {
				dup = true
				break
			}
		}
		if !dup {
			out = append(out, rgb)
		}
	}
	return out
}

// closestSyntaxColours returns the two colours of a palette that look most
// alike, as a plain RGB distance (0 = identical, 441 = opposite corners).
func closestSyntaxColours(colours [][3]uint8) (int, [3]uint8, [3]uint8) {
	best := -1
	var a, b [3]uint8
	for i := range colours {
		for j := i + 1; j < len(colours); j++ {
			d := 0
			for k := 0; k < 3; k++ {
				delta := int(colours[i][k]) - int(colours[j][k])
				d += delta * delta
			}
			if best < 0 || d < best {
				best, a, b = d, colours[i], colours[j]
			}
		}
	}
	return int(math.Sqrt(float64(best))), a, b
}

// TestPlainCodeHighlightKeepsTokenClassesApart is the regression guard for the
// read_file card whose code read as one pale tone: the diff's brightness lift was
// applied to code painted straight onto the terminal background, which pulled
// every token to a single luminance — the comment and the whitespace around it
// came out one RGB step apart — and left plain text brighter than every
// highlighted token. Code on a plain background keeps its theme's own
// emphasis; it is only held above the legibility floor.
func TestPlainCodeHighlightKeepsTokenClassesApart(t *testing.T) {
	const minDistance = 60
	t.Setenv("NO_COLOR", "")
	t.Setenv("COLORTERM", "truecolor")

	const goBody = "1|// parked reports whether the call is awaiting approval\n" +
		"2|func parked(f Frame) bool {\n" +
		"3|\treturn f.Status == \"awaiting approval\" && f.Lines > 0\n" +
		"4|}"

	// The surfaces the user reads: a read_file card and a fenced block in a
	// message. Both are painted on the terminal's own background.
	surfaces := map[string]string{
		"read_file":  formatHighlightedToolOutput(goBody, "render.go", DiffThemeDark),
		"code block": renderMarkdownCodeBlock("go", "// comment\nfunc main() {\n\treturn \"awaiting approval\"\n}", 60, DiffThemeDark),
	}
	for name, rendered := range surfaces {
		colours := syntaxRGBs(t, rendered)
		if len(colours) < 4 {
			t.Fatalf("%s emitted %d distinct syntax colours, want the theme's classes:\n%q", name, len(colours), rendered)
		}
		dist, a, b := closestSyntaxColours(colours)
		if dist < minDistance {
			t.Fatalf("%s: #%02x%02x%02x and #%02x%02x%02x are only %d apart, want >= %d",
				name, a[0], a[1], a[2], b[0], b[1], b[2], dist, minDistance)
		}
		for _, c := range colours {
			if lum := relativeLuminance(c[0], c[1], c[2]); lum < plainLuminanceDark-0.02 {
				t.Fatalf("%s emitted #%02x%02x%02x at luminance %.3f, below the %.2f legibility floor",
					name, c[0], c[1], c[2], lum, plainLuminanceDark)
			}
		}
	}

	// Every code surface carries the same mainstream theme.
	if got := resolveCodeStyle(DiffThemeDark); got == nil || got.Name != codeStyleDark {
		t.Fatalf("dark plain code style = %v, want %q", got, codeStyleDark)
	}
	if got := resolveCodeStyle(DiffThemeLight); got == nil || got.Name != codeStyleLight {
		t.Fatalf("light plain code style = %v, want %q", got, codeStyleLight)
	}

	// Code over a diff's add/del band keeps the band policy: the band raises the
	// background under the text, so every token is still held at the target.
	dark := RenderDiff(event.Parse(yamlDiffFixture), DiffThemeDark)
	for _, lum := range diffForegroundLuminances(t, dark) {
		if lum < syntaxLuminanceDark-0.02 {
			t.Fatalf("dark diff colour at luminance %.3f is dimmer than the %.2f target", lum, syntaxLuminanceDark)
		}
	}
}

// TestSyntaxColorsNeverEmitTrueColorToA256Terminal is the regression guard for
// the bug this pattern caused: a terminal without 24-bit support (Apple
// Terminal, say) does not ignore "\x1b[38;2;r;g;bm" — it reads the parameters
// one at a time and the "2" lands as SGR 2, faint. Emitting the 24-bit form as
// a "fallback" therefore rendered every syntax-coloured span at half
// brightness, on exactly the terminals that could least afford it.
func TestSyntaxColorsNeverEmitTrueColorToA256Terminal(t *testing.T) {
	t.Setenv("NO_COLOR", "")
	t.Setenv("COLORTERM", "")
	t.Setenv("TERM", "xterm-256color")

	surfaces := map[string]string{
		"diff":       RenderDiff(event.Parse(yamlDiffFixture), DiffThemeDark),
		"code block": renderMarkdownCodeBlock("go", "// comment\nfunc main() {}", 60, DiffThemeDark),
		"read_file":  formatHighlightedToolOutput("1|// comment\n2|func main() {}", "main.go", DiffThemeDark),
	}
	for name, rendered := range surfaces {
		if strings.Contains(rendered, "\x1b[38;2;") || strings.Contains(rendered, "\x1b[48;2;") {
			t.Fatalf("%s sent 24-bit colour to a 256-colour terminal, which renders it faint:\n%q", name, rendered)
		}
		if strings.Contains(rendered, "\x1b[2m") {
			t.Fatalf("%s used ANSI dim:\n%q", name, rendered)
		}
	}

	// The brightness floor has to survive quantisation: the palette's steps are
	// coarse, and plain nearest-colour matching rounds back down a step.
	matches := ansi256FG.FindAllStringSubmatch(surfaces["diff"], -1)
	if len(matches) == 0 {
		t.Fatalf("no 256-colour syntax codes emitted:\n%q", surfaces["diff"])
	}
	checked := 0
	for _, m := range matches {
		idx, err := strconv.Atoi(m[1])
		if err != nil || idx < 16 || idx > 255 {
			t.Fatalf("bad palette index %q", m[1])
		}
		entry := xterm256Palette()[idx-16]
		if entry.lum < syntaxLuminanceDark-0.02 {
			// The gutter and +/- markers are chrome with their own colours;
			// only syntax colours carry the floor.
			if idx == 78 || idx == 217 || idx == 252 {
				continue
			}
			t.Fatalf("256-colour index %d sits at luminance %.3f, below the %.2f floor", idx, entry.lum, syntaxLuminanceDark)
		}
		checked++
	}
	if checked == 0 {
		t.Fatalf("no syntax colours were checked:\n%q", surfaces["diff"])
	}
}

// TestTerminalTrueColorReadsTheEnvironment covers the detection itself: only an
// explicit 24-bit claim counts, because guessing wrong in that direction is the
// failure that dims the whole diff.
func TestTerminalTrueColorReadsTheEnvironment(t *testing.T) {
	for _, tc := range []struct {
		colorterm, term string
		want            bool
	}{
		{"truecolor", "xterm-256color", true},
		{"24bit", "xterm-256color", true},
		{"", "xterm-direct", true},
		{"", "xterm-256color", false},
		{"", "", false},
		{"256", "screen-256color", false},
	} {
		t.Setenv("COLORTERM", tc.colorterm)
		t.Setenv("TERM", tc.term)
		if got := terminalTrueColor(); got != tc.want {
			t.Fatalf("COLORTERM=%q TERM=%q: terminalTrueColor() = %v, want %v", tc.colorterm, tc.term, got, tc.want)
		}
	}
}

