func TestApprovalConfirmationTextExitPlanApproval(t *testing.T) {
	for _, toolName := range []string{"exit_plan_mode", "ExitPlanMode"} {
		t.Run(toolName, func(t *testing.T) {
			for _, decision := range []turn.ToolApprovalDecision{
				{Approved: true},
				{Approved: true, Update: &safety.PermissionUpdate{
					Type: safety.UpdateSetMode,
					Mode: safety.ModeOnRequest,
				}},
			} {
				msg, approved := approvalConfirmationText(turn.ToolApprovalRequest{
					ToolName:           toolName,
					PermissionToolName: toolName,
				}, decision)
				if !approved {
					t.Fatal("approved plan exit must be reported as approved")
				}
				if want := "You approved forebrain to exit plan mode"; msg != want {
					t.Fatalf("confirmation = %q, want %q", msg, want)
				}
			}
		})
	}
}

func TestApprovalConfirmationTextExitPlanDenial(t *testing.T) {
	for _, toolName := range []string{"exit_plan_mode", "ExitPlanMode"} {
		t.Run(toolName, func(t *testing.T) {
			for _, reason := range []string{"", "Please revise the validation section."} {
				msg, approved := approvalConfirmationText(turn.ToolApprovalRequest{
					ToolName:           toolName,
					PermissionToolName: toolName,
				}, turn.ToolApprovalDecision{Denied: true, DenyReason: reason})
				if approved {
					t.Fatal("denied plan exit must not be reported as approved")
				}
				if want := "You did not approve forebrain to exit plan mode"; msg != want {
					t.Fatalf("confirmation = %q, want %q", msg, want)
				}
				if strings.Contains(msg, reason) && reason != "" {
					t.Fatalf("confirmation must not repeat feedback: %q", msg)
				}
			}
		})
	}

	msg, approved := approvalConfirmationText(turn.ToolApprovalRequest{ToolName: "shell", PermissionInput: "git status"}, turn.ToolApprovalDecision{Denied: true})
	if approved || msg != "You did not approve forebrain to run git status" {
		t.Fatalf("ordinary denial changed: approved=%t msg=%q", approved, msg)
	}
}

