func TestApprovalConfirmationTextEnterPlanApproval(t *testing.T) {
	for _, toolName := range []string{"enter_plan_mode", "EnterPlanMode"} {
		t.Run(toolName, func(t *testing.T) {
			msg, approved := approvalConfirmationText(turn.ToolApprovalRequest{
				ToolName:           toolName,
				PermissionToolName: toolName,
				PermissionInput:    `{"reason":"Need an implementation plan."}`,
			}, turn.ToolApprovalDecision{Approved: true})
			if !approved {
				t.Fatal("approved plan entry must be reported as approved")
			}
			if want := "You approved forebrain to enter plan mode"; msg != want {
				t.Fatalf("confirmation = %q, want %q", msg, want)
			}
		})
	}
}

func TestApprovalConfirmationTextEnterPlanDenial(t *testing.T) {
	for _, toolName := range []string{"enter_plan_mode", "EnterPlanMode"} {
		t.Run(toolName, func(t *testing.T) {
			for _, reason := range []string{"", "Use a smaller scope."} {
				msg, approved := approvalConfirmationText(turn.ToolApprovalRequest{
					ToolName:           toolName,
					PermissionToolName: toolName,
					PermissionInput:    `{"reason":"Need an implementation plan."}`,
				}, turn.ToolApprovalDecision{Denied: true, DenyReason: reason})
				if approved {
					t.Fatal("denied plan entry must not be reported as approved")
				}
				if want := "You did not approve forebrain to enter plan mode"; msg != want {
					t.Fatalf("confirmation = %q, want %q", msg, want)
				}
				if reason != "" && strings.Contains(msg, reason) {
					t.Fatalf("confirmation must not repeat feedback: %q", msg)
				}
			}
		})
	}
}

func TestExitPlanModeDeniedToolFrameReplacesPendingCard(t *testing.T) {
	var reducer Reducer
	pending := reducer.Reduce(NewMessageMsg{Msg: Message{
		Kind:      MsgKindTool,
		StepID:    "exit-call-1",
		ToolName:  "exit_plan_mode",
		ToolMeta:  tool.ToolMeta{ToolName: "exit_plan_mode", Status: "awaiting approval"},
		Timestamp: time.Now(),
	}}).Frames
	if len(pending) != 1 || !strings.Contains(ToolDisplayHeader(pending[0], ""), "Exiting plan mode") {
		t.Fatalf("pending = %#v", pending)
	}

	denied := reducer.Reduce(NewMessageMsg{Msg: Message{
		Kind:      MsgKindTool,
		StepID:    "exit-call-1",
		ToolName:  "exit_plan_mode",
		Content:   "Please split the plan into milestones.",
		ToolMeta:  tool.ToolMeta{ToolName: "exit_plan_mode", Status: "denied"},
		ToolPhase: "tool_call_completed",
		Timestamp: time.Now(),
	}}).Frames
	if len(denied) != 1 || !strings.Contains(ToolDisplayHeader(denied[0], ""), "Kept planning") {
		t.Fatalf("denied = %#v", denied)
	}
	if got := summaryToolBody(denied[0], "exit_plan_mode"); got != "Please split the plan into milestones." {
		t.Fatalf("denied body = %q", got)
	}
	if toolStatusPending(denied[0]) || !toolStatusDenied(denied[0]) {
		t.Fatalf("denied status not terminal: %#v", denied[0].ToolMeta)
	}
	if denied[0].Duration != 0 {
		t.Fatalf("Kept planning must not carry executor duration: %#v", denied[0])
	}

	empty := denied[0]
	empty.Content = ""
	if got := summaryToolBody(empty, "exit_plan_mode"); got != "" {
		t.Fatalf("empty denial body = %q", got)
	}
}

func TestAllowedRootDeniedReadFrameReplacesPendingCard(t *testing.T) {
	var reducer Reducer
	pending := reducer.Reduce(NewMessageMsg{Msg: Message{
		Kind:     MsgKindTool,
		StepID:   "read-call-1",
		ToolName: "read_file",
		ToolMeta: tool.ToolMeta{
			ToolName: "read_file",
			Status:   "awaiting approval",
			Input:    map[string]any{"file_path": "/outside/note.txt", "offset": float64(0), "limit": float64(20)},
		},
		Timestamp: time.Now(),
	}}).Frames
	if len(pending) != 1 || !toolStatusPending(pending[0]) {
		t.Fatalf("pending = %#v", pending)
	}
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	renderer.EnableViewportMode()
	t.Cleanup(renderer.DisableViewportMode)
	renderer.RenderFrame(pending[0])
	if len(renderer.vm.blocks) != 1 || !toolStatusPending(renderer.vm.blocks[0].frame) {
		t.Fatalf("pending viewport blocks = %#v", renderer.vm.blocks)
	}

	canceled := reducer.Reduce(NewMessageMsg{Msg: Message{
		Kind:      MsgKindTool,
		StepID:    "read-call-1",
		ToolName:  "read_file",
		FilePath:  "/outside/note.txt",
		ToolMeta:  tool.ToolMeta{ToolName: "read_file", Status: "canceled", Input: pending[0].ToolMeta.Input},
		ToolPhase: "tool_call_completed",
		Timestamp: time.Now(),
	}}).Frames
	if len(canceled) != 1 || canceled[0].StepID != pending[0].StepID {
		t.Fatalf("canceled = %#v", canceled)
	}
	if toolStatusPending(canceled[0]) || !toolStatusCanceled(canceled[0]) {
		t.Fatalf("canceled status not terminal: %#v", canceled[0].ToolMeta)
	}
	if canceled[0].Duration != 0 || canceled[0].FilePath != "/outside/note.txt" {
		t.Fatalf("canceled frame metadata = %#v", canceled[0])
	}
	if header := ToolDisplayHeader(canceled[0], ""); !strings.Contains(header, "Canceled") || !strings.Contains(header, "/outside/note.txt") {
		t.Fatalf("canceled header = %q", header)
	}
	renderer.RenderFrame(canceled[0])
	if len(renderer.vm.blocks) != 1 {
		t.Fatalf("same-step completion appended instead of replacing: %#v", renderer.vm.blocks)
	}
	if toolStatusPending(renderer.vm.blocks[0].frame) || !toolStatusCanceled(renderer.vm.blocks[0].frame) {
		t.Fatalf("viewport block did not become terminal: %#v", renderer.vm.blocks[0].frame)
	}
}

func exitPlanReviewRequest(t *testing.T, plan string) turn.ToolApprovalRequest {
	t.Helper()
	planFile := filepath.Join(t.TempDir(), "implementation.md")
	if err := os.WriteFile(planFile, []byte(plan), 0o600); err != nil {
		t.Fatal(err)
	}
	return turn.ToolApprovalRequest{
		ToolName:           "exit_plan_mode",
		PermissionToolName: "exit_plan_mode",
		PlanFilePath:       planFile,
		PlanReviewModels: []turn.PlanReviewModelOption{
			{Provider: "anthropic", Model: "claude-opus-4-1", Label: "Claude Opus 4.1", Current: true},
			{Provider: "openai", Model: "gpt-5.1"},
		},
	}
}

func TestExitPlanChoicesOfferReviewOnlyWhenModelsAreConfigured(t *testing.T) {
	withModels := buildExitPlanChoices(exitPlanReviewRequest(t, "# Plan\n"), 0)
	if len(withModels) != 4 {
		t.Fatalf("choices=%d want 4", len(withModels))
	}
	if got := withModels[3].label; got != "Ask another model to review this plan" {
		t.Fatalf("review label=%q", got)
	}
	if !withModels[3].isPlanReview || withModels[3].allowOnce || withModels[3].denyOnce || withModels[3].cancel {
		t.Fatalf("review choice must decide nothing: %#v", withModels[3])
	}
	// The three verdicts keep their positions so the number keys do not move.
	if withModels[0].label != "Yes, clear context and proceed" || withModels[1].label != "Yes, proceed" ||
		withModels[2].label != "No, keep planning" {
		t.Fatalf("verdict rows moved: %#v", withModels[:3])
	}
	if denyChoiceIndex(withModels) != 2 {
		t.Fatalf("n must still select keep planning, got index %d", denyChoiceIndex(withModels))
	}

	withoutModels := buildExitPlanChoices(turn.ToolApprovalRequest{
		ToolName: "exit_plan_mode", PermissionToolName: "exit_plan_mode",
	}, 0)
	if len(withoutModels) != 3 {
		t.Fatalf("choices without configured models=%d want 3", len(withoutModels))
	}
	if planReviewChoiceIndex(withoutModels) >= 0 {
		t.Fatal("a session with no configured reviewer must not offer the review row")
	}
}

func TestExitPlanOverlayPicksReviewerWithoutDecidingApproval(t *testing.T) {
	req := exitPlanReviewRequest(t, "# Plan\n")
	// "4" selects the review row, Enter opens the picker, "2" picks the model
	// that is not the current one, Enter requests the review.
	decision, err := runOverlayWithKeys(t, req, []byte{'4', '\r', '2', '\r'})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if decision.Approved || decision.Denied || decision.Cancelled {
		t.Fatalf("requesting a review must not decide the approval: %#v", decision)
	}
	if decision.RequestPlanReview == nil {
		t.Fatal("expected a plan review request")
	}
	if got := *decision.RequestPlanReview; got.Provider != "openai" || got.Model != "gpt-5.1" {
		t.Fatalf("selected reviewer=%#v", got)
	}
}

