func TestExitPlanOverlayEscapeLeavesPickerWithApprovalIntact(t *testing.T) {
	req := exitPlanReviewRequest(t, "# Plan\n")
	f := newFakeRawSelector(t)
	overlay := newApprovalOverlay(context.Background(), io.Discard, f.rs, req, nil)
	done := make(chan struct{})
	var decision turn.ToolApprovalDecision
	var runErr error
	go func() {
		decision, runErr = overlay.Run()
		close(done)
	}()

	// Each write is spaced out because a bare Esc is only recognised as one
	// when no byte follows it within the escape-sequence window.
	f.write([]byte{'m'})
	time.Sleep(120 * time.Millisecond)
	f.write([]byte{0x1b})
	time.Sleep(120 * time.Millisecond)
	// Back on the choice list: pick "Yes, proceed" and commit.
	f.write([]byte{'2', '\r'})

	select {
	case <-done:
	case <-time.After(2 * time.Second):
		t.Fatal("overlay did not return after leaving the reviewer picker")
	}
	if runErr != nil {
		t.Fatalf("overlay run failed: %v", runErr)
	}
	if decision.RequestPlanReview != nil {
		t.Fatalf("escaping the picker must not request a review: %#v", decision)
	}
	if !decision.Approved || decision.ClearContext {
		t.Fatalf("expected plain approval after leaving the picker: %#v", decision)
	}
}

