// TestMCPRealisticCodegraphOutput mirrors the real codegraph_explore payload
// (a JSON envelope whose text block is Markdown with bold section headers,
// bullet lists, and a fenced code block). It verifies:
//   - the raw JSON is unwrapped (no "content":[ or "type":"text" leaks),
//   - the bold section headers survive rendering (not stripped as metadata),
//   - the long body collapses to a click-to-expand preview by default,
//   - expanding reveals the full body.
func TestMCPRealisticCodegraphOutput(t *testing.T) {
	forcedTermWidth = 160
	forcedTermHeight = 60
	t.Cleanup(func() { forcedTermWidth = 0; forcedTermHeight = 0 })

	text := strings.Join([]string{
		"**Exploration: sample query**",
		"",
		"Found 23 symbols across 3 files.",
		"",
		"**Blast radius — what depends on these**",
		"",
		"- `Select` (internal/tui/raw_selector.go:564) — 2 callers",
		"- `Options` (internal/tui/types.go:195) — 1 caller",
		"",
		"**Relationships**",
		"",
		"**calls:**",
		"- Select → acquireComposerInput",
		"- Select → pickerMaxVisible",
	}, "\n")

	// Build the JSON envelope exactly like the MCP transport does.
	envelope := `{"content":[{"type":"text","text":` + jsonQuote(text) + `}]}`

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	r.RenderFrame(Frame{
		Kind:    FrameTool,
		Title:   "mcp__codegraph__codegraph_explore",
		Content: envelope,
		Final:   true,
		ToolMeta: tool.ToolMeta{
			Status: "completed",
			Input:  map[string]any{"query": "sample query"},
		},
	})

	// --- Collapsed (default) view: preview + click-to-expand hint ---
	collapsed := renderViewport(&r.vm, 160, 40, 0, DiffThemeDark)
	collapsedPlain := stripANSI(strings.Join(collapsed.lines, "\n"))

	if strings.Contains(collapsedPlain, `"content":[`) || strings.Contains(collapsedPlain, `"type":"text"`) {
		t.Fatalf("collapsed view must not leak raw JSON:\n%s", collapsedPlain)
	}
	if !strings.Contains(collapsedPlain, "more lines (click to expand)") {
		t.Fatalf("long MCP output should collapse with a click-to-expand hint:\n%s", collapsedPlain)
	}
	// First rendered body line is the first section header.
	if !strings.Contains(collapsedPlain, "Exploration: sample query") {
		t.Fatalf("collapsed preview should show the first bold header:\n%s", collapsedPlain)
	}

	// --- Expanded view: full body, all headers preserved ---
	for i := range r.vm.blocks {
		r.vm.blocks[i].expanded = true
	}
	expanded := renderViewport(&r.vm, 160, 80, 0, DiffThemeDark)
	expandedPlain := stripANSI(strings.Join(expanded.lines, "\n"))

	for _, header := range []string{
		"Exploration: sample query",
		"Blast radius",
		"Relationships",
		"calls:",
	} {
		if !strings.Contains(expandedPlain, header) {
			t.Errorf("expanded view should preserve bold header %q, got:\n%s", header, expandedPlain)
		}
	}
	if !strings.Contains(expandedPlain, "Found 23 symbols across 3 files.") {
		t.Errorf("expanded view should render body text:\n%s", expandedPlain)
	}
	if strings.Contains(expandedPlain, `"content":[`) || strings.Contains(expandedPlain, `\"type\"`) {
		t.Errorf("expanded view must not leak raw JSON:\n%s", expandedPlain)
	}
}

// jsonQuote returns the JSON string literal (with surrounding quotes) for s.
func jsonQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\t':
			b.WriteString(`\t`)
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func TestMCPToolExtractsAllContentArrayItems(t *testing.T) {
	// Simulate the actual codegraph MCP tool output structure
	mcpOutput := `{"content":[{"type":"text","text":"**First Section**\n\nFirst paragraph."},{"type":"text","text":"**Second Section**\n\nSecond paragraph."}]}`

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()

	r.RenderFrame(Frame{
		Kind:    FrameTool,
		Title:   "mcp__codegraph__codegraph_explore",
		Content: mcpOutput,
		Final:   true,
		ToolMeta: tool.ToolMeta{
			Status: "completed",
			Input:  map[string]any{"query": "test"},
		},
	})

	// Expand the block so all content items are visible (long output is
	// collapsed to a 3-row preview by default via click-to-expand).
	for i := range r.vm.blocks {
		r.vm.blocks[i].expanded = true
	}
	vr := renderViewport(&r.vm, 120, 60, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(vr.lines, "\n"))

	// Should extract and render both text blocks as markdown.
	if !strings.Contains(plain, "First Section") {
		t.Errorf("Should extract first content item text, got:\n%s", plain)
	}
	if !strings.Contains(plain, "Second Section") {
		t.Errorf("Should extract second content item text, got:\n%s", plain)
	}
	if !strings.Contains(plain, "First paragraph") {
		t.Errorf("Should render markdown from first item, got:\n%s", plain)
	}
	if !strings.Contains(plain, "Second paragraph") {
		t.Errorf("Should render markdown from second item, got:\n%s", plain)
	}

	// Should NOT show raw JSON
	if strings.Contains(plain, `"content":[`) {
		t.Errorf("Should not show raw JSON structure, got:\n%s", plain)
	}
	if strings.Contains(plain, `"type":"text"`) {
		t.Errorf("Should not show JSON type field, got:\n%s", plain)
	}
}

