func TestMCPToolLongOutputCollapsesTo3Lines(t *testing.T) {
	// Create output with many lines
	longText := "**Header**\n\nLine 1\n\nLine 2\n\nLine 3\n\nLine 4\n\nLine 5\n\nLine 6"
	mcpOutput := `{"content":[{"type":"text","text":"` + longText + `"}]}`

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()

	r.RenderFrame(Frame{
		Kind:    FrameTool,
		Title:   "mcp__test__long_output",
		Content: mcpOutput,
		Final:   true,
		ToolMeta: tool.ToolMeta{
			Status: "completed",
		},
	})

	// Render the viewport to get the collapsed view
	vr := renderViewport(&r.vm, 80, 20, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(vr.lines, "\n"))

	// Should show truncation hint for long output
	if !strings.Contains(plain, "more lines (click to expand)") && !strings.Contains(plain, "… +") {
		// The specific truncation message may vary, but there should be some indication
		// Let's check if not all lines are visible
		lineCount := strings.Count(plain, "Line ")
		if lineCount >= 6 {
			t.Errorf("Long output should be collapsed, showing all %d lines:\n%s", lineCount, plain)
		}
	}
}

func TestMCPOutputSectionTextExtractsMultipleContentItems(t *testing.T) {
	// Test the mcpOutputSectionText function directly
	content := `output:\n\n` + "```" + `json\n{\n  \"output\": \"{\\"content\\":[{\\"type\\":\\"text\\",\\"text\\":\\"**Exploration\\"}]}\"\n}\n` + "```" + ``
	result := mcpOutputSectionText(content)

	if !strings.Contains(result, "**Exploration") {
		t.Errorf("Should extract first text, got: %s", result)
	}
}

func TestMCPOutputSectionTextExtractsMultipleContentItems2(t *testing.T) {
	// Test the mcpOutputSectionText function directly
	content := "output:\n```json\n{\"content\":[{\"type\":\"text\",\"text\":\"First\"},{\"type\":\"text\",\"text\":\"Second\"}]}\n```"

	result := mcpOutputSectionText(content)

	if !strings.Contains(result, "First") {
		t.Errorf("Should extract first text, got: %s", result)
	}
	if !strings.Contains(result, "Second") {
		t.Errorf("Should extract second text, got: %s", result)
	}

	// Should join text blocks with a blank line so each stays a distinct
	// Markdown region (a single "\n" would fold a following bold header into
	// the previous paragraph as a soft break).
	if result != "First\n\nSecond" {
		t.Errorf("Should join texts with a blank line, got: %q", result)
	}
}

