func TestMCPToolStructuredOutputRendersOnlyContentText(t *testing.T) {
	content := "output:\n```json\n" +
		`{"output":{"content":[{"type":"text","text":"**First Section**\n\nFirst paragraph."},{"type":"resource","text":"**Second Section**\n\nSecond paragraph."},{"type":"image","mimeType":"image/png"}],"trace":"do not display"},"request_id":"hidden"}` +
		"\n```"

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	r.RenderFrame(Frame{
		Kind:    FrameTool,
		Title:   "mcp__codegraph__codegraph_explore",
		Content: content,
		Final:   true,
		ToolMeta: tool.ToolMeta{
			Status: "completed",
		},
	})

	for i := range r.vm.blocks {
		r.vm.blocks[i].expanded = true
	}
	vr := renderViewport(&r.vm, 120, 60, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(vr.lines, "\n"))
	for _, want := range []string{"First Section", "First paragraph", "Second Section", "Second paragraph"} {
		if !strings.Contains(plain, want) {
			t.Fatalf("rendered MCP output missing %q:\n%s", want, plain)
		}
	}
	for _, unwanted := range []string{`"output"`, `"content"`, `"type"`, "trace", "request_id", "do not display", "image/png"} {
		if strings.Contains(plain, unwanted) {
			t.Fatalf("rendered MCP output leaked %q:\n%s", unwanted, plain)
		}
	}
}

