func TestNoExternalLegacyTUIImports(t *testing.T) {
	repoRoot := findRepoRoot(t)
	var offenders []string

	err := filepath.WalkDir(filepath.Join(repoRoot, "pkg"), func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}
		rel, _ := filepath.Rel(repoRoot, path)
		rel = filepath.ToSlash(rel)
		fset := token.NewFileSet()
		file, parseErr := parser.ParseFile(fset, path, nil, parser.ImportsOnly)
		if parseErr != nil {
			return parseErr
		}
		for _, imp := range file.Imports {
			spec := strings.Trim(imp.Path.Value, "\"")
			if strings.Contains(spec, "/internal/forebraintui") || strings.Contains(spec, "/internal/tui") {
				offenders = append(offenders, rel+" -> "+spec)
			}
		}
		return nil
	})
	if err != nil {
		t.Fatalf("walk failed: %v", err)
	}
	if len(offenders) == 0 {
		return
	}
	var b bytes.Buffer
	b.WriteString("legacy TUI imports detected:\n")
	for _, item := range offenders {
		b.WriteString(" - ")
		b.WriteString(item)
		b.WriteByte('\n')
	}
	t.Fatal(b.String())
}

func findRepoRoot(t *testing.T) string {
	t.Helper()
	wd, err := os.Getwd()
	if err != nil {
		t.Fatalf("getwd: %v", err)
	}
	cur := wd
	for {
		if fileExists(filepath.Join(cur, "go.mod")) {
			return cur
		}
		next := filepath.Dir(cur)
		if next == cur {
			t.Fatalf("repo root not found from %s", wd)
		}
		cur = next
	}
}

func fileExists(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}

func codeModelID(version string) string {
	return "gpt-" + version + "-co" + "dex"
}

func mcLocalTexts(state *streamState) []string {
	out := []string{}
	for _, s := range state.pendingSteers {
		out = append(out, s.Text)
	}
	return out
}

// Simulate the screenshot: user repeatedly edits the last queued steer and
// resubmits with Enter, while the agent is actively working (draining steers at
// tool boundaries). interactive=true to match the real composer.
func TestMultiCycleEditAccumulates(t *testing.T) {
	session := newRTSession()
	state := &streamState{sessionID: "s1"}
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	dispatch := func(ev inputEvent) {
		handleActiveRunInput(context.Background(), session, renderer, nil, state, nil, ev, nil)
	}

	edits := []string{
		"auto fix and commit",
		"auto fix and commits",
		"auto fix and commit and push",
		"auto fix and commit and push to remote",
	}

	// First queue.
	dispatch(inputEvent{kind: inputEventLine, line: edits[0]})
	t.Logf("cycle 0 queue: local=%v rt=%d", mcLocalTexts(state), len(session.rt.Snapshot()))

	for i := 1; i < len(edits); i++ {
		// Agent works between user actions: drain delivers pending steers.
		session.rt.DrainSteers()
		// User recalls last queued message to edit it.
		dispatch(inputEvent{kind: inputEventHotkey, hotkey: hotkeyEditLastQueued})
		// User edits and resubmits with Enter.
		dispatch(inputEvent{kind: inputEventDraft, draft: edits[i], cursor: 0})
		dispatch(inputEvent{kind: inputEventLine, line: edits[i]})
		t.Logf("cycle %d: local=%v rt=%d", i, mcLocalTexts(state), len(session.rt.Snapshot()))
	}

	got := mcLocalTexts(state)
	if len(got) != 1 {
		t.Fatalf("expected queue to hold a single edited message, accumulated %d: %v", len(got), got)
	}
}

// Without a drain in between, every edit-hotkey recalls the steer it just
// queued, so repeated edit/resubmit cycles replace one message instead of
// stacking a new copy per cycle — in both the local mirror and the runtime.
func TestMultiCycleEditNoDrainReplacesPendingSteer(t *testing.T) {
	session := newRTSession()
	state := &streamState{sessionID: "s1"}
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	dispatch := func(ev inputEvent) {
		handleActiveRunInput(context.Background(), session, renderer, nil, state, nil, ev, nil)
	}
	dispatch(inputEvent{kind: inputEventLine, line: "v0"})
	for i := 1; i <= 4; i++ {
		dispatch(inputEvent{kind: inputEventHotkey, hotkey: hotkeyEditLastQueued})
		txt := "v" + string(rune('0'+i))
		dispatch(inputEvent{kind: inputEventDraft, draft: txt, cursor: 0})
		dispatch(inputEvent{kind: inputEventLine, line: txt})
		t.Logf("cycle %d: local=%v rt=%d", i, mcLocalTexts(state), len(session.rt.Snapshot()))
	}
	if got := mcLocalTexts(state); len(got) != 1 || got[0] != "v4" {
		t.Fatalf("expected the queue to hold only the newest edit, got %v", got)
	}
	if got := len(session.rt.Snapshot()); got != 1 {
		t.Fatalf("expected the runtime queue to match the mirror, got %d entries", got)
	}
	_ = run.TurnInputModeSteer
	_ = llm.Text
}

// rtSession backs the steer surface on a real TurnInputRuntime, exactly like the
// production ChatSession, so divergence between the local pendingSteers mirror
// and the runtime is observable.
type rtSession struct {
	*fakeSession
	rt     *run.TurnInputRuntime
	active bool
}

func newRTSession() *rtSession {
	return &rtSession{fakeSession: &fakeSession{}, rt: run.NewTurnInputRuntime(), active: true}
}

func (s *rtSession) SteerSurfaceRun(sessionID, channel string, parts []llm.ContentPart) bool {
	if !s.active || s.rt == nil || len(parts) == 0 {
		return false
	}
	s.rt.Enqueue(run.TurnInputModeSteer, parts)
	return true
}

func (s *rtSession) RetractSurfaceSteer(sessionID, channel string) bool {
	if !s.active || s.rt == nil {
		return false
	}
	_, ok := s.rt.RetractLastSteer()
	return ok
}

func (s *rtSession) SurfacePendingSteerCount(sessionID, channel string) (int, bool) {
	if !s.active || s.rt == nil {
		return 0, false
	}
	count := 0
	for _, e := range s.rt.Snapshot() {
		if e.Mode == run.TurnInputModeSteer {
			count++
		}
	}
	return count, true
}

func localSteerTexts(state *streamState) []string {
	out := []string{}
	for _, s := range state.pendingSteers {
		out = append(out, s.Text)
	}
	return out
}

// An undelivered pending steer is recalled by the queue-edit shortcut: it is
// retracted from the runtime and pulled back into the composer, so the preview's
// "edit last queued message" hint is honest for the pending-steer section.
func TestEditPendingSteerNoDrainRecallsSteerForEditing(t *testing.T) {
	session := newRTSession()
	state := &streamState{sessionID: "s1"}
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	dispatch := func(ev inputEvent) {
		handleActiveRunInput(context.Background(), session, renderer, nil, state, nil, ev, nil)
	}

	dispatch(inputEvent{kind: inputEventLine, line: "auto fix all bugs"})
	dispatch(inputEvent{kind: inputEventHotkey, hotkey: hotkeyEditLastQueued})

	if got := localSteerTexts(state); len(got) != 0 {
		t.Fatalf("recalled steer must leave the mirror, got %v", got)
	}
	if count, _ := session.SurfacePendingSteerCount("s1", "tui"); count != 0 {
		t.Fatalf("recalled steer must be retracted from the runtime, got %d", count)
	}
	if state.composer.DraftText != "auto fix all bugs" {
		t.Fatalf("expected steer restored to composer, got %q", state.composer.DraftText)
	}
}

func TestDeliveredPendingSteerIsReconciledBeforeNewSteer(t *testing.T) {
	session := newRTSession()
	state := &streamState{sessionID: "s1"}
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	dispatch := func(ev inputEvent) {
		handleActiveRunInput(context.Background(), session, renderer, nil, state, nil, ev, nil)
	}

	// User queues a steer while the agent works.
	dispatch(inputEvent{kind: inputEventLine, line: "auto fix all bugs"})
	// Agent hits a tool boundary and delivers the steer to the model.
	if delivered := session.rt.DrainSteers(); len(delivered) != 1 {
		t.Fatalf("expected 1 delivered steer, got %d", len(delivered))
	}
	// User submits a distinct follow-up after the original steer was delivered.
	dispatch(inputEvent{kind: inputEventDraft, draft: "auto fix all bugs and commit", cursor: 0})
	dispatch(inputEvent{kind: inputEventLine, line: "auto fix all bugs and commit"})

	got := localSteerTexts(state)
	if len(got) != 1 || got[0] != "auto fix all bugs and commit" {
		t.Fatalf("delivered steer was not reconciled — got duplicate queue: %v", got)
	}
}

func TestPendingSteerPreviewDropsDeliveredSteerAndKeepsNewOne(t *testing.T) {
	session := newRTSession()
	state := &streamState{sessionID: "s1"}
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	dispatch := func(ev inputEvent) {
		handleActiveRunInput(context.Background(), session, renderer, nil, state, nil, ev, nil)
	}

	dispatch(inputEvent{kind: inputEventLine, line: "review后提交代码"})
	// Agent delivers it at a tool boundary, so it is no longer recallable and the
	// next message is queued alongside nothing.
	session.rt.DrainSteers()
	dispatch(inputEvent{kind: inputEventHotkey, hotkey: hotkeyEditLastQueued})
	dispatch(inputEvent{kind: inputEventDraft, draft: "review后修复问题并提交代码", cursor: len([]rune("review后修复问题并提交代码"))})
	dispatch(inputEvent{kind: inputEventLine, line: "review后修复问题并提交代码"})

	preview := state.composerPendingInputPreview()
	if len(preview.PendingSteers) != 1 {
		t.Fatalf("expected only the undelivered pending steer, got %#v", preview.PendingSteers)
	}
	if preview.PendingSteers[0] != "review后修复问题并提交代码" {
		t.Fatalf("unexpected pending steer preview: %#v", preview.PendingSteers)
	}
	// The delivered one moved into the transcript rather than vanishing.
	if got := deliveredSteerTranscript(t, renderer); len(got) != 1 || got[0] != "review后提交代码" {
		t.Fatalf("delivered steer missing from transcript: %#v", got)
	}
}

// Once the runtime has drained a steer it is on its way to the model, so the
// recall shortcut must not hand the user an editable copy of it.
func TestEditDeliveredPendingSteerLeavesSteerUntouched(t *testing.T) {
	session := newRTSession()
	state := &streamState{sessionID: "s1"}
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	dispatch := func(ev inputEvent) {
		handleActiveRunInput(context.Background(), session, renderer, nil, state, nil, ev, nil)
	}

	dispatch(inputEvent{kind: inputEventLine, line: "review后提交代码"})
	// The change hook mirrors production: the surface reconciles against the
	// post-drain count as soon as the delivery notification lands.
	session.rt.SetChangeHook(func(delivered []run.TurnInputEntry) {
		renderDeliveredSteerMessages(renderer, state.reconcilePendingSteersCount(0))
	})
	session.rt.DrainSteers()

	dispatch(inputEvent{kind: inputEventHotkey, hotkey: hotkeyEditLastQueued})

	if got := strings.TrimSpace(state.composer.DraftText); got != "" {
		t.Fatalf("delivered steer must not be restored to composer, got %q", got)
	}
	if got := localSteerTexts(state); len(got) != 0 {
		t.Fatalf("delivered steer must leave the preview, got %v", got)
	}
	if got := deliveredSteerTranscript(t, renderer); len(got) != 1 || got[0] != "review后提交代码" {
		t.Fatalf("delivered steer missing from transcript: %#v", got)
	}
}

// End-to-end through the real composer: a steer carrying an image and a folded
// large paste must reach the transcript in its composer form. The model-facing
// text has the image placeholder stripped and the paste expanded, so rendering
// that instead would drop the image entirely (an image-only steer would render
// nothing at all) and dump the whole paste into history.
func TestDeliveredSteerTranscriptKeepsImageAndPastePlaceholders(t *testing.T) {
	imagePath := filepath.Join(t.TempDir(), "clip.png")
	if err := os.WriteFile(imagePath, []byte("\x89PNG\r\n\x1a\nimage-data"), 0o600); err != nil {
		t.Fatalf("write image: %v", err)
	}
	session := newRTSession()
	state := &streamState{sessionID: "s1"}
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	dispatch := func(ev inputEvent) {
		handleActiveRunInput(context.Background(), session, renderer, nil, state, nil, ev, nil)
	}

	pasted := strings.Repeat("payload", 200)
	dispatch(inputEvent{kind: inputEventPaste, paste: pasted})
	placeholder := strings.TrimSpace(state.composer.PendingPastes[0].Placeholder)
	state.appendImageAttachment(InputAttachment{Path: imagePath, MIMEType: "image/png", Label: "clip.png"})
	line := state.composer.DraftText
	dispatch(inputEvent{kind: inputEventDraft, draft: line, cursor: len([]rune(line))})
	dispatch(inputEvent{kind: inputEventLine, line: line})

	// Agent reaches a tool boundary and hands the steer to the model.
	session.rt.DrainSteers()
	dispatch(inputEvent{kind: inputEventMouseMove})

	got := deliveredSteerTranscript(t, renderer)
	if len(got) != 1 {
		t.Fatalf("expected the delivered steer in the transcript, got %#v", got)
	}
	if !strings.Contains(got[0], "[Image #1]") {
		t.Fatalf("image placeholder missing from transcript: %q", got[0])
	}
	if !strings.Contains(got[0], placeholder) {
		t.Fatalf("paste placeholder %q missing from transcript: %q", placeholder, got[0])
	}
	if strings.Contains(got[0], pasted) {
		t.Fatalf("expanded paste leaked into transcript: %q", got[0])
	}
}

// An image-only steer has no model-facing text whatsoever, so it is the case
// that vanished outright: nothing left the queue into the transcript and the
// user could only conclude the message had been dropped.
func TestDeliveredImageOnlySteerReachesTranscript(t *testing.T) {
	imagePath := filepath.Join(t.TempDir(), "clip.png")
	if err := os.WriteFile(imagePath, []byte("\x89PNG\r\n\x1a\nimage-data"), 0o600); err != nil {
		t.Fatalf("write image: %v", err)
	}
	session := newRTSession()
	state := &streamState{sessionID: "s1"}
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	dispatch := func(ev inputEvent) {
		handleActiveRunInput(context.Background(), session, renderer, nil, state, nil, ev, nil)
	}

	state.appendImageAttachment(InputAttachment{Path: imagePath, MIMEType: "image/png", Label: "clip.png"})
	line := state.composer.DraftText
	dispatch(inputEvent{kind: inputEventDraft, draft: line, cursor: len([]rune(line))})
	dispatch(inputEvent{kind: inputEventLine, line: line})

	if len(state.pendingSteers) != 1 || state.pendingSteers[0].Text != "" {
		t.Fatalf("expected one text-less pending steer, got %#v", state.pendingSteers)
	}
	session.rt.DrainSteers()
	dispatch(inputEvent{kind: inputEventMouseMove})

	if got := deliveredSteerTranscript(t, renderer); len(got) != 1 || !strings.Contains(got[0], "[Image #1]") {
		t.Fatalf("expected image-only steer in transcript, got %#v", got)
	}
}

// Reconciliation must keep the undelivered tail when only some steers were
// delivered: queue A then B, deliver both, queue C, then reconcile.
func TestReconcilePendingSteersKeepsUndeliveredSuffix(t *testing.T) {
	session := newRTSession()
	state := &streamState{
		sessionID: "s1",
		pendingSteers: []ComposerSubmission{
			{Text: "A", Parts: []llm.ContentPart{llm.Text("A")}, DisplayText: "A"},
			{Text: "B", Parts: []llm.ContentPart{llm.Text("B")}, DisplayText: "B"},
			{Text: "C", Parts: []llm.ContentPart{llm.Text("C")}, DisplayText: "C"},
		},
	}
	// Runtime only still holds C (A and B were delivered).
	session.rt.Enqueue(run.TurnInputModeSteer, []llm.ContentPart{llm.Text("C")})

	state.reconcilePendingSteers(session)

	if got := localSteerTexts(state); len(got) != 1 || got[0] != "C" {
		t.Fatalf("expected only undelivered suffix [C], got %v", got)
	}
}

// When no run is active (ok=false), the mirror is left untouched so other
// lifecycle code (turn-boundary clears, interrupt resubmit) keeps working.
func TestReconcilePendingSteersNoopWhenInactive(t *testing.T) {
	session := newRTSession()
	session.active = false
	state := &streamState{
		sessionID: "s1",
		pendingSteers: []ComposerSubmission{
			{Text: "A", Parts: []llm.ContentPart{llm.Text("A")}, DisplayText: "A"},
		},
	}
	state.reconcilePendingSteers(session)
	if got := localSteerTexts(state); len(got) != 1 {
		t.Fatalf("expected mirror untouched when inactive, got %v", got)
	}
}

