// fakeSubagentExecutor records how each review run was dispatched and replays a
// scripted outcome per call.
type fakeSubagentExecutor struct {
	replies []func(ctx context.Context) (string, error)
	calls   []fakeSubagentCall
}

type fakeSubagentCall struct {
	ctx             context.Context
	task            string
	superviseRunID  string
	sessionID       string
	workerSessionID string
	subagentType    string
}

func (h *fakeSubagentExecutor) RunSubagentExec(ctx context.Context, task, superviseExistingRunID, parentRunID, sessionID, workerSessionID, subagentType string) (string, error) {
	h.calls = append(h.calls, fakeSubagentCall{
		ctx: ctx, task: task, superviseRunID: superviseExistingRunID,
		sessionID: sessionID, workerSessionID: workerSessionID, subagentType: subagentType,
	})
	idx := len(h.calls) - 1
	if idx >= len(h.replies) {
		return "", fmt.Errorf("unexpected subagent call %d", idx)
	}
	return h.replies[idx](ctx)
}

type scriptedApprovalSink struct {
	decisions []turn.ToolApprovalDecision
	requests  []turn.ToolApprovalRequest
}

func (s *scriptedApprovalSink) PromptToolApproval(_ context.Context, req turn.ToolApprovalRequest) (turn.ToolApprovalDecision, error) {
	s.requests = append(s.requests, req)
	idx := len(s.requests) - 1
	if idx >= len(s.decisions) {
		return turn.ToolApprovalDecision{}, fmt.Errorf("unexpected approval prompt %d", idx)
	}
	return s.decisions[idx], nil
}

// planReviewConfig is a session that can run plan review: models configured.
// The subagent switch is left unset because plan review does not depend on it.
func planReviewConfig(providers ...appcfg.AgentLLMProviderConfig) *appcfg.Root {
	return &appcfg.Root{Agents: appcfg.AgentsSection{
		Definitions: map[string]appcfg.AgentDefinition{"main": {LLMProviders: providers}},
	}}
}

