func TestPlanReviewRunsAsAPlanReviewerSubagentOnTheChosenModel(t *testing.T) {
	executor := &fakeSubagentExecutor{replies: []func(context.Context) (string, error){
		func(context.Context) (string, error) { return "Verdict: rework. internal/x.go:12 says otherwise.", nil },
	}}
	cs, _ := newReviewRunSession(t, executor)
	reviewer := &planSubagentReviewer{
		session: cs,
		model:   turn.Model{Provider: "anthropic", Model: "claude-sonnet-4"},
	}

	result, err := reviewer.Review(context.Background(), turn.Request{
		Plan: "# Plan\n\n1. Ship it.", Task: "Add S3 sync.",
	})
	if err != nil {
		t.Fatalf("Review error: %v", err)
	}
	if !strings.Contains(result.Text, "Verdict: rework") {
		t.Fatalf("review text = %q", result.Text)
	}
	if len(executor.calls) != 1 {
		t.Fatalf("subagent calls=%d want 1", len(executor.calls))
	}
	call := executor.calls[0]

	if call.subagentType != planReviewerSubtype ||
		tool.SubagentTypeFromContext(call.ctx) != planReviewerSubtype {
		t.Fatalf("review must run as the plan-reviewer subtype: param=%q ctx=%q",
			call.subagentType, tool.SubagentTypeFromContext(call.ctx))
	}
	// The reviewer keeps its own transcript: appending its investigation to the
	// user's session would both pollute the conversation and disturb the prompt
	// prefix the next turn is cached on.
	if call.workerSessionID == "" || call.workerSessionID == call.sessionID {
		t.Fatalf("reviewer must get its own worker session: worker=%q session=%q",
			call.workerSessionID, call.sessionID)
	}
	// It is dispatched under the conversation's session, like a subagent spawned
	// mid-turn, which is what links it to this conversation and keeps it in the
	// parent's prompt-cache bucket rather than opening one of its own.
	if call.sessionID != "session-1" {
		t.Fatalf("review dispatched under session %q, want the conversation's", call.sessionID)
	}
	if key := llm.PromptCacheKeyFromContext(call.ctx); key != "session-1" {
		t.Fatalf("prompt cache key = %q, want the parent bucket every subagent shares", key)
	}
	// Roster identity: the run is tagged with the key the roster row and the
	// per-agent view are built from.
	if strings.TrimSpace(tool.HookAgentIDFromContext(call.ctx)) == "" {
		t.Fatal("review run must carry a roster key or it cannot open an agent view")
	}
	if root := tool.ProjectRootFromContext(call.ctx); strings.TrimSpace(root) == "" {
		t.Fatal("reviewer must be pointed at the project root or it cannot read the code")
	}
	if !strings.Contains(call.task, "1. Ship it.") || !strings.Contains(call.task, "Add S3 sync.") {
		t.Fatalf("review task missing material:\n%s", call.task)
	}
	if !strings.Contains(call.task, "Read the code this touches before you judge the plan") {
		t.Fatalf("review task must order investigation before judgement:\n%s", call.task)
	}
}

