func TestPlanReviewToolApprovalIsShownAndTheRunResumes(t *testing.T) {
	ctx := context.Background()
	pendingActionID := ""
	executor := &fakeSubagentExecutor{}
	cs, actions := newReviewRunSession(t, executor)

	act, err := actions.CreatePending(ctx, "s1", "shell", map[string]any{"command": "rg exit_plan_mode"})
	if err != nil {
		t.Fatalf("CreatePending: %v", err)
	}
	pendingActionID = act.ID
	executor.replies = []func(context.Context) (string, error){
		func(context.Context) (string, error) {
			return "", &tool.RequiresActionError{
				ActionID: pendingActionID, ActionKind: "shell", ToolName: "shell", RunID: "review-run-1",
				ToolInput:       map[string]any{"command": "rg exit_plan_mode"},
				SessionSnapshot: []llm.Message{llm.AssistantMessage(nil, llm.ToolCall{ID: "call-1"})},
			}
		},
		func(context.Context) (string, error) { return "Verdict: approve with changes.", nil },
	}
	sink := &scriptedApprovalSink{decisions: []turn.ToolApprovalDecision{{Approved: true}}}
	cs.SetToolApprovalSink(sink)

	reviewer := &planSubagentReviewer{session: cs, model: turn.Model{Provider: "openai", Model: "gpt-4o"}}
	result, err := reviewer.Review(ctx, turn.Request{Plan: "# Plan", Task: "Add S3 sync."})
	if err != nil {
		t.Fatalf("Review error: %v", err)
	}
	if !strings.Contains(result.Text, "approve with changes") {
		t.Fatalf("review text = %q", result.Text)
	}

	// The reviewer's tool request reached the user rather than being refused.
	if len(sink.requests) != 1 {
		t.Fatalf("approval prompts=%d want 1", len(sink.requests))
	}
	if got := sink.requests[0]; got.ToolName != "shell" || got.ActionID != pendingActionID ||
		got.SubagentType != planReviewerSubtype || !strings.Contains(got.ToolInputJSON, "rg exit_plan_mode") {
		t.Fatalf("approval request = %#v", got)
	}

	// The action was resolved and the same run continued with the approval.
	stored, err := actions.Get(ctx, pendingActionID)
	if err != nil {
		t.Fatalf("Get action: %v", err)
	}
	if stored.Status != state.ActionApproved {
		t.Fatalf("action status = %s want approved", stored.Status)
	}
	if len(executor.calls) != 2 {
		t.Fatalf("subagent calls=%d want the run resumed", len(executor.calls))
	}
	resumed := executor.calls[1]
	if resumed.superviseRunID != "review-run-1" {
		t.Fatalf("resume must continue the same run, got %q", resumed.superviseRunID)
	}
	if tool.ApprovedActionIDFromContext(resumed.ctx) != pendingActionID {
		t.Fatal("resumed run must carry the approved action id")
	}
	state := tool.ToolApprovalResumeFromContext(resumed.ctx)
	if state == nil || state.Denied || len(state.Session) == 0 {
		t.Fatalf("resume state = %#v", state)
	}
}

