func newTestOverlay(form state.AskForm) *questionOverlay {
	answers := make([]map[int]bool, len(form.Questions))
	for i := range answers {
		answers[i] = make(map[int]bool)
	}
	otherText := make([]string, len(form.Questions))
	o := &questionOverlay{
		out:       &bytes.Buffer{},
		form:      form,
		answers:   answers,
		otherText: otherText,
	}
	o.syncOtherEditMode()
	return o
}

func sampleForm() state.AskForm {
	return state.AskForm{
		Title: "Pick options",
		Questions: []state.AskQuestion{
			{
				ID: "q1", Prompt: "Pick one",
				Options: []state.AskOption{
					{ID: "A", Label: "Alpha", Description: "first", Recommended: true},
					{ID: "B", Label: "Beta", Description: "second", Preview: "preview-b"},
				},
			},
		},
	}
}

// twoQuestionForm returns a multi-question form used to test tab navigation
// and the submit review view. Single-select, 2 options per question.
func twoQuestionForm() state.AskForm {
	return state.AskForm{
		Questions: []state.AskQuestion{
			{ID: "q1", Prompt: "p1", Options: []state.AskOption{{ID: "x", Label: "X"}, {ID: "y", Label: "Y"}}},
			{ID: "q2", Prompt: "p2", Options: []state.AskOption{{ID: "z", Label: "Z"}, {ID: "w", Label: "W"}}},
		},
	}
}

func TestQuestionOverlaySingleSelectCommit(t *testing.T) {
	o := newTestOverlay(sampleForm())
	// Single-question single-select: Enter on cursor=0 (Alpha) auto-submits.
	dec, done := o.handleKey(parsedKey{kind: rawKeyEnter})
	if !done {
		t.Fatal("expected auto-submit done=true on single-question Enter")
	}
	if !dec.Approved {
		t.Fatalf("expected Approved=true, got %+v", dec)
	}
	var ans state.AskAnswer
	if err := json.Unmarshal([]byte(dec.AskAnswerJSON), &ans); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(ans.Answers) != 1 || ans.Answers[0].QuestionID != "q1" {
		t.Fatalf("answers=%+v", ans)
	}
	if len(ans.Answers[0].OptionIDs) != 1 || ans.Answers[0].OptionIDs[0] != "A" {
		t.Fatalf("expected A selected, got %v", ans.Answers[0].OptionIDs)
	}
}

func TestQuestionOverlaySingleSelectMoveAndCommit(t *testing.T) {
	o := newTestOverlay(sampleForm())
	o.handleKey(parsedKey{kind: rawKeyDown}) // cursor=1 (Beta)
	dec, done := o.handleKey(parsedKey{kind: rawKeyEnter})
	if !done || !dec.Approved {
		t.Fatalf("auto-submit failed: done=%v dec=%+v", done, dec)
	}
	var ans state.AskAnswer
	_ = json.Unmarshal([]byte(dec.AskAnswerJSON), &ans)
	if ans.Answers[0].OptionIDs[0] != "B" {
		t.Fatalf("expected B selected, got %v", ans.Answers[0].OptionIDs)
	}
}

func TestQuestionOverlayMultiSelectCommit(t *testing.T) {
	form := sampleForm()
	form.Questions[0].AllowMultiple = true
	o := newTestOverlay(form)
	// Multi-select: Space toggles. Toggle A (cursor=0).
	o.handleKey(parsedKey{kind: rawKeySpace})
	// Move to B, toggle.
	o.handleKey(parsedKey{kind: rawKeyDown})
	o.handleKey(parsedKey{kind: rawKeySpace})
	// Navigate to Submit button: Down from B → Other (cursor=2) → Submit (cursor=3).
	o.handleKey(parsedKey{kind: rawKeyDown})
	o.handleKey(parsedKey{kind: rawKeyDown})
	// Enter on Submit advances to submit review view.
	_, done := o.handleKey(parsedKey{kind: rawKeyEnter})
	if done {
		t.Fatal("Submit button should go to submit view, not finalize")
	}
	if !o.inSubmitView() {
		t.Fatalf("expected submit view, current=%d", o.current)
	}
	// Enter on "Submit answers" commits.
	dec, done := o.handleKey(parsedKey{kind: rawKeyEnter})
	if !done || !dec.Approved {
		t.Fatalf("commit failed: done=%v dec=%+v", done, dec)
	}
	var ans state.AskAnswer
	_ = json.Unmarshal([]byte(dec.AskAnswerJSON), &ans)
	if len(ans.Answers[0].OptionIDs) != 2 {
		t.Fatalf("expected 2 selections, got %v", ans.Answers[0].OptionIDs)
	}
}

