func TestQuestionOverlayLongTextSoftWrapsAtViewportWidthAndReflowsOnResize(t *testing.T) {
	forcedTermWidth = 44
	forcedTermHeight = 200
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	const description = "允许 rg、grep/egrep/fgrep、git grep、find；可通过管道连接只读结果整形命令（如 head、sort、uniq、wc、cut、只读 sed），每个命令都必须完整显示。"
	form := sampleForm()
	form.Questions[0].Prompt = "search-shell 应允许哪些命令？"
	form.Questions[0].Options[0].Description = description

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	o := newTestOverlay(form)
	o.out = &out
	o.rs = newRawSelector(nil, r)
	o.render()

	assertWrapped := func(width int) int {
		t.Helper()
		lines := r.vpLastComposer.lines
		for i, line := range lines {
			if got := displayLineWidth(line); got > width-viewportRightPadding {
				t.Fatalf("overlay row %d exceeds viewport width: got=%d max=%d line=%q", i, got, width-viewportRightPadding, stripANSI(line))
			}
		}
		plain := strings.Join(strings.Fields(stripANSI(strings.Join(lines, "\n"))), "")
		wantDescription := strings.Join(strings.Fields(description), "")
		if !strings.Contains(plain, wantDescription) {
			t.Fatalf("wrapped overlay lost long description text:\n%s", stripANSI(strings.Join(lines, "\n")))
		}
		return len(lines)
	}

	wideRows := assertWrapped(forcedTermWidth)
	if !r.overlaySoftWrap {
		t.Fatal("question overlay must enable resize-aware soft wrapping")
	}

	// A SIGWINCH repaint must reflow the retained logical rows immediately;
	// the overlay should not require another key press to reveal hidden text.
	forcedTermWidth = 30
	r.ViewportResize()
	narrowRows := assertWrapped(forcedTermWidth)
	if narrowRows <= wideRows {
		t.Fatalf("narrower viewport should produce more visual rows: wide=%d narrow=%d", wideRows, narrowRows)
	}
}

