func TestQuestionOverlayTabNavigation(t *testing.T) {
	o := newTestOverlay(twoQuestionForm())
	// Enter on Q1 selects X and advances to Q2.
	_, done := o.handleKey(parsedKey{kind: rawKeyEnter})
	if done {
		t.Fatal("first question Enter should advance not commit")
	}
	if o.current != 1 {
		t.Fatalf("did not advance to Q2: current=%d", o.current)
	}
	// Enter on Q2 selects Z and advances to submit view.
	_, done = o.handleKey(parsedKey{kind: rawKeyEnter})
	if done {
		t.Fatal("second question Enter should advance to submit view")
	}
	if !o.inSubmitView() {
		t.Fatalf("expected submit view, current=%d", o.current)
	}
	// Enter on submit view "Submit answers" commits.
	dec, done := o.handleKey(parsedKey{kind: rawKeyEnter})
	if !done || !dec.Approved {
		t.Fatalf("submit view Enter must commit: done=%v dec=%+v", done, dec)
	}
	var ans state.AskAnswer
	_ = json.Unmarshal([]byte(dec.AskAnswerJSON), &ans)
	if len(ans.Answers) != 2 {
		t.Fatalf("expected 2 question answers, got %d", len(ans.Answers))
	}
}

