func TestQuestionOverlayEmptyOtherDoesNotReusePreviousQuestionBuffer(t *testing.T) {
	o := newTestOverlay(twoQuestionForm())

	// Save an Other answer for Q1, which advances to Q2.
	o.handleKey(parsedKey{kind: rawKeyDown})
	o.handleKey(parsedKey{kind: rawKeyDown})
	for _, r := range "first answer" {
		o.handleKey(parsedKey{kind: rawKeyRune, r: r})
	}
	o.handleKey(parsedKey{kind: rawKeyEnter})
	if o.current != 1 || o.otherText[0] != "first answer" {
		t.Fatalf("Q1 Other was not saved before advancing: current=%d otherText=%v", o.current, o.otherText)
	}

	// Q2's empty Other row must start a fresh edit state. It must not reuse
	// the completed Q1 edit buffer as an answer.
	o.handleKey(parsedKey{kind: rawKeyDown})
	o.handleKey(parsedKey{kind: rawKeyDown})
	buf := &bytes.Buffer{}
	o.out = buf
	o.render()
	if out := stripANSI(buf.String()); strings.Contains(out, "first answer") {
		t.Fatalf("Q2 rendered Q1's Other text:\n%s", out)
	}
	_, done := o.handleKey(parsedKey{kind: rawKeyEnter})
	if done {
		t.Fatal("empty Q2 Other should enter edit mode, not submit")
	}
	if !o.editingOther {
		t.Fatal("empty Q2 Other should enter edit mode")
	}
	if got := string(o.otherBuf); got != "" {
		t.Fatalf("Q2 edit buffer reused Q1 text: %q", got)
	}
	if o.otherText[1] != "" {
		t.Fatalf("Q2 Other should remain empty, got %q", o.otherText[1])
	}
}

func TestQuestionOverlayTabDoesNotFlushInactiveOtherBuffer(t *testing.T) {
	o := newTestOverlay(twoQuestionForm())
	o.current = 1
	o.restoreCursor()

	// A non-editing buffer is stale scratch state and must never be persisted by
	// tab navigation, even if one remains after an older or interrupted state.
	o.otherBuf = []rune("stale Q1 text")
	o.otherCursor = len(o.otherBuf)
	o.editingOther = false
	o.handleKey(parsedKey{kind: rawKeyTab})

	if !o.inSubmitView() {
		t.Fatalf("Tab should navigate to submit view, current=%d", o.current)
	}
	if o.otherText[1] != "" {
		t.Fatalf("inactive buffer was flushed into Q2: %q", o.otherText[1])
	}
}

func TestQuestionOverlayOtherTextIsolatedAcrossQuestionsAndSubmission(t *testing.T) {
	o := newTestOverlay(twoQuestionForm())

	// Answer Q1 with one custom value.
	o.handleKey(parsedKey{kind: rawKeyDown})
	o.handleKey(parsedKey{kind: rawKeyDown})
	for _, r := range "first answer" {
		o.handleKey(parsedKey{kind: rawKeyRune, r: r})
	}
	o.handleKey(parsedKey{kind: rawKeyEnter})

	// Answer Q2 with a different custom value, advancing to submit review.
	o.handleKey(parsedKey{kind: rawKeyDown})
	o.handleKey(parsedKey{kind: rawKeyDown})
	for _, r := range "second answer" {
		o.handleKey(parsedKey{kind: rawKeyRune, r: r})
	}
	o.handleKey(parsedKey{kind: rawKeyEnter})
	if !o.inSubmitView() {
		t.Fatalf("expected submit view after Q2, current=%d", o.current)
	}

	// Navigate back through both questions, then forward again. The shared edit
	// buffer must not overwrite either question while no edit session is active.
	// Q2's Other answer takes focus back on arrival, and ←/→ then move its
	// caret, so the tab bar is walked with Shift+Tab / Tab from here on.
	o.handleKey(parsedKey{kind: rawKeyLeft})     // Q2
	o.handleKey(parsedKey{kind: rawKeyShiftTab}) // Q1
	buf := &bytes.Buffer{}
	o.out = buf
	o.render()
	q1Render := stripANSI(buf.String())
	if !strings.Contains(q1Render, "Other: first answer") || strings.Contains(q1Render, "Other: second answer") {
		t.Fatalf("Q1 rendered the wrong Other text:\n%s", q1Render)
	}

	o.handleKey(parsedKey{kind: rawKeyTab}) // Q2
	if got := o.otherText; got[0] != "first answer" || got[1] != "second answer" {
		t.Fatalf("Other answers changed while switching tabs: %v", got)
	}
	buf.Reset()
	o.render()
	q2Render := stripANSI(buf.String())
	if !strings.Contains(q2Render, "Other: second answer") || strings.Contains(q2Render, "Other: first answer") {
		t.Fatalf("Q2 rendered the wrong Other text:\n%s", q2Render)
	}

	// Move to review and submit, then verify the serialized question mapping.
	o.handleKey(parsedKey{kind: rawKeyTab})
	dec, done := o.handleKey(parsedKey{kind: rawKeyEnter})
	if !done || !dec.Approved {
		t.Fatalf("commit failed: done=%v dec=%+v", done, dec)
	}
	var ans state.AskAnswer
	if err := json.Unmarshal([]byte(dec.AskAnswerJSON), &ans); err != nil {
		t.Fatalf("decode answer: %v", err)
	}
	got := make(map[string]string, len(ans.Answers))
	for _, item := range ans.Answers {
		got[item.QuestionID] = item.OtherText
	}
	if got["q1"] != "first answer" || got["q2"] != "second answer" {
		t.Fatalf("submitted Other answers mapped to wrong questions: %v", got)
	}
}

