func TestRawSelectorMemorySettingsStagesAndSaves(t *testing.T) {
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	defer r.Close()
	defer w.Close()
	sel := newRawSelector(r, nil)
	go func() {
		_, _ = w.Write([]byte{' '})
		_, _ = w.Write([]byte{0x1b, '[', 'B'})
		_, _ = w.Write([]byte{' '})
		_, _ = w.Write([]byte{'\r'})
	}()
	result, err := sel.SelectMemorySettings(false, true)
	if err != nil {
		t.Fatal(err)
	}
	if result.Action != MemorySettingsSave || !result.UseMemories || result.GenerateMemories {
		t.Fatalf("result=%#v", result)
	}
}

