func TestRawSelectorInputEditsBracketedPasteAtCursor(t *testing.T) {
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	defer r.Close()
	defer w.Close()

	sel := newRawSelector(r, nil)

	go func() {
		var input bytes.Buffer
		input.WriteString("\x1b[200~https://api.example/v1\x1b[201~")
		input.WriteString("\x1b[D\x1b[D") // move before the trailing "v1"
		input.WriteString("\x1b[200~beta-\x1b[201~")
		input.WriteByte('X')
		input.WriteString("\x1b[C") // move after the original "v"
		input.WriteByte(0x7f)       // remove that "v"
		input.WriteByte('\r')
		_, _ = w.Write(input.Bytes())
	}()

	got, ok, err := sel.Input("Base URL", "")
	if err != nil {
		t.Fatalf("Input error: %v", err)
	}
	if !ok || got != "https://api.example/beta-X1" {
		t.Fatalf("expected cursor-edited URL, got (%q, %v)", got, ok)
	}
}

// An input is a panel: the question, the field, and the keys that answer it.
// The caret sits at the logical cursor, measured in display cells.
func TestInputPanelShowsQuestionFieldAndKeys(t *testing.T) {
	layout := inputPanel("Base URL", []rune("A界B"), 2, false, "Esc to cancel").layout(60, 0, 0, false)
	var plain []string
	for _, line := range layout.lines {
		plain = append(plain, stripANSI(line))
	}
	want := []string{"  Base URL", "› A界B", "", "", "  Enter to confirm · Esc to cancel"}
	if strings.Join(plain, "\n") != strings.Join(want, "\n") {
		t.Fatalf("panel = %q, want %q", plain, want)
	}
	if layout.caretRow != 1 || layout.caretCol != 5 {
		t.Fatalf("field row %d, cursor column %d; want 1, 5", layout.caretRow, layout.caretCol)
	}
}

// Outside the viewport a prompt is a setup page drawn over the whole screen:
// the brand and the step on top, the progress rule, then the panel, with the
// hardware caret placed in the field at the logical cursor.
func TestStandalonePromptPaintsASetupPage(t *testing.T) {
	forcedTermWidth, forcedTermHeight = 60, 16
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })
	var out strings.Builder
	sel := newStandaloneRawSelector(nil, &out)
	sel.SetupPage(2, 5)

	sel.showPanel(inputPanel("URL", []rune("A界B"), 2, false, sel.escHint()))

	got := out.String()
	for _, want := range []string{"Forebrain Harness", "Step 2 of 5", "━", "  URL", "› A界B", "Esc to go back"} {
		if !strings.Contains(stripANSI(got), want) {
			t.Fatalf("page is missing %q:\n%s", want, stripANSI(got))
		}
	}
	// Four rows of page chrome, then the title: the field is on row 6, its
	// caret after "› A界" at column 5, one-based in the escape.
	if want := "\x1b[6;6H\x1b[?25h"; !strings.HasSuffix(got, want) {
		t.Fatalf("page = %q, want the caret placed with %q", got, want)
	}
}

