// A filter lists the rows that match it best first — the one it names, then
// the ones starting with it, then a word starting with it, then anywhere in
// the label, then only in the description — in their own order within each.
func TestPickerFiltersRankTheBestMatchFirst(t *testing.T) {
	st := &selectState{
		options: []string{
			"context-restore: resumes from a context-save checkpoint",
			"precontext-saver",
			"context-save: saves the session context",
			"Context-Save",
		},
	}
	st.filter = filterField{text: "context-save", cursor: 12}
	st.applyFilter()
	var got []string
	for _, i := range st.filtered {
		got = append(got, strings.SplitN(st.options[i], ":", 2)[0])
	}
	if strings.Join(got, ",") != "Context-Save,context-save,context-restore,precontext-saver" {
		t.Fatalf("plain picker lists %v", got)
	}

	p := &richPickerState{items: []SelectItem{
		{Label: "context-restore", Description: "resumes from a context-save checkpoint", Category: "Skills"},
		{Label: "commit", Description: "saves your work", Category: "Commands"},
		{Label: "context-save", Description: "saves the session context", Category: "Skills"},
		{Label: "save-all", Category: "Commands"},
	}}
	p.filter = filterField{text: "context-save", cursor: 12}
	p.rebuildSelectable()
	got = got[:0]
	for _, i := range p.selectable {
		got = append(got, p.items[i].Label)
	}
	if strings.Join(got, ",") != "context-save,context-restore" {
		t.Fatalf("rich picker lists %v for context-save", got)
	}
	p.filter = filterField{text: "save", cursor: 4}
	p.rebuildSelectable()
	got = got[:0]
	for _, i := range p.selectable {
		got = append(got, p.items[i].Label)
	}
	// Commands holds the best match (save-all starts with it), so it leads,
	// and each category stays together under its one header.
	if strings.Join(got, ",") != "save-all,commit,context-save,context-restore" {
		t.Fatalf("rich picker lists %v for save", got)
	}
}

