func TestRendererBannerKeepsFullWorkingDirectory(t *testing.T) {
	dir := "/workspace/very/long/path/that/exceeds/the/old/banner/directory/length/limit/project"
	for _, width := range []int{120, 80, 50, 24} {
		lines := forebrainBannerLines("v0.1.0", dir, width)
		// A path wider than the text column wraps at its separators; with the
		// frame, mascot and padding dropped, the pieces rejoin to the path.
		var text strings.Builder
		for _, line := range lines {
			for _, r := range stripANSI(line) {
				if r > ' ' && r < 0x7f {
					text.WriteRune(r)
				}
			}
			if w := displayLineWidth(line); w > width {
				t.Fatalf("width %d: banner line is %d columns wide: %q", width, w, stripANSI(line))
			}
		}
		if !strings.Contains(text.String(), dir) {
			t.Fatalf("width %d: banner truncated working directory: %q", width, stripANSI(strings.Join(lines, "\n")))
		}
	}
}

func TestThinkingDisplayLinesFinalShowsAllLinesWithoutCap(t *testing.T) {
	body := strings.Join([]string{
		"line 01 has enough words to wrap",
		"line 02 has enough words to wrap",
		"line 03 has enough words to wrap",
		"line 04 has enough words to wrap",
		"line 05 has enough words to wrap",
		"line 06 has enough words to wrap",
		"line 07 has enough words to wrap",
		"line 08 has enough words to wrap",
		"line 09 has enough words to wrap",
		"line 10 has enough words to wrap",
		"line 11 has enough words to wrap",
		"line 12 has enough words to wrap",
	}, "\n")
	lines := thinkingDisplayLinesWithWidth(Frame{
		Kind:    FrameThinking,
		Content: body,
		Final:   true,
	}, 36)
	plain := strings.Join(lines, "\n")
	if len(lines) != 25 {
		t.Fatalf("expected 24 content lines + blank (wraps with contentRightMargin), got %d: %#v", len(lines), lines)
	}
	if !strings.HasPrefix(stripANSI(lines[0]), "▸ ") {
		t.Fatalf("first thinking line should use triangle prefix, got %#v", lines)
	}
	if strings.Contains(plain, "Thinking") {
		t.Fatalf("thinking header should not be rendered, got %#v", lines)
	}
	stripped := stripANSI(plain)
	if !strings.Contains(stripped, "line 11 has enough") || !strings.Contains(stripped, "words") || !strings.Contains(stripped, "to wrap") || !strings.Contains(stripped, "line 12 has enough") {
		t.Fatalf("final thinking should show all lines, got %#v", lines)
	}
	if strings.Contains(plain, "lines (click to expand)") {
		t.Fatalf("final thinking should not truncate, got %#v", lines)
	}
}

