// TestRendererThinkingTokenDeltasDoNotFragmentLines reproduces the bug where
// token-level reasoning deltas ("The", "user", "is", ...) each landed on their
// own line. The reducer accumulates deltas; append-only streaming advances the
// cursor forward on the same line so all words share one line on screen.
func TestRendererFinalAssistantWrapsLongLinesWithinPadding(t *testing.T) {
	forcedTermWidth = 60
	t.Cleanup(func() { forcedTermWidth = 0 })
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	longWord := strings.Repeat("word ", 40)
	longCode := strings.Repeat("x", 120)
	r.RenderFrame(Frame{
		Kind:    FrameAssistant,
		Content: "A long paragraph: " + longWord + "\n\n```\n" + longCode + "\n```\n\n### " + longWord,
		Final:   true,
	})
	// Markdown wraps to termWidth-2-1=57, then renderAssistant prepends a
	// 2-col bullet/continuation prefix, so the widest rendered line is 59 —
	// one column short of the 60-col terminal, i.e. the right padding holds.
	const cap = 60 - 1
	for _, line := range strings.Split(stripANSI(out.String()), "\n") {
		if w := lipgloss.Width(line); w > cap {
			t.Fatalf("rendered line exceeds content width and runs into terminal autowrap: width=%d cap=%d line=%q", w, cap, line)
		}
	}
}

