// markdownCodeFixture is a fenced block whose lines carry no digits of their
// own, so any digit in front of a code row can only be a line-number gutter.
// Twelve lines is past the point where a gutter would widen to two columns.
var markdownCodeWords = []string{
	"alpha", "bravo", "charlie", "delta", "echo", "foxtrot",
	"golf", "hotel", "india", "juliett", "kilo", "lima",
}

func markdownCodeFixture() string {
	var sb strings.Builder
	sb.WriteString("Intro paragraph.\n\n```go\n")
	for _, word := range markdownCodeWords {
		fmt.Fprintf(&sb, "%s := compute()\n", word)
	}
	sb.WriteString("```\n")
	return sb.String()
}

