func TestRendererSkillReadCardUsesDedicatedHeaderAndProjectRelativeSource(t *testing.T) {
	project := t.TempDir()
	if err := os.Mkdir(filepath.Join(project, ".git"), 0o755); err != nil {
		t.Fatal(err)
	}
	nested := filepath.Join(project, "cmd", "forebrain")
	if err := os.MkdirAll(nested, 0o755); err != nil {
		t.Fatal(err)
	}
	projectRoot := memory.ProjectRoot(nested)
	skillPath := filepath.Join(projectRoot, ".forebrain", "skills", "review", "SKILL.md")
	// The completed card carries exactly the shared semantic body the runtime
	// persisted for this read — never the file preview it replaced.
	evt := tool.StepEvent{
		Kind: event.RunEventToolCompleted, StepID: "read-skill-1", ToolName: "read_file",
		Category: "skill", SkillName: "review", SkillPath: skillPath, Origin: "llm-read",
		Duration: 50 * time.Millisecond,
	}
	body, _ := tool.FormatToolStepResult(evt, tool.DefaultMaxFormattedBody)
	var out bytes.Buffer
	r := NewRenderer(&out, &out).WithWorkingDir(nested)
	r.renderCompactFrame(Frame{
		Kind:     FrameTool,
		Title:    "read_file",
		Content:  body,
		Final:    true,
		Duration: 50 * time.Millisecond,
		ToolMeta: tool.BuildToolMeta(evt),
	}, "tool", "214")
	plain := stripANSI(out.String())
	compact := strings.Join(strings.Fields(plain), "")
	for _, want := range []string{"●Skillreview<0.1s", "└Loadedfrom" + filepath.Join(".forebrain", "skills", "review", "SKILL.md")} {
		if !strings.Contains(compact, want) {
			t.Fatalf("skill card missing %q:\n%s", want, plain)
		}
	}
	for _, unwanted := range []string{"Read ", "body that must stay hidden", "1|"} {
		if strings.Contains(plain, unwanted) {
			t.Fatalf("skill card contains %q:\n%s", unwanted, plain)
		}
	}
}

