// renderExplicitSkillStepCard drives the exact projection seam the live TUI and
// the resume replay share: a tool StepEvent goes through tool.BuildToolMeta and
// tool.FormatToolStepResult before a Frame is ever drawn. Building the frame
// here keeps the explicit-path assertions honest about what the producer sent.
func renderExplicitSkillStepCard(t *testing.T, evt tool.StepEvent) (string, string) {
	t.Helper()
	meta := tool.BuildToolMeta(evt)
	body, _ := tool.FormatToolStepResult(evt, tool.DefaultMaxFormattedBody)
	var out bytes.Buffer
	NewRenderer(&out, &out).renderCompactFrame(Frame{
		Kind:     FrameTool,
		Title:    meta.ToolName,
		Content:  body,
		Final:    evt.Kind != tool.StepKindToolStarted,
		Duration: evt.Duration,
		ToolMeta: meta,
	}, "tool", "214")
	return out.String(), meta.Category
}

// explicitSkillStep builds the StepEvent the runner preload emits for one
// explicit skill lifecycle boundary.
func explicitSkillStep(kind string, errorText string, duration time.Duration) tool.StepEvent {
	return tool.StepEvent{
		Kind:      kind,
		StepID:    "skill-explicit-1",
		ToolName:  "skill",
		Category:  "skill",
		SkillName: "review-agent",
		SkillPath: "/Users/doudou/.codex/skills/.system/review-agent/SKILL.md",
		Origin:    "explicit",
		Error:     errorText,
		Duration:  duration,
	}
}

// TestExplicitSkillInvocationRendersDedicatedCard pins the final card for the
// explicit /review-agent path. The invocation used to reach the TUI as a
// fabricated completed step ({"explicit":true} plus the whole activation body),
// which painted the raw JSON envelope instead of a Skill card.
func TestExplicitSkillInvocationRendersDedicatedCard(t *testing.T) {
	rendered, category := renderExplicitSkillStepCard(t, explicitSkillStep(tool.StepKindToolCompleted, "", 50*time.Millisecond))
	plain := stripANSI(rendered)
	compact := strings.Join(strings.Fields(plain), "")
	if category != "skill" {
		t.Fatalf("explicit invocation lost its Skill category (got %q):\n%s", category, plain)
	}
	if !strings.Contains(compact, "●Skillreview-agent<0.1s") {
		t.Fatalf("explicit skill card header = %q, want a completed Skill header", plain)
	}
	if !strings.Contains(compact, "└Loadedfrom/Users/doudou/.codex/skills/.system/review-agent/SKILL.md") {
		t.Fatalf("explicit skill card must name the loaded source:\n%s", plain)
	}
	for _, unwanted := range []string{`{"explicit":true}`, "output:", "<skill>", "<context>", "\\u003c"} {
		if strings.Contains(plain, unwanted) {
			t.Fatalf("explicit skill card leaks %q:\n%s", unwanted, plain)
		}
	}
}

