func assertMarkdownTableColumnsAligned(t *testing.T, rendered string) {
	t.Helper()
	var want []int
	for _, line := range strings.Split(stripANSI(rendered), "\n") {
		if !strings.HasPrefix(strings.TrimSpace(line), "|") {
			continue
		}
		got := pipeDisplayColumns(line)
		if len(got) == 0 {
			continue
		}
		if want == nil {
			want = got
			continue
		}
		if strings.Trim(line, "|-: ") == "" {
			continue
		}
		if !intSlicesEqual(got, want) {
			t.Fatalf("table columns are misaligned:\n%s\ncolumns=%v want=%v", stripANSI(rendered), got, want)
		}
	}
	if len(want) == 0 {
		t.Fatalf("no markdown table lines found in %q", rendered)
	}
}

// pipeDisplayColumns reports the display column each "|" of a rendered table
// row lands on, measured the way the terminal draws it.
func pipeDisplayColumns(line string) []int {
	cols := []int{}
	width := 0
	for _, r := range line {
		if r == '|' {
			cols = append(cols, width)
		}
		width += lipgloss.Width(string(r))
	}
	return cols
}

func intSlicesEqual(a []int, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

