func TestRendererViewportRetainsCompletedSandboxAttemptAcrossRetryLifecycle(t *testing.T) {
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	r.RenderFrame(Frame{
		Kind: FrameTool, Title: "shell", StepID: "call-1",
		ToolMeta: tool.ToolMeta{Status: "running"},
	})
	r.RenderFrame(Frame{
		Kind: FrameTool, Title: "shell", StepID: "call-1", Content: "sandbox failure output",
		ToolMeta: tool.ToolMeta{Status: "completed"}, RetainAsHistory: true,
	})
	r.RenderFrame(Frame{
		Kind: FrameTool, Title: "shell", StepID: "call-1",
		ToolMeta: tool.ToolMeta{Status: "awaiting approval"},
	})
	r.RenderFrame(Frame{
		Kind: FrameTool, Title: "shell", StepID: "call-1",
		ToolMeta: tool.ToolMeta{Status: "running"},
	})
	r.RenderFrame(Frame{
		Kind: FrameTool, Title: "shell", StepID: "call-1", Content: "host retry output",
		ToolMeta: tool.ToolMeta{Status: "completed"},
	})

	if len(r.vm.blocks) != 2 {
		t.Fatalf("sandbox attempt and host retry must both remain, got %d blocks", len(r.vm.blocks))
	}
	if got := r.vm.blocks[0].frame; !got.RetainAsHistory || got.Content != "sandbox failure output" {
		t.Fatalf("first sandbox attempt was overwritten: %#v", got)
	}
	if got := r.vm.blocks[1].frame; got.RetainAsHistory || got.Content != "host retry output" || got.ToolMeta.Status != "completed" {
		t.Fatalf("retry lifecycle did not update its own block: %#v", got)
	}
}

