func TestRendererViewportPrintErrorPrecedesWorkedStatus(t *testing.T) {
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	r.RenderFrame(Frame{Kind: FrameTool, Title: "shell", StepID: "call-1", Content: "done", Final: true})
	r.RenderFrame(Frame{Kind: FrameAssistant, Content: "completed", Final: true})
	r.RenderFrame(Frame{Kind: FrameStatus, Title: "Worked for 1s", Final: true})
	r.PrintError(fmt.Errorf("provider context_length_exceeded"))

	if len(r.vm.blocks) != 4 {
		t.Fatalf("expected tool, assistant, error, worked blocks; got %#v", r.vm.blocks)
	}
	got := make([]FrameKind, len(r.vm.blocks))
	for i, block := range r.vm.blocks {
		got[i] = block.frame.Kind
	}
	want := []FrameKind{FrameTool, FrameAssistant, FrameError, FrameStatus}
	if !slices.Equal(got, want) {
		t.Fatalf("frame order = %v, want %v", got, want)
	}
	if got := r.vm.blocks[2].frame.Content; got != "provider context_length_exceeded" {
		t.Fatalf("error content = %q", got)
	}
}

func TestRendererViewportPrintErrorDoesNotCrossPreviousTurnWorkedStatus(t *testing.T) {
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	r.RenderFrame(Frame{Kind: FrameUser, Content: "first turn", Final: true})
	r.RenderFrame(Frame{Kind: FrameAssistant, Content: "first response", Final: true})
	r.RenderFrame(Frame{Kind: FrameStatus, Title: "Worked for 1s", Final: true})
	r.RenderFrame(Frame{Kind: FrameUser, Content: "second turn", Final: true})
	r.PrintError(fmt.Errorf("second turn provider error"))
	r.RenderFrame(Frame{Kind: FrameStatus, Title: "Worked for 2s", Final: true})

	if len(r.vm.blocks) != 6 {
		t.Fatalf("expected two complete turns, got %#v", r.vm.blocks)
	}
	if got := r.vm.blocks[2].frame; got.Kind != FrameStatus || got.Title != "Worked for 1s" {
		t.Fatalf("first turn boundary moved: %#v", got)
	}
	if got := r.vm.blocks[3].frame; got.Kind != FrameUser || got.Content != "second turn" {
		t.Fatalf("second turn user frame moved: %#v", got)
	}
	if got := r.vm.blocks[4].frame; got.Kind != FrameError || got.Content != "second turn provider error" {
		t.Fatalf("second turn error misplaced: %#v", got)
	}
	if got := r.vm.blocks[5].frame; got.Kind != FrameStatus || got.Title != "Worked for 2s" {
		t.Fatalf("second turn worked status misplaced: %#v", got)
	}
}

// TestRendererViewportSeedsStartupChromeAsBannerBlock verifies the banner is
// retained inside the alt-screen viewport as one FrameBannerInfo block when
// viewport mode is active, instead of being written to the hidden normal
// buffer, and that the block reflows to whatever width it is painted at.
func TestRendererViewportSeedsStartupChromeAsBannerBlock(t *testing.T) {
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)
	out.Reset()

	r.Banner(StartupInfo{Version: "v9.9.9", Directory: "~/proj"})
	r.StartupInfo(StartupInfo{Version: "v9.9.9", Directory: "~/proj"})
	r.StartupHint()

	var rawBlocks []*viewBlock
	var bannerBlocks []*viewBlock
	for _, b := range r.vm.blocks {
		switch b.frame.Kind {
		case FrameRaw:
			rawBlocks = append(rawBlocks, b)
		case FrameBannerInfo:
			bannerBlocks = append(bannerBlocks, b)
		}
	}
	if len(rawBlocks) != 0 {
		t.Fatalf("expected no FrameRaw blocks, got %d (total blocks %d)", len(rawBlocks), len(r.vm.blocks))
	}
	if len(bannerBlocks) != 1 {
		t.Fatalf("expected 1 FrameBannerInfo block, got %d (total blocks %d)", len(bannerBlocks), len(r.vm.blocks))
	}
	frame := bannerBlocks[0].frame
	for _, width := range []int{200, 80, 56, 40, 20} {
		lines := renderFrameLines(frame, width, r.DiffTheme(), 0)
		plain := stripANSI(strings.Join(lines, "\n"))
		for _, want := range []string{"Forebrain Harness", "v9.9.9", "~/proj", "/ commands", "@ mention", "esc interrupt", "ctrl+j newline"} {
			if !strings.Contains(plain, want) {
				t.Fatalf("width %d: startup card missing %q: %q", width, want, plain)
			}
		}
		for _, line := range lines {
			if w := displayLineWidth(line); w > width {
				t.Fatalf("width %d: startup card line is %d columns wide: %q", width, w, stripANSI(line))
			}
		}
	}
	// The mascot sits beside the text only when the card has room for both.
	wide := stripANSI(strings.Join(renderFrameLines(frame, 200, r.DiffTheme(), 0), "\n"))
	narrow := stripANSI(strings.Join(renderFrameLines(frame, 40, r.DiffTheme(), 0), "\n"))
	if !strings.Contains(wide, "▄▄███▄██▄▄██▄███▄▄") || strings.Contains(narrow, "▄▄███▄██▄▄██▄███▄▄") {
		t.Fatalf("mascot should show at width 200 and not at width 40:\n%s\n---\n%s", wide, narrow)
	}
}

func TestRendererBeginBatchSuppressesRepaint(t *testing.T) {
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)
	// Seed one frame and clear the buffer so only subsequent writes are measured.
	r.RenderFrame(Frame{Kind: FrameSystem, Title: "sys", Content: "seed", Final: true})
	out.Reset()

	// During a batch, appends must NOT repaint the viewport.
	r.BeginBatch()
	r.RenderFrame(Frame{Kind: FrameSystem, Title: "sys", Content: "batched-a", Final: true})
	r.RenderFrame(Frame{Kind: FrameSystem, Title: "sys", Content: "batched-b", Final: true})
	if out.Len() != 0 {
		t.Fatalf("batch should suppress repaint, but %d bytes were written", out.Len())
	}

	// Ending the outermost batch paints exactly once.
	r.EndBatch()
	if out.Len() == 0 {
		t.Fatalf("EndBatch should repaint once after the batch")
	}

	// Nesting: only the outermost EndBatch paints.
	out.Reset()
	r.BeginBatch()
	r.BeginBatch()
	r.RenderFrame(Frame{Kind: FrameSystem, Title: "sys", Content: "nested", Final: true})
	r.EndBatch()
	if out.Len() != 0 {
		t.Fatalf("inner EndBatch must not paint while outer batch is open, got %d bytes", out.Len())
	}
	r.EndBatch()
	if out.Len() == 0 {
		t.Fatalf("outer EndBatch should paint once")
	}
}

