// TestLayoutNormalComposerCursorAtSoftWrapBoundary locks in the fix for the
// cursor-misalignment bug at soft-wrap break points. When long input word-wraps,
// the space at the break point is consumed (trimmed) between the two visual
// lines. Previously the cursor was positioned by re-wrapping the text prefix,
// which kept that trailing space and left the caret in the blank area past the
// end of the first visual line when the cursor sat right after the break space.
// The cursor must instead land on the next visual line.
func TestLayoutNormalComposerCursorAtSoftWrapBoundary(t *testing.T) {
	// normalComposerContentWidth(14) = 14 - 2 (prefix) - 2 (safety) = 10.
	// "aaaa bbbb cccc" word-wraps to ["aaaa bbbb", "cccc"]; the space after
	// "bbbb" (rune index 9) is the consumed break point.
	const termWidth = 14
	text := "aaaa bbbb cccc"
	// Each visual line is prefixed: "› " on row 0, "  " on row 1 (both width 2).
	const prefix = 2

	cases := []struct {
		name    string
		cursor  int
		wantRow int
		wantCol int
	}{
		{"start", 0, 0, prefix + 0},
		{"mid line0", 5, 0, prefix + 5},                         // after "aaaa "
		{"end of line0 content", 9, 0, prefix + 9},              // after "aaaa bbbb", before break space
		{"start of line1 after break space", 10, 1, prefix + 0}, // after consumed space -> line 1
		{"mid line1", 12, 1, prefix + 2},                        // after "cc"
		{"end", 14, 1, prefix + 4},                              // after "cccc"
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			cursor := tc.cursor
			layout := layoutNormalComposer(text, &cursor, termWidth)
			if layout.cursorRowFromTop != tc.wantRow {
				t.Fatalf("cursor row: got %d, want %d (cursor=%d)", layout.cursorRowFromTop, tc.wantRow, tc.cursor)
			}
			if layout.cursorCol != tc.wantCol {
				t.Fatalf("cursor col: got %d, want %d (cursor=%d)", layout.cursorCol, tc.wantCol, tc.cursor)
			}
		})
	}

	// Multiple consecutive break spaces are all consumed; the caret stays at the
	// end of the first line's visible content until it reaches line 1's content.
	t.Run("multiple break spaces", func(t *testing.T) {
		multi := "aaaa bbbb  cccc" // two spaces between bbbb and cccc
		cursor := 10               // the second space (consumed)
		layout := layoutNormalComposer(multi, &cursor, termWidth)
		if layout.cursorRowFromTop != 0 || layout.cursorCol != prefix+9 {
			t.Fatalf("cursor in consumed spaces should stay at end of line0 content: got row=%d col=%d, want row=0 col=%d",
				layout.cursorRowFromTop, layout.cursorCol, prefix+9)
		}
		cursor = 11 // start of "cccc"
		layout = layoutNormalComposer(multi, &cursor, termWidth)
		if layout.cursorRowFromTop != 1 || layout.cursorCol != prefix+0 {
			t.Fatalf("cursor at start of line1: got row=%d col=%d, want row=1 col=%d",
				layout.cursorRowFromTop, layout.cursorCol, prefix+0)
		}
	})

	// Character wrap (no spaces): the caret at the exact boundary lands on the
	// next visual line rather than one column past the end of the previous one.
	t.Run("char wrap boundary", func(t *testing.T) {
		nowrap := "aaaaaaaaaabbbbbbbbbb" // 10 + 10, wraps to two full lines
		cursor := 10
		layout := layoutNormalComposer(nowrap, &cursor, termWidth)
		if layout.cursorRowFromTop != 1 || layout.cursorCol != prefix+0 {
			t.Fatalf("cursor at char-wrap boundary: got row=%d col=%d, want row=1 col=%d",
				layout.cursorRowFromTop, layout.cursorCol, prefix+0)
		}
	})
}

