func TestRendererFailedToolRendersNormalizedErrorOnce(t *testing.T) {
	const failure = "apply_patch heredoc must not contain trailing shell commands"
	content := "**error** (shell)\n\n```\n" + failure + "\n```"

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.renderCompactFrame(Frame{
		Kind:    FrameTool,
		Title:   "shell",
		Content: content,
		Final:   true,
		ToolMeta: tool.ToolMeta{
			ToolName: "shell",
			Status:   "failed",
			Input:    map[string]any{"command": "apply_patch <<'PATCH'"},
		},
	}, "tool", "214")

	plain := stripANSI(out.String())
	if count := strings.Count(plain, failure); count != 1 {
		t.Fatalf("failure text count = %d, want 1:\n%s", count, plain)
	}
	for _, leaked := range []string{"**error**", "```", "error: " + failure} {
		if strings.Contains(plain, leaked) {
			t.Fatalf("failed tool output leaked %q:\n%s", leaked, plain)
		}
	}
	if !strings.Contains(plain, "Failed to run apply_patch <<'PATCH'") {
		t.Fatalf("failed tool header missing command:\n%s", plain)
	}
}

func TestNormalizeFailedToolContent(t *testing.T) {
	tests := []struct {
		name    string
		content string
		want    string
	}{
		{
			name:    "plain error",
			content: "permission denied",
			want:    "permission denied",
		},
		{
			name:    "fenced envelope",
			content: "**error** (shell)\n\n```\nfirst line\nsecond line\n```",
			want:    "first line\nsecond line",
		},
		{
			name:    "heading with plain remainder",
			content: "**error** (shell)\npermission denied",
			want:    "permission denied",
		},
		{
			name:    "unclosed fence",
			content: "**error** (shell)\n\n```\npermission denied",
			want:    "permission denied",
		},
		{
			name:    "inline detail",
			content: "**error** (shell) permission denied",
			want:    "permission denied",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := normalizeFailedToolContent(tt.content); got != tt.want {
				t.Fatalf("normalizeFailedToolContent() = %q, want %q", got, tt.want)
			}
		})
	}
}

