func TestRendererToolHeaderContinuationRespectsRightMargin(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() {
		forcedTermWidth = 0
		forcedTermHeight = 0
	})

	summary := `ran codegraph.codegraph_explore {"query":"keyhandler up down arrow history tui some more words here to force wrap"}`

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.RenderFrame(Frame{
		Kind:    FrameTool,
		Title:   "mcp__codegraph__codegraph_explore",
		Summary: summary,
		Final:   true,
	})
	plain := stripANSI(out.String())
	lines := strings.Split(strings.TrimRight(plain, "\n"), "\n")

	maxAllowed := forcedTermWidth - contentRightMargin // 70
	for i, line := range lines {
		if len(line) == 0 {
			continue
		}
		if len(line) > maxAllowed {
			t.Fatalf("line %d exceeds right margin: width=%d max=%d (term=%d margin=%d): %q",
				i, len(line), maxAllowed, forcedTermWidth, contentRightMargin, line)
		}
	}
}

