func TestToolDisplayHeaderOmitsOutputDerivedSuffixes(t *testing.T) {
	tests := []struct {
		name           string
		frame          Frame
		cwd            string
		wantContains   []string
		wantNotContain []string
	}{
		{
			name: "read_file line range",
			frame: Frame{
				Kind:     FrameTool,
				Title:    "read_file",
				Final:    true,
				Duration: 1500 * time.Millisecond,
				Content:  `{"offset":999,"limit":1}`,
				ToolMeta: tool.ToolMeta{
					ToolName: "read_file",
					Status:   "completed",
					Input: map[string]any{
						"file_path": "/repo/hello.go",
						"offset":    float64(0),
						"limit":     float64(27),
					},
				},
			},
			wantContains:   []string{"Read /repo/hello.go lines 1-27 · 1.5s"},
			wantNotContain: []string{"lines 1000-1000"},
		},
		{
			name: "web_fetch size",
			frame: Frame{
				Kind:    FrameTool,
				Title:   "web_fetch",
				Final:   true,
				Content: "output:\n\n```json\n{\"bytes\":2048}\n```",
				ToolMeta: tool.ToolMeta{
					ToolName: "web_fetch",
					Status:   "completed",
					Input:    map[string]any{"url": "https://example.com/very/long/path"},
				},
			},
			wantContains:   []string{"Fetched", "https://example.com/very/long/path"},
			wantNotContain: []string{"2048", "2.0 KB"},
		},
		{
			name: "web_search count",
			frame: Frame{
				Kind:    FrameTool,
				Title:   "web_search",
				Final:   true,
				Content: `{"count":5}`,
				ToolMeta: tool.ToolMeta{
					ToolName: "web_search",
					Status:   "completed",
					Input:    map[string]any{"query": "tui replay"},
				},
			},
			wantContains:   []string{"Searched", "tui replay"},
			wantNotContain: []string{"5 results"},
		},
		{
			name: "working_set_show count",
			frame: Frame{
				Kind:    FrameTool,
				Title:   "working_set_show",
				Final:   true,
				Content: `{"count":4}`,
				ToolMeta: tool.ToolMeta{
					ToolName: "working_set_show",
					Status:   "completed",
				},
			},
			wantContains:   []string{"Working set"},
			wantNotContain: []string{"4 entries"},
		},
		{
			name: "subagent_list count",
			frame: Frame{
				Kind:    FrameTool,
				Title:   "subagent_list",
				Final:   true,
				Content: `{"count":2}`,
				ToolMeta: tool.ToolMeta{
					ToolName: "subagent_list",
					Status:   "completed",
				},
			},
			wantContains:   []string{"Agent list"},
			wantNotContain: []string{"2 agents"},
		},
		{
			name: "edit_file diff stats",
			frame: Frame{
				Kind:    FrameTool,
				Title:   "edit_file",
				Final:   true,
				Content: "turn diff: `/repo/edit.go` (+2/-1)\n\n```diff\n--- /repo/edit.go:before\n+++ /repo/edit.go:after\n@@ -1 +1,2 @@\n-old\n+new\n+more\n```",
				ToolMeta: tool.ToolMeta{
					ToolName: "edit_file",
					Status:   "completed",
					Input:    map[string]any{"file_path": "/repo/edit.go"},
				},
			},
			wantContains:   []string{"Edited /repo/edit.go"},
			wantNotContain: []string{"(+", "−", "no changes"},
		},
		{
			name: "write_file diff stats",
			frame: Frame{
				Kind:    FrameTool,
				Title:   "write_file",
				Final:   true,
				Content: "turn diff: `/repo/new.go` (+3/-0)\n\n```diff\n--- /repo/new.go:before\n+++ /repo/new.go:after\n@@ -0,0 +1,3 @@\n+one\n+two\n+three\n```",
				ToolMeta: tool.ToolMeta{
					ToolName: "write_file",
					Status:   "completed",
					Input:    map[string]any{"file_path": "/repo/new.go"},
				},
			},
			wantContains:   []string{"Created /repo/new.go"},
			wantNotContain: []string{"(+", "−"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			header := ToolDisplayHeader(tt.frame, tt.cwd)
			for _, want := range tt.wantContains {
				if !strings.Contains(header, want) {
					t.Fatalf("header %q missing %q", header, want)
				}
			}
			for _, unwanted := range tt.wantNotContain {
				if strings.Contains(header, unwanted) {
					t.Fatalf("header %q unexpectedly contains %q", header, unwanted)
				}
			}
		})
	}
}

func TestWebSearchToolBodyFormatsLegacyJSONEnvelope(t *testing.T) {
	providerBody := `{"results":[{"title":"Terminal UX Guide","url":"https://example.com/tui","description":"Readable terminal interfaces."}]}`
	transportBytes, err := json.Marshal(map[string]any{
		"status":       200,
		"content_type": "application/json",
		"body":         providerBody,
		"limit":        5,
		"truncated":    false,
	})
	if err != nil {
		t.Fatal(err)
	}
	eventBytes, err := json.Marshal(map[string]any{"output": string(transportBytes)})
	if err != nil {
		t.Fatal(err)
	}
	legacy := "output:\n\n```json\n" + string(eventBytes) + "\n```"
	frame := Frame{
		Kind:    FrameTool,
		Title:   "web_search",
		Final:   true,
		Content: legacy,
		ToolMeta: tool.ToolMeta{
			ToolName: "web_search",
			Status:   "completed",
			Input:    map[string]any{"query": "terminal UX"},
		},
	}

	body := summaryToolBody(frame, frame.Title)
	for _, want := range []string{"**1 search result**", "[Terminal UX Guide](https://example.com/tui)", "Readable terminal interfaces."} {
		if !strings.Contains(body, want) {
			t.Fatalf("formatted legacy body missing %q:\n%s", want, body)
		}
	}
	if strings.Contains(body, "{") || strings.Contains(body, `"content_type"`) || strings.Contains(body, `"results"`) {
		t.Fatalf("legacy web search body exposed raw JSON:\n%s", body)
	}

	for _, tc := range []struct {
		name    string
		content string
	}{
		{name: "legacy replay", content: legacy},
		{name: "live markdown", content: body},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var out bytes.Buffer
			renderer := NewRenderer(&out, &out)
			liveFrame := frame
			liveFrame.Content = tc.content
			renderer.renderCompactFrame(liveFrame, "tool", "214")
			plain := stripANSI(out.String())
			flat := strings.Join(strings.Fields(plain), " ")
			for _, forbidden := range []string{"output:", "```json", `"content_type"`, `"results"`} {
				if strings.Contains(flat, forbidden) {
					t.Fatalf("rendered web search card exposed %q:\n%s", forbidden, plain)
				}
			}
			for _, want := range []string{"1 search result", "Terminal UX Guide", "Readable terminal interface"} {
				if !strings.Contains(flat, want) {
					t.Fatalf("rendered Markdown card missing %q:\n%s", want, plain)
				}
			}
		})
	}
}

func TestWebFetchToolBodyRendersOnlyFetchedMarkdown(t *testing.T) {
	transportBytes, err := json.Marshal(map[string]any{
		"status":       200,
		"content_type": "text/html; charset=utf-8",
		"body":         "# API reference\n\n- First parameter\n- Second parameter",
		"bytes":        2048,
		"final_url":    "https://example.com/api",
		"truncated":    false,
		"rule_content": "domain:example.com",
	})
	if err != nil {
		t.Fatal(err)
	}
	eventOutput := map[string]any{"output": string(transportBytes)}
	eventBytes, err := json.Marshal(eventOutput)
	if err != nil {
		t.Fatal(err)
	}
	liveBody, truncated := tool.FormatToolStepResult(tool.StepEvent{
		Kind:     tool.StepKindToolCompleted,
		ToolName: "web_fetch",
		Input:    map[string]any{"url": "https://example.com/api"},
		Output:   eventOutput,
	}, tool.DefaultMaxFormattedBody)
	if truncated {
		t.Fatal("unexpected truncation")
	}
	legacyBody := "output:\n\n```json\n" + string(eventBytes) + "\n```"

	for _, tc := range []struct {
		name    string
		content string
	}{
		{name: "legacy replay", content: legacyBody},
		{name: "live markdown", content: liveBody},
	} {
		t.Run(tc.name, func(t *testing.T) {
			frame := Frame{
				Kind:    FrameTool,
				Title:   "web_fetch",
				Final:   true,
				Content: tc.content,
				ToolMeta: tool.ToolMeta{
					ToolName: "web_fetch",
					Status:   "completed",
					Input:    map[string]any{"url": "https://example.com/api"},
				},
			}
			if body := summaryToolBody(frame, frame.Title); body != liveBody {
				t.Fatalf("summary body = %q, want fetched Markdown %q", body, liveBody)
			}

			var out bytes.Buffer
			renderer := NewRenderer(&out, &out)
			renderer.renderCompactFrame(frame, "tool", "214")
			plain := stripANSI(out.String())
			flat := strings.Join(strings.Fields(plain), " ")
			for _, forbidden := range []string{"output:", "```json", `"content_type"`, `"rule_content"`, `"final_url"`, "# API reference"} {
				if strings.Contains(flat, forbidden) {
					t.Fatalf("rendered web fetch card exposed %q:\n%s", forbidden, plain)
				}
			}
			for _, want := range []string{"API reference", "First parameter", "Second parameter"} {
				if !strings.Contains(flat, want) {
					t.Fatalf("rendered Markdown card missing %q:\n%s", want, plain)
				}
			}
		})
	}
}

