// TestRendererCanceledToolDisplaysCanceledAction verifies the toolDisplayParts
// override renders "Canceled" for a canceled shell tool instead of "Ran" or
// "Running".
func TestRendererCanceledToolDisplaysCanceledAction(t *testing.T) {
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	r.RenderFrame(Frame{
		Kind:   FrameTool,
		Title:  "shell",
		StepID: "call-cancel",
		Final:  true,
		ToolMeta: tool.ToolMeta{
			ToolName: "shell",
			Status:   "canceled",
			Input:    map[string]any{"command": "go test ./..."},
		},
		Summary: "awaiting approval · go test ./...",
	})

	plain := stripANSI(out.String())
	if !strings.Contains(plain, "Canceled") {
		t.Fatalf("expected 'Canceled' action for canceled shell tool, got %q", plain)
	}
	if strings.Contains(plain, "Running") {
		t.Fatalf("canceled shell tool should not show 'Running', got %q", plain)
	}
	if !strings.Contains(plain, "go test ./...") {
		t.Fatalf("canceled shell tool should still show the command target, got %q", plain)
	}
}

// TestRendererRequestPermissionsHeaderStates verifies the request_permissions
// tool card renders distinct headers for completed, denied, and canceled
// outcomes now that the lifecycle is always user-visible.
func TestRendererRequestPermissionsHeaderStates(t *testing.T) {
	cases := []struct {
		status string
		want   string
	}{
		{"completed", "Requested permissions"},
		{"awaiting approval", "Requesting permissions"},
		{"denied", "Permission request denied"},
		{"canceled", "Permission request canceled"},
	}
	for _, tc := range cases {
		t.Run(tc.status, func(t *testing.T) {
			var out bytes.Buffer
			r := NewRenderer(&out, &out)
			r.EnableViewportMode()
			t.Cleanup(r.DisableViewportMode)

			r.RenderFrame(Frame{
				Kind:   FrameTool,
				Title:  "request_permissions",
				StepID: "call-rp",
				Final:  true,
				ToolMeta: tool.ToolMeta{
					ToolName: "request_permissions",
					Status:   tc.status,
				},
				Summary: "request permissions",
			})

			plain := stripANSI(out.String())
			if !strings.Contains(plain, tc.want) {
				t.Fatalf("status=%q header missing %q, got %q", tc.status, tc.want, plain)
			}
		})
	}
}

