// TestRendererReadFileHeaderDoesNotTruncatePathUnderCwd verifies that a long
// file path under the cwd is shown in full (relative) in the tool header,
// not middle-truncated with "…/".
func TestRendererReadFileHeaderDoesNotTruncatePathUnderCwd(t *testing.T) {
	cwd := "/home/user/project"
	// Relative form exceeds the old 60-char truncation limit so the old code
	// would have reduced it to "…/jjjj/openapi.yaml".
	relPath := "aaaa/bbbb/cccc/dddd/eeee/ffff/gggg/hhhh/iiii/jjjj/openapi.yaml"
	filePath := cwd + "/" + relPath

	forcedTermWidth = 200
	t.Cleanup(func() { forcedTermWidth = 0 })

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.cwd = cwd

	r.renderCompactFrame(Frame{
		Kind:   FrameTool,
		Title:  "read_file",
		StepID: "call-read",
		Final:  true,
		ToolMeta: tool.ToolMeta{
			ToolName: "read_file",
			Status:   "completed",
			Input:    map[string]any{"file_path": filePath},
		},
		Content: `{"line_start":1,"line_end":200}`,
	}, "tool", "214")

	plain := stripANSI(out.String())
	if !strings.Contains(plain, relPath) {
		t.Fatalf("expected full relative path %q in header, got %q", relPath, plain)
	}
	if strings.Contains(plain, "…/") {
		t.Fatalf("header must not truncate the file path, got %q", plain)
	}
}

