func TestWrapCardLineIndexFillsTheLineWithAWordWiderThanIt(t *testing.T) {
	longPath := "/Users/doudou/.forebrain/workspace/plans/forebrain/simplify-openclaw-event-forwarding.md"
	header := "○ Created " + longPath + " (+96 −0)"
	maxWidth := 40

	idx := wrapCardLineIndex(header, maxWidth)
	if idx >= len(header) {
		t.Fatalf("expected wrapCardLineIndex to break within the line, got full length %d", idx)
	}
	firstSegment := header[:idx]
	firstWidth := runewidth.StringWidth(firstSegment)
	if firstWidth > maxWidth {
		t.Fatalf("first segment width %d exceeds maxWidth %d: %q", firstWidth, maxWidth, firstSegment)
	}
	if firstWidth != maxWidth {
		t.Fatalf("expected first segment to use all %d columns, got width %d: %q", maxWidth, firstWidth, firstSegment)
	}
	if !strings.Contains(firstSegment, "/Users/") {
		t.Fatalf("expected first segment to include the long path instead of stopping at the previous space: %q", firstSegment)
	}
}

func TestWrapCardLineIndexHardBreaksALineWithNoWordBoundary(t *testing.T) {
	// A line with no word boundary at all can only be broken inside itself.
	text := strings.Repeat("a", 100)
	maxWidth := 20

	idx := wrapCardLineIndex(text, maxWidth)
	if idx >= len(text) {
		t.Fatalf("expected wrapCardLineIndex to break within the line")
	}
	firstSegment := text[:idx]
	firstWidth := runewidth.StringWidth(firstSegment)
	if firstWidth > maxWidth {
		t.Fatalf("first segment width %d exceeds maxWidth %d: %q", firstWidth, maxWidth, firstSegment)
	}
	// It fills the line: 20 'a's.
	if firstWidth != 20 {
		t.Fatalf("expected first segment width 20, got %d: %q", firstWidth, firstSegment)
	}
}

func TestWrapCardLineIndexUsesAvailableColumnsAcrossWords(t *testing.T) {
	text := "hello world foo bar baz"
	maxWidth := 15

	idx := wrapCardLineIndex(text, maxWidth)
	if idx >= len(text) {
		t.Fatalf("expected wrapCardLineIndex to break within the line")
	}
	firstSegment := text[:idx]
	firstWidth := runewidth.StringWidth(firstSegment)
	if firstWidth > maxWidth {
		t.Fatalf("first segment width %d exceeds maxWidth %d: %q", firstWidth, maxWidth, firstSegment)
	}
	if firstSegment != "hello world foo" {
		t.Fatalf("expected the break at the last space that fits, got segment: %q", firstSegment)
	}
}

func TestWrapCardLineIndexBreaksBetweenCJKCharacters(t *testing.T) {
	// CJK characters are 2 display cells wide; should break correctly.
	text := "这是一个很长的中文字符串测试软换行功能"
	maxWidth := 10

	idx := wrapCardLineIndex(text, maxWidth)
	if idx >= len(text) {
		t.Fatalf("expected wrapCardLineIndex to break within the CJK string")
	}
	firstSegment := text[:idx]
	firstWidth := runewidth.StringWidth(firstSegment)
	if firstWidth > maxWidth {
		t.Fatalf("first segment width %d exceeds maxWidth %d: %q", firstWidth, maxWidth, firstSegment)
	}
	// Each CJK char is 2 wide, so with maxWidth=10 we should get 5 chars.
	if firstWidth != 10 {
		t.Fatalf("expected first segment width 10 (5 CJK chars), got %d: %q", firstWidth, firstSegment)
	}
}

// A word that fits on a line is never split across two: it moves to the next
// line whole. Character packing used to leave "Approv" at the end of one row
// and "al" at the start of the next.
func TestWrapCardLineKeepsAWordThatFitsWhole(t *testing.T) {
	text := "Waiting for your Approval before the plan is carried out"
	for width := 10; width <= len(text); width++ {
		lines := wrapCardLine(text, width)
		if got := strings.Join(lines, " "); got != text {
			t.Fatalf("width %d: lines %q do not rejoin into the text at spaces", width, lines)
		}
		for _, line := range lines {
			if displayLineWidth(line) > width {
				t.Fatalf("width %d: line %q is wider than the width", width, line)
			}
		}
	}
}

// A hyphen inside a word is a place a line may end, so a hyphenated word that
// straddles the edge breaks after its hyphen, not inside one of its parts.
func TestWrapCardLineBreaksAfterAHyphenInsideAWord(t *testing.T) {
	lines := wrapCardLine("the module cache is mounted read-only today", 35)
	want := []string{"the module cache is mounted read-", "only today"}
	if strings.Join(lines, "|") != strings.Join(want, "|") {
		t.Fatalf("lines = %q, want %q", lines, want)
	}
}

// Chinese breaks between characters, but punctuation that closes a phrase
// never begins a line: it stays with the character it follows.
func TestWrapCardLineKeepsClosingPunctuationOffTheStartOfALine(t *testing.T) {
	lines := wrapCardLine("这是第一句，这是第二句。", 10)
	want := []string{"这是第一", "句，这是第", "二句。"}
	if strings.Join(lines, "|") != strings.Join(want, "|") {
		t.Fatalf("lines = %q, want %q", lines, want)
	}
}

func TestWrapCardLineBreaksLongWordAcrossMultipleLines(t *testing.T) {
	// A path wider than the line is broken inside itself, starting where it
	// stands after the short words before it.
	longPath := "/Users/doudou/.forebrain/workspace/plans/forebrain/simplify-openclaw-event-forwarding.md"
	header := "○ Created " + longPath + " (+96 −0)"
	maxWidth := 40

	lines := wrapCardLine(header, maxWidth)
	if len(lines) <= 1 {
		t.Fatalf("expected multiple lines after wrapping, got %d", len(lines))
	}
	firstWidth := runewidth.StringWidth(lines[0])
	if firstWidth > maxWidth {
		t.Fatalf("first line width %d exceeds maxWidth %d: %q", firstWidth, maxWidth, lines[0])
	}
	// All lines should fit within maxWidth.
	for i, line := range lines {
		w := runewidth.StringWidth(line)
		if w > maxWidth {
			t.Fatalf("line %d width %d exceeds maxWidth %d: %q", i, w, maxWidth, line)
		}
	}
	// The first line should contain the initial text before the long path.
	if !strings.HasPrefix(lines[0], "○ Created") {
		t.Fatalf("first line should start with '○ Created', got: %q", lines[0])
	}
}

func TestWrapToolDisplayLineWidthPreservesWordBoundaries(t *testing.T) {
	line := "Ran gofmt -w internal/clifacade/chat_session.go internal/clifacade/chat_surface.go internal/clifacade/tool_step_notify.go internal/clifacade/chat_surface_test.go internal/clifacade/chat_session_slash_handlers_test.go internal/surface/types.go internal/tui/run.go internal/tui/run_test.go && go test ./internal/clifacade ./internal/tui ./internal/surface"

	out := wrapToolDisplayLineWidth(line, "  │ ", 120)

	// Check that no ordinary words are broken across lines.
	if strings.Contains(out, "int\n") || strings.Contains(out, "ste\n") || strings.Contains(out, "p_not\n") {
		t.Errorf("wrapToolDisplayLineWidth broke words mid-character:\n%s", out)
	}

	assertWrappedToolDisplayLines(t, out, "  │ ", 120)

	// Check that all words from the original appear in the output (joined).
	outClean := strings.ReplaceAll(out, "\n  │ ", " ")
	outClean = strings.ReplaceAll(outClean, "\n", " ")
	for _, word := range strings.Fields(line) {
		if !strings.Contains(outClean, word) {
			t.Errorf("word %q missing from wrapped output", word)
		}
	}
}

func TestWrapToolDisplayLineWidthWrapsCJKAndLongTokens(t *testing.T) {
	const prefix = "  │ "
	longPath := "/Users/doudou/.forebrain/workspace/plans/forebrain/simplify-openclaw-event-forwarding.md"
	tests := []struct {
		name string
		line string
	}{
		{
			name: "Chinese",
			line: "完成工具调用后继续检查这个没有空格的中文摘要以确保软换行正确工作",
		},
		{
			name: "Mixed Chinese and English",
			line: "完成任务后检查tui工具完成状态以及长英文标识符ToolCompletionSummary",
		},
		{
			name: "Long path",
			line: "Created " + longPath,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			out := wrapToolDisplayLineWidth(tt.line, prefix, 48)
			if !strings.Contains(out, "\n") {
				t.Fatalf("expected wrapped output, got %q", out)
			}
			assertWrappedToolDisplayLines(t, out, prefix, 48)

			got := strings.ReplaceAll(out, "\n"+prefix, "")
			got = strings.ReplaceAll(got, "\n", "")
			want := strings.Join(strings.Fields(tt.line), "")
			if got != want {
				t.Fatalf("wrapped content changed: got %q, want %q", got, want)
			}
		})
	}
}

func TestWrapToolDisplayLineWidthPreservesANSIStyledContent(t *testing.T) {
	const prefix = "  │ "
	line := "\x1b[38;5;214m完成工具调用\x1b[0m \x1b[2mwith-an-uninterrupted-English-token-that-needs-wrapping\x1b[0m"

	out := wrapToolDisplayLineWidth(line, prefix, 48)
	assertWrappedToolDisplayLines(t, out, prefix, 48)

	got := strings.ReplaceAll(out, "\n"+prefix, "")
	got = strings.ReplaceAll(got, "\n", "")
	gotPlain := strings.Join(strings.Fields(stripANSI(got)), "")
	wantPlain := strings.Join(strings.Fields(stripANSI(line)), "")
	if gotPlain != wantPlain {
		t.Fatalf("ANSI-wrapped content changed: got %q, want %q", gotPlain, wantPlain)
	}
	if !strings.Contains(out, "\x1b[38;5;214m") || !strings.Contains(out, "\x1b[0m") {
		t.Fatalf("ANSI styling was not preserved: %q", out)
	}
}

// TestFoldedMultiLineToolHeaderKeepsEveryRowColoured drives a shell header
// that wraps onto several rows through the real fold path and pins what the
// viewport painter relies on: every continuation row keeps its prefix, opens
// the header foreground before any visible rune, and ends back in the default
// SGR state. The old wrapper left the opener on the first row only, so a row
// the damage painter redrew on its own came back terminal-white.
func TestFoldedMultiLineToolHeaderKeepsEveryRowColoured(t *testing.T) {
	forceColorProfile(t)
	r := newComposerRenderer(t, 100, 40)
	r.RenderFrame(Frame{Kind: FrameTool, Title: "shell", Content: "ok", Final: true,
		ToolMeta: tool.ToolMeta{Input: map[string]any{"command": longShellCommand}}})

	r.mu.Lock()
	defer r.mu.Unlock()
	// Leading header rows: the marker row plus every "  │ " continuation, up
	// to the "  └ " body marker.
	var headerRows []string
	for _, row := range r.vpPainted {
		plain := stripANSI(row)
		if strings.TrimSpace(plain) == "" || (!strings.HasPrefix(plain, "  │ ") && len(headerRows) > 0) {
			break
		}
		headerRows = append(headerRows, row)
	}
	if len(headerRows) < 3 {
		t.Fatalf("expected the header to wrap onto at least 3 rows, got %d: %q",
			len(headerRows), headerRows)
	}
	// The width/prefix budget is about the visible layout: normalisation
	// opens the carry before the prefix (zero-width), so assert on plain text.
	plainRows := make([]string, len(headerRows))
	for i, row := range headerRows {
		plainRows[i] = stripANSI(row)
	}
	assertWrappedToolDisplayLines(t, strings.Join(plainRows, "\n"), "  │ ", 100)
	for i, row := range headerRows {
		plain := plainRows[i]
		if i > 0 && !strings.HasPrefix(plain, "  │ ") {
			t.Fatalf("continuation row %d lost its prefix: %q", i, row)
		}
		if !opensSGRBeforeVisibleText(row) {
			t.Fatalf("row %d draws visible text before any SGR opener, so repainting it alone loses the header colour: %q", i, row)
		}
		if state := sgrStateAfter(row); state != "" {
			t.Fatalf("row %d leaves SGR %q in effect: %q", i, state, row)
		}
	}
}

// opensSGRBeforeVisibleText reports whether row carries an SGR sequence before
// its first visible rune, so the row opens the style it is drawn in.
func opensSGRBeforeVisibleText(row string) bool {
	opened := false
	for i := 0; i < len(row); {
		if row[i] == 0x1b {
			seq, n := paintEscapeSequence(row[i:])
			if n == 0 {
				i++
				continue
			}
			if seq[len(seq)-1] == 'm' && seq != "\x1b[0m" && seq != "\x1b[m" {
				opened = true
			}
			i += n
			continue
		}
		if row[i] == ' ' {
			i++
			continue
		}
		return opened
	}
	return false
}

func assertWrappedToolDisplayLines(t *testing.T, out, prefix string, width int) {
	t.Helper()
	firstWidth := width - contentRightMargin
	if firstWidth < 20 {
		firstWidth = 20
	}
	continuationWidth := width - contentRightMargin - displayLineWidth(prefix)
	if continuationWidth < 20 {
		continuationWidth = 20
	}

	for i, line := range strings.Split(out, "\n") {
		maxWidth := firstWidth
		content := line
		if i > 0 {
			if !strings.HasPrefix(line, prefix) {
				t.Fatalf("continuation line %d missing prefix: %q", i, line)
			}
			maxWidth = continuationWidth
			content = strings.TrimPrefix(line, prefix)
		}
		if gotWidth := displayLineWidth(content); gotWidth > maxWidth {
			t.Fatalf("line %d width %d exceeds max %d: %q", i, gotWidth, maxWidth, line)
		}
	}
}

func TestRetrieveOutputHeaderUsesReadableInputSummary(t *testing.T) {
	input := map[string]any{
		"category": "shell",
		"id":       4,
		"query":    "internal/clifacade/chat_session_permission_state.go",
		"reason":   "Recover the relevant diff.",
		"top":      5,
	}
	for _, test := range []struct {
		name   string
		status string
		final  bool
		want   string
	}{
		{name: "running", status: "running", want: "Searching saved output #4 matching “internal/clifacade/chat_session_permission_state.go”"},
		{name: "completed", status: "completed", final: true, want: "Searched saved output #4 matching “internal/clifacade/chat_session_permission_state.go”"},
	} {
		t.Run(test.name, func(t *testing.T) {
			header := ToolDisplayHeader(Frame{
				Kind: FrameTool, Title: "retrieve_output", Final: test.final,
				ToolMeta: tool.ToolMeta{ToolName: "retrieve_output", Status: test.status, Input: input},
			}, "")
			if header != test.want {
				t.Fatalf("header=%q want %q", header, test.want)
			}
			if strings.Contains(header, "{") || strings.Contains(header, `"reason"`) {
				t.Fatalf("header exposed raw JSON: %q", header)
			}
		})
	}
}

func TestRetrieveOutputBodyRendersAsMarkdownWithoutTransportEnvelope(t *testing.T) {
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	r.RenderFrame(Frame{
		Kind: FrameTool, Title: "retrieve_output", Final: true,
		Content: "# output 4 (`git diff`) — 2 matched groups\n130|first\n142|second",
		ToolMeta: tool.ToolMeta{
			ToolName: "retrieve_output", Status: "completed",
			Input: map[string]any{"id": 4, "query": "permission persistence"},
		},
	})
	for i := range r.vm.blocks {
		r.vm.blocks[i].expanded = true
	}
	view := renderViewport(&r.vm, 100, 30, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(view.lines, "\n"))
	for _, want := range []string{"output 4 (git diff)", "2 matched groups", "130|first", "142|second"} {
		if !strings.Contains(plain, want) {
			t.Fatalf("Markdown output missing %q:\n%s", want, plain)
		}
	}
	for _, unwanted := range []string{"output:", "# output", `"output"`, "```json"} {
		if strings.Contains(plain, unwanted) {
			t.Fatalf("output was not rendered as Markdown; found %q:\n%s", unwanted, plain)
		}
	}
}

