func TestRebuildFiltered_CursorClampsOnShrinking(t *testing.T) {
	t.Parallel()
	o := newSlashOverlay()
	o.rebuildFiltered(nil)
	total := len(o.Visible)
	if total < 3 {
		t.Skipf("registry has only %d commands; need >=3 for clamp test", total)
	}
	o.SelectedIdx = total - 1
	o.FilterText = "co"
	o.rebuildFiltered(nil)
	if o.SelectedIdx >= len(o.Visible) {
		t.Fatalf("cursor %d not clamped into Visible len %d", o.SelectedIdx, len(o.Visible))
	}
}

