func slashMenuPlain(p slashPanel, width, rows, top int) ([]string, panelLayout) {
	layout := p.layout(width, rows, top, true)
	var out []string
	for _, line := range layout.lines {
		out = append(out, stripAnsi(line))
	}
	return out, layout
}

func TestSlashMenuPanel_NilOrEmptyShowsNoMatchRow(t *testing.T) {
	t.Parallel()
	o := newSlashOverlay()
	o.FilterText = "zzz-nonexistent"
	o.rebuildFiltered(nil)
	for _, overlay := range []*SlashOverlay{nil, o} {
		if got, _ := slashMenuPlain(slashMenuPanel(overlay), 80, 0, 0); got[1] != "  No matching commands" {
			t.Fatalf("empty menu = %q", got)
		}
	}
}

// The slash menu lists the built-in commands and the skills under a heading
// each, built-ins first, the descriptions in one column; an exact match leads,
// so Enter runs what was typed.
func TestSlashMenuPanelGroupsCommandsAndSkills(t *testing.T) {
	o := &SlashOverlay{Visible: []turn.Command{
		{Name: "model", Description: "choose a model"},
		{Name: "new", Description: "start a new chat"},
		{Name: "caveman", Description: "talk less", Category: turn.SkillCategory},
	}}
	got, _ := slashMenuPlain(slashMenuPanel(o), 80, 0, 0)
	want := []string{
		"",
		"  Commands",
		"❯ /model    choose a model",
		"  /new      start a new chat",
		"",
		"  Skills",
		"  /caveman  talk less",
		"",
		"  ↑/↓ to navigate · Tab to complete · Enter to run · Esc to close",
	}
	if strings.Join(got, "\n") != strings.Join(want, "\n") {
		t.Fatalf("menu = %q, want %q", got, want)
	}

	turn.ResetDynamic()
	t.Cleanup(turn.ResetDynamic)
	skill := turn.DynamicCommand{
		Command: turn.Command{Name: "context-save", Description: "save", Category: turn.SkillCategory, AllowedSurfaces: []turn.Surface{turn.SurfaceTUI}, Visibility: turn.VisibilityPublic},
		Handler: func(turn.Context, string, []string) turn.Result { return turn.Result{Handled: true} },
	}
	if err := turn.ReplaceDynamicSource("test", []turn.DynamicCommand{skill}); err != nil {
		t.Fatal(err)
	}
	filtered := newSlashOverlay()
	filtered.FilterText = "context-save"
	filtered.rebuildFiltered(nil)
	if len(filtered.Visible) == 0 || filtered.Visible[0].Name != "context-save" {
		t.Fatalf("exact skill match does not lead: %v", filtered.Visible)
	}
}

// The menu takes the rows it is given whatever it lists, scrolls its body so
// the selected command shows whole — a heading is never left on screen
// without its first row under it — and keeps its key hint on screen. A
// description too long for the terminal wraps under its own column instead of
// being cut.
func TestSlashMenuPanelScrollsTheSelectionIntoView(t *testing.T) {
	o := &SlashOverlay{Visible: []turn.Command{
		{Name: "connect", Description: "configure or switch LLM provider"},
		{Name: "golang-continuous-integration", Description: "GitHub Actions CI/CD pipeline configuration for Golang projects with workflow files for test, lint and coverage jobs", Category: turn.SkillCategory},
	}}
	const hint = "  ↑/↓ to navigate · Tab to complete · Enter to run · Esc to close"
	got, layout := slashMenuPlain(slashMenuPanel(o), 80, 8, 0)
	want := []string{
		"",
		"  Commands",
		"❯ /connect                        configure or switch LLM provider",
		"",
		"  Skills",
		"  /golang-continuous-integration  GitHub Actions CI/CD pipeline configuration",
		"  ↓ 2 more",
		hint,
	}
	if strings.Join(got, "\n") != strings.Join(want, "\n") {
		t.Fatalf("menu = %q, want %q", got, want)
	}

	o.SelectedIdx = 1
	got, _ = slashMenuPlain(slashMenuPanel(o), 80, 8, layout.top)
	want = []string{
		"",
		"",
		"  Skills",
		"❯ /golang-continuous-integration  GitHub Actions CI/CD pipeline configuration",
		"                                  for Golang projects with workflow files for",
		"                                  test, lint and coverage jobs",
		"  ↑ 2 more",
		hint,
	}
	if strings.Join(got, "\n") != strings.Join(want, "\n") {
		t.Fatalf("menu = %q, want %q", got, want)
	}
}

// The @ mention menu takes a fixed eight lines around the selected row, and
// a row too long for the terminal wraps whole under its own text instead of
// being cut.
func TestComposerMenuLinesWrapRowsWholeAroundTheSelection(t *testing.T) {
	t.Parallel()
	r := &Renderer{}
	var rows []OverlayRow
	for i := 0; i < 20; i++ {
		rows = append(rows, OverlayRow{Lead: fmt.Sprintf("/cmd%02d  ", i), Text: "short"})
	}
	rows[12].Text = "a description long enough that it cannot fit on one forty-column row"
	rows[12].Selected = true
	lines := r.composerMenuLines(rows, 40)
	if len(lines) != composerMenuRows {
		t.Fatalf("menu takes %d lines, want %d: %q", len(lines), composerMenuRows, lines)
	}
	var plain []string
	for _, line := range lines {
		plain = append(plain, stripAnsi(line))
		if w := runewidth.StringWidth(stripAnsi(line)); w > 39 {
			t.Fatalf("line %q is %d columns, past the terminal", stripAnsi(line), w)
		}
	}
	joined := strings.Join(plain, "\n")
	if strings.Contains(joined, "…") || !strings.Contains(joined, "/cmd12  a description") {
		t.Fatalf("selected row not shown whole:\n%s", joined)
	}
	var body []string
	for _, line := range plain {
		if strings.HasPrefix(line, "  /cmd12") || (len(body) > 0 && strings.HasPrefix(line, strings.Repeat(" ", 10)) && !strings.HasPrefix(line, "  /cmd")) {
			body = append(body, strings.TrimSpace(strings.TrimPrefix(line, "  /cmd12")))
		}
	}
	if strings.Join(body, " ") != rows[12].Text {
		t.Fatalf("wrapped row reads %q, want %q", strings.Join(body, " "), rows[12].Text)
	}
	if !strings.Contains(joined, "/cmd11") || !strings.Contains(joined, "/cmd13") {
		t.Fatalf("rows around the selection are missing:\n%s", joined)
	}
}

