func TestOverlay_SelectedIdxWrapsForward(t *testing.T) {
	t.Parallel()
	o := newSlashOverlay()
	o.rebuildFiltered(nil)
	if len(o.Visible) < 2 {
		t.Skip("registry too small")
	}
	o.SelectedIdx = len(o.Visible) - 1
	o.SelectedIdx++
	if o.SelectedIdx < len(o.Visible) {
		t.Fatal("setup: bumped past end")
	}
	// Wrap logic mirrors run.go event-loop branch.
	if o.SelectedIdx >= len(o.Visible) {
		o.SelectedIdx = 0
	}
	if o.SelectedIdx != 0 {
		t.Fatalf("wrap-forward failed: SelectedIdx = %d", o.SelectedIdx)
	}
}

func TestOverlay_SelectedIdxWrapsBackward(t *testing.T) {
	t.Parallel()
	o := newSlashOverlay()
	o.rebuildFiltered(nil)
	if len(o.Visible) < 2 {
		t.Skip("registry too small")
	}
	o.SelectedIdx = 0
	o.SelectedIdx--
	if o.SelectedIdx < 0 {
		o.SelectedIdx = len(o.Visible) - 1
	}
	if o.SelectedIdx != len(o.Visible)-1 {
		t.Fatalf("wrap-backward failed: SelectedIdx = %d", o.SelectedIdx)
	}
}

// startsWithLower is a local helper for assertions.
func startsWithLower(s, prefix string) bool {
	if len(s) < len(prefix) {
		return false
	}
	for i := 0; i < len(prefix); i++ {
		a := s[i]
		b := prefix[i]
		if a >= 'A' && a <= 'Z' {
			a += 'a' - 'A'
		}
		if b >= 'A' && b <= 'Z' {
			b += 'a' - 'A'
		}
		if a != b {
			return false
		}
	}
	return true
}

func containsAll(s, needle string) bool {
	return len(needle) == 0 || (len(s) >= len(needle) && strings.Contains(s, needle))
}

