type lockedBuffer struct {
	mu sync.Mutex
	b  bytes.Buffer
}

func (l *lockedBuffer) Write(p []byte) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.Write(p)
}

func (l *lockedBuffer) String() string {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.String()
}

func TestSanitizeTerminalTitleText(t *testing.T) {
	in := "hello\x1b]0;evil\x07world\nnext\rline\x7f"
	got := sanitizeTerminalTitleText(in)
	if strings.ContainsAny(got, "\x1b\x07\n\r\x7f") {
		t.Fatalf("sanitized title still contains control bytes: %q", got)
	}
	if got == "" {
		t.Fatalf("sanitized title must keep printable text")
	}
}

func TestTerminalTitleAnimatorAnimateAndSettle(t *testing.T) {
	buf := &lockedBuffer{}
	a := newTerminalTitleAnimator(buf)
	a.Animate("优化 Forebrain Harness agent 的记忆机制")
	first := buf.String()
	if !strings.Contains(first, "\x1b]0;") || !strings.Contains(first, "优化 Forebrain Harness agent 的记忆机制\x07") {
		t.Fatalf("expected immediate animated frame, got %q", first)
	}
	// The animated frame must lead with the Braille spinner glyph, not the
	// half-moon set other agents use in their titles.
	if !strings.Contains(first, spinnerGlyphs[0]+" 优化") {
		t.Fatalf("expected braille spinner glyph in frame, got %q", first)
	}

	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) && strings.Count(buf.String(), "\x1b]0;") < 3 {
		time.Sleep(20 * time.Millisecond)
	}
	if strings.Count(buf.String(), "\x1b]0;") < 3 {
		t.Fatalf("expected animated frames on tick, got %q", buf.String())
	}

	a.Settle("优化 Forebrain Harness agent 的记忆机制")
	out := buf.String()
	if !strings.HasSuffix(out, "\x1b]0;优化 Forebrain Harness agent 的记忆机制\x07") {
		t.Fatalf("expected static title last, got %q", out)
	}
	settled := strings.Count(buf.String(), "\x1b]0;")
	time.Sleep(3 * terminalTitleTick)
	if got := strings.Count(buf.String(), "\x1b]0;"); got != settled {
		t.Fatalf("animation kept writing after Settle: %d -> %d", settled, got)
	}
}

