func TestParseOSC11Response(t *testing.T) {
	tests := []struct {
		name     string
		response string
		wantDark bool
		wantOk   bool
	}{
		{
			name:     "dark background 16-bit",
			response: "\x1b]11;rgb:1111/1111/1111\x1b\\",
			wantDark: true,
			wantOk:   true,
		},
		{
			name:     "light background 16-bit",
			response: "\x1b]11;rgb:ffff/ffff/ffff\x1b\\",
			wantDark: false,
			wantOk:   true,
		},
		{
			name:     "dark background 8-bit",
			response: "\x1b]11;rgb:20/20/20\x07",
			wantDark: true,
			wantOk:   true,
		},
		{
			name:     "light background 8-bit",
			response: "\x1b]11;rgb:ff/ff/ff\x07",
			wantDark: false,
			wantOk:   true,
		},
		{
			name:     "mid-gray (should be dark)",
			response: "\x1b]11;rgb:7f/7f/7f\x1b\\",
			wantDark: true,
			wantOk:   true,
		},
		{
			name:     "no rgb prefix",
			response: "\x1b]11;something\x1b\\",
			wantDark: false,
			wantOk:   false,
		},
		{
			name:     "malformed rgb",
			response: "\x1b]11;rgb:ff/ff\x1b\\",
			wantDark: false,
			wantOk:   false,
		},
		{
			name:     "invalid hex",
			response: "\x1b]11;rgb:gg/hh/ii\x1b\\",
			wantDark: false,
			wantOk:   false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			gotDark, gotOk := parseOSC11Response(tt.response)
			if gotOk != tt.wantOk {
				t.Errorf("parseOSC11Response() ok = %v, want %v", gotOk, tt.wantOk)
			}
			if gotOk && gotDark != tt.wantDark {
				t.Errorf("parseOSC11Response() dark = %v, want %v", gotDark, tt.wantDark)
			}
		})
	}
}

func TestProbeDarkBackgroundBounded_Timeout(t *testing.T) {
	// This test verifies the timeout mechanism works
	// In a non-terminal environment (CI), the probe should timeout quickly
	start := time.Now()
	isDark, ok := probeDarkBackgroundBounded(50 * time.Millisecond)
	elapsed := time.Since(start)

	// Should return false, false (no terminal or timeout)
	if ok {
		t.Errorf("probeDarkBackgroundBounded() in non-terminal should return ok=false, got ok=true, isDark=%v", isDark)
	}

	// Should complete within reasonable time (not hang for 5s like termenv would)
	if elapsed > 500*time.Millisecond {
		t.Errorf("probeDarkBackgroundBounded() took %v, expected < 500ms", elapsed)
	}
}

// A terminal query must never leave a read in flight. The probe used to hand
// its read to a goroutine and walk away at the timeout; a Read() blocked on a
// tty cannot be cancelled, so that goroutine stayed live for the rest of the
// session and ate the next thing the user typed.
func TestReadOSC11ResponseStopsReadingWhenItGivesUp(t *testing.T) {
	if !canGateTerminalReads {
		t.Skip("terminal reads cannot be gated on readiness on this platform")
	}
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("os.Pipe: %v", err)
	}
	defer r.Close()
	defer w.Close()

	if dark, ok := readOSC11Response(r, 50*time.Millisecond); ok {
		t.Fatalf("silent terminal reported an answer (dark=%v)", dark)
	}

	// Whatever arrives after the probe gave up belongs to the input pipeline.
	const typed = "read it"
	if _, err := w.Write([]byte(typed)); err != nil {
		t.Fatalf("write: %v", err)
	}
	got, err := readAllAvailableForTest(r, len(typed))
	if err != nil {
		t.Fatalf("read back: %v", err)
	}
	if got != typed {
		t.Fatalf("input typed after the probe gave up arrived as %q, want %q", got, typed)
	}
}

// A silent terminal costs at most the one byte that proved it silent: the rest
// of a type-ahead burst has to stay in the stream, because there is no way to
// put a byte back into a tty.
func TestReadOSC11ResponseLeavesTypeAheadBehind(t *testing.T) {
	if !canGateTerminalReads {
		t.Skip("terminal reads cannot be gated on readiness on this platform")
	}
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("os.Pipe: %v", err)
	}
	defer r.Close()
	defer w.Close()

	if _, err := w.Write([]byte("read it")); err != nil {
		t.Fatalf("write: %v", err)
	}
	if dark, ok := readOSC11Response(r, 200*time.Millisecond); ok {
		t.Fatalf("typed text was parsed as an answer (dark=%v)", dark)
	}
	got, err := readAllAvailableForTest(r, len("ead it"))
	if err != nil {
		t.Fatalf("read back: %v", err)
	}
	if got != "ead it" {
		t.Fatalf("probe consumed %q of the typed text, want it to stop after the first byte", "read it"[:len("read it")-len(got)])
	}
}

func TestReadOSC11ResponseParsesAnAnswerSplitAcrossWrites(t *testing.T) {
	if !canGateTerminalReads {
		t.Skip("terminal reads cannot be gated on readiness on this platform")
	}
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("os.Pipe: %v", err)
	}
	defer r.Close()
	defer w.Close()

	go func() {
		_, _ = w.Write([]byte("\x1b]11;rgb:1a1a"))
		time.Sleep(10 * time.Millisecond)
		_, _ = w.Write([]byte("/1a1a/1a1a\x1b\\"))
	}()

	dark, ok := readOSC11Response(r, time.Second)
	if !ok {
		t.Fatal("an answer delivered in two writes was not parsed")
	}
	if !dark {
		t.Fatal("rgb:1a1a/1a1a/1a1a is a dark background")
	}
}

// The answer has to be consumed to its terminator. Its colour triple parses
// while the last component is still arriving, and stopping there left the tail
// of the reply in the tty for the input pipeline to read as keystrokes: a
// composer that opened holding "a43".
func TestReadOSC11ResponseConsumesTheWholeAnswer(t *testing.T) {
	if !canGateTerminalReads {
		t.Skip("terminal reads cannot be gated on readiness on this platform")
	}
	for _, answer := range []string{
		"\x1b]11;rgb:1e1e/1e1e/2a43\x1b\\",
		"\x1b]11;rgb:20/20/20\x07",
	} {
		t.Run(strconv.Quote(answer), func(t *testing.T) {
			r, w, err := os.Pipe()
			if err != nil {
				t.Fatalf("os.Pipe: %v", err)
			}
			defer r.Close()
			defer w.Close()

			if _, err := w.Write([]byte(answer)); err != nil {
				t.Fatalf("write: %v", err)
			}
			dark, ok := readOSC11Response(r, time.Second)
			if !ok {
				t.Fatalf("answer %q was not parsed", answer)
			}
			if !dark {
				t.Fatalf("answer %q is a dark background", answer)
			}

			// Anything still in the stream is the tail of the answer, and the
			// input pipeline would show it as typed characters.
			leftover, err := readAllAvailableForTest(r, 1)
			if err != nil {
				t.Fatalf("read back: %v", err)
			}
			if leftover != "" {
				t.Fatalf("probe left %q of the answer in the stream", leftover)
			}
		})
	}
}

// Leaving lipgloss unpinned is not inert: the first AdaptiveColor render makes
// it ask termenv, which queries the terminal and then reads the terminal fd
// itself, discarding everything that is not the ESC it wants — keystrokes
// included. Every theme, DiffThemeUnknown included, has to pin a value.
func TestApplyDiffThemePinsLipglossForEveryTheme(t *testing.T) {
	restore := lipgloss.HasDarkBackground()
	t.Cleanup(func() { lipgloss.SetHasDarkBackground(restore) })

	for _, tc := range []struct {
		name  string
		theme DiffTheme
		want  bool
	}{
		{"dark", DiffThemeDark, true},
		{"light", DiffThemeLight, false},
		{"unknown", DiffThemeUnknown, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			// Start from the opposite value: a theme that pins nothing would
			// leave this one standing.
			lipgloss.SetHasDarkBackground(!tc.want)
			ApplyDiffTheme(tc.theme)
			if got := lipgloss.HasDarkBackground(); got != tc.want {
				t.Fatalf("ApplyDiffTheme(%v) left lipgloss at dark=%v, want %v", tc.theme, got, tc.want)
			}
		})
	}
}

// The one byte that proved the terminal silent is the user's. It cannot go back
// into the tty, so it has to reach the input pipeline instead of being dropped.
func TestReadOSC11ResponseHandsTypeAheadToTheInputPipeline(t *testing.T) {
	if !canGateTerminalReads {
		t.Skip("terminal reads cannot be gated on readiness on this platform")
	}
	t.Cleanup(func() { takePendingTerminalInput() })
	takePendingTerminalInput()

	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("os.Pipe: %v", err)
	}
	defer r.Close()
	defer w.Close()

	if _, err := w.Write([]byte("hello")); err != nil {
		t.Fatalf("write: %v", err)
	}
	if _, ok := readOSC11Response(r, 200*time.Millisecond); ok {
		t.Fatal("typed text was parsed as an answer")
	}

	carried := string(takePendingTerminalInput())
	rest, err := readAllAvailableForTest(r, len("ello"))
	if err != nil {
		t.Fatalf("read back: %v", err)
	}
	if carried+rest != "hello" {
		t.Fatalf("the input pipeline would see %q, want the whole %q", carried+rest, "hello")
	}
}

// readAllAvailableForTest reads until want bytes have arrived or the pipe goes
// quiet, so a test can assert on what a probe did and did not consume.
func readAllAvailableForTest(r *os.File, want int) (string, error) {
	var got []byte
	buf := make([]byte, 64)
	for len(got) < want {
		readable, err := pollReadableInputFD(int(r.Fd()), 200)
		if err != nil {
			return string(got), err
		}
		if !readable {
			break
		}
		n, err := r.Read(buf)
		got = append(got, buf[:n]...)
		if err != nil {
			return string(got), err
		}
	}
	return string(got), nil
}

func TestFanoutHeaderIncludesExecutorDurationOnlyWhenFinal(t *testing.T) {
	var out strings.Builder
	r := NewRenderer(&out, &out)
	r.renderFanout(Frame{Kind: FrameFanout, Final: true, Summary: "Ran 2 tasks", Duration: 1250 * time.Millisecond})
	if got := stripANSI(out.String()); !strings.Contains(got, "Ran 2 tasks · 1.2s") {
		t.Fatalf("final fanout header missing duration: %q", got)
	}

	out.Reset()
	r.renderFanout(Frame{Kind: FrameFanout, Final: false, Summary: "Running 2 tasks…", Duration: 1250 * time.Millisecond})
	if got := stripANSI(out.String()); strings.Contains(got, "1.2s") {
		t.Fatalf("running fanout header unexpectedly includes duration: %q", got)
	}
}

func TestCompletedToolFrameUsesSuppliedDurationWithoutStartEvent(t *testing.T) {
	var reducer Reducer
	frames := reducer.Reduce(NewMessageMsg{Msg: Message{
		Kind:      MsgKindTool,
		StepID:    "read-1",
		ToolName:  "read_file",
		ToolMeta:  tool.ToolMeta{ToolName: "read_file", Status: "completed"},
		ToolPhase: "tool_call_completed",
		Duration:  150 * time.Millisecond,
		Timestamp: time.Now(),
	}}).Frames
	if len(frames) != 1 {
		t.Fatalf("expected one frame, got %#v", frames)
	}
	if got := frames[0].Duration; got != 150*time.Millisecond {
		t.Fatalf("duration = %s, want 150ms", got)
	}
	if header := ToolDisplayHeader(frames[0], ""); !strings.Contains(header, "0.1s") {
		t.Fatalf("header = %q, want supplied duration", header)
	}
}

