// Bare Up remains history navigation even when queued input exists. Queue recall
// is reserved for Shift+Left.
func TestBareUpWithEditableQueuedInputBrowsesHistory(t *testing.T) {
	drainInteractiveInputSeedQueue()
	editableQueuedInputActive.Store(true)
	t.Cleanup(func() { editableQueuedInputActive.Store(false) })

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("pipe error: %v", err)
	}
	defer r.Close()

	events := readRawInputEvents(ctx, r, io.Discard, stubRawInputController{}, testRawInputHistoryStore{history: []string{"older entry"}})
	if _, err := w.Write([]byte("\x1b[A")); err != nil {
		t.Fatalf("write up: %v", err)
	}
	var draft inputEvent
	for {
		ev, ok := <-events
		if !ok {
			t.Fatal("channel closed before draft event")
		}
		if ev.kind == inputEventHotkey && ev.hotkey == hotkeyEditLastQueued {
			t.Fatalf("bare up must browse history, got edit hotkey")
		}
		if ev.kind == inputEventDraft {
			draft = ev
			break
		}
	}
	if draft.draft != "older entry" {
		t.Fatalf("expected history recall %q, got %q", "older entry", draft.draft)
	}
	_ = w.Close()
}

