// A second Up while already browsing history must keep browsing even when
// queued input exists — only the first press at an empty composer is an edit
// gesture.
func TestUpWhileBrowsingHistoryKeepsBrowsing(t *testing.T) {
	drainInteractiveInputSeedQueue()
	editableQueuedInputActive.Store(false)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("pipe error: %v", err)
	}
	defer r.Close()

	events := readRawInputEvents(ctx, r, io.Discard, stubRawInputController{}, testRawInputHistoryStore{history: []string{"first", "second"}})
	if _, err := w.Write([]byte("\x1b[A")); err != nil {
		t.Fatalf("write up: %v", err)
	}
	var draft inputEvent
	for {
		ev, ok := <-events
		if !ok {
			t.Fatal("channel closed before draft event")
		}
		if ev.kind == inputEventDraft {
			draft = ev
			break
		}
	}
	if draft.draft != "second" {
		t.Fatalf("expected first recall %q, got %q", "second", draft.draft)
	}

	// Queue becomes editable mid-browse; the next Up must still browse.
	editableQueuedInputActive.Store(true)
	t.Cleanup(func() { editableQueuedInputActive.Store(false) })
	if _, err := w.Write([]byte("\x1b[A")); err != nil {
		t.Fatalf("write up: %v", err)
	}
	for {
		ev, ok := <-events
		if !ok {
			t.Fatal("channel closed before second draft event")
		}
		if ev.kind == inputEventHotkey && ev.hotkey == hotkeyEditLastQueued {
			t.Fatalf("up mid-browse must keep browsing history, got edit hotkey")
		}
		if ev.kind == inputEventDraft {
			draft = ev
			break
		}
	}
	if draft.draft != "first" {
		t.Fatalf("expected deeper recall %q, got %q", "first", draft.draft)
	}
	_ = w.Close()
}

// The user card renderer ends with an erase-in-line spacer row so the
// append-only path is not glued to the activity area below it. In viewport mode
// renderViewport already separates blocks with one blank row, so that spacer
// must be trimmed with the block's other trailing blanks - otherwise the card
// sits two blank rows above whatever follows it.
func TestUserMessageCardHasSingleBlankRowBelow(t *testing.T) {
	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()

	r.RenderFrame(Frame{Kind: FrameUser, Content: "change the fetch call"})
	r.RenderFrame(Frame{Kind: FrameThinking, Content: "Reasoning about the change.", Final: true})

	lines := renderViewport(&r.vm, 100, 60, 0, DiffThemeDark).allLines
	card := -1
	for i, line := range lines {
		if strings.Contains(line, composerPromptMarker) {
			card = i
			break
		}
	}
	if card < 0 {
		t.Fatalf("user card not rendered:\n%s", strings.Join(lines, "\n"))
	}
	// card, bottom border, exactly one blank row, then the next block.
	blank := card + 2
	if blank >= len(lines) || !isBlankRow(lines[blank]) {
		t.Fatalf("expected a blank row at %d, got %q", blank, lines[blank])
	}
	if next := blank + 1; next >= len(lines) || isBlankRow(lines[next]) {
		t.Fatalf("expected content directly after the blank row, rows:\n%q", lines[card:])
	}
}

func isBlankRow(line string) bool {
	return strings.TrimSpace(blankRowPattern.ReplaceAllString(line, "")) == ""
}

// The floating control announces messages that arrived below the viewport while
// the user was reading history: " 1 new message (ctrl+End) ↓ ". Reaching the
// bottom by any route marks them read and restores the plain label.

func TestNewMessageBadgeCountsMessagesArrivingWhileScrolledUp(t *testing.T) {
	r, out := newScrolledJumpToBottomRenderer(t)

	out.Reset()
	r.RenderFrame(Frame{Kind: FrameAssistant, Content: "first reply", Final: true})
	if got := stripAnsi(out.String()); !strings.Contains(got, "1 new message (ctrl+End) ↓") {
		t.Fatalf("one new message should be announced; output=%q", got)
	}

	out.Reset()
	r.RenderFrame(Frame{Kind: FrameAssistant, Content: "second reply", Final: true})
	r.RenderFrame(Frame{Kind: FrameUser, Content: "queued question"})
	got := stripAnsi(out.String())
	if !strings.Contains(got, "3 new messages (ctrl+End) ↓") {
		t.Fatalf("three new messages should be announced in plural; output=%q", got)
	}
	if r.vpFollow {
		t.Fatal("arriving messages must not yank a scrolled-up viewport to the bottom")
	}
}

func TestNewMessageBadgeStaysSilentWhileFollowing(t *testing.T) {
	r, out := newScrolledJumpToBottomRenderer(t)
	r.ViewportJumpToBottom()

	out.Reset()
	r.RenderFrame(Frame{Kind: FrameAssistant, Content: "streamed at the bottom", Final: true})
	if got := stripAnsi(out.String()); strings.Contains(got, "new message") {
		t.Fatalf("messages seen at the bottom need no badge; output=%q", got)
	}
	if r.vpNewMessages != 0 {
		t.Fatalf("unseen count=%d, want 0 while following", r.vpNewMessages)
	}
}

