// TestRuneIndexAtVisualColCoversWideAndNarrow verifies the column->rune-index
// helper used to map mouse clicks to runes.
func TestRuneIndexAtVisualColCoversWideAndNarrow(t *testing.T) {
	runes := []rune("a你b")
	// 'a' at cells [0,1), '你' at [1,3), 'b' at [3,4)
	cases := []struct {
		col, want int
	}{
		{0, 0}, // 'a'
		{1, 1}, // '你' (first cell)
		{2, 1}, // '你' (second cell)
		{3, 2}, // 'b'
		{4, 3}, // past end
		{-1, 0},
	}
	for _, c := range cases {
		if got := runeIndexAtVisualCol(runes, c.col); got != c.want {
			t.Fatalf("runeIndexAtVisualCol(%d) = %d, want %d", c.col, got, c.want)
		}
	}
}

// TestVisualColAtRuneIndexSumsDisplayWidth verifies rune-index->column
// conversion so word boundaries are stored as visual columns.
func TestVisualColAtRuneIndexSumsDisplayWidth(t *testing.T) {
	runes := []rune("a你b")
	cases := []struct {
		idx, want int
	}{
		{0, 0},
		{1, 1}, // after 'a'
		{2, 3}, // after '你' (2 cells)
		{3, 4}, // after 'b'
		{4, 4}, // clamped past end
	}
	for _, c := range cases {
		if got := visualColAtRuneIndex(runes, c.idx); got != c.want {
			t.Fatalf("visualColAtRuneIndex(%d) = %d, want %d", c.idx, got, c.want)
		}
	}
}

// TestViewportSelectEndPersistsSelectionAfterCopy guards the native-terminal
// selection model: after a drag-select copy the selection anchors MUST persist
// (highlight stays until the user clicks elsewhere) while the mouse-button flag
// selectDragging is released so the composer cursor is restored. The cursor is
// no longer coupled to the highlight (paintViewportLocked hides the caret only
// while selectDragging, not while a selection merely exists). A subsequent
// single-click press dismisses the persisted selection.
func TestViewportSelectEndPersistsSelectionAfterCopy(t *testing.T) {
	r := NewRenderer(nil, nil)
	r.viewportMode = true
	r.composerSuppressed = true

	r.vm.append(Frame{Kind: FrameStatus, Content: "line one"})
	r.vpBodyHeight = 5
	r.vpHeight = 5
	r.vpLastRender = renderViewport(&r.vm, 80, 5, 0, DiffThemeDark)

	// Simulate a completed drag: start then end.
	r.ViewportSelectStart(0, 0)
	r.ViewportSelectDrag(8, 0)
	r.ViewportSelectEnd(8, 0)

	// The selection must persist (native-terminal model): anchors remain set so
	// the highlight stays, while the button is released so the cursor shows.
	if r.selectStartRow < 0 {
		t.Fatalf("selection should persist after copy, got selectStartRow=%d", r.selectStartRow)
	}
	if r.selectDragging {
		t.Fatal("selectDragging should be false after release even while the selection persists")
	}
}

// TestViewportSelectEndRepositionsCursorToComposer guards bug 2 end-to-end via
// the actual paint output: after a copy, the rendered viewport must reposition
// the hardware cursor to the composer prompt (\x1b[?25h at the prompt cell),
// not leave it hidden (\x1b[?25l) which stranded it at the footer's right edge.
func TestViewportSelectEndRepositionsCursorToComposer(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)
	out.Reset()

	cursor := 0
	r.RenderComposerState(ComposerRenderState{Text: "", Cursor: &cursor})

	// Seed a visible transcript line to select.
	r.RenderFrame(Frame{Kind: FrameStatus, Content: "selectable line", Final: true})

	// Perform a drag selection + copy.
	r.ViewportSelectStart(0, 0)
	r.ViewportSelectDrag(8, 0)
	out.Reset()
	r.ViewportSelectEnd(8, 0)

	repaint := out.String()
	// The cursor must be shown (\x1b[?25h) and repositioned to the composer
	// prompt via a CPR-style \x1b[<row>;<col>H. It must NOT be left hidden.
	if !strings.Contains(repaint, "\x1b[?25h") {
		t.Fatalf("after copy, cursor should be shown (\\x1b[?25h) at the composer prompt; output:\n%q", repaint)
	}
	if !strings.Contains(repaint, "\x1b[") || !strings.Contains(repaint, "H") {
		t.Fatalf("after copy, cursor should be repositioned via \\x1b[<row>;<col>H; output:\n%q", repaint)
	}
	if strings.HasSuffix(strings.TrimSpace(repaint), "\x1b[?25l") {
		t.Fatalf("after copy, paint must not end with cursor-hidden (\\x1b[?25l); output:\n%q", repaint)
	}
	// The selection must persist (native-terminal model): anchors remain set so
	// the highlight stays, while the button is released so the cursor shows.
	if r.selectStartRow < 0 {
		t.Fatalf("selection should persist after copy, got selectStartRow=%d", r.selectStartRow)
	}
	if r.selectDragging {
		t.Fatal("selectDragging should be false after release even while the selection persists")
	}
}

// TestViewportCursorBlinkPreservedWhileStreaming locks in the native-blink fix.
// While the agent streams, paintViewportLocked runs many times per second but
// the composer caret does not move. Re-issuing DECTCEM show (\x1b[?25h) on
// every paint restarts the terminal's blink timer (iTerm2 / Terminal.app) and
// freezes the caret solid - the reported "cursor doesn't blink during a
// conversation" bug. After the fix a steady-state paint emits only the
// cursor-position sequence (CUP) and never ?25h/?25l; ?25h is reserved for an
// actual visibility transition (e.g. releasing a mouse-drag selection).
func TestViewportCursorBlinkPreservedWhileStreaming(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	cursor := 0
	r.RenderComposerState(ComposerRenderState{Text: "", Cursor: &cursor})
	out.Reset()

	// Paint twice at the same caret cell; the second paint must be steady.
	r.RenderComposerState(ComposerRenderState{Text: "", Cursor: &cursor})
	first := out.String()
	out.Reset()
	r.RenderComposerState(ComposerRenderState{Text: "", Cursor: &cursor})
	second := out.String()

	for _, s := range []string{first, second} {
		if strings.Contains(s, "\x1b[?25l") {
			t.Fatalf("steady composer paint should not hide cursor (\\x1b[?25l), got:\n%q", s)
		}
		if strings.Contains(s, "\x1b[?25h") {
			t.Fatalf("steady composer paint should not re-show cursor (\\x1b[?25h), got:\n%q", s)
		}
		if !strings.Contains(s, "H") {
			t.Fatalf("steady composer paint should still position cursor via CUP, got:\n%q", s)
		}
	}
}

// TestSoftwareCursorHidesHardwareAndPaintsBlock verifies that enabling the
// software cursor hides the hardware caret and paints a reverse-video block at
// the composer prompt.
func TestSoftwareCursorHidesHardwareAndPaintsBlock(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	cursor := 0
	r.RenderComposerState(ComposerRenderState{Text: "", Cursor: &cursor})
	out.Reset()

	r.EnableSoftwareCursor()
	if !strings.Contains(out.String(), "\x1b[?25l") {
		t.Fatalf("EnableSoftwareCursor should hide hardware cursor (\\x1b[?25l), got:\n%q", out.String())
	}
	out.Reset()

	r.RenderComposerState(ComposerRenderState{Text: "hi", Cursor: &cursor})
	paint := out.String()
	if !strings.Contains(paint, "\x1b[7m") {
		t.Fatalf("software cursor should paint reverse-video block (\\x1b[7m), got:\n%q", paint)
	}
	if strings.Contains(paint, "\x1b[?25h") {
		t.Fatalf("software cursor should never re-show hardware cursor, got:\n%q", paint)
	}
}

// TestSoftwareCursorBlinkToggle verifies the 500ms ticker toggles the
// reverse-video block on and off, producing a blinking caret.
func TestSoftwareCursorBlinkToggle(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	cursor := 0
	r.RenderComposerState(ComposerRenderState{Text: "hi", Cursor: &cursor})
	out.Reset()

	r.EnableSoftwareCursor()
	out.Reset()

	r.RenderComposerState(ComposerRenderState{Text: "hi", Cursor: &cursor})

	// cursorBlinkVisible starts true -> block is painted.
	r.mu.Lock()
	if !r.cursorBlinkVisible {
		t.Fatal("cursorBlinkVisible should start true after EnableSoftwareCursor")
	}
	// Manually toggle to simulate the ticker's off phase.
	r.cursorBlinkVisible = false
	out.Reset()
	r.paintViewportLocked()
	offPaint := out.String()
	r.mu.Unlock()

	// In the off phase the reverse-video block must NOT be painted.
	if strings.Contains(offPaint, "\x1b[7m") {
		t.Fatalf("off-phase paint must not paint the reverse-video block, got:\n%q", offPaint)
	}
	// But the hardware cursor must still be hidden (no ?25h).
	if strings.Contains(offPaint, "\x1b[?25h") {
		t.Fatalf("off-phase paint must not emit \\x1b[?25h, got:\n%q", offPaint)
	}
}

// TestSoftwareCursorBlinkOffRepositionsCaret guards the pinyin-IME jump bug.
// In the blink-off phase the software cursor must STILL emit a CUP to the caret
// cell. Previously the off phase emitted nothing, so the (hidden) hardware
// cursor stayed at the footer's right edge - the last cell written by the
// repaint. An inline IME (pinyin) anchors its preedit at the hardware cursor,
// so it drew the pinyin there, overflowed the bottom screen row and scrolled
// the viewport up every 500ms: the TUI jumped while typing pinyin, and a stray
// third caret appeared after "xxxxx tokens". After the fix every frame
// repositions the cursor at the caret, matching the hardware-cursor path.
func TestSoftwareCursorBlinkOffRepositionsCaret(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	cursor := 2
	r.RenderComposerState(ComposerRenderState{Text: "hi", Cursor: &cursor})
	r.EnableSoftwareCursor()
	out.Reset()

	r.mu.Lock()
	r.cursorBlinkVisible = false // simulate the ticker's off phase
	r.paintViewportLocked()
	offPaint := out.String()
	r.mu.Unlock()

	// The caret cell the on-phase would paint at, in 1-based screen coords.
	wantRow := r.vpBodyHeight + r.vpLastComposer.cursorRow + 1
	wantCol := r.vpLastComposer.cursorCol + 1
	wantCUP := fmt.Sprintf("\x1b[%d;%dH", wantRow, wantCol)
	if !strings.Contains(offPaint, wantCUP) {
		t.Fatalf("off-phase paint must reposition the cursor at the caret (%q), "+
			"otherwise an inline IME drifts its preedit to the footer and the "+
			"viewport jumps. got:\n%q", wantCUP, offPaint)
	}
	// The reverse-video block is still only painted on the visible phase.
	if strings.Contains(offPaint, "\x1b[7m") {
		t.Fatalf("off-phase paint must not paint the reverse-video block, got:\n%q", offPaint)
	}
	if strings.Contains(offPaint, "\x1b[?25h") {
		t.Fatalf("off-phase paint must not emit \\x1b[?25h, got:\n%q", offPaint)
	}
}

// TestTallComposerClampsHeightAndKeepsCursorOnScreen guards the bug where a
// very tall composer (large pasted content) grew beyond the terminal height and
// pushed the hardware cursor into the footer row.
func TestTallComposerClampsHeightAndKeepsCursorOnScreen(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 10
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	// Build a 20-line composer; with a 10-row terminal the composer area is
	// capped to height - minBodyHeight = 7 rows.
	var lines []string
	for i := 0; i < 20; i++ {
		lines = append(lines, "line-"+strings.Repeat("x", i))
	}
	text := strings.Join(lines, "\n")
	cursor := len([]rune(text))

	r.RenderComposerState(ComposerRenderState{Text: text, Cursor: &cursor})

	maxComposerHeight := forcedTermHeight / 3 // minBodyHeight = max(height/3,3) = 3
	if forcedTermHeight/3 < 3 {
		maxComposerHeight = 3
	}
	maxComposerHeight = forcedTermHeight - maxComposerHeight // 7

	if got := len(r.vpLastComposer.lines); got > maxComposerHeight {
		t.Fatalf("tall composer should be clamped to at most %d visible rows, got %d", maxComposerHeight, got)
	}
	if r.vpLastComposer.fullLines == nil {
		t.Fatal("tall composer should preserve fullLines for selection lookup")
	}
	if r.composerScrollOffset <= 0 {
		t.Fatalf("tall composer should have a positive scroll offset to keep the cursor visible, got %d", r.composerScrollOffset)
	}
	if r.cursorScreenRow <= 0 || r.cursorScreenRow > forcedTermHeight {
		t.Fatalf("hardware cursor must stay inside the terminal (%d rows), got row %d", forcedTermHeight, r.cursorScreenRow)
	}
	// The cursor must be on a visible composer row.
	if got := r.vpBodyHeight + r.vpLastComposer.cursorRow + 1; got != r.cursorScreenRow {
		t.Fatalf("cursor screen row mismatch: bodyHeight=%d visibleCursorRow=%d -> %d, got %d",
			r.vpBodyHeight, r.vpLastComposer.cursorRow, got, r.cursorScreenRow)
	}
}

// TestTallComposerSelectionMapsToScrolledLine verifies that mouse selection in
// a scrolled composer resolves to the correct logical line rather than the
// top of the full composer block.
func TestTallComposerSelectionMapsToScrolledLine(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 10
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	r := NewRenderer(nil, nil)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	var lines []string
	for i := 0; i < 20; i++ {
		lines = append(lines, "line-"+strings.Repeat("x", i))
	}
	text := strings.Join(lines, "\n")
	cursor := len([]rune(text))
	r.RenderComposerState(ComposerRenderState{Text: text, Cursor: &cursor})

	// Pick a visible composer row (the second row of the visible slice).
	visibleRow := r.vpBodyHeight + 1
	if visibleRow >= r.vpBodyHeight+len(r.vpLastComposer.lines) {
		t.Fatalf("test assumes at least two visible composer rows")
	}

	r.ViewportSelectStart(0, visibleRow)
	r.ViewportSelectDrag(4, visibleRow)

	got := r.extractSelectedTextLocked()
	want := stripAnsi(r.vpLastComposer.lines[visibleRow-r.vpBodyHeight])
	if got != want[:4] {
		t.Fatalf("selection on scrolled composer extracted wrong text: got %q, want first 4 chars of visible line %q", got, want)
	}
}

// TestTallComposerMouseWheelScrollsComposer verifies that wheel events over
// the composer area scroll the composer itself when it is taller than its
// allocated area. The cursor is placed at the top of the content so the
// auto-scroll logic does not immediately pull the offset back down.
func TestTallComposerMouseWheelScrollsComposer(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 10
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	r := NewRenderer(nil, nil)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	var lines []string
	for i := 0; i < 20; i++ {
		lines = append(lines, "line-"+strings.Repeat("x", i))
	}
	text := strings.Join(lines, "\n")
	cursor := 0 // at the top of the composer content
	r.RenderComposerState(ComposerRenderState{Text: text, Cursor: &cursor})

	if r.composerScrollOffset != 0 {
		t.Fatalf("expected composer to start unscrolled, got offset %d", r.composerScrollOffset)
	}
	// Wheel down over the composer area should scroll toward the bottom.
	r.ViewportScrollAt(1, 0, r.vpBodyHeight)
	if r.composerScrollOffset != 1 {
		t.Fatalf("wheel down should increase composer scroll offset by 1, got %d", r.composerScrollOffset)
	}
}

// TestStripAnsiSGRMouse guards that stripAnsi removes SGR mouse sequences
// (ESC [ < ... M or ESC [ < ... m) which could otherwise leak into the
// clipboard text as trailing garbage like "[<35;42;28M".
func TestStripAnsiSGRMouse(t *testing.T) {
	cases := []struct {
		input string
		want  string
	}{
		// SGR mouse press: ESC [ < Cb ; Cx ; Cy M
		{"hello\x1b[<35;42;28M", "hello"},
		// SGR mouse release: ESC [ < Cb ; Cx ; Cy m
		{"hello\x1b[<0;5;10m", "hello"},
		// SGR mouse in the middle
		{"before\x1b[<1;2;3Mafter", "beforeafter"},
		// Normal CSI sequences should still be stripped
		{"\x1b[31mred\x1b[0m", "red"},
		// OSC sequences should still be stripped
		{"\x1b]0;title\x07text", "text"},
		// Mixed: SGR + normal CSI
		{"\x1b[1m\x1b[<0;0;0Mbold\x1b[0m", "bold"},
		// Clipboard/multiplexer corruption can lose the ESC prefix.
		{"hello[<35;42;28Mworld", "helloworld"},
		// Generic CSI must not leave cursor-affecting bytes in copied text.
		{"hello\x1b[2Kworld", "helloworld"},
	}
	for _, c := range cases {
		got := stripAnsi(c.input)
		if got != c.want {
			t.Fatalf("stripAnsi(%q) = %q, want %q", c.input, got, c.want)
		}
	}
}

// TestViewportPaintUsesAbsoluteRowPositioningAfterFullWidthToolOutput guards
// the delayed-wrap regression: a full-width tool row must not make the next
// viewport repaint clear or draw at the wrong physical terminal row.
func TestViewportPaintUsesAbsoluteRowPositioningAfterFullWidthToolOutput(t *testing.T) {
	forcedTermWidth = 40
	forcedTermHeight = 16
	t.Cleanup(func() { forcedTermWidth, forcedTermHeight = 0, 0 })

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)
	out.Reset()

	// A long tool result exercises the tool-output path over repeated full
	// viewport paints. Terminals may leave a full-width rendered row in
	// delayed-wrap state; each subsequent physical row must therefore be
	// addressed independently instead of relying on CRLF from its predecessor.
	//
	// The painter skips rows whose bytes did not change, so the shadow of the
	// screen is dropped before each paint here to make both frames full ones —
	// the case where every row is written and every row must therefore carry
	// its own absolute address.
	forceFullPaint(r)
	r.RenderFrame(Frame{
		Kind:    FrameTool,
		Title:   "shell",
		Summary: "ran command",
		Content: strings.Repeat("x", 240),
		Final:   true,
	})
	firstPaint := out.String()
	out.Reset()
	forceFullPaint(r)
	r.RenderComposerState(ComposerRenderState{Text: "next paint"})
	secondPaint := out.String()

	for name, paint := range map[string]string{"first": firstPaint, "second": secondPaint} {
		for row := 1; row <= forcedTermHeight; row++ {
			prefix := fmt.Sprintf("\x1b[%d;1H\x1b[2K", row)
			if !strings.Contains(paint, prefix) {
				t.Fatalf("%s paint does not absolutely clear and draw terminal row %d; missing %q in:\n%q", name, row, prefix, paint)
			}
		}
		if strings.Contains(paint, "\r\n") {
			t.Fatalf("%s paint must not use relative CRLF row advancement; got:\n%q", name, paint)
		}
	}
}

// forceFullPaint makes the next paint write every row, by forgetting what the
// painter believes is already on screen.
func forceFullPaint(r *Renderer) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.dropPaintShadowLocked()
}

// TestExtractColumnRangeEndColSemantics verifies that extractColumnRange
// uses endCol as an exclusive upper bound (half-open interval [startCol, endCol))
// and that a drag selection from column 0 to column N selects the correct text.
// This guards the bug where the selection was one character off.
func TestExtractColumnRangeEndColSemantics(t *testing.T) {
	plain := "hello world"
	// endCol is exclusive: [0, 5) => columns 0-4 => "hello"
	got := extractColumnRange(plain, 0, 5)
	if got != "hello" {
		t.Fatalf("extractColumnRange(%q, 0, 5) = %q, want %q", plain, got, "hello")
	}
	// [0, 11) => all 11 characters
	got = extractColumnRange(plain, 0, 11)
	if got != plain {
		t.Fatalf("extractColumnRange(%q, 0, 11) = %q, want %q", plain, got, plain)
	}
	// [6, 11) => "world"
	got = extractColumnRange(plain, 6, 11)
	if got != "world" {
		t.Fatalf("extractColumnRange(%q, 6, 11) = %q, want %q", plain, got, "world")
	}
	// endCol -1 means "to end of line"
	got = extractColumnRange(plain, 6, -1)
	if got != "world" {
		t.Fatalf("extractColumnRange(%q, 6, -1) = %q, want %q", plain, got, "world")
	}
}

// TestViewportDragSelectExtractedText guards that a drag selection from
// column 0 to column N on a viewport line extracts the correct text.
func TestViewportDragSelectExtractedText(t *testing.T) {
	r := NewRenderer(nil, nil)
	r.viewportMode = true
	r.composerSuppressed = true

	r.vm.append(Frame{Kind: FrameStatus, Content: "hello world"})
	r.vpBodyHeight = 5
	r.vpHeight = 5
	r.vpLastRender = renderViewport(&r.vm, 80, 5, 0, DiffThemeDark)

	// Drag from column 0 to column 5 (exclusive in extractColumnRange).
	// With the half-open interval [0, 5), the extracted text should be "hello".
	r.ViewportSelectStart(0, 0)
	r.ViewportSelectDrag(5, 0)
	r.ViewportSelectEnd(5, 0)

	got := r.extractSelectedTextLocked()
	if got != "hello" {
		t.Fatalf("drag [0,5) extracted %q, want %q", got, "hello")
	}

	// Drag from column 6 to column 11 (exclusive) => "world"
	r.ViewportSelectClear()
	r.ViewportSelectStart(6, 0)
	r.ViewportSelectDrag(11, 0)
	r.ViewportSelectEnd(11, 0)

	got = r.extractSelectedTextLocked()
	if got != "world" {
		t.Fatalf("drag [6,11) extracted %q, want %q", got, "world")
	}
}

// TestExtractColumnRangeCJKPrecedingChar guards the bug where selecting from
// the middle of a CJK text line includes the preceding wide character. The
// user reported dragging to select "我已经仔细审查了" but getting "。我已经仔细审查了"
// (the preceding period was included). This test verifies the visual-column
// mapping correctly excludes the character at [0,2) when startCol=4.
func TestExtractColumnRangeCJKPrecedingChar(t *testing.T) {
	plain := "。我已经仔细审查了"
	// "。" at visual columns [0,2), "我" at [2,4), "已" at [4,6), etc.
	// Select from column 4 (start of "已"): should get "已经仔细审查了"
	got := extractColumnRange(plain, 4, -1)
	want := "已经仔细审查了"
	if got != want {
		t.Fatalf("extractColumnRange(%q, 4, -1) = %q, want %q", plain, got, want)
	}
	// Select from column 2 (start of "我"): should get "我已经仔细审查了"
	got = extractColumnRange(plain, 2, -1)
	want = "我已经仔细审查了"
	if got != want {
		t.Fatalf("extractColumnRange(%q, 2, -1) = %q, want %q", plain, got, want)
	}
	// Select from column 0 (start of "。"): should get the whole line
	got = extractColumnRange(plain, 0, -1)
	if got != plain {
		t.Fatalf("extractColumnRange(%q, 0, -1) = %q, want %q", plain, got, plain)
	}
}

// TestViewportDragSelectCJK guards the end-to-end behavior of CJK text
// selection in the viewport body. The assistant message renders with a
// bullet prefix, so the first rendered line is "● <content>". The user
// clicks on the content text, and the selection must respect the visual
// column of the bullet + any leading content characters.
func TestViewportDragSelectCJK(t *testing.T) {
	r := NewRenderer(nil, nil)
	r.viewportMode = true
	r.composerSuppressed = true

	// Render an assistant-style message with CJK content that has a
	// leading period character, similar to the user's reported scenario.
	// The viewport renders FrameAssistant with a bullet prefix.
	content := "。我已经仔细审查了"
	r.vm.append(Frame{Kind: FrameAssistant, Content: content, Final: true})
	r.vpBodyHeight = 10
	r.vpHeight = 10
	r.vpLastRender = renderViewport(&r.vm, 80, 10, 0, DiffThemeDark)

	// Print the first rendered line to see what it actually looks like
	if len(r.vpLastRender.lines) > 0 {
		t.Logf("First rendered line: %q", r.vpLastRender.lines[0])
		plain := stripAnsi(r.vpLastRender.lines[0])
		t.Logf("Stripped: %q", plain)
	}

	// The first rendered line should be: "● 。我已经仔细审查了"
	// The bullet ● is at visual column 0, space at 1, 。 at [2,4), 我 at [4,6), etc.
	// If the user clicks on "我" (column 4), the selection should start from "我"
	// But if the selection includes "。", the startCol was 2 instead of 4.

	// Simulate clicking on "我" (visual column 4) and dragging to the end of line
	r.ViewportSelectStart(4, 0)
	r.ViewportSelectDrag(30, 0)
	r.ViewportSelectEnd(30, 0)

	got := r.extractSelectedTextLocked()
	// Expected: "我已经仔细审查了" (without "。")
	expected := "我已经仔细审查了"
	if got != expected {
		t.Fatalf("drag [4,30) on CJK assistant line extracted %q, want %q\nRendered line: %q\nStripped: %q",
			got, expected, r.vpLastRender.lines[0], stripAnsi(r.vpLastRender.lines[0]))
	}
}

func TestViewportCollapsedIntermediateToolPreservesMarkdownRendering(t *testing.T) {
	vm := viewModel{}
	content := strings.Join([]string{
		"## Investigation Notes",
		"",
		"- **Finding**: collapsed previews must preserve rich rendering.",
		"- `edit_file` uses a diff card.",
		"- `write_file` uses the same path.",
		"- extra line 1",
		"- extra line 2",
	}, "\n")
	vm.append(Frame{
		Kind:    FrameTool,
		Title:   "intermediate_tool",
		Content: content,
		Summary: "saved intermediate notes",
		Final:   true,
	})

	vr := renderViewport(&vm, 100, 20, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(vr.lines, "\n"))
	if !strings.Contains(plain, "Investigation Notes") {
		t.Fatalf("collapsed markdown preview missing heading text:\n%s", plain)
	}
	if strings.Contains(plain, "## Investigation Notes") {
		t.Fatalf("collapsed preview should render markdown heading, not raw markdown:\n%s", plain)
	}
	if !strings.Contains(plain, "Finding: collapsed previews must preserve rich rendering") {
		t.Fatalf("collapsed preview should include rendered markdown list text:\n%s", plain)
	}
	if !strings.Contains(plain, "more lines (click to expand)") {
		t.Fatalf("long markdown preview should remain folded with hint:\n%s", plain)
	}
}

