func TestViewportMCPHeaderSoftWrapsAllArgumentsAndPreservesMarkdown(t *testing.T) {
	query := "EventResult WorkedStatus consumption apply reducer result append frames history transcript worked status RunStartedMsg multi-turn internal/tui run.go commands.go renderer view model"
	markdown := strings.Join([]string{
		"## Exploration: MCP viewport rendering",
		"",
		"- first result",
		"- second result",
		"- third result",
		"- fourth result",
	}, "\n")
	payload, err := json.Marshal(map[string]any{
		"content": []map[string]any{{"type": "text", "text": markdown}},
	})
	if err != nil {
		t.Fatalf("marshal MCP result: %v", err)
	}

	vm := viewModel{}
	vm.append(Frame{
		Kind:    FrameTool,
		Title:   "mcp__codegraph__codegraph_explore",
		Content: string(payload),
		ToolMeta: tool.ToolMeta{Input: map[string]any{
			"maxFiles":    12,
			"projectPath": "/Users/doudou/workspace/unionj-cloud/forebrain-harness",
			"query":       query,
		}},
		Final: true,
	})

	vr := renderViewport(&vm, 80, 30, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(vr.lines, "\n"))
	flattened := strings.ReplaceAll(plain, "\n  │ ", " ")
	flattened = strings.Join(strings.Fields(flattened), " ")
	for _, want := range []string{
		"max files: 12",
		"project path: /Users/doudou/workspace/unionj-cloud/forebrain-harness",
		"query: " + query,
	} {
		if !strings.Contains(flattened, want) {
			t.Fatalf("MCP header missing complete argument %q:\n%s", want, plain)
		}
	}
	if strings.Contains(plain, "...") || strings.Contains(plain, "…") {
		t.Fatalf("MCP header should soft-wrap without ellipsis:\n%s", plain)
	}
	if !strings.Contains(plain, "Exploration: MCP viewport rendering") {
		t.Fatalf("MCP Markdown heading missing:\n%s", plain)
	}
	if strings.Contains(plain, "## Exploration: MCP viewport rendering") {
		t.Fatalf("MCP heading rendered as raw Markdown:\n%s", plain)
	}
	if !strings.Contains(plain, "- first result") {
		t.Fatalf("MCP Markdown list missing:\n%s", plain)
	}
	for _, leaked := range []string{`"content"`, `"type"`, `"text"`} {
		if strings.Contains(plain, leaked) {
			t.Fatalf("MCP transport envelope leaked %q:\n%s", leaked, plain)
		}
	}
	if !strings.Contains(plain, "more lines (click to expand)") {
		t.Fatalf("long MCP Markdown should retain the folded preview affordance:\n%s", plain)
	}
	for i, line := range vr.lines {
		if width := displayLineWidth(line); width > 80 {
			t.Fatalf("MCP line %d exceeds viewport width: width=%d line=%q", i, width, stripANSI(line))
		}
	}
}

