func assertCollapsedDiffToolPreservesDiffCard(t *testing.T, title string) {
	t.Helper()
	vm := viewModel{}
	vm.append(Frame{
		Kind:    FrameTool,
		Title:   title,
		Content: longViewportTurnDiff(title),
		Summary: "ran " + title,
		Final:   true,
	})

	vr := renderViewport(&vm, 100, 50, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(vr.lines, "\n"))
	if !strings.Contains(plain, "Added 35 lines, removed 1 line") {
		t.Fatalf("collapsed diff preview should use rendered diff-card summary, got:\n%s", plain)
	}
	if !strings.Contains(plain, "+ var line 00 = 0") {
		t.Fatalf("collapsed diff preview should include rendered diff rows, got:\n%s", plain)
	}
	if strings.Contains(plain, "turn diff:") || strings.Contains(plain, "```diff") {
		t.Fatalf("collapsed diff preview should not show raw turn-diff markdown fence, got:\n%s", plain)
	}
	if !strings.Contains(plain, "more lines (click to expand)") {
		t.Fatalf("long diff preview should remain folded with hint, got:\n%s", plain)
	}
}

func longViewportTurnDiff(name string) string {
	var b strings.Builder
	b.WriteString("turn diff: `/repo/")
	b.WriteString(name)
	b.WriteString(".go` (+35/-1)\n\n```diff\n")
	b.WriteString("--- /repo/")
	b.WriteString(name)
	b.WriteString(".go:before\n")
	b.WriteString("+++ /repo/")
	b.WriteString(name)
	b.WriteString(".go:after\n")
	b.WriteString("@@ -1,2 +1,36 @@\n")
	b.WriteString(" package demo\n")
	b.WriteString("-var oldValue = 1\n")
	for i := 0; i < 35; i++ {
		b.WriteString(fmt.Sprintf("+var line %02d = %d\n", i, i))
	}
	b.WriteString("```")
	return b.String()
}

func TestViewportToolHeaderColorMatchesShortAndFoldedPaths(t *testing.T) {
	t.Setenv("NO_COLOR", "")
	useANSI256ColorProfile(t)
	tests := []struct {
		name   string
		title  string
		input  map[string]any
		target string
	}{
		{
			name:   "shell",
			title:  "shell",
			input:  map[string]any{"command": "echo header-color"},
			target: "echo header-color",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			renderHeader := func(bodyLines int) string {
				t.Helper()
				body := make([]string, bodyLines)
				for i := range body {
					body[i] = fmt.Sprintf("row %02d", i+1)
				}
				vm := viewModel{}
				vm.append(Frame{
					Kind:     FrameTool,
					Title:    tt.title,
					Content:  strings.Join(body, "\n"),
					Summary:  "completed",
					Final:    true,
					Duration: 1500 * time.Millisecond,
					ToolMeta: tool.ToolMeta{
						ToolName: tt.title,
						Status:   "completed",
						Input:    tt.input,
					},
				})
				vr := renderViewport(&vm, 100, 30, 0, DiffThemeDark)
				if len(vr.allLines) == 0 {
					t.Fatal("viewport rendered no lines")
				}
				return vr.allLines[0]
			}

			shortHeader := renderHeader(2)
			foldedHeader := renderHeader(toolOutputMaxLines + 2)
			for path, header := range map[string]string{
				"short":  shortHeader,
				"folded": foldedHeader,
			} {
				t.Run(path, func(t *testing.T) {
					for _, text := range []string{"●", tt.target, "1.5s"} {
						assertHeaderTextANSIStyle(t, header, text, "214", false)
					}
				})
			}
			if stripANSI(shortHeader) != stripANSI(foldedHeader) {
				t.Fatalf("short and folded headers differ:\nshort:  %q\nfolded: %q", stripANSI(shortHeader), stripANSI(foldedHeader))
			}
		})
	}
}

