func TestViewportFailedToolNormalizesMultilineErrorEnvelope(t *testing.T) {
	failureLines := []string{
		"apply_patch heredoc must not contain trailing shell commands",
		"run gofmt in a separate shell call",
		"run tests in a separate shell call",
		"do not append commands after PATCH",
	}
	content := "**error** (shell)\n\n```\n" + strings.Join(failureLines, "\n") + "\n```"

	vm := viewModel{}
	vm.append(Frame{
		Kind:    FrameTool,
		Title:   "shell",
		Content: content,
		Final:   true,
		ToolMeta: tool.ToolMeta{
			ToolName: "shell",
			Status:   "failed",
			Input:    map[string]any{"command": "apply_patch <<'PATCH'"},
		},
	})

	vr := renderViewport(&vm, 80, 20, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(vr.lines, "\n"))
	if count := strings.Count(plain, failureLines[0]); count != 1 {
		t.Fatalf("failure text count = %d, want 1:\n%s", count, plain)
	}
	for _, leaked := range []string{"**error**", "```", "error: " + failureLines[0]} {
		if strings.Contains(plain, leaked) {
			t.Fatalf("failed viewport tool leaked %q:\n%s", leaked, plain)
		}
	}
	for _, want := range failureLines[:toolOutputMaxLines] {
		if !strings.Contains(plain, want) {
			t.Fatalf("failed viewport preview missing %q:\n%s", want, plain)
		}
	}
	if strings.Contains(plain, failureLines[toolOutputMaxLines]) {
		t.Fatalf("collapsed failed tool should hide the fourth error line:\n%s", plain)
	}
	if !strings.Contains(plain, "1 more lines (click to expand)") {
		t.Fatalf("collapsed failed tool missing expansion hint:\n%s", plain)
	}
}

