func TestViewportComposerRendersRosterBelowFooterOnlyForRunningSubagent(t *testing.T) {
	r := NewRenderer(nil, nil)
	r.viewportMode = true
	r.SetComposerFooter(ComposerFooter{Model: "m", Directory: "d"})

	r.composerState = ComposerRenderState{
		Text:   "hello",
		Cursor: ptrInt(5),
		AgentRoster: AgentRosterSnapshot{Rows: []AgentRosterRow{
			{ID: "primary", Kind: "primary", Label: "primary", Status: "running"},
		}},
	}
	block := r.buildComposerBlock(r.composerState, 80)
	plain := stripANSI(strings.Join(block.lines, "\n"))
	if strings.Contains(plain, "Live agents") {
		t.Fatalf("primary-only roster should stay hidden, got %q", plain)
	}

	r.composerState = ComposerRenderState{
		Text:   "hello",
		Cursor: ptrInt(5),
		AgentRoster: AgentRosterSnapshot{Rows: []AgentRosterRow{
			{ID: "primary", Kind: "primary", Label: "primary", Status: "running"},
			{ID: "sub-1", Kind: "subagent", Label: "review", Status: "running", Task: "working"},
		}},
		RosterFocused:  true,
		RosterSelected: 0,
	}
	block = r.buildComposerBlock(r.composerState, 80)
	plain = stripANSI(strings.Join(block.lines, "\n"))
	footerIdx := strings.Index(plain, "m")
	blankIdx := strings.Index(plain, "\n\n")
	// The cursor row (index 0, focused) is primary → "❯ primary" with hint.
	rosterIdx := strings.Index(plain, "❯ primary")
	if footerIdx < 0 || blankIdx < 0 || rosterIdx < 0 || !(footerIdx < blankIdx && blankIdx < rosterIdx) {
		t.Fatalf("expected footer before roster, got %q", plain)
	}
	if !strings.Contains(plain, "\n\n❯ primary") {
		t.Fatalf("expected blank separator directly before selected roster row, got %q", plain)
	}
	// The subagent row is named by what it is, with what it is working on
	// beside it; its uuid key stays out of the line.
	if !strings.Contains(plain, "  review  working") {
		t.Fatalf("expected named roster row for running subagent, got %q", plain)
	}
	if strings.Contains(plain, "sub-1") {
		t.Fatalf("roster line must not show the raw id, got %q", plain)
	}
}

func TestViewportComposerKeepsSingleSpacingAroundWorkingAndPendingQueue(t *testing.T) {
	r := NewRenderer(nil, nil)
	r.RenderTransientStatus(transientSourceWorking, "Working (51s • esc to interrupt)")
	cursor := 0
	state := ComposerRenderState{
		Text:   "",
		Cursor: &cursor,
		PendingInput: ComposerPendingInputPreview{
			PendingSteers: []string{"需要先给出方案"},
		},
	}

	assertSpacing := func(t *testing.T, block composerBlock, composerLine func(string) bool) {
		t.Helper()
		plainLines := make([]string, len(block.lines))
		for i, line := range block.lines {
			plainLines[i] = stripANSI(line)
		}
		isBlank := func(line string) bool {
			return strings.TrimSpace(strings.ReplaceAll(line, "\x1b[K", "")) == ""
		}

		workingRow := -1
		queuedMessageRow := -1
		composerRow := -1
		for i, line := range plainLines {
			switch {
			case strings.Contains(line, "Working ("):
				workingRow = i
			case strings.Contains(line, "需要先给出方案"):
				queuedMessageRow = i
			case composerRow < 0 && composerLine(line):
				composerRow = i
			}
		}
		if workingRow < 1 || !isBlank(plainLines[workingRow-1]) {
			t.Fatalf("expected one blank boundary row before Working, got %#v", plainLines)
		}
		if workingRow != 1 {
			t.Fatalf("expected Working immediately after its single leading spacer, row=%d lines=%#v", workingRow, plainLines)
		}
		if queuedMessageRow < 0 || composerRow < 0 {
			t.Fatalf("missing pending message or composer row: %#v", plainLines)
		}
		// The queue block (message plus its recall hint) runs straight into the
		// composer: no blank row is allowed to open up between them.
		if queuedMessageRow > composerRow {
			t.Fatalf("expected pending message above composer, got %#v", plainLines)
		}
		for i := queuedMessageRow; i < composerRow; i++ {
			if isBlank(plainLines[i]) {
				t.Fatalf("expected no blank row between pending queue and composer, got %#v", plainLines)
			}
		}
	}

	t.Run("normal composer", func(t *testing.T) {
		block := r.buildComposerBlock(state, 80)
		assertSpacing(t, block, func(line string) bool {
			return strings.Contains(line, "──")
		})
	})

	t.Run("slash composer", func(t *testing.T) {
		slashCursor := len([]rune("/help"))
		slashState := state
		slashState.Text = "/help"
		slashState.Cursor = &slashCursor
		block := r.buildComposerBlock(slashState, 80)
		assertSpacing(t, block, func(line string) bool {
			return strings.HasPrefix(line, composerPromptMarker+"/help")
		})
	})
}

