func TestRenderBlockFullCacheInvalidatesOnFrameMutation(t *testing.T) {
	b := &viewBlock{
		id:          1,
		frame:       Frame{Kind: FrameStatus, Content: "alpha"},
		collapsible: true,
	}
	first := renderBlockFull(b, 80, DiffThemeDark, 0)
	// renderBlockFull detects content changes via the cache validity flag, not
	// by re-deriving a per-frame string signature (that O(content) signature
	// was the dominant cost when thousands of blocks are checked every repaint).
	// The contract is: every frame mutation must set cache.valid=false, exactly
	// as viewmodel.append/replaceOrAppendBlock and FinalizePendingTools do.
	b.frame.Content = "omega"
	b.cache.valid = false
	second := renderBlockFull(b, 80, DiffThemeDark, 0)

	if strings.Join(first, "\n") == strings.Join(second, "\n") {
		t.Fatalf("expected invalidated content change to refresh cache: %q", strings.Join(second, "\n"))
	}
	if !strings.Contains(strings.Join(second, "\n"), "omega") {
		t.Fatalf("expected refreshed content in second render, got %q", strings.Join(second, "\n"))
	}
	// A subsequent render with no mutation reuses the cache (no re-render).
	b.cache.valid = true // simulate "no change since last render"
	cached := renderBlockFull(b, 80, DiffThemeDark, 0)
	if strings.Join(cached, "\n") != strings.Join(second, "\n") {
		t.Fatalf("expected cached reuse when no mutation occurred")
	}
}

// TestFoldBlockMemoizes guards the fold cache: foldBlock runs for every block
// on every repaint, so for a session with thousands of blocks it must not
// re-derive the fold each frame. The cache must hit on identical inputs,
// invalidate on expand/width changes, and refresh when the underlying full
// lines change (gen bump).
func TestFoldBlockMemoizes(t *testing.T) {
	vm := viewModel{}
	body := strings.Join([]string{
		"r01", "r02", "r03", "r04", "r05", "r06", "r07", "r08", "r09", "r10",
		"r11", "r12", "r13",
	}, "\n")
	b := vm.append(Frame{Kind: FrameTool, Title: "shell", Content: body, Summary: "ran echo", ToolMeta: tool.ToolMeta{ToolName: "shell", Status: "completed", Input: map[string]any{"command": "echo"}}})
	full := renderBlockFull(b, 80, DiffThemeDark, 0)

	lines1, hdr1 := foldBlock(b, full, 80, 0)
	if len(lines1) == 0 {
		t.Fatalf("expected folded output")
	}
	// Identical inputs: cache hit returns the SAME slice (no recompute).
	lines2, hdr2 := foldBlock(b, full, 80, 0)
	if hdr1 != hdr2 || strings.Join(lines1, "\n") != strings.Join(lines2, "\n") {
		t.Fatalf("fold cache should return cached result on identical inputs")
	}
	if len(lines1) > 0 && len(lines2) > 0 && &lines1[0] != &lines2[0] {
		t.Fatalf("fold cache hit should return the stored slice, not a recompute")
	}

	// Toggling expanded invalidates and changes the output.
	b.expanded = true
	lines3, _ := foldBlock(b, full, 80, 0)
	if strings.Join(lines2, "\n") == strings.Join(lines3, "\n") {
		t.Fatalf("expanding should change the folded output")
	}
	// Re-collapsing recomputes the collapsed view (matches the original).
	b.expanded = false
	lines4, _ := foldBlock(b, full, 80, 0)
	if strings.Join(lines1, "\n") != strings.Join(lines4, "\n") {
		t.Fatalf("re-collapsing should match the original collapsed output")
	}

	// A content change (valid=false -> renderBlockFull recompute -> gen bump)
	// invalidates the fold cache.
	b.frame.Content = body + "\nr14"
	b.cache.valid = false
	full2 := renderBlockFull(b, 80, DiffThemeDark, 0)
	lines5, _ := foldBlock(b, full2, 80, 0)
	if strings.Join(lines4, "\n") == strings.Join(lines5, "\n") {
		t.Fatalf("content change should refresh the fold")
	}
}

// TestWrapCardLineHugeLineCompletesFast is a regression guard for the TUI
// freeze: wrapCardLine used to call displayLineWidth (ANSI-strip regex +
// runewidth over the whole remaining suffix) inside its loop, making it O(n^2).
// A replayed block whose fold header carried a multi-KB summary pinned the
// renderer lock for seconds. The fixed wrapCardLine is O(n), so wrapping a
// 100KB line must finish near-instantly.
func TestWrapCardLineHugeLineCompletesFast(t *testing.T) {
	// 100KB single "word" (no spaces) wider than any terminal -> exercises the
	// no-break-point path, which previously re-scanned the whole suffix.
	huge := strings.Repeat("x", 100*1024)
	done := make(chan []string, 1)
	go func() { done <- wrapCardLine(huge, 80) }()
	select {
	case got := <-done:
		// Each wrapped line is at most ~80 visible columns.
		for _, l := range got {
			if displayLineWidth(l) > 80 {
				t.Fatalf("wrapped line exceeds maxWidth: %d", displayLineWidth(l))
			}
		}
	case <-time.After(2 * time.Second):
		t.Fatalf("wrapCardLine on 100KB line did not complete within 2s (O(n^2) regression?)")
	}
}

func BenchmarkWrapCardLineHuge(b *testing.B) {
	// 50KB line with occasional spaces -> exercises the break-point path.
	parts := make([]string, 500)
	for i := range parts {
		parts[i] = strings.Repeat("w", 100)
	}
	huge := strings.Join(parts, " ")
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		wrapCardLine(huge, 80)
	}
}

