// TestViewportThinkingCacheNotMutatedByFold verifies that foldBlock's
// normalization of the first thinking line does not corrupt the render cache.
func TestViewportThinkingCacheNotMutatedByFold(t *testing.T) {
	vm := viewModel{}
	vm.append(Frame{Kind: FrameThinking, Content: "first thought\nsecond thought", Final: true})

	// First render — populates cache and normalizes the "▸ " prefix.
	first := renderViewport(&vm, 80, 20, 0, DiffThemeDark)
	firstPlain := stripANSI(strings.Join(first.lines, "\n"))

	// Second render — should produce the same output (cache was not mutated).
	second := renderViewport(&vm, 80, 20, 0, DiffThemeDark)
	secondPlain := stripANSI(strings.Join(second.lines, "\n"))

	if firstPlain != secondPlain {
		t.Fatalf("cache corrupted by foldBlock normalization:\nfirst:\n%s\nsecond:\n%s", firstPlain, secondPlain)
	}
}

// TestViewportThinkingHeaderShowsDuration verifies that a finalized thinking
// block with a non-zero Duration renders "Thought for 1m 10s" in the header,
// and that zero duration falls back to plain "Thought".
func TestViewportThinkingHeaderShowsDuration(t *testing.T) {
	// Long block (> 12 lines) → clickable header with duration.
	vm := viewModel{}
	paragraphs := make([]string, toolOutputMaxLines+3)
	for i := range paragraphs {
		paragraphs[i] = fmt.Sprintf("step %d", i)
	}
	vm.append(Frame{Kind: FrameThinking, Content: strings.Join(paragraphs, "\n"), Final: true, Duration: time.Minute + 10*time.Second})

	vr := renderViewport(&vm, 80, 30, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(vr.lines, "\n"))
	if !strings.Contains(plain, "Thought for 1m 10s") {
		t.Fatalf("expected 'Thought for 1m 10s' header, got:\n%s", plain)
	}

	// Short block (≤ 12 lines) → non-clickable header with duration.
	vm2 := viewModel{}
	vm2.append(Frame{Kind: FrameThinking, Content: "first thought\nsecond thought", Final: true, Duration: 42 * time.Second})
	vr2 := renderViewport(&vm2, 80, 20, 0, DiffThemeDark)
	plain2 := stripANSI(strings.Join(vr2.lines, "\n"))
	if !strings.Contains(plain2, "Thought for 42s") {
		t.Fatalf("expected 'Thought for 42s' header, got:\n%s", plain2)
	}

	// Zero duration → plain "Thought".
	vm3 := viewModel{}
	vm3.append(Frame{Kind: FrameThinking, Content: "first thought\nsecond thought", Final: true})
	vr3 := renderViewport(&vm3, 80, 20, 0, DiffThemeDark)
	plain3 := stripANSI(strings.Join(vr3.lines, "\n"))
	if !strings.Contains(plain3, "Thought") || strings.Contains(plain3, "Thought for") {
		t.Fatalf("expected plain 'Thought' header for zero duration, got:\n%s", plain3)
	}
}

// TestViewportIsClickableRow verifies the hover-target predicate used by the
// paint loop to decide which rows to highlight.
func TestViewportIsClickableRow(t *testing.T) {
	// Long tool block: body rows are clickable, header is a static status indicator.
	vm := viewModel{}
	longBody := strings.Join([]string{
		"row 01", "row 02", "row 03", "row 04", "row 05", "row 06",
		"row 07", "row 08", "row 09", "row 10", "row 11", "row 12", "row 13",
	}, "\n")
	vm.append(Frame{Kind: FrameTool, Title: "shell", Content: longBody, Summary: "ran echo", ToolMeta: tool.ToolMeta{ToolName: "shell", Status: "completed", Input: map[string]any{"command": "echo"}}})
	vr := renderViewport(&vm, 80, 20, 0, DiffThemeDark)
	if vr.isClickableRow(0, &vm) {
		t.Fatal("long tool header row should not be clickable")
	}
	if !vr.isClickableRow(2, &vm) {
		t.Fatal("long tool body row should be clickable")
	}
	if !vr.isClickableRow(1+toolOutputMaxLines, &vm) {
		t.Fatal("long tool truncation hint row should be clickable")
	}
	// Row outside the block span → not clickable.
	if vr.isClickableRow(100, &vm) {
		t.Fatal("row outside any block should not be clickable")
	}

	// Short tool block: not clickable (full content shown inline, no header).
	vm2 := viewModel{}
	vm2.append(Frame{Kind: FrameTool, Title: "shell", Content: "row 01\nrow 02", Summary: "ran echo", ToolMeta: tool.ToolMeta{ToolName: "shell", Status: "completed", Input: map[string]any{"command": "echo"}}})
	vr2 := renderViewport(&vm2, 80, 20, 0, DiffThemeDark)
	if vr2.isClickableRow(0, &vm2) {
		t.Fatal("short tool header row should not be clickable")
	}

	// Long thinking block: body rows are clickable, header is a static status indicator.
	vm3 := viewModel{}
	paragraphs := make([]string, toolOutputMaxLines+3)
	for i := range paragraphs {
		paragraphs[i] = fmt.Sprintf("step %d", i)
	}
	vm3.append(Frame{Kind: FrameThinking, Content: strings.Join(paragraphs, "\n"), Final: true})
	vr3 := renderViewport(&vm3, 80, 30, 0, DiffThemeDark)
	if vr3.isClickableRow(0, &vm3) {
		t.Fatal("long thinking header row should not be clickable")
	}
	if !vr3.isClickableRow(3, &vm3) {
		t.Fatal("long thinking body row should be clickable")
	}

	// Short thinking block: not clickable.
	vm4 := viewModel{}
	vm4.append(Frame{Kind: FrameThinking, Content: "first thought\nsecond thought", Final: true})
	vr4 := renderViewport(&vm4, 80, 20, 0, DiffThemeDark)
	if vr4.isClickableRow(0, &vm4) {
		t.Fatal("short thinking header row should not be clickable")
	}

	// Streaming thinking: not clickable (no header).
	vm5 := viewModel{}
	vm5.append(Frame{Kind: FrameThinking, Content: "partial reasoning", Final: false})
	vr5 := renderViewport(&vm5, 80, 20, 0, DiffThemeDark)
	if vr5.isClickableRow(0, &vm5) {
		t.Fatal("streaming thinking row should not be clickable")
	}
}

// TestViewportHoverBackgroundReappliedAfterReset verifies that the hover
// background highlight survives \x1b[0m resets inside a lipgloss-rendered line.
// lipgloss emits \x1b[0m after each styled segment; without re-applying the
// background, only the first segment would be highlighted. It also pins the
// fill-to-the-edge contract: the highlight must reach the full width with
// explicitly painted spaces, because terminals without back-color-erase
// (macOS Terminal.app) would stop an \x1b[K fill right after the text.
func TestViewportHoverBackgroundReappliedAfterReset(t *testing.T) {
	// Simulate a lipgloss-rendered tool header line: multiple styled segments
	// each terminated by \x1b[0m, exactly as lipgloss produces.
	line := "\x1b[1;93m•\x1b[0m \x1b[1;93mRan\x1b[0m echo\x1b[0m"

	hoverBgSeq := "\x1b[48;5;236m"
	const width = 80
	painted := applyHoverHighlight(line, width, hoverBgSeq)

	// The hover background must appear at the start.
	if !strings.HasPrefix(painted, hoverBgSeq) {
		t.Fatalf("hover background should prefix the line, got %q", painted)
	}
	// The hover background must be re-applied after each \x1b[0m reset.
	// The line has 3 \x1b[0m occurrences, so 3 re-applications.
	reapplyCount := strings.Count(painted, "\x1b[0m"+hoverBgSeq)
	if reapplyCount != 3 {
		t.Fatalf("expected 3 background re-applications after resets, got %d in:\n%q", reapplyCount, painted)
	}
	// The fill to the edge must be explicit pad spaces, not \x1b[K, so the
	// background survives terminals without back-color-erase.
	if strings.Contains(painted, "\x1b[K") {
		t.Fatalf("hover row must not rely on \\x1b[K for the edge fill:\n%q", painted)
	}
	plain := stripANSI(painted)
	if w := lipgloss.Width(painted); w != width {
		t.Fatalf("hover row spans %d columns, want the full %d (plain %q)", w, width, plain)
	}
	if padCount := strings.Count(plain, " "); padCount < width-lipgloss.Width(line) {
		t.Fatalf("expected %d pad spaces after the text, plain row %q", width-lipgloss.Width(line), plain)
	}
	// The final reset must be present.
	if !strings.HasSuffix(painted, "\x1b[0m") {
		t.Fatalf("expected final \\x1b[0m reset, got tail %q", painted[len(painted)-20:])
	}

	// Verify there is NO gap where the background is missing between segments.
	// Every space between segments should be preceded by a re-application.
	// "•\x1b[0m\x1b[48;5;236m " — the space after bullet has the background.
	if !strings.Contains(painted, "\x1b[0m"+hoverBgSeq+" \x1b[1;93mRan") {
		t.Fatalf("background not re-applied before 'Ran' segment:\n%q", painted)
	}
}

// TestViewportScrollClearsHover verifies that scrolling clears the hover row
// so a stale highlight doesn't land on the wrong content after the viewport
// shifts.
func TestViewportScrollClearsHover(t *testing.T) {
	r := NewRenderer(nil, nil)
	r.viewportMode = true
	r.composerSuppressed = true

	for i := 0; i < 30; i++ {
		r.vm.append(Frame{Kind: FrameStatus, Content: fmt.Sprintf("line %02d", i)})
	}

	// Manually set vpLastRender (paintViewportLocked returns early when
	// composerSuppressed is true, so we seed the render cache directly).
	r.vpLastRender = renderViewport(&r.vm, 80, 10, 0, DiffThemeDark)
	r.vpScrollOffset = 0
	r.vpFollow = false

	// Simulate a hover on row 2.
	r.vpHoverRow = 2

	// Scroll up by 3 rows.
	r.ViewportScroll(-3)

	if r.vpHoverRow != -1 {
		t.Fatalf("expected hover row cleared to -1 after scroll, got %d", r.vpHoverRow)
	}
}

// TestViewportDragPastTopEdgeAutoScrolls verifies that when a drag-selection is
// pinned at the top body row, autoScrollStepLocked scrolls the transcript up one
// row and extends the selection end into the newly-revealed row — the core of
// the "drag to the top edge to keep selecting off-screen content" fix.
func TestViewportDragPastTopEdgeAutoScrolls(t *testing.T) {
	r := NewRenderer(nil, nil)
	r.viewportMode = true
	r.composerSuppressed = true // paintViewportLocked early-returns; seed render manually

	for i := 0; i < 30; i++ {
		r.vm.append(Frame{Kind: FrameStatus, Content: fmt.Sprintf("line %02d", i)})
	}

	const bodyHeight = 10
	r.vpBodyHeight = bodyHeight
	r.vpHeight = bodyHeight
	// Start scrolled part-way down so there is content above the window to scroll into.
	r.vpScrollOffset = 5
	r.vpFollow = false
	r.vpLastRender = renderViewport(&r.vm, 80, bodyHeight, 5, DiffThemeDark)

	// Simulate an in-progress drag whose end is pinned at the top body row.
	r.selectStartRow = r.vpLastRender.firstRow + 4 // an absolute row inside the window
	r.selectStartCol = 0
	r.selectEndRow = r.vpLastRender.firstRow // top of the window
	r.selectEndCol = 3
	r.selectDidDrag = true
	r.autoScrollCol = 3

	beforeOffset := r.vpScrollOffset
	r.autoScrollStepLocked(-1)

	if r.vpScrollOffset != beforeOffset-1 {
		t.Fatalf("expected scroll offset to decrease by 1 (from %d), got %d", beforeOffset, r.vpScrollOffset)
	}
	// Refresh the render at the new offset (paint was suppressed) and confirm the
	// selection end now pins to the newly-exposed top row.
	r.vpLastRender = renderViewport(&r.vm, 80, bodyHeight, r.vpScrollOffset, DiffThemeDark)
	if r.selectEndRow != r.vpScrollOffset {
		t.Fatalf("expected selection end pinned to new top row %d, got %d", r.vpScrollOffset, r.selectEndRow)
	}
}

// TestViewportSelectionExtractsOffScreenRows verifies that after auto-scrolling,
// the extracted selection text includes rows that are no longer in the visible
// window — extraction reads the full transcript (allLines), not just vr.lines.
func TestViewportSelectionExtractsOffScreenRows(t *testing.T) {
	r := NewRenderer(nil, nil)
	r.viewportMode = true
	r.composerSuppressed = true

	for i := 0; i < 30; i++ {
		r.vm.append(Frame{Kind: FrameStatus, Content: fmt.Sprintf("line %02d", i)})
	}

	const bodyHeight = 5
	r.vpBodyHeight = bodyHeight
	r.vpHeight = bodyHeight
	r.vpScrollOffset = 20
	r.vpFollow = false
	r.vpLastRender = renderViewport(&r.vm, 80, bodyHeight, 20, DiffThemeDark)

	// Select an absolute row range that spans well above the current window,
	// which starts at row 20. The first block starts at row 0 and each later
	// block carries a leading blank separator, so "line NN" lands at absolute
	// row 2*NN. Rows 2..22 therefore cover line 01..line 11, all off-screen.
	r.selectStartRow = 2
	r.selectStartCol = 0
	r.selectEndRow = 22
	r.selectEndCol = -1
	r.selectDidDrag = true

	text := r.extractSelectedTextLocked()
	// Off-screen early rows must be present (proves allLines, not the visible slice).
	for _, want := range []string{"line 01", "line 05", "line 11"} {
		if !strings.Contains(text, want) {
			t.Fatalf("expected extracted text to contain off-screen %q, got:\n%s", want, text)
		}
	}
}

func TestViewportTerminalErrorMirrorsIntoActiveSubagentView(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() {
		forcedTermWidth = 0
		forcedTermHeight = 0
	})

	var out strings.Builder
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)

	const agentID = "task-explore-1"
	r.RenderFrame(Frame{
		Kind:    FrameTool,
		Title:   "example_tool",
		Content: "subagent tool output",
		Summary: "ran example tool",
		AgentID: agentID,
		Final:   true,
	})
	r.SetActiveView(agentID)
	out.Reset()

	r.PrintError(fmt.Errorf("context_length_exceeded: input too large"))

	if len(r.vm.blocks) != 1 || r.vm.blocks[0].frame.Kind != FrameError {
		t.Fatalf("primary transcript error = %#v", r.vm.blocks)
	}
	vm := r.perAgentVM[agentID]
	if vm == nil || len(vm.blocks) != 2 {
		t.Fatalf("active subagent VM blocks = %#v", vm)
	}
	if got := vm.blocks[1].frame; got.Kind != FrameError || got.Content != "context_length_exceeded: input too large" {
		t.Fatalf("mirrored subagent error = %#v", got)
	}
	if painted := stripAllANSI(out.String()); !strings.Contains(painted, "context_length_exceeded: input too large") {
		t.Fatalf("active subagent viewport did not repaint error:\n%s", painted)
	}
}

// TestSetActiveViewShowsSubagentToolFramesByRosterKey guards the roster-Enter
// behaviour end to end. Subagent tool frames carry AgentID = the roster key
// (task_id); appendFrameViewportLocked routes them to perAgentVM[key], and
// pressing Enter on the roster row calls SetActiveView(key), which must paint
// that per-agent transcript. If the routing key and the roster key ever drift
// apart (the nested-subagent bug), the switched view is empty and Enter appears
// to "do nothing".
func TestSetActiveViewShowsSubagentToolFramesByRosterKey(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() {
		forcedTermWidth = 0
		forcedTermHeight = 0
	})
	r := NewRenderer(nil, nil)
	r.viewportMode = true
	r.composerSuppressed = true

	const rosterKey = "task-explore-1"

	// Primary-view frame and a subagent-tagged tool frame arrive interleaved.
	r.RenderFrame(Frame{Kind: FrameAssistant, Content: "primary answer"})
	r.RenderFrame(Frame{
		Kind:    FrameTool,
		Title:   "example_tool",
		Content: "subagent tool output",
		Summary: "ran example tool",
		ToolMeta: tool.ToolMeta{
			ToolName: "example_tool",
			Status:   "completed",
			Input:    map[string]any{"query": "subagent example"},
		},
		AgentID: rosterKey,
	})

	// The subagent tool frame must NOT be on the primary transcript.
	if got := stripANSI(strings.Join(renderViewport(&r.vm, 80, 24, 1<<30, DiffThemeDark).lines, "\n")); strings.Contains(got, "subagent tool output") {
		t.Fatalf("subagent tool frame leaked onto primary view:\n%s", got)
	}
	// It must live on the per-agent VM keyed by the roster key.
	vm, ok := r.perAgentVM[rosterKey]
	if !ok || vm == nil {
		t.Fatalf("expected per-agent VM for roster key %q, got %v", rosterKey, r.perAgentVM)
	}

	// Enter on the roster row switches the active view to the roster key.
	r.SetActiveView(rosterKey)
	if r.ActiveView() != rosterKey {
		t.Fatalf("active view=%q want %q", r.ActiveView(), rosterKey)
	}
	painted := stripANSI(strings.Join(renderViewport(vm, 80, 24, 1<<30, DiffThemeDark).lines, "\n"))
	if !strings.Contains(painted, "example_tool") || !strings.Contains(painted, "subagent tool output") {
		t.Fatalf("switched subagent view should show its tool frame, got:\n%s", painted)
	}
}

func TestRendererBrowseStateRoundTripsPrimaryAndSubagentViews(t *testing.T) {
	build := func() *Renderer {
		r := NewRenderer(io.Discard, io.Discard)
		r.viewportMode = true
		r.composerSuppressed = true
		for i := 0; i < 50; i++ {
			r.vm.append(Frame{Kind: FrameMemoryCompact, Title: fmt.Sprintf("primary-%d", i), Content: "line\nline\nline\nline", Final: true})
		}
		agentVM := r.ensurePerAgentVM("agent-1")
		for i := 0; i < 50; i++ {
			agentVM.append(Frame{Kind: FrameTool, AgentID: "agent-1", StepID: fmt.Sprintf("tool-%d", i), Content: "line\nline\nline\nline", Final: true})
		}
		return r
	}

	live := build()
	live.vm.blocks[10].expanded = true
	live.perAgentVM["agent-1"].blocks[11].expanded = true
	live.viewBrowseState = map[string]viewportBrowseState{
		"": {ScrollOffset: 7, Follow: false, NewMessages: 2},
	}
	live.activeView = "agent-1"
	live.vpScrollOffset = 9
	live.vpFollow = false
	live.vpNewMessages = 3
	snapshot := live.SnapshotBrowseState()

	replayed := build()
	replayed.RestoreBrowseState(snapshot)
	if replayed.ActiveView() != "agent-1" {
		t.Fatalf("active view = %q, want agent-1", replayed.ActiveView())
	}
	if replayed.vpFollow || replayed.vpNewMessages != 3 {
		t.Fatalf("agent browse state = follow %v unseen %d", replayed.vpFollow, replayed.vpNewMessages)
	}
	if !replayed.perAgentVM["agent-1"].blocks[11].expanded {
		t.Fatal("subagent fold state was not restored")
	}
	replayed.SetActiveView("")
	if replayed.vpFollow || replayed.vpNewMessages != 2 {
		t.Fatalf("primary browse state = follow %v unseen %d", replayed.vpFollow, replayed.vpNewMessages)
	}
	if !replayed.vm.blocks[10].expanded {
		t.Fatal("primary fold state was not restored")
	}
}

func TestViewportToolFallbackOmitsSummaryForUnknownTool(t *testing.T) {
	vm := viewModel{}
	vm.append(Frame{
		Kind:    FrameTool,
		Title:   "subagent_fanout",
		Content: strings.Join([]string{"row 01", "row 02", "row 03", "row 04", "row 05"}, "\n"),
		Summary: "running subagent_fanout",
		Final:   true,
	})

	vr := renderViewport(&vm, 80, 20, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(vr.lines, "\n"))
	if !strings.Contains(plain, "subagent_fanout") {
		t.Fatalf("expected tool title fallback, got:\n%s", plain)
	}
	if strings.Contains(plain, "running subagent_fanout") {
		t.Fatalf("tool fallback must not leak full summary into header:\n%s", plain)
	}
	if !strings.Contains(plain, "row 01") {
		t.Fatalf("expected tool body to remain visible, got:\n%s", plain)
	}
}

// TestViewportFoldHeaderWrapsAndDoesNotDuplicate guards against three
// regressions in the viewport fold path for long mixed-language tool summaries:
//  1. The fold header must be wrapped to the viewport width (no overflow that
//     triggers terminal autowrap).
//  2. Continuation lines must respect contentRightMargin (no flush-right text).
//  3. The body must not contain header continuation lines (no duplicate text).
func TestViewportFoldHeaderWrapsAndDoesNotDuplicate(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() {
		forcedTermWidth = 0
		forcedTermHeight = 0
	})

	longBody := ""
	for i := 0; i < 300; i++ {
		longBody += fmt.Sprintf("line %03d\n", i)
	}
	const headerText = "完成工具调用后继续检查这个没有空格的中文摘要以确保软换行正确工作 duplicate-marker 后续内容"

	var vm viewModel
	vm.append(Frame{
		Kind:    FrameTool,
		Title:   "shell",
		Summary: "ran " + headerText + " · exit 0",
		Content: longBody,
		Final:   true,
	})

	contentWidth := 80 - viewportRightPadding
	vr := renderViewport(&vm, contentWidth, 40, 1<<30, DiffThemeDark)

	// Use contentWidth directly for the max allowed width, as the body
	// rendering (formatToolOutputBlock) wraps to termWidth - contentRightMargin,
	// and contentWidth = forcedTermWidth - viewportRightPadding. The extra
	// viewportRightPadding (2) is free space; body lines may use it.
	maxAllowed := contentWidth
	markerCount := 0
	for i, line := range vr.lines {
		plain := stripANSI(line)
		// 1+2: no line may exceed the right margin. This must use terminal
		// display cells because UTF-8 byte length overcounts Chinese text.
		if lineWidth := displayLineWidth(line); lineWidth > maxAllowed {
			t.Fatalf("line %d exceeds right margin: width=%d max=%d: %q",
				i, lineWidth, maxAllowed, plain)
		}
		// 3: duplicate-marker belongs to a continuation header line and must
		// appear only once; a second copy means it leaked into the body.
		if strings.Contains(plain, "duplicate-marker") {
			markerCount++
		}
	}
	if markerCount != 1 {
		t.Fatalf("header marker appeared %d times, expected 1:\n%s",
			markerCount, stripANSI(strings.Join(vr.lines, "\n")))
	}

	plain := stripANSI(strings.Join(vr.lines, "\n"))
	flattened := strings.ReplaceAll(plain, "\n  │ ", "")
	flattened = strings.ReplaceAll(flattened, "\n", "")
	headerWithoutSpaces := strings.ReplaceAll(headerText, " ", "")
	if !strings.Contains(strings.ReplaceAll(flattened, " ", ""), headerWithoutSpaces) {
		t.Fatalf("folded header lost or changed mixed-language content:\n%s", plain)
	}
	// Sanity: the actual tool output must be present.
	if !strings.Contains(plain, "line 000") {
		t.Fatalf("folded body should show first output row, got:\n%s", plain)
	}
	if !strings.Contains(plain, "more lines") {
		t.Fatalf("folded body should show truncation hint, got:\n%s", plain)
	}
}

// TestViewportStripsTerminalBells ensures that raw BEL (0x07) bytes in model or
// tool output are not emitted to the terminal. Terminal.app shows a bell icon on
// the tab and plays the alert sound when it receives a BEL, which must not
// happen while a turn is still streaming.
func TestViewportStripsTerminalBells(t *testing.T) {
	vm := viewModel{}
	vm.append(Frame{Kind: FrameAssistant, Content: "hello\x07world", Final: true})
	vm.append(Frame{Kind: FrameTool, Title: "shell", Content: "beep\x07boop", Summary: "ran echo", Final: true})

	vr := renderViewport(&vm, 80, 24, 1<<30, DiffThemeDark)
	for i, line := range vr.lines {
		if strings.Contains(line, "\x07") {
			t.Fatalf("rendered line %d still contains BEL: %q", i, line)
		}
	}
	plain := stripANSI(strings.Join(vr.lines, "\n"))
	if !strings.Contains(plain, "helloworld") {
		t.Fatalf("expected BEL-stripped assistant text, got:\n%s", plain)
	}
	if !strings.Contains(plain, "beepboop") {
		t.Fatalf("expected BEL-stripped tool output, got:\n%s", plain)
	}
}

func TestViewportRunningShellShowsNewestLiveOutput(t *testing.T) {
	var output strings.Builder
	for i := 1; i <= 20; i++ {
		fmt.Fprintf(&output, "live line %02d\n", i)
	}
	vm := viewModel{}
	vm.append(Frame{
		Kind:            FrameTool,
		Title:           "shell",
		Content:         output.String(),
		StepID:          "shell-live",
		Summary:         "running tests",
		ToolMeta:        tool.ToolMeta{ToolName: "shell", Status: "running"},
		StreamingOutput: true,
	})

	vr := renderViewport(&vm, 80, 40, 1<<30, DiffThemeDark)
	plain := stripANSI(strings.Join(vr.lines, "\n"))
	if !strings.Contains(plain, "live line 20") {
		t.Fatalf("live shell preview did not follow newest output:\n%s", plain)
	}
	if strings.Contains(plain, "live line 01") {
		t.Fatalf("collapsed live shell preview should show the output tail:\n%s", plain)
	}
	if !strings.Contains(plain, "earlier lines") {
		t.Fatalf("live shell preview should explain omitted earlier lines:\n%s", plain)
	}
}

type wizardSelector struct {
	selects       []string
	inputs        []string
	confirms      []bool
	inputLabels   []string
	inputDefaults []string
	si            int
	ii            int
	ci            int
}

func (f *wizardSelector) Select(string, []string, string) (string, bool, error) {
	if f.si >= len(f.selects) {
		return "", false, nil
	}
	v := f.selects[f.si]
	f.si++
	return v, true, nil
}

func (f *wizardSelector) MultiSelect(string, []string, []string) ([]string, bool, error) {
	return nil, false, nil
}

func (f *wizardSelector) Input(label string, defaultValue string) (string, bool, error) {
	f.inputLabels = append(f.inputLabels, label)
	f.inputDefaults = append(f.inputDefaults, defaultValue)
	if f.ii >= len(f.inputs) {
		return "", false, nil
	}
	v := f.inputs[f.ii]
	f.ii++
	return v, true, nil
}

func (f *wizardSelector) Confirm(string, bool) (bool, bool, error) {
	if f.ci >= len(f.confirms) {
		return false, false, nil
	}
	v := f.confirms[f.ci]
	f.ci++
	return v, true, nil
}

func (f *wizardSelector) SelectRich(_ string, items []SelectItem, _ int) (int, bool, error) {
	if f.si >= len(f.selects) {
		return -1, false, nil
	}
	v := f.selects[f.si]
	f.si++
	return scriptedItem(items, v)
}

func (f *wizardSelector) Secret(label string, defaultValue string) (string, bool, error) {
	return f.Input(label, defaultValue)
}

// Review saves unless the script runs out of answers before it: a wizard run
// that scripts nothing is one the user closes.
func (f *wizardSelector) Review(string, []turn.StatusFact, []string, int) (int, bool, error) {
	if f.si >= len(f.selects) && f.ii >= len(f.inputs) {
		return -1, false, nil
	}
	return 0, true, nil
}

