// Back on the providers, the picker opens on the provider picked before —
// and on the plan picked before, for a provider offered by plan.
func TestSetupBackOnProvidersOpensOnTheChoiceMade(t *testing.T) {
	useSetupTestCatalog(t)
	for _, tc := range []struct {
		name    string
		selects []string
		want    []string
	}{
		{"single way in", []string{"OpenAI", "OpenAI"}, []string{"", "OpenAI"}},
		{"by plan", []string{"Qwen Cloud", "Coding Plan API Key for Global/Intl (subscription)", "Qwen Cloud", "Coding Plan API Key for Global/Intl (subscription)"},
			[]string{"", "", "Qwen Cloud", "Coding Plan API Key for Global/Intl (subscription)"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			title := "OpenAI API key"
			if strings.HasPrefix(tc.name, "by plan") {
				title = "Qwen API key"
			}
			selector := &backtrackSelector{fakeSelector: fakeSelector{selects: tc.selects, inputs: []string{"sk-test"}}, backAt: map[string]int{title: 1}}
			if _, _, err := PromptMainLLMSetup(PromptConfig{Selector: selector}); err != nil {
				t.Fatalf("setup: %v", err)
			}
			if got := selector.selectDefaults[:len(tc.want)]; strings.Join(got, "|") != strings.Join(tc.want, "|") {
				t.Fatalf("pickers opened on %q, want %q", got, tc.want)
			}
		})
	}
}

// backtrackSelector presses Esc on a page the first backAt[title] times it
// opens, and records every page title it is shown.
type backtrackSelector struct {
	fakeSelector
	backAt map[string]int
	pages  []string
}

func (s *backtrackSelector) page(label string) bool {
	title, _, _ := strings.Cut(label, "\n")
	s.pages = append(s.pages, title)
	if s.backAt[title] > 0 {
		s.backAt[title]--
		return true
	}
	return false
}

func (s *backtrackSelector) Select(label string, options []string, defaultOption string) (string, bool, error) {
	s.page(label)
	return s.fakeSelector.Select(label, options, defaultOption)
}

func (s *backtrackSelector) SelectRich(label string, items []SelectItem, defaultIdx int) (int, bool, error) {
	if s.page(label) {
		return -1, false, nil
	}
	if strings.HasPrefix(label, "Channels\n") {
		return 0, true, nil
	}
	return s.fakeSelector.SelectRich(label, items, defaultIdx)
}

func (s *backtrackSelector) MultiSelect(string, []string, []string) ([]string, bool, error) {
	return nil, false, nil
}

func (s *backtrackSelector) Secret(label string, defaultValue string) (string, bool, error) {
	if s.page(label) {
		return "", false, nil
	}
	return s.fakeSelector.Secret(label, defaultValue)
}

func (s *backtrackSelector) Review(label string, facts []turn.StatusFact, actions []string, _ int) (int, bool, error) {
	if s.page(label) {
		return -1, false, nil
	}
	return 0, true, nil
}

