// agentChannelsConfig builds a configuration whose main agent owns channels.
// There is nowhere else to put them: a channel is always some agent's.
func agentChannelsConfig(channels appcfg.ChannelsSection) appcfg.Root {
	cfg := appcfg.Root{}
	appcfg.SetChannelsForAgent(&cfg, "main", channels)
	return cfg
}

// Configuring a channel under one primary agent must leave every other agent's
// channels untouched, and its secret must be stored under an agent-scoped
// variable so two agents cannot overwrite each other's token.
func TestChannelConfigurationIsScopedToOnePrimaryAgent(t *testing.T) {
	home := t.TempDir()
	cfgPath := filepath.Join(home, "forebrain.yaml")
	if err := os.WriteFile(cfgPath, []byte("agents: {}\n"), 0o600); err != nil {
		t.Fatalf("write config: %v", err)
	}
	cfg := appcfg.Root{}
	cfg.Agents.Definitions = map[string]appcfg.AgentDefinition{
		"main": {},
		"acme": {Primary: true},
	}
	w := &Wizard{
		rt: process.Context{Home: home, ConfigPath: cfgPath, Config: cfg},
		selector: &wizardSelector{
			inputs: []string{"acme-telegram-token"},
		},
	}

	if err := w.handleChannelChoice("acme", "telegram"); err != nil {
		t.Fatalf("handleChannelChoice error: %v", err)
	}

	acme := appcfg.ChannelsForAgent(&w.rt.Config, "acme")
	if !acme.Telegram.Enabled {
		t.Fatalf("acme telegram not configured: %+v", acme.Telegram)
	}
	if got := acme.Telegram.BotToken; got != "${FOREBRAIN_ACME_TELEGRAM_BOT_TOKEN}" {
		t.Fatalf("acme bot token reference = %q, want an acme-scoped env reference", got)
	}
	if main := appcfg.ChannelsForAgent(&w.rt.Config, "main"); main.Telegram.Enabled || main.Telegram.BotToken != "" {
		t.Fatalf("configuring acme's telegram changed main's: %+v", main.Telegram)
	}
}

var _ Selector = (*wizardSelector)(nil)

// TestCharacterizationSlashReloadKeepsEnvironmentConfigLive pins the invariant
// that the Environment's config is the live one after a slash-triggered
// reload, not just the session's own copy.
//
// The TUI has two reload paths. Environment.reloadConfig pushes the new value
// into the session through OnConfigReload, but the slash-command path
// (reloadConfigFromDisk, reached from /model and friends) writes s.cfg() and
// s.runner().AppCfg and nothing else. Env.Config is never assigned anywhere in
// pkg/tui, so the sync only ever ran in one direction.
//
// This is load-bearing rather than tidy: Environment.stateRoot() resolves the
// active primary agent's workspace from Env.Config, and the run executor calls
// AgentContextForProject with it after the TUI has already built a context
// from its own copy. The executor's value therefore wins, so a stale Env.Config
// would silently send the agent's plan-path and session-mode lookups at the
// previous agent's workspace.
func TestCharacterizationSlashReloadKeepsEnvironmentConfigLive(t *testing.T) {
	reply := llm.AssistantMessage([]llm.ContentPart{llm.Text("done")})
	s := newCharacterizationSession(t, &steerInjectingLLM{results: []*llm.Result{{Message: &reply}}})

	t.Setenv("FOREBRAIN_CHARACTERIZATION_TEST_KEY", "test-key")
	s.cfg().Agents.Definitions["main"].LLMProviders[0].APIKey = "${FOREBRAIN_CHARACTERIZATION_TEST_KEY}"
	cfgPath := filepath.Join(s.home(), "forebrain.yaml")
	if err := appcfg.Save(cfgPath, *s.cfg()); err != nil {
		t.Fatalf("appcfg.Save (initial): %v", err)
	}

	updated := *s.cfg()
	updated.Agents.Definitions = map[string]appcfg.AgentDefinition{
		"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{{
			Provider: "openai", Model: "gpt-main-v2",
			APIKey: "${FOREBRAIN_CHARACTERIZATION_TEST_KEY}", BaseURL: "https://example.invalid",
		}}},
	}
	if err := appcfg.Save(cfgPath, updated); err != nil {
		t.Fatalf("appcfg.Save (updated): %v", err)
	}

	if err := s.reloadConfigFromDisk(); err != nil {
		t.Fatalf("reloadConfigFromDisk = %v, want nil", err)
	}

	if got := s.cfg().Agents.Definitions["main"].LLMProviders[0].Model; got != "gpt-main-v2" {
		t.Fatalf("session config model = %q, want the reloaded value", got)
	}
	if s.Env == nil || s.Env.Deps.AppCfg == nil {
		t.Fatal("characterization session must carry an Environment with a config")
	}
	if got := s.Env.Deps.AppCfg.Agents.Definitions["main"].LLMProviders[0].Model; got != "gpt-main-v2" {
		t.Fatalf("Environment config model = %q, want %q: a slash-triggered reload must leave "+
			"the Environment holding the live config, because the run executor resolves the "+
			"agent state root from it", got, "gpt-main-v2")
	}
}

// TestCharacterizationHotReloadKeepsTheSessionPermissionPreset pins that a
// preset chosen with /permissions survives a hot reload of forebrain.yaml.
//
// The choice is never written to forebrain.yaml; it lives in the permission
// store, scoped to the session, so the environment's hot reload — which
// cannot see session state — has nothing to undo. Editing the config file for
// any unrelated reason must not silently revert the user's sandbox choice,
// and the choice must not leak into the reloaded config either.
func TestCharacterizationHotReloadKeepsTheSessionPermissionPreset(t *testing.T) {
	reply := llm.AssistantMessage([]llm.ContentPart{llm.Text("done")})
	s := newCharacterizationSession(t, &steerInjectingLLM{results: []*llm.Result{{Message: &reply}}})

	t.Setenv("FOREBRAIN_CHARACTERIZATION_TEST_KEY", "test-key")
	s.cfg().Agents.Definitions["main"].LLMProviders[0].APIKey = "${FOREBRAIN_CHARACTERIZATION_TEST_KEY}"
	// The file on disk asks for a writable workspace.
	s.cfg().SandboxMode = appcfg.SandboxModeWorkspaceWrite
	cfgPath := filepath.Join(s.home(), "forebrain.yaml")
	if err := appcfg.Save(cfgPath, *s.cfg()); err != nil {
		t.Fatalf("appcfg.Save: %v", err)
	}

	// The user then picks the more restrictive preset for this session only.
	if _, err := s.ApplyPermissionPreset("char-preset", string(safety.PresetReadOnly)); err != nil {
		t.Fatalf("ApplyPermissionPreset: %v", err)
	}
	sessionSandbox := func() appcfg.SandboxMode {
		return safety.ConfigForSnapshot(s.cfg(), s.runner().PermissionSnapshotForSession("char-preset")).SandboxMode
	}
	if got := sessionSandbox(); got != appcfg.SandboxModeReadOnly {
		t.Fatalf("session sandbox after preset = %q, want %q", got, appcfg.SandboxModeReadOnly)
	}

	// A hot reload of the same unchanged file must not undo that.
	if err := s.Env.ReloadConfig(); err != nil {
		t.Fatalf("ReloadConfig: %v", err)
	}
	if got := sessionSandbox(); got != appcfg.SandboxModeReadOnly {
		t.Fatalf("session sandbox after hot reload = %q, want the session preset %q to survive: "+
			"reloading forebrain.yaml must not silently restore the sandbox the user moved away from",
			got, appcfg.SandboxModeReadOnly)
	}
	if got := s.cfg().SandboxMode; got != appcfg.SandboxModeWorkspaceWrite {
		t.Fatalf("live config sandbox = %q, want the file's %q: a session preset must not move the config other conversations run under",
			got, appcfg.SandboxModeWorkspaceWrite)
	}
}

// TestCharacterizationHotReloadLetsYOLOOutrankTheSessionPreset pins the other
// half of the rule above: a session-scoped preset may not walk back YOLO.
//
// YOLO comes from the environment, not from anything the user picked in this
// session, so the session's own sandbox choice gives way to it.
func TestCharacterizationHotReloadLetsYOLOOutrankTheSessionPreset(t *testing.T) {
	reply := llm.AssistantMessage([]llm.ContentPart{llm.Text("done")})
	s := newCharacterizationSession(t, &steerInjectingLLM{results: []*llm.Result{{Message: &reply}}})

	t.Setenv("FOREBRAIN_CHARACTERIZATION_TEST_KEY", "test-key")
	s.cfg().Agents.Definitions["main"].LLMProviders[0].APIKey = "${FOREBRAIN_CHARACTERIZATION_TEST_KEY}"
	s.cfg().SandboxMode = appcfg.SandboxModeWorkspaceWrite
	if err := appcfg.Save(filepath.Join(s.home(), "forebrain.yaml"), *s.cfg()); err != nil {
		t.Fatalf("appcfg.Save: %v", err)
	}
	if _, err := s.ApplyPermissionPreset("char-preset-yolo", string(safety.PresetReadOnly)); err != nil {
		t.Fatalf("ApplyPermissionPreset: %v", err)
	}

	t.Setenv(safety.EnvYOLO, "1")
	if err := s.Env.ReloadConfig(); err != nil {
		t.Fatalf("ReloadConfig: %v", err)
	}
	snap := s.runner().PermissionSnapshotForSession("char-preset-yolo")
	if got := safety.ConfigForSnapshot(s.cfg(), snap).SandboxMode; got != appcfg.SandboxModeDangerFullAccess {
		t.Fatalf("session sandbox under YOLO = %q, want %q: a session preset must not walk YOLO back",
			got, appcfg.SandboxModeDangerFullAccess)
	}
}

// TestReloadConfigFromDiskRepointsEveryConfigHolder pins P2-8's invariant: the
// environment is the single owner of the live config, and a reload swaps the
// pointer it holds rather than overwriting a value in place.
//
// Two things follow, and both used to be easy to get wrong. The session must
// read the new config without being told (it has no copy of its own any more),
// and every pointer the session handed out has to be re-pointed -- the user
// hook runtime captured &ChatSession.Config at construction and was never
// updated, which only worked while that field was a value whose contents were
// overwritten. Reading the config through the environment turns that silent
// aliasing into an explicit hand-off.
func TestReloadConfigFromDiskRepointsEveryConfigHolder(t *testing.T) {
	t.Setenv("FOREBRAIN_REPOINT_TEST_KEY", "test-key")
	home := t.TempDir()
	t.Setenv("FOREBRAIN_HOME", home)
	path := filepath.Join(home, "forebrain.yaml")
	body := "agents:\n  definitions:\n    main:\n      llm_providers:\n" +
		"        - provider: openai\n          model: gpt-old\n" +
		"          api_key: ${FOREBRAIN_REPOINT_TEST_KEY}\n          base_url: http://localhost:0/v1\n"
	require.NoError(t, os.WriteFile(path, []byte(body), 0o600))
	cfg, err := appcfg.Load(path)
	require.NoError(t, err)

	runner := &run.Runner{Deps: &run.Deps{Home: home, AgentName: "main", AppCfg: &cfg}}
	require.NoError(t, runner.Load())
	s := sessionEnv{Home: home, Config: cfg, Runner: runner}.session()
	s.userHooks = &hook.Runtime{Home: home, Cfg: s.cfg()}

	before := s.cfg()
	require.NoError(t, os.WriteFile(path, []byte(strings.Replace(body, "gpt-old", "gpt-new", 1)), 0o600))
	require.NoError(t, s.reloadConfigFromDisk())

	require.NotSame(t, before, s.cfg(), "a reload must publish a new config, not mutate the old one in place")
	require.Equal(t, "gpt-new", s.cfg().Agents.Definitions["main"].LLMProviders[0].Model)
	require.Same(t, s.cfg(), s.Env.Deps.AppCfg,
		"the session must read the environment's config, not a copy of it")
	require.Same(t, s.cfg(), s.runner().AppCfg,
		"the runner shares the environment's Deps, so it sees the same config")
	require.Same(t, s.cfg(), s.userHooks.Cfg,
		"the user hook runtime holds a pointer the session handed out; a reload must re-point it")
}

// sessionEnv describes the process.Environment a ChatSession under test reads
// through. P2-8 moved Home/Config/Sandbox/SQL/the stores/Runner/Pipe off the
// session and onto the environment, which is now their single owner; the field
// names here match what the session literal used to carry so the fixtures read
// the same way they did before.
type sessionEnv struct {
	Home        string
	Config      appcfg.Root
	Sandbox     *safety.Manager
	SQL         *sql.DB
	MemoryStore *memory.Store
	SessStore   *state.SessionStore
	ActionSvc   *state.ActionService
	Runner      *run.Runner
	Pipe        *hook.AgentPipeline
	RunSvc      *state.RunStore
}

// session builds the ChatSession over the described environment.
//
// A supplied Runner is re-pointed at the environment's Deps, because that is
// the invariant production establishes (process.Open hands the runner
// &Environment.Deps). A fixture that let the two hold separate Deps would pass
// while the real wiring diverged.
func (e sessionEnv) session() *ChatSession {
	env := &process.Environment{
		Root:    e.Home,
		SQL:     e.SQL,
		Sandbox: e.Sandbox,
		Runner:  e.Runner,
		Hooks:   e.Pipe,
	}
	if e.Home != "" {
		// process.Open always fills this in, and the environment's reload path
		// refuses to run without it.
		env.ConfigPath = filepath.Join(e.Home, "forebrain.yaml")
	}
	if e.Runner != nil && e.Runner.Deps != nil {
		env.Deps = *e.Runner.Deps
	}
	cfg := e.Config
	if env.Deps.AppCfg == nil {
		env.Deps.AppCfg = &cfg
	}
	if e.Home != "" {
		env.Deps.Home = e.Home
	}
	if e.MemoryStore != nil {
		env.Deps.MemoryStore = e.MemoryStore
	}
	if e.SessStore != nil {
		env.Deps.SessionStore = e.SessStore
	}
	if e.ActionSvc != nil {
		env.Deps.Actions = e.ActionSvc
	}
	if e.RunSvc != nil {
		// Every production store carries the process owner process.Open
		// stamped on it; the resume claims these tests drive are refused
		// without one.
		if strings.TrimSpace(e.RunSvc.Owner) == "" {
			e.RunSvc.Owner = "tui-test"
		}
		env.Deps.RunRT = e.RunSvc
	}
	if e.Runner != nil {
		e.Runner.Deps = &env.Deps
	}
	// One controller, shared: the environment asks it whether a run is active
	// before applying a config reload, while the session asks it the same
	// question through tuiRunActive. Two controllers would disagree, and a
	// reload meant to be deferred would land mid-run.
	if env.Control == nil {
		env.Control = run.NewController()
	}
	return &ChatSession{Env: env, tuiControl: env.Control}
}

// ptrTo publishes a config value into the environment, which owns it by
// pointer.
func ptrTo(v appcfg.Root) *appcfg.Root { return &v }

// The second half of the reported bug: three fanout subagents were shown as
// failed on the fanout card, but opening any one of them showed its last
// assistant message and nothing else — the reason it stopped was in the one
// place the user was not looking. The closing frame is tagged with the roster
// key, so it belongs to that subagent's own view, and the fanout card in the
// primary transcript keeps its own account of the same event.
func TestSubagentFailureLandsInItsOwnView(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() {
		forcedTermWidth = 0
		forcedTermHeight = 0
	})
	r := NewRenderer(nil, nil)
	r.viewportMode = true
	r.composerSuppressed = true

	const rosterKey = "task-plan-1"
	r.RenderFrame(Frame{Kind: FrameAssistant, Content: "primary answer"})
	r.RenderFrame(Frame{
		Kind:    FrameError,
		Title:   "subagent failed",
		Content: "the sandbox blocked git grep",
		AgentID: rosterKey,
		Final:   true,
	})

	primary := stripANSI(strings.Join(renderViewport(&r.vm, 80, 24, 1<<30, DiffThemeDark).lines, "\n"))
	if strings.Contains(primary, "the sandbox blocked git grep") {
		t.Fatalf("a subagent's own failure must not be retained on the primary transcript:\n%s", primary)
	}
	vm, ok := r.perAgentVM[rosterKey]
	if !ok || vm == nil {
		t.Fatalf("expected per-agent VM for roster key %q, got %v", rosterKey, r.perAgentVM)
	}
	painted := stripANSI(strings.Join(renderViewport(vm, 80, 24, 1<<30, DiffThemeDark).lines, "\n"))
	if !strings.Contains(painted, "the sandbox blocked git grep") {
		t.Fatalf("the subagent's view must end on why it stopped, got:\n%s", painted)
	}
}

// A terminal error that belongs to no subagent stays global: it is retained on
// the primary transcript and mirrored into whichever subagent view is open.
func TestUnownedErrorStaysGlobal(t *testing.T) {
	forcedTermWidth = 80
	forcedTermHeight = 24
	t.Cleanup(func() {
		forcedTermWidth = 0
		forcedTermHeight = 0
	})
	r := NewRenderer(nil, nil)
	r.viewportMode = true
	r.composerSuppressed = true

	r.RenderFrame(Frame{Kind: FrameError, Title: "error", Content: "the provider refused the request", Final: true})
	primary := stripANSI(strings.Join(renderViewport(&r.vm, 80, 24, 1<<30, DiffThemeDark).lines, "\n"))
	if !strings.Contains(primary, "the provider refused the request") {
		t.Fatalf("an unowned error must stay on the primary transcript:\n%s", primary)
	}
}

// The helpers below were production functions that only the tests ever
// called: each is a thin composition of live code. They live here so the
// production files carry no unused code while the tests keep exercising
// the live functions underneath.

// OpenChatSessionWithConfig is a variant of OpenChatSession that accepts a
// pre-loaded config, skipping the redundant appcfg.Load() call inside
// openChatSession. Use this when the caller (e.g. the TUI startup flow) has
// already loaded the config via process.Resolve().
func OpenChatSessionWithConfig(ctx context.Context, cfg appcfg.Root) (*ChatSession, error) {
	return openProcessChatSession(ctx, cfg, "")
}

func (s *ChatSession) sqlDB() *sql.DB {
	if s == nil || s.Env == nil {
		return nil
	}
	return s.Env.SQL
}

func (s *ChatSession) tuiTrack(runID, sessionID string, cancel context.CancelFunc) {
	if s == nil {
		return
	}
	s.tuiRunMu.Lock()
	if s.tuiTurnInputRT == nil {
		s.tuiTurnInputRT = run.NewTurnInputRuntime()
	}
	s.installTUITurnInputRuntimeHookLocked(runID, "")
	ctl, rt := s.tuiControlLocked(), s.tuiTurnInputRT
	s.tuiRunMu.Unlock()
	ctl.TrackRuntime(runID, sessionID, cancel, rt)
	s.notifyUI(RunStartedMsg{RunID: runID})
}

func SupportedProviders() []string {
	seen := make(map[string]struct{}, len(providerGroups))
	out := make([]string, 0, len(providerGroups))
	for _, group := range providerGroups {
		for _, choice := range group.Options {
			provider := strings.TrimSpace(choice.Provider)
			if provider == "" {
				continue
			}
			if _, ok := seen[provider]; ok {
				continue
			}
			seen[provider] = struct{}{}
			out = append(out, provider)
		}
	}
	return out
}

func exactCatalogMatch(token string) (llm.Model, bool) {
	needle := strings.ToLower(strings.TrimSpace(token))
	if needle == "" {
		return llm.Model{}, false
	}
	for _, m := range llm.AllModels() {
		if strings.EqualFold(m.ID, needle) || strings.EqualFold(m.APIModel, needle) {
			return m, true
		}
	}
	return llm.Model{}, false
}

func TestCatalogModelsHaveAPIModelWhenMatchedByID(t *testing.T) {
	for _, m := range llm.AllModels() {
		got, ok := exactCatalogMatch(m.ID)
		if !ok {
			t.Fatalf("expected id match for %q", m.ID)
		}
		if got.ID != m.ID {
			t.Fatalf("id=%q model=%+v", m.ID, got)
		}
		if strings.TrimSpace(got.APIModel) == "" {
			t.Fatalf("catalog model %q has blank APIModel", m.ID)
		}
	}
}

// Saving a memory note is something Forebrain Harness does alongside the user's request,
// never the request itself, so refusing it must leave the run alive. The
// overlay's negative row is therefore a denial, and the "n" key reaches it.
func TestMemoryApprovalOverlayRefusalDeniesWithoutCancellingTheTurn(t *testing.T) {
	for _, tc := range []struct {
		name      string
		toolName  string
		inputJSON string
		wantLabel string
	}{
		{
			name:      "note",
			toolName:  "memories_add_ad_hoc_note",
			inputJSON: `{"filename":"2026-09-11T08-54-34-superchat-kb.md","note":"# Endpoint"}`,
			wantLabel: "No, don't save this note",
		},
		{
			name:      "read",
			toolName:  "memories_read",
			inputJSON: `{"path":"MEMORY.md"}`,
			wantLabel: "No, continue without reading memory",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			req := withServiceDecisions(turn.ToolApprovalRequest{ToolName: tc.toolName, ToolInputJSON: tc.inputJSON})
			overlay := newApprovalOverlay(context.Background(), io.Discard, nil, req, nil)

			plain := stripANSI(strings.Join(func() []string { lines, _ := overlay.buildApprovalContent(80); return lines }(), "\n"))
			if !strings.Contains(plain, tc.wantLabel) {
				t.Fatalf("overlay missing %q:\n%s", tc.wantLabel, plain)
			}
			for _, option := range overlay.options {
				if option.cancel {
					t.Fatalf("memory approval offered a turn-cancelling row: %#v", overlay.options)
				}
			}

			decision, done := overlay.handleKey(parsedKey{kind: rawKeyRune, r: 'n'})
			if !done || !decision.Denied || decision.Cancelled || decision.Approved {
				t.Fatalf("refusal decision = %#v done=%v", decision, done)
			}
			if choice := approvalChoice(&state.Action{Kind: tc.toolName}, decision); choice != "deny" {
				t.Fatalf("refusal choice = %q, want deny", choice)
			}
		})
	}
}

// A declined memory note keeps the run alive, so its card must say the note
// was denied. Reporting a cancel there told the user the whole turn had been
// torn down when Forebrain Harness was already carrying on without the note.
func TestResumeAfterDenialMarksMemoryNoteCardDenied(t *testing.T) {
	ctx := context.Background()
	home := t.TempDir()
	db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
	if err != nil {
		t.Fatalf("OpenStateForTest: %v", err)
	}
	defer db.Close()

	actions := newTestActions(t, db)
	act, err := actions.CreatePending(ctx, "s1", "memories_add_ad_hoc_note", map[string]any{"filename": "2026-09-11T08-54-34-note.md"})
	if err != nil {
		t.Fatalf("CreatePending: %v", err)
	}
	if _, err := actions.Deny(ctx, act.ID, ""); err != nil {
		t.Fatalf("Deny: %v", err)
	}
	runs := &state.RunStore{DB: db}
	if err := state.NewSessionStore(db, "main").Ensure(ctx, "session-1", "session-1"); err != nil {
		t.Fatal(err)
	}
	run, err := runs.CreateRun(ctx, "session-1", "remember the endpoint")
	if err != nil {
		t.Fatalf("CreateRun: %v", err)
	}

	snapshot := []llm.Message{
		llm.AssistantMessage(nil,
			llm.ToolCall{ID: "note-call-1", Type: llm.ToolTypeFunction, Function: llm.FunctionCall{
				Name: "memories_add_ad_hoc_note", Arguments: `{"filename":"2026-09-11T08-54-34-note.md","note":"# Endpoint"}`,
			}},
		),
	}
	cs := sessionEnv{Home: home, ActionSvc: actions, RunSvc: runs}.session()
	notified := make(chan NewMessageMsg, 1)
	cs.PrependUINotify(func(msg any) {
		if event, ok := msg.(NewMessageMsg); ok {
			notified <- event
		}
	})
	cs.setPendingApproval(&chatApprovalResume{
		ActionID:        act.ID,
		RunID:           run.ID,
		SessionID:       "session-1",
		ToolName:        "memories_add_ad_hoc_note",
		ToolStepID:      "note-call-1",
		SessionSnapshot: snapshot,
	})
	t.Cleanup(cs.stopUINotificationDispatcher)

	if !cs.resumeAfterDenial(act.ID) {
		t.Fatal("resumeAfterDenial returned false")
	}
	select {
	case event := <-notified:
		if event.Msg.ToolName != "memories_add_ad_hoc_note" || event.Msg.ToolMeta.Status != "denied" {
			t.Fatalf("notification = %#v", event.Msg)
		}
		action, _, _ := toolDisplayParts(Frame{
			Kind: FrameTool, Title: event.Msg.ToolName, ToolMeta: event.Msg.ToolMeta, Final: true,
		}, "", home)
		if action != "Memory note save denied" {
			t.Fatalf("card action = %q", action)
		}
	case <-time.After(time.Second):
		t.Fatal("timed out waiting for denied memory-note notification")
	}
}

// A refused call never ran, so its card must not report it in the past tense.
// Tools that phrase their own refusal keep it; everything else falls back to
// the same flat verdict the canceled path already used.
func TestToolCardRefusalNeverClaimsTheCallRan(t *testing.T) {
	for _, tc := range []struct {
		title string
		meta  tool.ToolMeta
		want  string
	}{
		{title: "shell", meta: tool.ToolMeta{Status: "denied", Input: map[string]any{"command": "rm -rf /tmp/x"}}, want: "Denied"},
		{title: "write_file", meta: tool.ToolMeta{Status: "denied", Input: map[string]any{"file_path": "/repo/main.go"}}, want: "Denied"},
		{title: "exit_plan_mode", meta: tool.ToolMeta{Status: "denied"}, want: "Kept planning"},
		{title: "memories_add_ad_hoc_note", meta: tool.ToolMeta{Status: "denied", Input: map[string]any{"filename": "note.md"}}, want: "Memory note save denied"},
		{title: "memories_read", meta: tool.ToolMeta{Status: "denied", Input: map[string]any{"path": "MEMORY.md"}}, want: "Memory read denied"},
	} {
		action, _, suffix := toolDisplayParts(Frame{Kind: FrameTool, Title: tc.title, ToolMeta: tc.meta, Final: true}, "", "/repo")
		if action != tc.want {
			t.Fatalf("%s denied action = %q, want %q", tc.title, action, tc.want)
		}
		if tc.want == "Denied" && suffix != "" {
			t.Fatalf("%s denied card kept a suffix %q", tc.title, suffix)
		}
	}
}

// Esc dismisses the prompt, and which refusal that is belongs to the request:
// a memory note or a permission request is declined so the run survives, while
// a request that offers a cancel is still torn down. ctrl+c stays the terminal
// interrupt in every case.
func TestApprovalOverlayEscapeRefusesTheWayTheRequestDoes(t *testing.T) {
	for _, tc := range []struct {
		name     string
		req      turn.ToolApprovalRequest
		wantDeny bool
		wantHint string
	}{
		{
			name:     "memory note",
			req:      turn.ToolApprovalRequest{ToolName: "memories_add_ad_hoc_note", ToolInputJSON: `{"filename":"2026-09-11T08-54-34-note.md","note":"# Note"}`},
			wantDeny: true,
			wantHint: "Esc to decline",
		},
		{
			name:     "memory read",
			req:      turn.ToolApprovalRequest{ToolName: "memories_read", ToolInputJSON: `{"path":"MEMORY.md"}`},
			wantDeny: true,
			wantHint: "Esc to decline",
		},
		{
			name:     "request_permissions",
			req:      turn.ToolApprovalRequest{ToolName: "request_permissions", ActionKind: "request_permissions", ToolInputJSON: `{"reason":"inspect"}`},
			wantDeny: true,
			wantHint: "Esc to decline",
		},
		{
			name:     "shell",
			req:      turn.ToolApprovalRequest{ToolName: "shell", ToolInputJSON: `{"command":"ls"}`},
			wantDeny: false,
			wantHint: "Esc to cancel",
		},
		{
			name:     "exit_plan_mode",
			req:      turn.ToolApprovalRequest{ToolName: "exit_plan_mode", ActionKind: "exit_plan_mode", ToolInputJSON: `{"action":"exit"}`},
			wantDeny: false,
			wantHint: "Esc to cancel",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			overlay := newApprovalOverlay(context.Background(), io.Discard, nil, withServiceDecisions(tc.req), nil)

			decision, done := overlay.handleKey(parsedKey{kind: rawKeyEscape})
			if !done || decision.Denied != tc.wantDeny || decision.Cancelled == tc.wantDeny {
				t.Fatalf("escape decision = %#v done=%v", decision, done)
			}
			interrupt, done := overlay.handleKey(parsedKey{kind: rawKeyCtrlC})
			if !done || !interrupt.Cancelled {
				t.Fatalf("ctrl+c decision = %#v done=%v", interrupt, done)
			}

			lines, _ := overlay.buildApprovalContent(80)
			if plain := stripANSI(strings.Join(lines, "\n")); !strings.Contains(plain, tc.wantHint) {
				t.Fatalf("overlay hint missing %q:\n%s", tc.wantHint, plain)
			}
		})
	}
}

// ---- approval display records: what a surface showed must be replayable ----

// sessionEventsForTest reads a session's display history in cursor order.
func sessionEventsForTest(t *testing.T, runs *state.RunStore, sessionID string) []state.SessionEvent {
	t.Helper()
	page, err := runs.ListSessionEvents(context.Background(), sessionID, 0, 0, 200)
	if err != nil {
		t.Fatalf("ListSessionEvents error: %v", err)
	}
	return page.Events
}

func approvalEventsOfType(t *testing.T, runs *state.RunStore, sessionID, eventType string) []state.SessionEvent {
	t.Helper()
	var out []state.SessionEvent
	for _, e := range sessionEventsForTest(t, runs, sessionID) {
		if strings.TrimSpace(e.Type) == eventType {
			out = append(out, e)
		}
	}
	return out
}

// A canceled plan-mode gate says what was canceled. Without a branch of its own
// it fell through to the generic "the request to run <permission input>" wording,
// which for plan mode is the tool's whole argument JSON - the plan document
// itself - printed back at the user as the thing they had just refused.
func TestPlanModeCancellationNamesTheActionNotItsInputJSON(t *testing.T) {
	for _, tc := range []struct{ tool, want string }{
		{"exit_plan_mode", "You canceled forebrain's request to exit plan mode"},
		{"enter_plan_mode", "You canceled forebrain's request to enter plan mode"},
	} {
		t.Run(tc.tool, func(t *testing.T) {
			req := withServiceDecisions(turn.ToolApprovalRequest{
				ToolName: tc.tool, ActionKind: tc.tool, ToolInputJSON: `{"plan":"do the thing"}`,
			})
			decision := turn.ToolApprovalDecision{Cancelled: true}
			got, ok := approvalConfirmationText(req, decision)
			if got != tc.want || ok {
				t.Fatalf("cancel confirmation = %q (%v), want %q (false)", got, ok, tc.want)
			}
			if strings.Contains(got, "do the thing") || strings.ContainsAny(got, "{}") {
				t.Fatalf("the confirmation carried the tool's input JSON: %q", got)
			}
			if line, lineOK := approvalConfirmationLine(req, decision); line != "✗ "+tc.want || lineOK {
				t.Fatalf("confirmation line = %q (%v)", line, lineOK)
			}
		})
	}
}

// The gate is recorded before the overlay is drawn and the answer before the
// line is printed, so a user who answers a prompt and quits - or is interrupted
// while it is open - still finds both in the session's display history.
func TestApprovalSinkPersistsTheGateAndTheCancelThatAnswerIt(t *testing.T) {
	ctx := context.Background()
	home := t.TempDir()
	db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
	require.NoError(t, err)
	defer db.Close()

	actions := newTestActions(t, db)
	runs := &state.RunStore{DB: db}
	run, err := runs.CreateRun(ctx, "s1", "plan the work")
	require.NoError(t, err)
	act, err := actions.CreatePending(ctx, "s1", "exit_plan_mode", map[string]any{"plan": "do the thing"})
	require.NoError(t, err)
	require.NoError(t, runs.SetWaitingAction(ctx, run.ID, state.Wait{
		RunID: run.ID, ActionID: act.ID, ToolName: "exit_plan_mode",
		ToolInputJSON: `{"plan":"do the thing"}`,
		SessionSnapshot: []llm.Message{
			llm.UserMessage(llm.Text("plan the work")),
			llm.AssistantMessage([]llm.ContentPart{llm.Text("thinking")}, llm.ToolCall{
				ID: "call-exit", Type: llm.ToolTypeFunction,
				Function: llm.FunctionCall{Name: "exit_plan_mode", Arguments: `{"plan":"do the thing"}`},
			}),
		},
	}))

	cs := sessionEnv{Home: home, ActionSvc: actions, RunSvc: runs}.session()
	req, err := cs.buildSurfaceToolApprovalRequest(ctx, "s1")
	require.NoError(t, err)
	require.NotNil(t, req)
	// The wait row's snapshot is the durable source for the parked call, and the
	// card identity has to survive to the surface for the record to anchor.
	if req.ToolStepID != "call-exit" {
		t.Fatalf("approval request ToolStepID = %q, want the parked call", req.ToolStepID)
	}

	f := newFakeRawSelector(t)
	f.write([]byte{0x1b})
	f.close()

	var out bytes.Buffer
	sink := NewInteractiveApprovalSinkWithTTY(&out, f.rs).WithRecorder(cs)
	decision, err := sink.PromptToolApproval(ctx, *req)
	require.NoError(t, err)
	require.True(t, decision.Cancelled, "esc must cancel a plan-mode gate: %#v", decision)

	gates := approvalEventsOfType(t, runs, "s1", event.RunEventApprovalReq)
	require.Len(t, gates, 1, "the gate the user saw must be recorded exactly once")
	var requested event.ApprovalRequestedPayload
	require.NoError(t, json.Unmarshal(gates[0].Payload, &requested))
	if requested.ActionID != act.ID || requested.ActionKind != "exit_plan_mode" || requested.ToolStepID != "call-exit" {
		t.Fatalf("gate record = %+v", requested)
	}

	resolved := approvalEventsOfType(t, runs, "s1", event.RunEventApprovalResolved)
	require.Len(t, resolved, 1)
	var p event.ApprovalResolvedPayload
	require.NoError(t, json.Unmarshal(resolved[0].Payload, &p))
	if p.Decision != string(state.ActionCancelled) || p.ToolStepID != "call-exit" {
		t.Fatalf("resolved record = %+v", p)
	}
	want := "✗ You canceled forebrain's request to exit plan mode"
	if p.Confirmation != want {
		t.Fatalf("confirmation = %q, want %q", p.Confirmation, want)
	}
	if !strings.Contains(stripANSI(out.String()), want) {
		t.Fatalf("the persisted line is not what the terminal showed: %q", out.String())
	}
	// The event id is the one the post-decision publish builds from the action,
	// which is what keeps the two writes one record.
	if !strings.HasSuffix(strings.TrimSpace(resolved[0].ID), ":"+string(state.ActionCancelled)) {
		t.Fatalf("resolved event id = %q", resolved[0].ID)
	}
}

// Asking a second model to review the plan decides nothing: the gate stays open
// and the user answers it again afterwards. The line is still shown, so it is
// still recorded - but under its own id and saying what it is, rather than as a
// resolution with no decision in it.
func TestPlanReviewRequestIsRecordedAsItselfNotAsAResolution(t *testing.T) {
	req := turn.ToolApprovalRequest{
		ActionID: "act-1", ActionKind: "exit_plan_mode", ToolName: "exit_plan_mode", ToolStepID: "call-exit",
	}
	review := turn.PlanReviewModelOption{Provider: "openai", Model: "gpt-5"}

	id, reported, ok := approvalDisplayRecord(req.ActionID, req.ActionKind, turn.ToolApprovalDecision{RequestPlanReview: &review})
	require.True(t, ok, "a printed line must have a record")
	if strings.HasPrefix(id, "approval-resolved:") {
		t.Fatalf("a review request claimed a resolution id: %q", id)
	}
	if reported != approvalDisplayDecisionReviewRequested {
		t.Fatalf("review request decision = %q, want %q", reported, approvalDisplayDecisionReviewRequested)
	}
	// The gate is answered afterwards, and that answer is the resolution: its id
	// is the one the post-decision publish builds, so the two writes stay one.
	resolvedID, resolved, ok := approvalDisplayRecord(req.ActionID, req.ActionKind, turn.ToolApprovalDecision{Approved: true})
	require.True(t, ok)
	if resolvedID == id {
		t.Fatalf("the review note and the decision share one record id: %q", id)
	}
	if resolved != string(state.ActionApproved) {
		t.Fatalf("resolution decision = %q", resolved)
	}
}

// The record is written by the same function that prints the line, so "shown
// implies recorded" cannot be split by a later confirmFn call site.
func TestApprovalSinkRecordsTheLineBeforeItPrintsIt(t *testing.T) {
	forcedTermWidth = 120
	t.Cleanup(func() { forcedTermWidth = 0 })

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	t.Cleanup(r.DisableViewportMode)
	recorder := &drawProbeApprovalRecorder{out: &out}
	req, decision := exactCommandApproval("go test ./...")

	NewInteractiveApprovalSinkWithTTY(&out, nil).WithRenderer(r).WithRecorder(recorder).printApprovalConfirmation(req, decision)

	if recorder.confirmation == "" {
		t.Fatal("the sink recorded no confirmation")
	}
	if recorder.printedAtRecord {
		t.Fatal("the confirmation was already drawn when it was recorded")
	}
	if !strings.Contains(stripANSI(out.String()), recorder.confirmation) {
		t.Fatalf("recorded %q but printed %q", recorder.confirmation, out.String())
	}
}

// drawProbeApprovalRecorder remembers whether the renderer had already drawn the
// line by the time the sink asked it to persist it.
type drawProbeApprovalRecorder struct {
	out             *bytes.Buffer
	confirmation    string
	printedAtRecord bool
}

func (r *drawProbeApprovalRecorder) RecordApprovalGate(turn.ToolApprovalRequest) {}

func (r *drawProbeApprovalRecorder) RecordApprovalDecision(_ turn.ToolApprovalRequest, _ turn.ToolApprovalDecision, confirmation string) {
	r.confirmation = confirmation
	r.printedAtRecord = strings.Contains(stripANSI(r.out.String()), strings.TrimPrefix(confirmation, "✔ "))
}

// One action, one display record. The recorder writes the answer before the
// action service applies it, and the post-decision publish then writes the same
// id from the stored action: if the status the recorder derived ever drifted
// from the status the action takes, resume would show two records for one
// decision.
func TestApprovalDisplayRecordCollapsesWithThePostDecisionPublish(t *testing.T) {
	for _, tc := range []struct {
		name       string
		kind       string
		payload    map[string]any
		decision   turn.ToolApprovalDecision
		wantStatus string
	}{
		{"cancel", "exit_plan_mode", map[string]any{"plan": "do the thing"}, turn.ToolApprovalDecision{Cancelled: true}, string(state.ActionCancelled)},
		{"deny", "shell", map[string]any{"command": "ls"}, turn.ToolApprovalDecision{Denied: true}, string(state.ActionDenied)},
		{"approve", "shell", map[string]any{"command": "ls"}, turn.ToolApprovalDecision{Approved: true}, string(state.ActionApproved)},
	} {
		t.Run(tc.name, func(t *testing.T) {
			ctx := context.Background()
			home := t.TempDir()
			db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
			require.NoError(t, err)
			defer db.Close()

			actions := newTestActions(t, db)
			runs := &state.RunStore{DB: db}
			run, err := runs.CreateRun(ctx, "s1", "gated work")
			require.NoError(t, err)
			act, err := actions.CreatePending(ctx, "s1", tc.kind, tc.payload)
			require.NoError(t, err)
			require.NoError(t, runs.SetWaitingAction(ctx, run.ID, state.Wait{
				RunID: run.ID, ActionID: act.ID, ToolName: tc.kind, ToolInputJSON: `{"command":"ls"}`,
			}))

			cs := sessionEnv{Home: home, ActionSvc: actions, RunSvc: runs}.session()
			req := turn.ToolApprovalRequest{
				SessionID: "s1", RunID: run.ID, ActionID: act.ID, ToolName: tc.kind,
				ActionKind: tc.kind, ToolInputJSON: `{"command":"ls"}`, ToolStepID: "call-1",
			}

			cs.RecordApprovalGate(req)
			cs.RecordApprovalDecision(req, tc.decision, "✗ one line")
			require.NoError(t, cs.completeSurfaceApproval(ctx, act.ID, tc.decision, nil))

			resolved := approvalEventsOfType(t, runs, "s1", event.RunEventApprovalResolved)
			require.Len(t, resolved, 1, "one decision must leave one display record")
			var p event.ApprovalResolvedPayload
			require.NoError(t, json.Unmarshal(resolved[0].Payload, &p))
			if p.Decision != tc.wantStatus {
				t.Fatalf("record decision = %q, want %q", p.Decision, tc.wantStatus)
			}
			// The first writer wins the id, so the payload a resume replays is
			// the one carrying the line the user read.
			if p.Confirmation != "✗ one line" || p.ToolStepID != "call-1" {
				t.Fatalf("record = %+v", p)
			}
		})
	}
}

// A subagent's approval is recorded first, so it has to carry the agent that
// owns it: the store keeps the first event for an id, and a record without one
// routes the child's own decision into the conversation view.
func TestSubagentApprovalRecordKeepsItsAgentRouting(t *testing.T) {
	ctx := context.Background()
	home := t.TempDir()
	db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
	require.NoError(t, err)
	defer db.Close()

	actions := newTestActions(t, db)
	runs := &state.RunStore{DB: db}
	run, err := runs.CreateRun(ctx, "s1", "child work")
	require.NoError(t, err)
	act, err := actions.CreatePending(ctx, "s1", "shell", map[string]any{"command": "ls"})
	require.NoError(t, err)

	cs := sessionEnv{Home: home, ActionSvc: actions, RunSvc: runs}.session()
	req := turn.ToolApprovalRequest{
		SessionID: "s1", RunID: run.ID, ActionID: act.ID, ToolName: "shell", ActionKind: "shell",
		ToolInputJSON: `{"command":"ls"}`, AgentID: "subagent-42", SubagentType: "explore",
	}

	cs.RecordApprovalGate(req)
	cs.RecordApprovalDecision(req, turn.ToolApprovalDecision{Approved: true}, "✔ one line")

	resolved := approvalEventsOfType(t, runs, "s1", event.RunEventApprovalResolved)
	require.Len(t, resolved, 1)
	var p event.ApprovalResolvedPayload
	require.NoError(t, json.Unmarshal(resolved[0].Payload, &p))
	if p.AgentID != "subagent-42" || p.SubagentType != "explore" {
		t.Fatalf("subagent record lost its routing: %+v", p)
	}
	if p.Confirmation != "✔ one line" {
		t.Fatalf("subagent record lost its confirmation: %+v", p)
	}
	gates := approvalEventsOfType(t, runs, "s1", event.RunEventApprovalReq)
	require.Len(t, gates, 1)
	var requested event.ApprovalRequestedPayload
	require.NoError(t, json.Unmarshal(gates[0].Payload, &requested))
	if requested.AgentID != "subagent-42" {
		t.Fatalf("subagent gate lost its routing: %+v", requested)
	}
}

// An answered AskUserQuestion is display history too: the overlay prints no
// confirmation line and the sink has no decision hook for it, so without its own
// record a resume shows questions that were asked and never that they were
// answered.
func TestAskUserQuestionAnswerIsRecordedAsAnswered(t *testing.T) {
	ctx := context.Background()
	home := t.TempDir()
	db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
	require.NoError(t, err)
	defer db.Close()

	actions := newTestActions(t, db)
	runs := &state.RunStore{DB: db}
	run, err := runs.CreateRun(ctx, "s1", "ask the user")
	require.NoError(t, err)
	act, err := actions.CreatePending(ctx, "s1", "user_interaction", state.AskForm{
		SessionID: "s1",
		Questions: []state.AskQuestion{{
			ID: "q1", Prompt: "which?", Options: []state.AskOption{{ID: "one", Label: "one"}, {ID: "two", Label: "two"}},
		}},
	})
	require.NoError(t, err)
	require.NoError(t, runs.SetWaitingAction(ctx, run.ID, state.Wait{
		RunID: run.ID, ActionID: act.ID, ToolName: "user_interaction",
	}))

	cs := sessionEnv{Home: home, ActionSvc: actions, RunSvc: runs}.session()
	answer, err := json.Marshal(state.AskAnswer{Answers: []state.AskAnswerItem{{QuestionID: "q1", OptionIDs: []string{"one"}}}})
	require.NoError(t, err)

	require.NoError(t, cs.completeSurfaceApproval(ctx, act.ID, turn.ToolApprovalDecision{
		Approved: true, AskAnswerJSON: string(answer),
	}, nil))

	stored, err := actions.Get(ctx, act.ID)
	require.NoError(t, err)
	require.Equal(t, state.ActionAnswered, stored.Status)

	resolved := approvalEventsOfType(t, runs, "s1", event.RunEventApprovalResolved)
	require.Len(t, resolved, 1, "an answered question must be recorded")
	var p event.ApprovalResolvedPayload
	require.NoError(t, json.Unmarshal(resolved[0].Payload, &p))
	if p.Decision != string(state.ActionAnswered) || p.ActionKind != "user_interaction" {
		t.Fatalf("answered record = %+v", p)
	}
	// The overlay drew no line, so a replay must not invent one.
	if p.Confirmation != "" {
		t.Fatalf("answered record invented a confirmation: %q", p.Confirmation)
	}
}

// The live surface already drew the conversation's gate as a tool card and its
// answer as the confirmation line. The notify branches that turn approval events
// into messages must therefore stay subagent-only, or the same decision lands
// twice on screen.
func TestConversationApprovalEventsDoNotNotifyTheSurfaceTwice(t *testing.T) {
	ctx := context.Background()
	home := t.TempDir()
	db, err := state.OpenStateForTest(ctx, filepath.Join(home, "state.sqlite"))
	require.NoError(t, err)
	defer db.Close()

	runs := &state.RunStore{DB: db}
	cs := sessionEnv{Home: home, RunSvc: runs}.session()
	require.NoError(t, state.NewSessionStore(db, "main").Ensure(ctx, "s1", "s1"))
	notified := make(chan any, 8)
	cs.PrependUINotify(func(msg any) {
		select {
		case notified <- msg:
		default:
		}
	})

	for _, evt := range []event.RunEvent{
		event.NewRunEvent("approval-requested:act-1", "", "s1", event.RunEventApprovalReq,
			event.ApprovalRequestedPayload{ActionID: "act-1", ActionKind: "exit_plan_mode", ToolStepID: "call-1"}, time.Now()),
		event.NewRunEvent("approval-resolved:act-1:cancelled", "", "s1", event.RunEventApprovalResolved,
			event.ApprovalResolvedPayload{ActionID: "act-1", ActionKind: "exit_plan_mode", Decision: "cancelled", ToolStepID: "call-1", Confirmation: "✗ You canceled forebrain's request to exit plan mode"}, time.Now()),
	} {
		require.NoError(t, cs.publishRunEvent(ctx, evt))
	}

	select {
	case msg := <-notified:
		if m, ok := msg.(NewMessageMsg); ok {
			t.Fatalf("a conversation approval notified the surface again: %#v", m.Msg)
		}
	case <-time.After(50 * time.Millisecond):
	}
}

// TestSkillCardHeaderIsNotTheReasoningColor pins the two cards apart. A Skill
// card and a "Thought for …" card sit next to each other in almost every turn
// that loads a skill, and both used foreground 147 for their glyph and header —
// so the tint that is supposed to say "this loaded a skill" said nothing.
func TestSkillCardHeaderIsNotTheReasoningColor(t *testing.T) {
	useANSI256ColorProfile(t)
	const reasoning = reasoningHeaderColor
	rendered, _ := renderExplicitSkillStepCard(t, explicitSkillStep(tool.StepKindToolCompleted, "", 50*time.Millisecond))
	header := strings.SplitN(rendered, "\n", 2)[0]
	if !strings.Contains(header, "38;5;"+skillCardHeaderColor) {
		t.Fatalf("skill header is not painted %s:\n%q", skillCardHeaderColor, header)
	}
	if strings.Contains(header, "38;5;"+reasoning) {
		t.Fatalf("skill header reuses the reasoning card's color %s:\n%q", reasoning, header)
	}
	if skillCardHeaderColor == reasoning {
		t.Fatal("the skill tint must not be the reasoning tint")
	}
	// It must also stay distinct from the ordinary tool tint, or the signal is
	// gone in the other direction.
	if skillCardHeaderColor == ordinaryToolHeaderColor {
		t.Fatal("the skill tint must not be the ordinary tool tint")
	}
}

// TestSkillCardOutputMatchesOtherToolOutputBrightness pins the skill body to
// the one foreground every tool's output block uses. It carried an extra Faint
// on top of that block color, which made it the only output in the transcript
// rendered at two levels of dimming.
func TestSkillCardOutputMatchesOtherToolOutputBrightness(t *testing.T) {
	useANSI256ColorProfile(t)
	rendered, _ := renderExplicitSkillStepCard(t, explicitSkillStep(tool.StepKindToolCompleted, "", 50*time.Millisecond))
	_, body, ok := strings.Cut(rendered, "\n")
	if !ok || strings.TrimSpace(stripANSI(body)) == "" {
		t.Fatalf("skill card rendered no output block:\n%q", rendered)
	}
	// \x1b[2m is the faint attribute. Ordinary tool output never carries it.
	if strings.Contains(body, "\x1b[2m") {
		t.Fatalf("skill output is faint; it must read like every other tool's output:\n%q", body)
	}
	var reference bytes.Buffer
	NewRenderer(&reference, &reference).renderCompactFrame(Frame{
		Kind:     FrameTool,
		Title:    "shell",
		Content:  "Loaded from /tmp/skills/review-agent/SKILL.md",
		Final:    true,
		ToolMeta: tool.ToolMeta{ToolName: "shell", Status: "completed"},
	}, "tool", "214")
	_, refBody, refOK := strings.Cut(reference.String(), "\n")
	if !refOK {
		t.Fatalf("reference tool card rendered no output block:\n%q", reference.String())
	}
	if got, want := outputBlockColors(body), outputBlockColors(refBody); got != want {
		t.Fatalf("skill output foreground %q, want the ordinary tool output foreground %q", got, want)
	}
}

// outputBlockColors collects the SGR foreground codes an output block opens its
// lines with, which is what "the same color as the other tool cards" means.
func outputBlockColors(block string) string {
	seen := map[string]bool{}
	var out []string
	for _, line := range strings.Split(strings.TrimRight(block, "\n"), "\n") {
		code := ""
		if rest, found := strings.CutPrefix(line, "\x1b[38;5;"); found {
			if digits, _, cut := strings.Cut(rest, "m"); cut {
				code = digits
			}
		}
		if !seen[code] {
			seen[code] = true
			out = append(out, code)
		}
	}
	return strings.Join(out, ",")
}

// A folded read_file card must count logical file lines, not rendered rows:
// the engine reports how many content lines the result holds
// (ToolMeta.ResultLines) and long lines wrap into extra terminal rows at
// narrow widths, which used to be counted as extra file lines.
func TestViewportCollapsedReadFileCountsLogicalLinesNotWrappedRows(t *testing.T) {
	var body strings.Builder
	for i := 1; i <= 200; i++ {
		if i%20 == 0 {
			// The engine prefixes every content line with its "N|" gutter;
			// these long lines wrap into several rendered rows.
			body.WriteString(fmt.Sprintf("%d|%s", i, strings.Repeat("x", 300)))
		} else {
			body.WriteString(fmt.Sprintf("%d|line %d", i, i))
		}
		body.WriteByte('\n')
	}
	content := "path: `/repo/big.py`\n\n```python\n" + strings.TrimRight(body.String(), "\n") + "\n```"

	var out bytes.Buffer
	r := NewRenderer(&out, &out)
	r.EnableViewportMode()
	r.RenderFrame(Frame{
		Kind:    FrameTool,
		Title:   "read_file",
		Content: content,
		Final:   true,
		ToolMeta: tool.ToolMeta{
			ToolName:     "read_file",
			Status:       "completed",
			ResultLines:  200,
			ResultOffset: 0,
			Input: map[string]any{
				"file_path": "/repo/big.py",
				"offset":    float64(0),
				"limit":     float64(220),
			},
		},
	})

	collapsed := renderViewport(&r.vm, 100, 40, 0, DiffThemeDark)
	plain := stripANSI(strings.Join(collapsed.lines, "\n"))
	if !strings.Contains(plain, "197 more lines (click to expand)") {
		t.Fatalf("fold hint must report the engine's remaining logical lines (200-3=197), got:\n%s", plain)
	}
	// The preview shows exactly the first three logical file lines.
	if !strings.Contains(plain, "line 3") {
		t.Fatalf("collapsed preview should show the third logical line:\n%s", plain)
	}
	if strings.Contains(plain, "line 4") {
		t.Fatalf("collapsed preview must stop after three logical lines:\n%s", plain)
	}

	// Expanding shows every logical line and no hint.
	for i := range r.vm.blocks {
		r.vm.blocks[i].expanded = true
	}
	expanded := renderViewport(&r.vm, 100, 400, 0, DiffThemeDark)
	expandedPlain := stripANSI(strings.Join(expanded.lines, "\n"))
	if strings.Contains(expandedPlain, "more lines (click to expand)") {
		t.Fatalf("expanded card must not keep the fold hint:\n%s", expandedPlain)
	}
	if !strings.Contains(expandedPlain, "199| line 199") || !strings.Contains(expandedPlain, "200|") {
		t.Fatalf("expanded card should show the last logical line:\n%s", expandedPlain)
	}
}

// The header range describes the page the engine returned, never the range
// the caller asked for: a limit beyond the 200-line ceiling used to print
// "lines 1-220" for a 200-line page.
func TestToolDisplayHeaderReadFileUsesResultLineFacts(t *testing.T) {
	tests := []struct {
		name        string
		resultLines int
		resultOff   int
		want        string
	}{
		{name: "top of file", resultLines: 200, resultOff: 0, want: "lines 1-200"},
		{name: "paged", resultLines: 200, resultOff: 200, want: "lines 201-400"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			header := ToolDisplayHeader(Frame{
				Kind:  FrameTool,
				Title: "read_file",
				Final: true,
				ToolMeta: tool.ToolMeta{
					ToolName:     "read_file",
					Status:       "completed",
					ResultLines:  tt.resultLines,
					ResultOffset: tt.resultOff,
					Input: map[string]any{
						"file_path": "/repo/big.py",
						"offset":    float64(tt.resultOff),
						"limit":     float64(220),
					},
				},
			}, "")
			if !strings.Contains(header, tt.want) {
				t.Fatalf("header = %q, want it to contain %q", header, tt.want)
			}
			if strings.Contains(header, "lines 1-220") {
				t.Fatalf("header must not show the requested range: %q", header)
			}
		})
	}
}

// TestPlanReviewRunIsAChildOfTheGatedRun pins that the reviewer's run row is a
// subagent run of the run parked at the exit_plan_mode gate, recorded in the
// conversation: a top-level run under the reviewer's worker session names a
// session that has no row, and the database refuses it.
func TestPlanReviewRunIsAChildOfTheGatedRun(t *testing.T) {
	executor := &fakeSubagentExecutor{replies: []func(context.Context) (string, error){
		func(context.Context) (string, error) { return "Verdict: ship it.", nil },
	}}
	home := t.TempDir()
	db, err := state.OpenStateForTest(context.Background(), filepath.Join(home, "state.db"))
	if err != nil {
		t.Fatalf("OpenStateForTest: %v", err)
	}
	t.Cleanup(func() { db.Close() })
	if err := state.NewSessionStore(db, "main").Ensure(context.Background(), "session-1", "session-1"); err != nil {
		t.Fatal(err)
	}
	runs := &state.RunStore{DB: db}
	gate, err := runs.CreateRun(context.Background(), "session-1", "plan the change")
	if err != nil {
		t.Fatal(err)
	}
	cfg := planReviewConfig(
		appcfg.AgentLLMProviderConfig{Provider: "openai", Model: "gpt-4o", APIKey: "key", BaseURL: "https://example.invalid"},
	)
	cs := sessionEnv{
		Home:      home,
		ActionSvc: newTestActions(t, db),
		Runner:    &run.Runner{Deps: &run.Deps{Home: home, AppCfg: cfg, ProjectRoot: home, RunRT: runs}, SubagentExecutor: executor},
	}.session()
	cs.setPendingApproval(&chatApprovalResume{ActionID: "plan-action", SessionID: "session-1", RunID: gate.ID})
	reviewer := &planSubagentReviewer{session: cs, model: turn.Model{Provider: "openai", Model: "gpt-4o"}}

	if _, err := reviewer.Review(context.Background(), turn.Request{Plan: "# Plan\n\n1. Ship it.", Task: "Ship."}); err != nil {
		t.Fatalf("Review error: %v", err)
	}
	if len(executor.calls) != 1 || executor.calls[0].superviseRunID == "" {
		t.Fatalf("review must supervise a child run of the gated run, calls = %+v", executor.calls)
	}
	child, err := runs.GetRun(context.Background(), executor.calls[0].superviseRunID)
	if err != nil {
		t.Fatal(err)
	}
	if child.ParentRunID != gate.ID || child.SessionID != "session-1" {
		t.Fatalf("review run = parent %q session %q, want a child of %q in session-1", child.ParentRunID, child.SessionID, gate.ID)
	}
}

// newModelSelectionTestSession builds a characterization-style session whose
// runner is loaded and pinned, with two reasoning-capable providers under
// main, both rows ensured.
func newModelSelectionTestSession(t *testing.T) *ChatSession {
	t.Helper()
	t.Setenv("FOREBRAIN_MODEL_SELECTION_TEST_KEY", "test-key")
	s := newCharacterizationSession(t, nil)
	main := s.cfg().Agents.Definitions["main"]
	main.LLMProviders[0].APIKey = "${FOREBRAIN_MODEL_SELECTION_TEST_KEY}"
	second := main.LLMProviders[0]
	second.Model = "gpt-other"
	second.Params = appcfg.LLMRequestParams(`{"reasoning":{"effort":"high"}}`)
	main.LLMProviders = append(main.LLMProviders, second)
	s.cfg().Agents.Definitions["main"] = main
	require.NoError(t, appcfg.Save(filepath.Join(s.home(), "forebrain.yaml"), *s.cfg()))
	// The pinned runtime follows the file the fixture just wrote.
	require.NoError(t, s.reloadConfigFromDisk())
	ctx := context.Background()
	for _, sid := range []string{"sess-a", "sess-b"} {
		require.NoError(t, s.sessStore().Ensure(ctx, sid, sid))
	}
	return s
}

func (s *ChatSession) storedSelection(t *testing.T, sid string) state.SessionModelSelection {
	t.Helper()
	sel, ok, err := s.sessStore().SessionModelSelection(context.Background(), sid)
	require.NoError(t, err)
	require.True(t, ok, "session %s has no stored selection", sid)
	return sel
}

func requireRunnerModel(t *testing.T, s *ChatSession, provider, model, effort string) {
	t.Helper()
	sel := run.PrimaryModelSelection(s.runner())
	require.True(t, sel.Set)
	require.Equal(t, provider, sel.Provider)
	require.Equal(t, model, sel.Model)
	require.Equal(t, effort, sel.Effort)
}

// newSwitchState builds the stream state the main loop switches through.
func newSwitchState(s *ChatSession, sid string) *streamState {
	return &streamState{sessionID: sid, session: s}
}

func TestInteractiveResumeRestoresSessionModelSelection(t *testing.T) {
	s := newModelSelectionTestSession(t)
	ctx := context.Background()

	// sess-a pins the second provider with its concrete effort; sess-b has
	// no row and follows the file default.
	require.NoError(t, s.SelectModel(ctx, "sess-a", turn.ModelChoice{Provider: "openai", Model: "gpt-other", CanReason: true}, nil))
	require.Equal(t, "gpt-other", s.storedSelection(t, "sess-a").Model)

	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	state := newSwitchState(s, "sess-a")

	// A → B: no stored row, the file default (gpt-main, no effort).
	switched, _, err := switchStreamSession(ctx, state, renderer, nil, "sess-b")
	require.NoError(t, err)
	require.True(t, switched)
	requireRunnerModel(t, s, "openai", "gpt-main", "")

	// B → A: the stored selection is restored exactly, effort included.
	switched, _, err = switchStreamSession(ctx, state, renderer, nil, "sess-a")
	require.NoError(t, err)
	require.True(t, switched)
	requireRunnerModel(t, s, "openai", "gpt-other", "high")

	// A → B → A again stays deterministic.
	switched, _, err = switchStreamSession(ctx, state, renderer, nil, "sess-b")
	require.NoError(t, err)
	require.True(t, switched)
	requireRunnerModel(t, s, "openai", "gpt-main", "")
	switched, _, err = switchStreamSession(ctx, state, renderer, nil, "sess-a")
	require.NoError(t, err)
	require.True(t, switched)
	requireRunnerModel(t, s, "openai", "gpt-other", "high")
}

func TestNewSessionResetsModelToConfigDefault(t *testing.T) {
	s := newModelSelectionTestSession(t)
	ctx := context.Background()
	require.NoError(t, s.SelectModel(ctx, "sess-a", turn.ModelChoice{Provider: "openai", Model: "gpt-other", CanReason: true}, nil))
	requireRunnerModel(t, s, "openai", "gpt-other", "high")

	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	state := newSwitchState(s, "sess-a")
	// /new creates a row and switches to it; the row has no model state, so
	// the runner resets to the latest file default.
	res, ok := s.ExecuteSurfaceSlash(ctx, "sess-a", "/new")
	require.True(t, ok)
	require.True(t, res.SessionSwitched)
	switched, _, err := switchStreamSession(ctx, state, renderer, nil, res.SessionID)
	require.NoError(t, err)
	require.True(t, switched)
	requireRunnerModel(t, s, "openai", "gpt-main", "")
}

func TestForkCopiesSessionModelSelection(t *testing.T) {
	s := newModelSelectionTestSession(t)
	ctx := context.Background()

	// The source never ran /model: its runtime pin has no durable row. The
	// fork must still inherit the live selection.
	requireRunnerModel(t, s, "openai", "gpt-main", "")
	res, ok := s.ExecuteSurfaceSlash(ctx, "sess-a", "/fork")
	require.True(t, ok)
	require.True(t, res.SessionSwitched)
	target := res.SessionID

	// The fork materialized the source's live selection before copying.
	require.Equal(t, "gpt-main", s.storedSelection(t, "sess-a").Model)
	require.Equal(t, "gpt-main", s.storedSelection(t, target).Model)

	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	state := newSwitchState(s, "sess-a")
	switched, _, err := switchStreamSession(ctx, state, renderer, nil, target)
	require.NoError(t, err)
	require.True(t, switched)
	requireRunnerModel(t, s, "openai", "gpt-main", "")

	// A source with an explicit non-default selection passes it on.
	require.NoError(t, s.SelectModel(ctx, "sess-b", turn.ModelChoice{Provider: "openai", Model: "gpt-other", CanReason: true}, nil))
	res, ok = s.ExecuteSurfaceSlash(ctx, "sess-b", "/fork")
	require.True(t, ok)
	require.True(t, res.SessionSwitched)
	require.Equal(t, "gpt-other", s.storedSelection(t, res.SessionID).Model)
	require.Equal(t, "high", s.storedSelection(t, res.SessionID).Effort)
}

func TestResumeMissingStoredModelFallsBackWithWarning(t *testing.T) {
	s := newModelSelectionTestSession(t)
	ctx := context.Background()
	require.NoError(t, s.SelectModel(ctx, "sess-a", turn.ModelChoice{Provider: "openai", Model: "gpt-other", CanReason: true}, nil))

	// Remove the pinned pair from the config; the stored row is now stale.
	main := s.cfg().Agents.Definitions["main"]
	main.LLMProviders = main.LLMProviders[:1]
	s.cfg().Agents.Definitions["main"] = main
	require.NoError(t, appcfg.Save(filepath.Join(s.home(), "forebrain.yaml"), *s.cfg()))
	require.NoError(t, s.reloadConfigFromDisk())

	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	state := newSwitchState(s, "sess-b")
	switched, warning, err := switchStreamSession(ctx, state, renderer, nil, "sess-a")
	require.NoError(t, err)
	require.True(t, switched)
	require.NotEmpty(t, warning, "the fallback must be visible to the user")
	require.Contains(t, warning, "no longer configured")
	requireRunnerModel(t, s, "openai", "gpt-main", "")
	// The stale row is overwritten with the fallback, so the next activation
	// is warning-free.
	require.Equal(t, "gpt-main", s.storedSelection(t, "sess-a").Model)
	_, err = s.ActivateSessionModel(ctx, "sess-a")
	require.NoError(t, err)
}

func TestModelPersistenceFailureRollsBackRunner(t *testing.T) {
	s := newModelSelectionTestSession(t)
	ctx := context.Background()

	// The session row is ensured while the database is still open; the save
	// then fails because the database is closed underneath it. The runner
	// itself does not need the database to rebuild, so the rollback runs.
	db := s.sessStore().DB()
	require.NoError(t, db.Close())

	err := s.SelectModel(ctx, "sess-a", turn.ModelChoice{Provider: "openai", Model: "gpt-other", CanReason: true}, nil)
	require.Error(t, err)
	// The rollback succeeded, so the outcome is a plain failure — not
	// uncertain, and the runner is back on the previous model.
	require.Equal(t, turn.ModelNotApplied, turn.SelectionApplyOutcome(err))
	requireRunnerModel(t, s, "openai", "gpt-main", "")
}

// TestSwitchFailureKeepsQueuedInputAndSession aborts the switch before any
// outgoing UI state moves: a failed activation must not drop queued input or
// change the active session id.
func TestSwitchFailureKeepsQueuedInputAndSession(t *testing.T) {
	s := newModelSelectionTestSession(t)
	ctx := context.Background()
	// Pin the live runtime on the second provider first, so the target's
	// stored choice is not already what the runner runs.
	require.NoError(t, s.SelectModel(ctx, "sess-a", turn.ModelChoice{Provider: "openai", Model: "gpt-other", CanReason: true}, nil))
	// sess-b's stored pair is the first provider's original model id.
	_, err := s.sessStore().SaveSessionModelSelection(ctx, "sess-b", state.SessionModelSelection{
		Provider: "openai", Model: "gpt-main", Effort: "",
	})
	require.NoError(t, err)
	// Remove that pair from the live config: the stored choice is stale.
	main := s.cfg().Agents.Definitions["main"]
	main.LLMProviders[0].Model = "gpt-renamed"
	s.cfg().Agents.Definitions["main"] = main
	require.NoError(t, appcfg.Save(filepath.Join(s.home(), "forebrain.yaml"), *s.cfg()))

	state := newSwitchState(s, "sess-a")
	state.queuedTurns = []queuedSubmission{{Action: queuedSubmissionActionTurn, Submission: textSubmission("still mine")}}
	var out bytes.Buffer
	renderer := NewRenderer(&out, &out)
	switched, warning, err := switchStreamSession(ctx, state, renderer, nil, "sess-b")
	// The stored pair is gone; the fallback adopts the new configured
	// default with a warning, and the switch still happens.
	require.NoError(t, err)
	require.True(t, switched)
	require.Contains(t, warning, "no longer configured")
	requireRunnerModel(t, s, "openai", "gpt-renamed", "")
	require.Empty(t, state.queuedTurns, "a successful switch still discards queued input")
	require.Equal(t, "sess-b", state.sessionID)
}

// stub usage to keep the llm import referenced when fixtures change shape.
var _ = llm.FormatProviderModel

// crossProcessFixture is two independently loaded runtimes — two Runners, two
// Environments — over one shared home and config file, the way two processes
// see the same installation. Both load before any switch, so each holds its
// own published pin.
type crossProcessFixture struct {
	home    string
	cfgPath string
	cfg     *appcfg.Root
	a       *ChatSession
	b       *ChatSession
}

func writeCrossProcessConfig(t *testing.T, path string, cfg *appcfg.Root) {
	t.Helper()
	require.NoError(t, appcfg.Save(path, *cfg))
}

func newCrossProcessFixture(t *testing.T) *crossProcessFixture {
	t.Helper()
	t.Setenv("FOREBRAIN_CROSS_PROCESS_TEST_KEY", "test-key")
	home := t.TempDir()
	cfgPath := filepath.Join(home, "forebrain.yaml")
	key := "${FOREBRAIN_CROSS_PROCESS_TEST_KEY}"
	cfg := &appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
		"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{
			{Provider: "openai", Model: "gpt-m1", APIKey: key, BaseURL: "http://m1.test/v1"},
			{Provider: "openai", Model: "gpt-m2", APIKey: key, BaseURL: "http://m2.test/v1"},
		}},
	}}}
	writeCrossProcessConfig(t, cfgPath, cfg)
	return &crossProcessFixture{home: home, cfgPath: cfgPath, cfg: cfg}
}

// loadRuntime builds one process's runtime: its own Deps over the shared
// home, its own loaded Runner, its own Environment and ChatSession. Loading
// reads the file as it stands, exactly as a process start does.
func (f *crossProcessFixture) loadRuntime(t *testing.T, sessionID string) *ChatSession {
	t.Helper()
	loaded, err := appcfg.Load(f.cfgPath)
	require.NoError(t, err)
	db, err := state.OpenStateForTest(context.Background(), filepath.Join(f.home, "state.db"))
	require.NoError(t, err)
	t.Cleanup(func() { _ = db.Close() })
	sessStore := state.NewSessionStore(db, "main")
	require.NoError(t, sessStore.Ensure(context.Background(), sessionID, sessionID))
	deps := run.Deps{
		Home:         f.home,
		AgentName:    "main",
		AppCfg:       &loaded,
		SessionStore: sessStore,
	}
	env := &process.Environment{Root: f.home, ConfigPath: f.cfgPath, Deps: deps}
	runner := &run.Runner{Deps: &env.Deps}
	env.Runner = runner
	require.NoError(t, runner.Load())
	return &ChatSession{Env: env, tuiControl: run.NewController()}
}

func (f *crossProcessFixture) reloadFileIn(t *testing.T, s *ChatSession, cfg *appcfg.Root) {
	t.Helper()
	writeCrossProcessConfig(t, f.cfgPath, cfg)
	require.NoError(t, s.reloadConfigFromDisk())
}

func requireModel(t *testing.T, s *ChatSession, provider, model, effort string) {
	t.Helper()
	sel := run.PrimaryModelSelection(s.runner())
	require.True(t, sel.Set)
	require.Equal(t, provider, sel.Provider)
	require.Equal(t, model, sel.Model)
	require.Equal(t, effort, sel.Effort)
}

// TestModelChoiceDoesNotLeakToSecondProcess is the headline bug: process A
// switching models and reordering the shared file cannot move process B's
// pinned provider, model, or concrete effort when B reloads.
func TestModelChoiceDoesNotLeakToSecondProcess(t *testing.T) {
	f := newCrossProcessFixture(t)
	ctx := context.Background()
	f.a = f.loadRuntime(t, "sess-a")
	f.b = f.loadRuntime(t, "sess-b")
	requireModel(t, f.a, "openai", "gpt-m1", "")
	requireModel(t, f.b, "openai", "gpt-m1", "")

	// A switches m1 → m2 through the real /model flow: live apply, shared
	// default write, synchronous catalog reload.
	require.Equal(t, "Switched to openai / gpt-m2.",
		f.a.ChooseSurfaceSlash(ctx, "sess-a", turn.SlashChoice{Command: "model", Value: "openai / gpt-m2"}).Reply)
	requireModel(t, f.a, "openai", "gpt-m2", "")
	// A's switch is immediately durable for A's own session.
	sel, ok, err := f.a.sessStore().SessionModelSelection(ctx, "sess-a")
	require.NoError(t, err)
	require.True(t, ok)
	require.Equal(t, "gpt-m2", sel.Model)

	// The shared file now leads with m2 — the old bug moved B with it.
	key := "${FOREBRAIN_CROSS_PROCESS_TEST_KEY}"
	reordered := &appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
		"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{
			{Provider: "openai", Model: "gpt-m2", APIKey: key, BaseURL: "http://m2.test/v1"},
			{Provider: "openai", Model: "gpt-m1", APIKey: key, BaseURL: "http://m1.test/v1"},
		}},
	}}}
	f.reloadFileIn(t, f.b, reordered)
	requireModel(t, f.b, "openai", "gpt-m1", "")

	// A concrete effort is pinned the same way: an empty pin stays empty and
	// a non-empty pin survives a later file change on the same pair.
	high := "high"
	require.NoError(t, f.b.SelectModel(ctx, "sess-b", turn.ModelChoice{Provider: "openai", Model: "gpt-m1"}, &high))
	requireModel(t, f.b, "openai", "gpt-m1", "high")
	withEffort := &appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
		"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{
			{Provider: "openai", Model: "gpt-m2", APIKey: key, BaseURL: "http://m2.test/v1",
				Params: appcfg.LLMRequestParams(`{"reasoning":{"effort":"low"}}`)},
			{Provider: "openai", Model: "gpt-m1", APIKey: key, BaseURL: "http://m1.test/v1"},
		}},
	}}}
	f.reloadFileIn(t, f.b, withEffort)
	requireModel(t, f.b, "openai", "gpt-m1", "high")

	// A session with no stored choice adopts the shared file default, which
	// now carries m2/low.
	fresh := f.loadRuntime(t, "sess-fresh")
	require.NoError(t, func() error { _, err := fresh.ActivateSessionModel(ctx, "sess-fresh"); return err }())
	requireModel(t, fresh, "openai", "gpt-m2", "low")

	// Resuming A's pinned session restores its stored selection even after
	// the file default moved again.
	require.NoError(t, func() error { _, err := f.a.ActivateSessionModel(ctx, "sess-a"); return err }())
	requireModel(t, f.a, "openai", "gpt-m2", "")
}

// TestCrossProcessProviderDetailsStillRefresh pins the other half of the
// contract: a pin is identity, not a frozen provider record. B's credentials
// and base URL refresh from the file on every reload.
func TestCrossProcessProviderDetailsStillRefresh(t *testing.T) {
	f := newCrossProcessFixture(t)
	f.a = f.loadRuntime(t, "sess-a")
	f.b = f.loadRuntime(t, "sess-b")
	requireModel(t, f.b, "openai", "gpt-m1", "")
	require.Equal(t, "http://m1.test/v1", run.PrimaryEndpoint(f.b.runner()))

	key := "${FOREBRAIN_CROSS_PROCESS_TEST_KEY}"
	rotated := &appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
		"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{
			{Provider: "openai", Model: "gpt-m1", APIKey: "rotated-key", BaseURL: "http://rotated.test/v1"},
			{Provider: "openai", Model: "gpt-m2", APIKey: key, BaseURL: "http://m2.test/v1"},
		}},
	}}}
	f.reloadFileIn(t, f.b, rotated)
	requireModel(t, f.b, "openai", "gpt-m1", "")
	require.Equal(t, "http://rotated.test/v1", run.PrimaryEndpoint(f.b.runner()))

	// Removing B's pair is a documented fallback, not a reload failure: B
	// moves to the new configured default with a warning.
	withoutPair := &appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
		"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{
			{Provider: "openai", Model: "gpt-m2", APIKey: key, BaseURL: "http://m2.test/v1"},
		}},
	}}}
	f.reloadFileIn(t, f.b, withoutPair)
	requireModel(t, f.b, "openai", "gpt-m2", "")
}

// TestCrossProcessAgentSwitchDropsOldPin pins the /agent rule at the
// Environment level: switching a loaded runtime to another primary agent
// adopts that agent's default; the previous agent's pin is not carried in.
func TestCrossProcessAgentSwitchDropsOldPin(t *testing.T) {
	f := newCrossProcessFixture(t)
	key := "${FOREBRAIN_CROSS_PROCESS_TEST_KEY}"
	f.cfg.Agents.Definitions["reviewer"] = appcfg.AgentDefinition{
		LLMProviders: []appcfg.AgentLLMProviderConfig{
			{Provider: "openai", Model: "gpt-review", APIKey: key, BaseURL: "http://review.test/v1"},
		},
	}
	writeCrossProcessConfig(t, f.cfgPath, f.cfg)
	f.a = f.loadRuntime(t, "sess-a")
	requireModel(t, f.a, "openai", "gpt-m1", "")

	// ApplyAgent mutates the shared runner's tenant fields and reloads; the
	// pin must follow the new agent's default, not survive as main's.
	require.NoError(t, process.ApplyAgent(f.a.agentSwitchDeps(), appcfg.Summary{ID: "reviewer", WorkspaceRoot: filepath.Join(f.home, "workspace")}))
	requireModel(t, f.a, "openai", "gpt-review", "")
}

var _ = os.Setenv

// tuiStubLLM answers one plain text result, so a rolled-back runner can be
// observed without provider credentials.
type tuiStubLLM struct{}

func (tuiStubLLM) Execute(context.Context, []llm.Message, []*llm.Tool) (*llm.Result, error) {
	msg := llm.AssistantMessage([]llm.ContentPart{llm.Text("ok")})
	return &llm.Result{Message: &msg}, nil
}

// The three model/config rollback invariants the process reload path pins in
// pkg/run, mirrored here for the TUI's own reload seam: a failed reload
// leaves the session on its previous config, a rollback failure is visible
// rather than discarded, and a live model selection concurrent with a config
// reload never corrupts the published selection.

func TestApplyConfigFromDiskRollsBackOnUnloadableConfig(t *testing.T) {
	t.Setenv("FOREBRAIN_TUI_RELOAD_TEST_KEY", "test-key")
	home := t.TempDir()
	cfgPath := filepath.Join(home, "forebrain.yaml")
	good := appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
		"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{{
			Provider: "openai", Model: "gpt-a",
			APIKey: "${FOREBRAIN_TUI_RELOAD_TEST_KEY}", BaseURL: "http://a.test/v1",
		}}},
	}}}
	require.NoError(t, appcfg.Save(cfgPath, good))
	db, err := state.OpenStateForTest(context.Background(), filepath.Join(home, "state.db"))
	require.NoError(t, err)
	t.Cleanup(func() { _ = db.Close() })
	s := sessionEnv{Home: home, SQL: db, SessStore: state.NewSessionStore(db, "main"),
		Runner: &run.Runner{Deps: &run.Deps{Home: home}}}.session()
	require.NoError(t, s.reloadConfigFromDisk())
	live := s.cfg()
	require.Equal(t, "gpt-a", live.Agents.Definitions["main"].LLMProviders[0].Model)

	// Parses, passes the startup check, but cannot load.
	require.NoError(t, os.WriteFile(cfgPath, []byte("agents:\n  definitions:\n    main: {}\n"), 0o600))
	require.Error(t, s.reloadConfigFromDisk())
	require.Same(t, live, s.cfg(), "a failed reload must leave the session on its previous config")
	require.Equal(t, "gpt-a", s.cfg().Agents.Definitions["main"].LLMProviders[0].Model)
}

func TestApplyConfigFromDiskRollbackFailureIsVisible(t *testing.T) {
	t.Setenv("FOREBRAIN_TUI_RELOAD_TEST_KEY", "test-key")
	restore := run.SetLLMOverrideForTest(tuiStubLLM{})
	defer restore()
	home := t.TempDir()
	cfgPath := filepath.Join(home, "forebrain.yaml")
	good := appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
		"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{{
			Provider: "openai", Model: "gpt-a",
			APIKey: "${FOREBRAIN_TUI_RELOAD_TEST_KEY}", BaseURL: "http://a.test/v1",
		}}},
	}}}
	require.NoError(t, appcfg.Save(cfgPath, good))
	db, err := state.OpenStateForTest(context.Background(), filepath.Join(home, "state.db"))
	require.NoError(t, err)
	t.Cleanup(func() { _ = db.Close() })
	s := sessionEnv{Home: home, SQL: db, SessStore: state.NewSessionStore(db, "main"),
		Runner: &run.Runner{Deps: &run.Deps{Home: home}}}.session()
	require.NoError(t, s.reloadConfigFromDisk())
	// Mutate the live config in place into an unloadable shape: the rollback
	// the next reload would run rebuilds against this same object and fails
	// too, so neither failure may be hidden.
	s.cfg().Agents.Definitions["main"] = appcfg.AgentDefinition{Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{
		{Provider: "unknownprov", Model: "x", APIKey: "k", BaseURL: "http://x.test/v1"},
		{Provider: "openai", Model: "gpt-a", APIKey: "${FOREBRAIN_TUI_RELOAD_TEST_KEY}", BaseURL: "http://a.test/v1"},
	}}
	s.cfg().ApprovalsReviewer = "auto_review"

	broken := good
	broken.Agents.Definitions["main"] = appcfg.AgentDefinition{Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{
		{Provider: "unknownprov", Model: "y", APIKey: "k", BaseURL: "http://y.test/v1"},
	}}
	broken.ApprovalsReviewer = "auto_review"
	require.NoError(t, appcfg.Save(cfgPath, broken))
	err = s.reloadConfigFromDisk()
	require.Error(t, err)
	require.True(t, run.IsPrimaryModelRuntimeUncertain(err), "a discarded rollback failure must surface as runtime-uncertain, got %v", err)
}

func TestSelectModelConcurrentWithConfigReload(t *testing.T) {
	t.Setenv("FOREBRAIN_TUI_CONCURRENT_TEST_KEY", "test-key")
	home := t.TempDir()
	cfgPath := filepath.Join(home, "forebrain.yaml")
	cfg := appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
		"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{
			{Provider: "openai", Model: "gpt-a", APIKey: "${FOREBRAIN_TUI_CONCURRENT_TEST_KEY}", BaseURL: "http://a.test/v1"},
			{Provider: "openai", Model: "gpt-b", APIKey: "${FOREBRAIN_TUI_CONCURRENT_TEST_KEY}", BaseURL: "http://b.test/v1"},
		}},
	}}}
	require.NoError(t, appcfg.Save(cfgPath, cfg))
	db, err := state.OpenStateForTest(context.Background(), filepath.Join(home, "state.db"))
	require.NoError(t, err)
	t.Cleanup(func() { _ = db.Close() })
	s := sessionEnv{Home: home, SQL: db, SessStore: state.NewSessionStore(db, "main"),
		Runner: &run.Runner{Deps: &run.Deps{Home: home}}}.session()
	require.NoError(t, s.reloadConfigFromDisk())

	var wg sync.WaitGroup
	const rounds = 6
	// Each round writes its own config objects: appcfg.Save normalizes in
	// place, so two goroutines sharing one Root would race inside the save
	// itself — a test bug, not the seam under test.
	newReordered := func() appcfg.Root {
		return appcfg.Root{Agents: appcfg.AgentsSection{Definitions: map[string]appcfg.AgentDefinition{
			"main": {Primary: true, LLMProviders: []appcfg.AgentLLMProviderConfig{
				{Provider: "openai", Model: "gpt-b", APIKey: "${FOREBRAIN_TUI_CONCURRENT_TEST_KEY}", BaseURL: "http://b.test/v1"},
				{Provider: "openai", Model: "gpt-a", APIKey: "${FOREBRAIN_TUI_CONCURRENT_TEST_KEY}", BaseURL: "http://a.test/v1"},
			}},
		}}}
	}
	for range rounds {
		wg.Add(2)
		go func() {
			defer wg.Done()
			_ = s.SelectModel(context.Background(), "s1", turn.ModelChoice{Provider: "openai", Model: "gpt-b"}, nil)
		}()
		go func() {
			defer wg.Done()
			require.NoError(t, appcfg.Save(cfgPath, newReordered()))
			_ = s.reloadConfigFromDisk()
		}()
	}
	wg.Wait()
	// Whatever interleaving won, the published selection is a coherent
	// configured pair and the runner still serves.
	sel := run.PrimaryModelSelection(s.runner())
	require.True(t, sel.Set)
	require.Equal(t, "openai", sel.Provider)
	require.Contains(t, []string{"gpt-a", "gpt-b"}, sel.Model)
	require.NotNil(t, s.runner().Agent())
}

// A recovered approval that cannot continue fails its run with one error
// block: publishing the turn error is what draws it, so nothing draws it a
// second time beside it.
func TestFailedRecoveredApprovalDrawsItsErrorOnce(t *testing.T) {
	ctx := context.Background()
	s := newCharacterizationSession(t, nil)
	sessionID := "char-recovered-failure"
	if err := s.sessStore().Ensure(ctx, sessionID, sessionID); err != nil {
		t.Fatal(err)
	}
	rn, err := s.runSvc().CreateRun(ctx, sessionID, "continue")
	if err != nil {
		t.Fatal(err)
	}
	act, err := s.actionSvc().CreatePending(ctx, sessionID, "shell", map[string]any{"session_id": sessionID, "command": "ls"})
	if err != nil {
		t.Fatal(err)
	}
	if err := s.runSvc().SetWaitingAction(ctx, rn.ID, state.Wait{RunID: rn.ID, ActionID: act.ID, ToolName: "shell"}); err != nil {
		t.Fatal(err)
	}
	rec := &notifiedRecorder{}
	s.PrependUINotify(rec.record)

	s.failRecoveredApproval(sessionID, act.ID, "approval action failed")

	errorsDrawn := 0
	for _, msg := range rec.awaitStable(t) {
		if m, ok := msg.(NewMessageMsg); ok && m.Msg.Kind == MsgKindError {
			errorsDrawn++
		}
	}
	if errorsDrawn != 1 {
		t.Fatalf("error blocks drawn = %d, want exactly one", errorsDrawn)
	}
}

// panelLSPControlStub is the control plane the /lsp panel tests drive: it
// records the actions and answers a fixed snapshot.
type panelLSPControlStub struct {
	snapshot  event.LSPSnapshot
	enabled   []string
	restarts  []string
	installs  []string
	recResets int
	err       error
}

func (c *panelLSPControlStub) Snapshot() event.LSPSnapshot { return c.snapshot }
func (c *panelLSPControlStub) Subscribe(func(event.LSPSnapshot)) func() {
	return func() {}
}
func (c *panelLSPControlStub) SetEnabled(serverID string, enabled bool) error {
	c.enabled = append(c.enabled, fmt.Sprintf("%v %s", enabled, serverID))
	return c.err
}
func (c *panelLSPControlStub) Restart(serverID string) error {
	c.restarts = append(c.restarts, serverID)
	return c.err
}
func (c *panelLSPControlStub) Install(context.Context, string, func(string)) error {
	c.installs = append(c.installs, "")
	return c.err
}
func (c *panelLSPControlStub) SetRecommendationListener(func(context.Context, event.LSPRecommendation)) {
}
func (c *panelLSPControlStub) DecideRecommendation(string, event.LSPRecommendationChoice) error {
	return nil
}
func (c *panelLSPControlStub) ResetRecommendations() error {
	c.recResets++
	return c.err
}

// Every /lsp panel action goes through the runner's control plane: without
// one the panel is unavailable, with one the reply is the sentence the panel
// shows, verbatim.
func TestPanelLSPSessionMethods(t *testing.T) {
	home := t.TempDir()
	s := sessionEnv{Home: home, Runner: &run.Runner{Deps: &run.Deps{Home: home}}}.session()
	if _, err := s.PanelLSPSnapshot(); err != errPanelUnavailable {
		t.Fatalf("snapshot without control = %v, want errPanelUnavailable", err)
	}
	if _, err := s.PanelSetLSPEnabled("gopls", true); err != errPanelUnavailable {
		t.Fatalf("enable without control = %v", err)
	}
	if _, err := s.PanelRestartLSP("gopls"); err != errPanelUnavailable {
		t.Fatalf("restart without control = %v", err)
	}
	if _, err := s.PanelInstallLSP("gopls"); err != errPanelUnavailable {
		t.Fatalf("install without control = %v", err)
	}
	if _, err := s.PanelResetLSPRecommendations(); err != errPanelUnavailable {
		t.Fatalf("reset without control = %v", err)
	}
	if _, ok := s.SubscribeLSPStatus(); ok {
		t.Fatal("subscribe without control must report false")
	}

	ctl := &panelLSPControlStub{snapshot: event.LSPSnapshot{
		ProjectRoot: "/proj", Trusted: true, FeatureEnabled: true,
		Servers: []event.LSPServerStatus{{ID: "gopls", Enabled: true, State: event.LSPStateReady, InstallCommand: "go install gopls"}},
	}}
	s = sessionEnv{Home: home, Runner: &run.Runner{Deps: &run.Deps{Home: home, CodeIntelControl: ctl}}}.session()

	snap, err := s.PanelLSPSnapshot()
	require.NoError(t, err)
	require.Equal(t, "/proj", snap.ProjectRoot)

	reply, err := s.PanelSetLSPEnabled("gopls", true)
	require.NoError(t, err)
	require.Equal(t, "Enabled. Diagnostics start with the next edit; the lsp tool appears in new sessions.", reply)
	reply, err = s.PanelSetLSPEnabled("gopls", false)
	require.NoError(t, err)
	require.Equal(t, "Disabled. Its instances in this project have stopped.", reply)
	reply, err = s.PanelRestartLSP("gopls")
	require.NoError(t, err)
	require.Equal(t, "Restarting…", reply)
	reply, err = s.PanelInstallLSP("gopls")
	require.NoError(t, err)
	require.Equal(t, "Installing: go install gopls", reply)
	reply, err = s.PanelResetLSPRecommendations()
	require.NoError(t, err)
	require.Equal(t, "Recommendations are back on.", reply)
	require.Equal(t, []string{"true gopls", "false gopls"}, ctl.enabled)
	require.Equal(t, []string{"gopls"}, ctl.restarts)
	require.Equal(t, 1, ctl.recResets)

	cancel, ok := s.SubscribeLSPStatus()
	require.True(t, ok)
	cancel()
}

// The text fallback of /lsp renders the control plane's snapshot; without a
// control plane it says so.
func TestHandleLSPSlashRendersSnapshot(t *testing.T) {
	home := t.TempDir()
	empty := sessionEnv{Home: home, Runner: &run.Runner{Deps: &run.Deps{Home: home}}}.session()
	reply, handled := empty.HandleLSPSlash("s1", "cli")
	require.True(t, handled)
	require.Equal(t, "lsp: unavailable", reply)

	ctl := &panelLSPControlStub{snapshot: event.LSPSnapshot{
		ProjectRoot: "/proj", Trusted: true, FeatureEnabled: true,
		Servers: []event.LSPServerStatus{{ID: "gopls", Enabled: true, State: event.LSPStateReady, Languages: []string{"Go"}}},
	}}
	s := sessionEnv{Home: home, Runner: &run.Runner{Deps: &run.Deps{Home: home, CodeIntelControl: ctl}}}.session()
	reply, handled = s.HandleLSPSlash("s1", "cli")
	require.True(t, handled)
	require.Contains(t, reply, "Language servers · 1 configured, 1 enabled")
	require.Contains(t, reply, "gopls")
}

// lspInstallWatchStub is the control plane the install watch drives: it
// hands the subscriber to the test, which feeds it the snapshots an
// install's lifecycle produces.
type lspInstallWatchStub struct {
	panelLSPControlStub
	subscribed func(event.LSPSnapshot)
}

func (c *lspInstallWatchStub) Subscribe(fn func(event.LSPSnapshot)) func() {
	c.subscribed = fn
	return func() {}
}

// Every answer returns the transcript line the spec spells out, and the
// not-now line says when five dismissals turned recommendations off.
func TestDecideLSPRecommendationTexts(t *testing.T) {
	home := t.TempDir()
	rec := event.LSPRecommendation{
		ID: "lsprec-1", ServerID: "gopls", DisplayName: "gopls",
		Languages: []string{"Go", "Go Workspaces"}, TriggerExtension: ".go",
		Mode: "enable", InstallCommand: "go install golang.org/x/tools/gopls@latest",
	}
	newSession := func(snap event.LSPSnapshot) *ChatSession {
		ctl := &lspInstallWatchStub{}
		ctl.snapshot = snap
		return sessionEnv{Home: home, Runner: &run.Runner{Deps: &run.Deps{Home: home, CodeIntelControl: ctl}}}.session()
	}

	text, err := newSession(event.LSPSnapshot{}).DecideLSPRecommendation(rec, event.LSPChoiceEnable)
	require.NoError(t, err)
	require.Equal(t, "gopls enabled for Go, Go Workspaces. Diagnostics start with the next edit.", text)

	text, err = newSession(event.LSPSnapshot{}).DecideLSPRecommendation(rec, event.LSPChoiceInstall)
	require.NoError(t, err)
	require.Equal(t, "Installing gopls: go install golang.org/x/tools/gopls@latest", text)

	text, err = newSession(event.LSPSnapshot{}).DecideLSPRecommendation(rec, event.LSPChoiceNotNow)
	require.NoError(t, err)
	require.Equal(t, "Not now. No language server will be suggested again in this session.", text)

	disabled := event.LSPSnapshot{RecommendationsDisabled: true}
	text, err = newSession(disabled).DecideLSPRecommendation(rec, event.LSPChoiceNotNow)
	require.NoError(t, err)
	require.Equal(t, "Language server recommendations are now off (dismissed 5 times in a row). Turn them back on in /lsp.", text)

	text, err = newSession(event.LSPSnapshot{}).DecideLSPRecommendation(rec, event.LSPChoiceNever)
	require.NoError(t, err)
	require.Equal(t, "gopls will not be suggested again. /lsp can still enable it.", text)

	text, err = newSession(event.LSPSnapshot{}).DecideLSPRecommendation(rec, event.LSPChoiceDisableAll)
	require.NoError(t, err)
	require.Equal(t, "Language server recommendations are off. Turn them back on in /lsp.", text)

	// Without a control plane there is no line and no decision.
	bare := sessionEnv{Home: home, Runner: &run.Runner{Deps: &run.Deps{Home: home}}}.session()
	_, err = bare.DecideLSPRecommendation(rec, event.LSPChoiceEnable)
	require.ErrorIs(t, err, errPanelUnavailable)
}

// The install answer subscribes before deciding, so every line the install
// prints and its outcome reach the UI: progress as the transient line, the
// result as one frame.
func TestDecideLSPRecommendationInstallReportsDone(t *testing.T) {
	home := t.TempDir()
	ctl := &lspInstallWatchStub{}
	s := sessionEnv{Home: home, Runner: &run.Runner{Deps: &run.Deps{Home: home, CodeIntelControl: ctl}}}.session()
	var mu sync.Mutex
	var got []any
	s.PrependUINotify(func(m any) {
		mu.Lock()
		defer mu.Unlock()
		got = append(got, m)
	})

	rec := event.LSPRecommendation{
		ID: "lsprec-2", ServerID: "gopls", DisplayName: "gopls",
		Languages: []string{"Go"}, TriggerExtension: ".go", Mode: "install",
		InstallCommand: "go install golang.org/x/tools/gopls@latest",
	}
	text, err := s.DecideLSPRecommendation(rec, event.LSPChoiceInstall)
	require.NoError(t, err)
	require.Equal(t, "Installing gopls: go install golang.org/x/tools/gopls@latest", text)
	require.NotNil(t, ctl.subscribed, "the install watch never subscribed")

	ctl.subscribed(event.LSPSnapshot{Servers: []event.LSPServerStatus{{ID: "gopls", Installing: true, InstallLog: []string{"downloading"}}}})
	ctl.subscribed(event.LSPSnapshot{Servers: []event.LSPServerStatus{{ID: "gopls", Installing: true, InstallLog: []string{"downloading", "linking"}}}})
	ctl.subscribed(event.LSPSnapshot{Servers: []event.LSPServerStatus{{ID: "gopls"}}})
	waitForQueuedNotifications(t, s)

	mu.Lock()
	defer mu.Unlock()
	require.Contains(t, got, LSPInstallProgressMsg{ServerID: "gopls", Line: "downloading"})
	require.Contains(t, got, LSPInstallProgressMsg{ServerID: "gopls", Line: "linking"})
	require.Contains(t, got, LSPInstallDoneMsg{ServerID: "gopls", Text: "gopls installed and enabled for Go. Diagnostics start with the next edit."})
}

// A failed install reports the failure text the snapshot carries.
func TestDecideLSPRecommendationInstallReportsFailure(t *testing.T) {
	home := t.TempDir()
	ctl := &lspInstallWatchStub{}
	s := sessionEnv{Home: home, Runner: &run.Runner{Deps: &run.Deps{Home: home, CodeIntelControl: ctl}}}.session()
	var mu sync.Mutex
	var got []any
	s.PrependUINotify(func(m any) {
		mu.Lock()
		defer mu.Unlock()
		got = append(got, m)
	})
	rec := event.LSPRecommendation{ID: "lsprec-3", ServerID: "gopls", DisplayName: "gopls", Languages: []string{"Go"}, Mode: "install", InstallCommand: "go install golang.org/x/tools/gopls@latest"}
	_, err := s.DecideLSPRecommendation(rec, event.LSPChoiceInstall)
	require.NoError(t, err)
	ctl.subscribed(event.LSPSnapshot{Servers: []event.LSPServerStatus{{ID: "gopls", Installing: true, InstallLog: []string{"fetching"}}}})
	ctl.subscribed(event.LSPSnapshot{Servers: []event.LSPServerStatus{{ID: "gopls", InstallError: "exit status 1: no network"}}})
	waitForQueuedNotifications(t, s)
	mu.Lock()
	defer mu.Unlock()
	require.Contains(t, got, LSPInstallDoneMsg{ServerID: "gopls", Err: "exit status 1: no network"})
}
